"""복사합성 적합기 — 녹음을 정답으로 두고 물리 파라미터를 역추정한다.

    fitter = CopySynthFitter(eng, target, sr, init_track)
    rep = fitter.fit_staged()
    y   = fitter.render()

왜 이 방식인가
--------------
음절을 손으로 작곡하면 "지표는 맞는데 사람 소리가 아닌" 상태에서 빠져나올 길이 없다.
무엇이 틀렸는지 비교할 정답이 없기 때문이다. 복사합성에는 정답이 있다 — 원본 파형.
되합성이 원본과 다르면 **엔진이 틀린 것**이고, 어느 파라미터가 부족한지 바로 좁혀진다.

두 가지 일치율을 따로 보고한다
------------------------------
* **포락 일치**: 멜 대역에서 잰다. "포먼트·세기·잡음색이 맞는가". 조음 파라미터가
  옳은지를 재는 값이고, 사람이 듣는 음색에 대응한다.
* **정밀 일치**: 선형 다해상도 STFT 에서 잰다. 창이 길면 하모닉이 분해되므로 F0 가
  0.1 % 만 틀려도 고차 하모닉이 통째로 빗나가 값이 0 근처로 무너진다. 즉 이 값은
  **F0 궤적과 성문 펄스 위치까지 맞았는가**를 재는 훨씬 가혹한 값이다.

둘 다 `100 · (1 − ‖|S_t| − |S_p|‖_F / ‖|S_t|‖_F)` (스펙트럼 수렴도) 로 정의한다.

왜 성김에서 촘촘함으로 가는가
-----------------------------
긴 창부터 켜면 F0 에 대한 손실면이 하모닉 간격마다 골이 파인 톱니가 되어 Adam 이
가장 가까운 가짜 골에 갇힌다. 짧은 창(256)에서는 하모닉이 분해되지 않아 손실면이
매끈하다. 그래서 짧은 창으로 포락과 세기를 먼저 맞추고, 길이를 늘려 가며 하모닉을
잠근다. 각 단계는 앞 단계의 해에서 출발한다.

경계 조건
---------
* 잔차 보정(residual)은 끈다. 학습되지 않은 NN 이 물리 적합을 오염시킨다.
* 로그 파라미터에서 0 은 "끔" 이다. 시그모이드 재매개화로는 0 에 닿을 수 없으므로
  초기값이 0 인 로그 파라미터는 고정한다(켜고 끄기는 물리 결정이지 적합 대상이 아니다).
* 전역 오프셋을 먼저 맞춘다. 전체 수준이 20 dB 틀린 채로 프레임별 적합을 돌리면
  Adam 이 그 20 dB 를 프레임마다 따로 메우고, 제어열이 물리적으로 말이 안 되게 굳는다.
"""
from __future__ import annotations

import os

import math
from dataclasses import dataclass, field

import numpy as np
from scipy.ndimage import uniform_filter1d
import torch

from . import room
from . import tract as _tract_mod
from .calibration import capture_calibration, engine_parameters, parameter_scope
from .events import build_control_events
from . import glottis as _glottis_mod
from . import voice as _voice_mod
from .control import INDEX, PARAMS, ControlTrack

FFT_SIZES = (256, 512, 1024, 2048, 4096)
MEL_FFT = 256              # 포락용 창 (5.3 ms @48 kHz) — 하모닉이 분해되지 않는다
HARM_FFT = 2048            # 하모닉용 창 (43 ms, 분해능 23 Hz) — F0 빗살이 보인다
# Target-synchronous relative amplitude errors; no new synthesis controls.
HARMONIC_W = 1.0
DB_RANGE = 70.0            # 정점 아래 이만큼까지만 본다 (전역 바닥)
#: **밴드별 바닥.** 전역 바닥 하나(정점 −70 dB)는 조용하지만 실재하는 고역을 통째로
#: 가린다 — 실측(`yang_00000040`)에서 멜 48 밴드 중 9 개가 바닥 아래였고 그중 7 개가
#: **13 kHz 위**였다. 목표의 14 kHz 밴드는 정점보다 73.9 dB 아래인데 70 dB 에서 잘리니
#: 그 대역에서는 무슨 짓을 해도 손실이 0 이다. 목표는 거기 20 kHz 코덱 절벽까지
#: 실제 결이 있다(스펙트로그램). `--sharp 1.0`(`out/L14`)이 그 대역을 −17.7 dB 로
#: 망가뜨린 것이 이 사각지대 때문이다 — 벌점이 없으니 공짜로 망가진다.
#:
#: 그래서 각 밴드는 **자기 정점에서 BAND_FLOOR_DB 아래까지** 보이게 한다. 단 전역
#: 정점에서 BAND_FLOOR_MIN 아래로는 내리지 않는다 — 그러지 않으면 F0 아래의 진짜
#: 무음(114 Hz 밴드가 −120 dB)까지 드러나 손실이 빈 대역을 좇는다. 실측 효과
#: (바닥 위에 있는 밴드×프레임 비율, s040 / s101):
#:
#:     12 kHz 위     24.6 → 46.6 %   38.9 → 75.0 %
#:     400 Hz 아래   57.1 → 57.1 %   59.7 → 59.7 %   (무음은 계속 가린다)
#:     400~12 kHz    82.0 → 82.1 %   88.7 → 88.7 %
#:
#: 0 이면 예전처럼 전역 바닥 하나다.
BAND_FLOOR_DB = 40.0
BAND_FLOOR_MIN = 95.0
#: **바닥은 녹음 바닥까지 내린다** (MEASUREMENTS §52.477). 녹음 바닥 잡음을 합성에 더하는 판(`FLOOR_NOISE`)이면, 그 잡음을 손실과 같은
#: 멜 분석에 넣어 대역마다 중앙값 + 이 여유를 바닥으로 삼는다 (위 두 바닥보다 낮을 때만 — 올리지는 않는다). 목표와 합성에 같은 바닥이
#: 깔리니 무음을 좇지 않고, 바닥 위로 솟는 것은 모두 보인다. 전의 바닥(전역 −70 dB·대역 −40 dB)은 3 kHz 위에서 녹음 바닥보다
#: 10~16 dB 높아 — 038 첫머리 6–12 kHz 는 목표가 −83.5, 녹음 바닥 −87.8, 손실 바닥 −71.8 dB — 합성이 거기서 16.7 dB 넘쳐도
#: 손실에는 5 dB 만 보였다. 조용한 첫머리·꼬리의 고역(지직임)이 그 사각지대에 산다. 0 이하면 끈다.
FLOOR_REC_MARGIN_DB = 3.0
# **난류 우세 빈에서 기대 스펙트럼을 볼 시간 폭 (ms). 0 이면 끈다.**
#
# 마찰 잡음의 STFT 크기는 확률변수다 (레일리). 프레임별 실현을 맞추라고 하면 기울기의
# 대부분이 그 잡음이고, 최적해도 실현마다 다르다. 재현할 수 있는 것은 **기대값**뿐이니
# 그것을 비교한다. 목표와 합성에 똑같이 걸리므로 편향은 없고 분산만 줄어든다.
#
# 25 ms 는 마찰음 길이(이 화자 실측 70~110 ms, `profiles/yang_female.json`)의 1/4 이라
# 정상부를 뭉개지 않으면서 창 256 에서 19 프레임을 평균한다(분산 1/19). 조화 우세
# 빈에는 `1−w` 가중이 0 이라 아무 일도 일어나지 않는다.
NOISE_EXPECT_MS = 25.0
# 성김 -> 촘촘함. 각 단계에서 켜는 창 크기.
STAGES = ((256, 512), (256, 512, 1024), (256, 512, 1024, 2048), FFT_SIZES)

# 전역 오프셋을 붙일 파라미터. **수준·기울기·잡음량만**이다.
# 포먼트에 전역 오프셋을 주면 최적화가 F4 를 F1 아래로 끌어내리는 식으로 스펙트럼을
# 맞춘다(실측: F1 887->248, F2 1550->3250, F4 5153->915). 대역 에너지는 맞지만
# 조음으로는 말이 안 되는 해다. 그런 자유도는 애초에 주지 않는다.
# `tract_gain` 은 여기 없다. 전역 수준은 `log_gain` 이 이미 닫힌 형태로 잡는데
# 둘 다 열어 두면 서로를 상쇄하며 떠돌고, 그 사이에서 `p_sub` 까지 끌려간다
# (실측: 보통 세기 모음인데 p_sub 가 17.6 cmH2O — 큰 소리로 외치는 값 — 로 갔다).
# `tract_gain` 은 폐쇄 감쇠 같은 **시간 변화**로만 쓴다.
GLOBAL_PARAMS = frozenset((
    "p_sub", "adduction", "rd_offset", "tilt", "aspiration",
    "fric_gain", "back_leak", "nasal_damp", "nasal_gain",
    "jitter", "shimmer", "bw1", "bw2", "bw3", "bw4",
))

# 사전(prior) 가중. 분석이 믿을 만한 양은 세게 묶고, 관측되지 않는 양은 기본값에
# 묶어 둔다. 약하게 푸는 것은 수준·음질 계열뿐이다.
# **조음 속도 상한 (Hz/ms).** 성도는 근육이 움직이는 물건이라 포먼트가 임의로 빨리
# 뛸 수 없다. 이 값을 넘으면 그건 조음이 아니라 적합기의 프레임별 난동이다.
#
# 계측(`data/ref` 여성 3 개, 유성 프레임 쌍 10,333 개, Praat 1 ms):
#
#   |    | 중앙 | 80분위 | 95분위 | 99분위 |
#   |----|------|--------|--------|--------|
#   | F1 |  2.9 |    8.5 |   27.2 |  147.3 |
#   | F2 |  7.0 |   22.7 |   92.7 |  604.9 |
#   | F3 | 11.5 |   37.5 |  151.0 |  770.7 |
#   | F4 | 10.7 |   31.2 |  145.2 |  771.8 |
#
# 99 분위의 폭주(F2 605, 최대 2043)는 Praat 추적기가 포먼트를 맞바꾼 것이지 조음이
# 아니다. 그래서 **95 분위를 상한**으로 잡는다. 그 아래는 공짜, 넘으면 이차로 문다
# (평활 벌점처럼 전 구간을 뭉개면 설측 F2 의 실제 급전이 같이 죽는다).
#
# 이 제약이 왜 필요했나 — 없을 때 적합된 궤적을 실측과 대조하면:
#   지속 모음 F1 실제 중앙 1.1 Hz/ms  vs  적합 126.4 Hz/ms (×115)
#   설측    F2 실제 중앙 25.5        vs  적합 309.0      (×12)
# 즉 `lam_smooth` 만으로는 네 자릿수 모자랐다. 해가 심하게 비-식별이 되어, 크기만
# 맞고 위상은 틀린 해로 굴러가도 밀어낼 힘이 없었다.
VEL_LIMIT_HZ_PER_MS: dict[str, float] = {
    "f1": 27.0, "f2": 93.0, "f3": 151.0, "f4": 145.0,
}

# **힌지는 틀린 형태였다.** 95 분위를 문턱으로 두면 그 아래의 균일한 난동을 그냥
# 통과시킨다. 실측: 지속 모음의 실제 F2 속도는 1.1 Hz/ms 인데 문턱은 93 이라, 모음에서
# 적합값이 57 Hz/ms 로 널뛰어도 벌점이 0 이다 (A/B 실측: 속도 77.9→57.3 으로 26 % 만
# 줄고 조화 SNR 은 4.6 dB 잃었다 — 나쁜 거래).
#
# 조음 속도의 실측 분포는 꼬리가 중앙의 200~300 배인 희소 신호다:
#
#   |    | 중앙 | 95분위 |   최대 | 꼬리/중앙 |
#   |----|------|--------|--------|-----------|
#   | F1 |  2.9 |   27.2 |  877.8 |      303× |
#   | F2 |  7.0 |   92.7 | 2043.0 |      292× |
#   | F3 | 11.5 |  151.0 | 2540.5 |      221× |
#
# "대부분 정지, 가끔 크게 이동" — 이런 분포의 사전은 이차(가우시안)가 아니라 L1
# (라플라스) 계열이다. 그래서 후버(smooth L1)를 쓴다: 무릎 아래는 이차라 미분이
# 살아 있고, 위는 선형이라 드문 급전에 이차 벌점처럼 가혹하지 않다.
#
# 무릎은 **실측 중앙값**이다 — "여기가 보통 속도" 라는 뜻이지 상한이 아니다.
VEL_KNEE_HZ_PER_MS: dict[str, float] = {
    "f1": 2.9, "f2": 7.0, "f3": 11.5, "f4": 10.7,
}
# **가속도 무릎 (Hz/ms²).** 1 차 차분(속도)으로는 난동과 실제 조음을 못 가른다 —
# 동적 구간에서 둘은 크기가 비슷하고 **시간 구조**만 다르다. 난동은 부호가 매 프레임
# 뒤집히고, 실제 급전은 한 방향으로 지속된다. 그래서 2 차 차분을 본다: 빠르게
# *움직이는* 것은 허용하고 빠르게 *방향을 바꾸는* 것만 문다.
#
# 실측 (data/ref 여성 3 개, 유성 프레임 삼중항 10,305 개, Praat 1 ms):
#
#   |    | 속도 중앙 | 가속 중앙 | 가속 80% | 가속 95% |
#   |----|-----------|-----------|----------|----------|
#   | F1 |       2.9 |       0.7 |      2.4 |     12.6 |
#   | F2 |       7.0 |       1.9 |      8.0 |     69.4 |
#   | F3 |      11.5 |       3.4 |     15.4 |    117.4 |
#   | F4 |      10.7 |       3.5 |     12.6 |    132.5 |
#
# 가속도가 더 나은 판별자인 이유가 이 표에 있다. 우리 적합의 난동은 F2 기준
# 300~500 Hz/ms 로 부호가 매 프레임 뒤집히므로 가속도는 약 600~1000 Hz/ms² 다.
#
#   속도로 보면   실제 7.0  vs 난동 ~300   ->  43 배
#   가속도로 보면 실제 1.9  vs 난동 ~600   -> 300 배
#
# 판별 여유가 7 배 넓다. 속도로는 실제 급전(최대 628 Hz/ms)이 난동 영역과 겹쳐서
# 못 갈랐는데, 가속도로는 실제 급전이 한 방향으로 지속되므로 겹치지 않는다.
ACC_KNEE_HZ_PER_MS2: dict[str, float] = {
    "f1": 0.7, "f2": 1.9, "f3": 3.4, "f4": 3.5,
}
# "off" | "hinge"(95 분위 상한) | "huber"(속도 중앙값 무릎) | "accel"(가속도 무릎)
#
# 앞의 둘은 기각됐다 (docs/MEASUREMENTS.md §8.6). 성긴 격자도 기각됐다 (§8.9) —
# 균일한 격자든 균일한 벌점이든 모든 시점에 똑같이 자유도를 주거나 뺏는데, 조음은
# "대부분 정지, 짧은 순간에 급전" 이라 그 틀로는 두 요구를 동시에 못 맞춘다.
VEL_MODE = "accel"
# **0.001 로 켠다** (0.3.15). 오래 기본값 0 이었는데, 그 이유였던 "포락을 얼마나
# 깎는지 모른다" 가 이제 측정됐다 — **깎지 않고 오히려 올린다.**
#
# 실측 (yang_00000040 **전체**, tilt 셸프 + a_c 속도 벌점 고정, 같은 코드):
#
#   | | 포락 | 정밀 | 제어열 곡률 rms | 95 분위 |
#   |---|---|---|---|---|
#   | 벌점 없음 | 90.47 % | 83.04 % | 147.97 | 256.90 |
#   | 잔물결 0.01 | 91.23 % | 84.05 % | **87.90** | **93.81** |
#   | **가속도 0.001** | **93.17 %** | **86.96 %** | 100.30 | 139.93 |
#
# 이전 세션의 세 구간 벤치와도 일치한다 (docs/HANDOFF.md §4: 모음 4.3→3.7°,
# 씨 17.6→12.1°, 설측 33.8→32.4° — 어디서도 무너지지 않는다).
#
# 힌지 자체는 검증했다: F2 이동 10/50/93 Hz/ms 는 벌점 0, 150 은 0.97, 309 는 14.0.
VEL_W = 0.001

# **잔물결 벌점** — 제어열이 조음 대역 **위에서** 흔들리는 것만 문다.
#
# 왜 필요한가 (docs/MEASUREMENTS.md §13, §16). 제어 격자가 1 ms 라 제어열의
# 나이퀴스트가 500 Hz 인데, 조음은 0~20 Hz 에 있고(음절률 4 Hz, 음소률 10~16 Hz)
# 여성 F0 는 250~300 Hz 다. 그 사이의 자유도는 **손실의 영공간**에 있다 — STFT
# 프레임 하나 안에 제어 프레임이 다섯 개 들어가고 `_expect` 가 난류 빈을 25 ms 로
# 뭉개므로, 그 안쪽 요동은 손실이 밀지도 당기지도 않는다. 그래서 표류한다.
#
# 그 표류가 두 증상으로 들린다. 실측(yang_00000101):
#
#   * **마찰 구간**: 고역 포락이 목표보다 3~5.5 배 맥동한다 -> "지지직"
#   * **유성 구간**: 트랙의 150~350 Hz 성분(전력의 4~6 %)이 1 차 하모닉과 곱해져
#     차주파수 0 Hz 로 내려온다 -> 0~80 Hz 가 20.7 dB 과다
#
# 트랙 14 개를 전부 25 ms 로 뭉개면 0~80 Hz 가 −20.8 → −47.8 dB 로 27 dB 내려간다.
# **어느 한 트랙이 아니라 전부가 조금씩 보태고 비간섭적으로 합쳐진다.** 그래서
# 벌점도 파라미터를 가리지 않는다.
#
# **2 차 차분이 그 자다.** dt = 1 ms 에서 |2 sin(πf·dt)|² 가 20 Hz 대 264 Hz 를
# 전력 27,000 : 1 로 가른다. 진폭 A, 주파수 f 의 정현 요동은 |Δ²| = A·(2πf·dt)²
# 이므로 F0 = 264 Hz 에서 걸음 0.1 짜리 잔물결이 0.275/ms², 15 Hz 짜리 조음이
# 걸음 1 이어도 0.0089/ms² 다. 무릎 0.02 면 조음은 이차(싼) 영역에 남고 잔물결만
# 선형(비싼) 영역으로 올라간다. 파열음 해제 같은 급전도 2 차 차분은 **양 끝
# 두 점**에만 크게 나와 평균 기여가 무시할 만하다 (VEL_MODE="accel" 과 같은 논리).
#
# 단위는 적합기의 **걸음**(`STEP`)이다 — `u = u0 + w·scale` 이므로 `w` 는 이미
# 파라미터마다 정규화돼 있다. 그래서 하나의 무릎이 28 개 파라미터에 다 통한다.
#
# 실측으로 무릎을 확인했다 (`out/sib/w0_track.npz`, 벌점 없이 적합한 350 프레임을
# raw 로 되돌려 |Δ²w|/dt² 를 낸 것):
#
#   조음이 내야 할 값 (15 Hz · 걸음 1)     0.0089
#   **실제 적합 트랙의 중앙값**            0.4746      <- 53 배
#   95 분위                                3.3604
#
# 즉 1 ms 격자에서는 **중앙값 자체가 이미 잔물결**이다. 무릎 0.02 는 조음을 이차
# 영역(0.4 배)에, 잔물결을 선형 영역(24 배)에 놓는다. 선형 영역이 L1 이라는 것도
# 맞는 성질이다 — 곡률의 L1 은 **희소한 곡률**, 즉 "움직이고 멈추는" 조각별 선형
# 궤적을 선호한다. 조음이 실제로 그 모양이다.
#
# 그래서 **세기는 작아야 한다.** 위 트랙에서 의사후버 평균이 44.66 이므로
# RIPPLE_W = 0.01 이면 벌점이 0.45 — 그 구간 손실 1.06 과 같은 자릿수다.
RIPPLE_KNEE = 0.02
# **0.01 로 켠다** (0.3.15). §23 의 A/B 가 "판정 불가" 였던 것은 자가 틀렸기
# 때문이다 — F0 아래 대역은 유성 총에너지의 1 % 미만이라 멜 포락 손실에 안 보인다
# (§26.4). 제대로 된 자로 다시 재니 결정적이다.
#
# 실측 (yang_00000040 **전체**, 나머지 기본값 전부 켠 채 잔물결만 갈라):
#
#   | | 포락 | 정밀 | 스펙트럼 |
#   |---|---|---|---|
#   | 0 | 90.71 % | 82.48 % | 71.15 % |
#   | **0.01** | **94.06 %** | **88.06 %** | **73.95 %** |
#
# +3.4 / +5.6 점이다. 제어열 곡률도 함께 내려간다 (§26.35 의 자로 rms 148 → 88).
# 이동평균과 달리 곡률의 L1 은 "움직이고 멈추는" 조각별 선형 궤적을 선호하므로
# 치찰음의 앞공동 공명이 이동하는 것은 그대로 두고 프레임률 잔떨림만 지운다 (§32.2).
RIPPLE_W = 0.01

# **조음기의 속도 한계** [neper/ms] — 협착 면적의 **로그**가 1 ms 에 이만큼 넘게
# 못 움직인다.
#
# 왜 로그인가: 조음기가 일정 속도로 움직이면 면적은 **지수적으로** 변한다(간극이
# 좁아질수록 같은 변위가 면적을 더 크게 바꾼다). 면적 그 자체에 한계를 걸면 실제
# 제스처(3.0 → 0.08 cm²)도 걸려 버린다 — 한 번 그렇게 해 보고 알았다.
#
# 왜 필요한가 (docs/MEASUREMENTS.md §24). 마찰음이 **유성 구간 한가운데서 1 ms 만에
# 켜졌다 꺼진다.** 그 순간의 `a_c`:
#
#     s040 프레임 295:  a_c  3.864 → 4.910 → **0.732**  (2 ms 안에)
#     s101 프레임 299:  a_c  1.775 → 1.089            (그때 fric_gain 208 배)
#
# 에너지로는 −36~−44 dB 라 레벨을 오염시키지는 않지만, 1 ms 짜리 광대역 스위칭이라
# 스펙트로그램에 세로 줄로 남고 고역 대역 에너지를 흔든다(마찰을 끄면 유성 구간의
# 세로 얼룩이 1.649 → 1.365).
#
# 한계값의 근거는 **v1 의 제스처 모형이 실제로 내는 값**이다 (최소 저크, 로그 면적):
#
#   | 제스처 | 중앙 | 95 분위 | 최대 |
#   |---|---|---|---|
#   | 130 ms 지속음 (0.35→0.08) | 0.0122 | 0.0213 | 0.0215 |
#   | 40 ms CV (0.35→0.08) | 0.0385 | 0.0706 | 0.0709 |
#   | **28 ms 가장 빠른 CV (0.60→0.05)** | 0.0922 | 0.1705 | **0.1724** |
#   | 적합 트랙 s101 | 0.0004 | 0.2250 | **0.8731** |
#   | 적합 트랙 s040 | 0.0019 | 0.4284 | **1.9032** |
#
# 0.20 은 가장 빠른 제스처(0.172) 바로 위이고 이탈(0.87~1.90)보다 4~10 배 아래다.
ARTIC_VEL_KNEE: dict[str, float] = {"a_c": 0.20}
# 세기. 이 항은 **기본으로 켠다** — 위 이탈이 물리적으로 불가능한 양이다.
ARTIC_VEL_W = 1.0

PRIOR_W: dict[str, float] = {
    # **f3·f4 는 Hz 당 벌점을 f2 수준으로 맞춘 값이다** (MEASUREMENTS §52.260·263). 사전 항은 raw(로그 범위의 로짓) 거리라
    # 같은 Hz 오차라도 높은 포먼트일수록 raw 가 작다 — 예전 20·10 에서는 100 Hz 오차의 실제 벌점이 f1 의 1/24·1/55 였고,
    # F4 가 목표에서 평균 864 Hz(한 판은 1657 Hz) 날아갔다. 130·150 으로 올리니 끝까지 도는 판 씨앗 셋 **모두** 최종 포락이
    # 올랐고(+2.02 평균, 폭 4.30 -> 1.88), F4 오차가 864 -> 167 Hz 로 분석 출발점(151) 수준에 붙었다. 빗살·문지기는 중립이다.
    "f0_target": 40.0, "f1": 40.0, "f2": 40.0, "f3": 130.0, "f4": 150.0,
    # 곁가지는 분석이 못 재는 양이다. 세게 묶으면 적합기가 열지를 못한다 —
    # 남 /나/ 머머가 "이득 −24 dB 내린 모음" 으로 굳던 원인.
    "velum": 3.0, "oral_open": 3.0, "lat_mix": 1.0, "lat_bw": 2.0,
    "nasal_f": 20.0, "nasal_f2": 20.0,
    "nasal_f3": 20.0, "nasal_z": 20.0, "nasal_gain": 10.0, "nasal_damp": 10.0,
    "a_c": 10.0, "obstacle": 10.0, "front_len": 10.0, "back_leak": 5.0,
    "bw1": 2.0, "bw2": 2.0, "bw3": 2.0, "bw4": 2.0,
    # p_sub 는 세기의 물리량이다. 이득과 겹치는 방향으로 끌려가지 않게 세게 묶는다.
    "p_sub": 3.0, "adduction": 0.3, "tilt": 0.1, "aspiration": 0.1,
    "rd_offset": 0.3, "tract_gain": 0.3, "fric_gain": 0.3,
    # 지터는 하모닉 차수에 비례해 위상변조 지수가 커진다(β ∝ k). 그래서 고차 하모닉을
    # 통째로 뭉개 **고역 잡음 바닥을 혼자 결정한다** (실측: 지터 0.004 + 시머 0.03 이
    # 광대역 바닥을 33 dB 들어올렸고, 그게 7 kHz 위 +9~+20 dB 오차의 정체였다).
    # 적합 대상에서 빼 두면 다른 파라미터가 그 초과분을 메우려고 비틀린다.
    "jitter": 0.1, "shimmer": 0.1,
}
# **크기 스펙트럼의 완화 상수 η** (목표 크기의 평균 대비 비율).
#
# `|z| = √(x²+y²)` 는 z = 0 에서 미분이 정의되지 않는다 — `∂|z|/∂x = x/|z|` 가 0/0 이다.
# torch 는 그 자리에서 **NaN 기울기**를 낸다. STFT 빈은 무음 구간에서 실제로 0 에
# 임의로 가까워지므로(부동소수 언더플로 포함) 이 자리가 비유한 기울기의 원인이 된다.
#
# 실측 (out/sw/r000, yang_00000040 전체, 예전 가드): 모든 단계가 "[30] 수렴 +
# 비유한 29 회 건너뜀" 으로 끝났다 — 단계당 실제 걸음이 1 번뿐이었고 포락이
# 82.7 % 에 머물렀다 (같은 파일의 정상 적합은 93.1 %).
#
# 받개는 **크기 자체를 완화하는 것**이다: `|z|_η = √(x²+y²+η²)`. 이러면
#   * 어디서나 C^∞ 이고 기울기 상한이 1 이다 (`∂|z|_η/∂x = x/|z|_η ≤ 1`),
#   * η ≪ |z| 인 곳에서는 `|z|` 와 구별되지 않으며,
#   * 로그를 씌워도 `log(|z|_η) ≥ log η` 로 아래가 막혀 있다.
# 즉 로그 처리와 완화가 같은 상수 하나로 맞물린다.
#
# 크기는 **목표 스펙트럼의 평균 크기에 비례**시킨다 — 절대값으로 두면 녹음 레벨에
# 따라 의미가 달라진다. 1e-6 이면 목표 평균보다 120 dB 아래이고, 손실이 보는 하한
# (`DB_RANGE` = 정점 −70 dB)보다 한참 밑이라 편향이 없다.
MAG_ETA_REL = 1e-6

# **세로 얼룩(스펙트럼 플럭스) 일치 항.**
#
# 사용자 조건 1 은 "세로 얼룩 없음" 인데, **지금 손실은 그것을 원리적으로 못 본다.**
# `_expect` 가 난류 우세 빈을 시간 평활한 기대 스펙트럼으로 갈아 끼워 비교하기
# 때문이다 (그 자체는 옳다 — 난류의 실현을 맞추라고 하면 기울기가 잡음이다).
# 그래서 적합기에게 프레임 간 급변을 줄일 이유가 없었다.
#
# 실현이 아니라 **통계**를 맞춘다 (§9 와 같은 철학):
#
#     F(k) = mean_t |dB_mel(t+L, k) − dB_mel(t, k)|      (L = 4 프레임 ≈ 5.3 ms)
#
# 그리고 **최소화가 아니라 일치**다. 난류는 원래 흔들리므로 목표보다 매끈하면 그것도
# 틀린 것이다 — 짧은 창의 스펙트럼이 안 흔들리는 잡음은 잡음이 아니라 음(音)이다.
# 사용자가 말한 "이전 창을 많이 반영하면 주기적 소리가 난다" 가 바로 그 이야기다.
# 그래서 `|F_합성 − F_목표|` 를 벌한다.
#
# 시간 간격 L: 합격 판정(`scripts/acceptance.py`)이 5 ms 격자에서 재므로 같은 눈금을
# 쓴다. MEL_FFT=256 의 홉이 64 표본(1.33 ms)이라 L=4 가 5.3 ms 다.
FLUX_LAG = 4
# **2.0 로 켠다** (0.3.15). 세기를 쓸어 보니 2 가 정확한 지점이다 — 같은 구간
# (yang_00000040 0.18~0.55 s), 시드 5 벌 중앙과 범위:
#
#   | 세기 | 포락 | 얼룩 p95 비 (범위) | 목표 p99 초과 % | 기울기 r |
#   |---|---|---|---|---|
#   | 0 | 91.96 % | 1.125 (1.050~1.204) | 3.08 | 0.836 |
#   | **2** | **94.04 %** | **1.058 (1.037~1.073)** | **0.000 (5 벌 전부)** | 0.834 |
#   | 5 | 93.84 % | 1.112 (1.075~1.129) | 1.54 | **0.598** (무너진다) |
#
# 2 에서 **목표 p99 를 넘는 프레임이 한 개도 없고** p95 비가 1.06 으로 목표에 붙는다.
# 시드 간 편차도 0.154 -> 0.036 으로 줄어든다 (통계를 맞추므로 실현 의존이 준다).
# 포락은 오히려 2.1 점 오른다 — 얼룩을 만들던 잔떨림이 스펙트럼에도 손해였다는 뜻이다.
# 5 는 과하다: 고역 기울기 궤적(`tilt_r`)이 0.836 -> 0.598 로 무너진다.
#: **주기 안 구조** 항 (MEASUREMENTS §52.108~110).
#:
#: 포락 점수는 5.3 ms 창 멜의 **빠른 변조**(성문 주기 안의 맥동)가 지배한다. 실측(음절
#: 0.451~1.293 s, 목표를 목표와 비교하며 빠른 성분만 건드림):
#:
#:   깊이 ×1.0 -> 100.00 %,  ×0.8 -> 96.50 %,  ×0.0 -> 83.23 %
#:   1.33 ms 밀기 -> 67.33 %,  자리 무작위 -> 70.69 %
#:
#: 즉 빠른 성분 하나가 **17~33 점**이다. 그런데 실제 판에서 우리 빠른 성분은 깊이만
#: 맞고(+0.18~0.31 dB 넘침) 목표와의 **상관이 0.02~0.34** 뿐이다 — 자리와 모양이 거의
#: 무관하다는 뜻이다. 포락 항은 느린 포락과 빠른 구조를 한 덩어리로 보는데 에너지가
#: 느린 쪽에 몰려 있어 빠른 쪽으로 기울기가 거의 안 간다. 이 항은 빠른 성분만 떼어 문다.
#:
#: 이것이 사용자가 말한 "펄스가 짧고 강해야 하는데 부드럽게 펴져 있다" 와 **같은 결함**이다.
FASTFIT_W = 0.0
#: 이보다 느린 변조는 빼고 본다 [ms]. 12 ms 는 멜 프레임률 750 Hz 에서 ≈80 Hz 경계다.
FASTFIT_MS = 12.0
#: **에너지 가중** (0 = 멜 띠를 고르게, 1 = 목표 에너지에 비례).
#:
#: 포락 점수 `_sc` 는 선형 에너지 비라 **에너지가 있는 곳만** 본다. 실측(§52.112): 음절의
#: 멜 에너지는 0~1 k 33.7 %, 1~3 k 65.5 %, **3~6 k 0.80 %**, 6 k 위 0.00 % 다. 3 kHz 위를
#: 통째로 목표로 갈아 끼워도 +0.51 점뿐이다. 그런데 멜 띠는 로그 간격이라 **띠 수로는**
#: 고역이 절반이 넘는다 — 고르게 보면 기울기를 점수 없는 곳에 쏟는다. 1 이면 점수와 같은
#: 곳을 본다. (고역의 사실감은 `hfline`·`hfcomb`·`hfrip` 이 따로 맡는다.)
#:
#: 가중은 **차 안쪽**에 곱한다 (`soft_abs(w·Δ)`). 그래서 대역마다 무릎의 실효 폭이 달라진다 —
#: 큰 대역은 0.5/w dB 로 좁아져 사실상 L1 이고, 작은 대역은 이차 영역에 머문다. `_soft_abs` 는
#: 어디서나 매끈하므로 **꺾임은 생기지 않는다** (C² 요건은 지켜진다). 바깥에 곱하는 형태
#: (`w·soft_abs(Δ)`)와는 선형 영역에서 같고 무릎 근처에서만 다르다.
FASTFIT_ENERGY = 1.0

#: **배음 빗살 대비** 항 (MEASUREMENTS §52.115). 화자의 "지문" 을 지킨다.
#:
#: 하모닉 빈 dB − 사이 빈 dB 를 대역마다 재서 목표와 맞춘다. 실측: 지금 판은 3~4 kHz 에서
#: 목표 20.95 dB 대비 10.63 dB 로 **10 dB** 얕은데, 포락 점수는 0.13 점밖에 안 움직인다 —
#: 포락 항이 **원리적으로 못 보는** 결함이라 따로 물어야 한다.
#:
#: **이것은 공진의 폭이 아니다 — 비주기성이다** (§52.171 에서 전제를 정정했다). 통제 실험:
#: 중심 1325 Hz 의 2 극 공진기에 F0 347 Hz 주기 여기를 넣고 대역폭을 50 → 800 Hz 로 **16 배**
#: 바꿔도 빗살은 +29.52 → +30.39 dB 로 **단조성조차 없다**. 반면 HNR 40 → 10 dB 에서
#: +29.22 → +16.12, 지터 0 → 0.02 에서 +29.36 → +18.03 으로 13 dB, 11 dB 움직인다.
#:
#: 까닭은 단순하다: **엄밀히 주기적인 신호의 스펙트럼은 필터와 무관하게 선 스펙트럼**이다.
#: 필터는 하모닉의 *크기*만 바꾸고 그 사이를 채우지 못한다. 사이를 채우는 것은 잡음·지터·창 누설뿐이다.
#: 그래서 `harm-jit 0.25` 제거(= 위상 지터 제거)가 빗살을 −10.3 → −0.19 dB 로 되돌린 것이다(§52.115).
#:
#: 대역폭을 보는 자는 **하모닉 크기의 모양**(대역 안 하모닉들의 정점 − 치마)이다 — 같은 실험에서
#: B 50 → 800 Hz 에 23.05 → 8.66 dB 로 단조 감소하고 잡음·지터에는 ±0.4 dB 밖에 안 움직인다.
#: 그 자는 `scripts/diag/bwhz.py` 이고, 적합에서 그것을 무는 항은 **배음 크기**(`HARM_FMAX`) 다.
#: 이 항은 `hnr` 과 거의 같은 것을 재고 있다는 뜻이기도 하다 (`BAL_W`: hnr 0.5, comb 1.0).
COMB_W = 0.0
#: 하모닉/사이 빈으로 셈할 위상 여유 (주기의 몫). 0.18 이면 하모닉 ±18 %, 사이 ±18 %.
COMB_ON = 0.18
#: 이 아래는 안 본다 [Hz] — F0 근방은 창이 분해를 못 한다.
COMB_FMIN = 800.0
#: 대역 묶음 [Hz]
COMB_BANDS = ((800.0, 2000.0), (2000.0, 3000.0), (3000.0, 4500.0),
              (4500.0, 6500.0), (6500.0, 9000.0))

FLUX_W = 2.0               # 0 이면 항이 빠진다. `copyfit --flux 0` 으로 끈다.

# **포먼트 대역폭의 손실 법칙** — 공진의 "경계조건" 을 강제하는 항.
#
# 대역폭은 기하가 정하는 양이 아니라 **손실 기전**이 정한다: 벽 진동(저역 지배),
# 점성·열(∝√f), 방사(∝f²), 그리고 성문 손실(내전에 따라). 그래서 포먼트 주파수와
# 달리 **자유 파라미터로 두면 안 된다** — 자유롭게 두면 적합기가 극을 뭉개서
# 스펙트럼 기울기를 흉내 내는 데 쓴다.
#
# 실측 (out/fin/s040, 유성 프레임 중앙; 법칙은 `tract.default_bw` = 40 + 0.05·F):
#
#   | F [Hz] | 법칙 | 적합값 | 배수 |
#   |---|---|---|---|
#   | 647 | 72 | 160 | 2.21 |
#   | 1890 | 134 | 209 | 1.55 |
#   | 3125 | 196 | 351 | 1.79 |
#   | 4206 | 250 | **679** | **2.71** |
#
# 다른 적합에서는 `bw4` 가 2526 Hz 까지 간다 — 그건 극이 아니라 완만한 경사다.
#
# 그 결과가 사용자가 지적한 "울림이 부족하고 살짝 플랫" 이다. 포먼트 사이 골의
# 깊이를 재면 (300~5000 Hz, 유성): 목표 5.49 / 5.07 / 4.54 dB 에 대해 합성이
# 3.37 / 3.49 / 3.29 dB — **1.25~2.12 dB 얕다** (s040 / s101 / s034).
#
# **구역별로 보면 저역이 아니라 상위 포먼트다** (s040):
#
#   | 구역 [Hz] | 300~1200 | 1200~2600 | **2600~4200** | 4200~6500 | 6500~9000 |
#   |---|---|---|---|---|---|
#   | 목표 | 6.10 | 4.93 | 4.88 | 4.48 | 3.30 |
#   | 합성 | 6.34 | 5.87 | **2.69** | 3.77 | 2.82 |
#
# F1·F2 구역은 이미 목표보다 또렷하다. 그래서 **일률 배율은 틀린 처방이다** —
# 전 대역 ×0.35 로 좁히면 1200~2600 Hz 가 10.09 dB 로 목표(4.93)의 두 배가 된다.
# 주파수 의존 법칙이라야 한다.
#
# 그리고 이것은 "노이즈가 들린다" 와 같은 결함이다. 유성 구간의 조화/잡음비는
# 이미 목표와 ±1 dB 로 맞는다(전 대역). 2.6~5 kHz 는 목표조차 HNR 이 1~3 dB 인
# 반쯤 잡음인 대역이므로, 거기서 골이 안 닫히면 **울림 부족으로도 잡음으로도**
# 들린다. 하나의 원인이 두 증상을 만든다 (MEASUREMENTS §35).
#
# 세기 0 이면 항이 빠진다. `copyfit --bw-law` 로 조절한다.
#: **파형 상관의 붕괴를 문다** (사용자 요청: "연속 조건을 더 강화").
#:
#: 20 ms 창의 정규화 파형 상관 `r_t = <a·b>/√(<a²><b²>)`. 유성 구간에서 1 에 가까워야
#: 하고, **0 근처로 떨어지거나 음수가 되는 곳이 귀에 끊겨 들리는 곳**이다 (펄스열이
#: 반 주기 어긋나면 음수까지 간다).
#:
#: **이 항이 필요한 이유는 멜 오차가 그 사건을 못 보기 때문이다.** 실측
#: (`out/lad/s040`): 0.41 s 에서 상관이 −0.80 인데 그 자리의 **멜 dB 오차는 오히려
#: `out/fix` 보다 낮다.** 크기 스펙트럼은 멀쩡하고 위상만 뒤집혔다. 그래서 연속
#: 벌점을 멜 오차 위에 걸면 아무것도 안 문다 — 상관 위에 걸어야 한다.
#:
#: `softplus(knee − r)^POW` 로, **큰 붕괴가 지배하도록** 제곱한다. 평균 손실에서
#: 한 창은 1/1000 무게인데, 그 한 창이 들리는 결함의 전부다.
#: **세기 2.0 은 측정으로 정했다** (§45). 끊김이 있는 구간(0.38~0.60 s)에서:
#:
#:                        포락    정밀 | 조화÷비조화 [dB]  | 끊김<0.5  <0  최소상관
#:     목표                     —      — | 14.5   1.2  −3.4 |     0    0    1.00
#:     기준 (전부 0)        86.63  72.57 | 11.6  −0.9  −3.2 |     2    0    0.21
#:     --hnr 2 만          83.15  70.48 | 13.8   1.7  −1.4 |  **13    6  −0.25**
#:     **--corr 2 --hnr 2** 84.90 **80.85**| **14.2 1.2 −3.3**| **0    0    0.74**
#:
#: `--hnr` 단독은 비조화를 목표 쪽으로 끌어당기지만 **그 대가로 위상 잠금을 잃는다**
#: (끊김 2 → 13 창). 둘은 상보적이라 같이 켜야 한다.
CORR_W = 2.0
CORR_WIN_MS = 20.0
CORR_HOP_MS = 5.0
CORR_KNEE = 0.90           # 이 아래로 떨어진 만큼 문다
CORR_POW = 2.0             # 1 이면 선형, 2 면 큰 붕괴가 지배한다

#: **주기성(조화 대 비조화)을 목표에 일치시킨다** (사용자 요청).
#:
#: F0 지연에서의 정규화 자기상관 `r(t) = <x(t)x(t+T₀)>/√(<x²><x(t+T₀)²>)` — Praat 의
#: HNR 이 쓰는 것과 같은 양이고 텐서 연산만으로 미분 가능하다.
#:
#: **왜 이 항이 없으면 안 되는가.** 손실의 크기 항은 난류부를 *기대* 스펙트럼으로
#: 비교하므로 **하모닉과 잡음이 서로 교환 가능하다.** 실제로 고차 극을 늘렸더니
#: 적합기가 `p_sub` 를 9.82 → 4.55 로 반 토막 내고 `fric_gain` 을 6.29 → **70.53**
#: (+1022 %) 으로 올려 같은 스펙트럼을 만들었다. 총 레벨이 같으니 포락 점수는 안
#: 떨어지고 소리만 망가진다 (§44). 실측 주기성 (yang_00000040):
#:
#:     대역        목표     fix    pole     lad
#:     전대역    0.8616  0.8436  0.7698  0.8179
#:     1~4 kHz   0.3760  0.3789  0.2916  0.2707
#:
#: **최대화가 아니라 일치**다. 잡음을 다 죽이면 그것대로 틀린다 — 실제 음성의 난류는
#: 목표에도 있다. 다만 **시끄러운 쪽을 더 세게** 문다 (`HNR_ASYM`).
HNR_W = 2.0
HNR_ASYM = 3.0             # r 이 목표보다 낮을 때(더 시끄러울 때)의 가중
HNR_HP_HZ = 1000.0         # 두 번째 대역: 이 위만 보는 고역통과
#: **세 번째 대역: 1.5~3 kHz 통과** (MEASUREMENTS §52.88). 실측으로 이 대역의 주기성이 목표보다 **+0.059~+0.090**
#: 높다 — 즉 잡음이 30 % 모자라 윙윙거린다. 그런데 손실이 보던 두 대역(전대역, >1 kHz)에서는 그 차이가
#: +0.006 / +0.026 로 3~5 배 희석된다 (3~12 kHz 는 반대 방향이라 상쇄된다). 게다가 `HNR_ASYM` 은 **시끄러운 쪽**을
#: 3 배로 무는 비대칭이라, 우리의 실제 실패 방향("과하게 주기적")은 가중이 1 이다 — 합쳐서 약 10 배 과소 검출이었다.
#: 그래서 결함이 있는 자리를 손실이 직접 보게 대역을 하나 더 둔다. (0, 0) 이면 끈다.
#: **배음 크기 항의 위쪽 끝** [Hz]. 3 kHz 로 묶여 있었다 (`min(3000.0, f_max)` 하드코딩).
#: 그런데 통제 실험(§52.171)이 보인 것은: **포먼트 대역폭이 드러나는 자는 하모닉 크기의 모양뿐**이다
#: — 빗살 대비는 대역폭에 무반응(B 50->800 Hz 에서 +29.5->+30.4 dB)이고 비주기성만 본다.
#: 그래서 이 상한 위의 극은 **폭을 잡아 주는 것이 하나도 없다.** 실측(§52.171): 목표의 F3 유효
#: 대역폭 209 Hz 인데 모든 판이 308~341 Hz 로 넓고, 5.5 kHz 는 123~272 Hz 다.
#:
#: 올려도 안전하다 — `HarmonicMagnitudeLoss` 는 `amp2 > 10·variance` 로 **관측 불가 하모닉을
#: 스스로 버린다**. 기본값은 바꾸지 않는다 (먼저 A/B 로 확인한다).
HARM_FMAX = 3000.0
#: **대역폭 사전을 끄는 위쪽 끝** [Hz]. `HARM_FMAX` 와 **따로 둔다** (§52.221).
#:
#: 배음 크기 항이 덮는 대역에서는 `bw1~bw4` 의 "관측 사전"(평활 포락에서 잰 초기값 쪽으로 당기는 항)을 끈다 —
#: 그 초기값은 관측이 아니라 출발점이고, 배음 크기 항이 더 나은 관측이기 때문이다. 그런데 `--harm-fmax` 를 올리면
#: **두 가지가 한꺼번에** 바뀐다: 배음 항이 넓어지고, 사전이 꺼진다. 6.5 kHz 로 올린 판은 **1 단계부터** 대조군에
#: −5 점이었다(선폭 0.460 대 0.186) — 사전이 사라진 `bw3`·`bw4` 가 풀린 탓으로 보인다. 둘을 가르려면 여기를 3 kHz 에
#: 묶어 둔 채 `HARM_FMAX` 만 올리면 된다. 실제로 쓰는 값은 `min(배음 항의 fmax, 이 값)` 이라 낮추는 쪽으로만 작동한다.
HARM_PRIOR_FMAX = 3000.0

HNR_BP_HZ: tuple[float, float] = (1500.0, 3000.0)
#: **덧대역**. `HNR_BP_HZ` 를 하나로 박아 둔 것이 문제였다 — 그 대역의 결함은 고쳐졌는데
#: (§52.174 실측: 1.5~3 kHz 에서 `hfeq2` 가 목표와 +0.000, `p96b` 가 +0.016) 결함이 **3~4.5 kHz 로
#: 옮겨갔고**(+0.075~+0.138) 거기를 손실이 안 본다. 자리가 옮겨 다니는 것을 상수 하나로 쫓을 수는 없다.
#: 그래서 대역을 **여러 개 받는다**. `--hnr-band 3000-4500` 처럼 몇 번이든 준다. 기본은 비어 있어
#: 지금까지와 똑같이 움직인다.
HNR_BANDS: tuple[tuple[float, float], ...] = ()
#: **주기성은 신호마다 제 주기에서 잰다** (§52.532). 예전에는 합성도 **목표의 f0 지연** (정수 표본) 에서 쟀다 — 합성 음높이가 원본과 1 % (15 cents, 038
#: m21 · m23 의 중앙 오차) 만 어긋나도 지연이 1–2 표본 틀려 합성의 주기성이 낮게 잡혔다. 038 모음, 원본 대비: 목표 지연으로 m23 전대역 −0.09 · 1.5–3 kHz
#: −0.09 · 3–5 kHz −0.04, **제 지연으로** −0.03 · −0.01 · **+0.05** (5–8 kHz +0.07) — 실제로는 합성이 고역에서 **더 주기적** 인데 손실은 "더 시끄럽다" 로 보고
#: 시끄러운 쪽을 3 배로 무는 `HNR_ASYM` 으로 잡음을 깎았다 (고역 가로줄의 한 뿌리). 이제 목표 지연 ± `PER_LAG_SEARCH` (비율) 안의 정수 지연마다 **전대역** 상관을 재
#: 가장 큰 것 — 목표 · 합성 모두 같은 규칙. 탐색 폭 6 % 는 038 판들의 음높이 오차 90 % 값 (88–100 cents) 을 덮는다 (음높이 오차는 음높이 항이 문다).
PER_LAG_SEARCH = 0.06

#: **창별 손실이 악화되면 문다** (사용자 요청). 평균 손실은 국소 붕괴를 못 본다 —
#: 실측(§38.2c): 50 ms 구간별 파형 상관이 대부분 1.00 인데 한 구간만 0.88 → **−0.06**
#: 으로 뒤집힌다(펄스가 1/3 주기 미끄러짐). 그 한 구간은 평균에서 1/28 의 무게다.
#: `softplus(e_t − e_{t−L})` 로 **악화분만** 문다 — 절대 수준 항(`env_db`)이 그대로
#: 있으므로 "전부 고르게 나쁘게" 로는 회피할 수 없다.
#: 제어열을 **값**이 아니라 **움직임**으로 매개화한다.
#:
#: 왜: 지금 `w` 는 격자 위의 값이고 `_delta` 가 그것을 선형 보간한다. 마지막 단계는
#: 격자를 1 ms 로 내리므로 격자점 수 = 프레임 수가 되어 **파라미터마다 1420 개의
#: 독립 자유값**이 남는다. 연속성을 강제하는 구조가 하나도 없다. 그 결과가 실측에
#: 그대로 있다 — `nasal_damp` 는 에너지의 40 %가 150~400 Hz 에 있고(조음은 20 Hz
#: 아래다), `fric_gain` 은 마찰음 한복판에서 **1 ms 마다 제 값의 23 %씩** 튄다.
#: 시변 필터의 계수가 그 속도로 흔들리면 통과하는 잡음이 그 속도로 변조된다 —
#: 고역 포락의 150~400 Hz 변조(목표의 5~10 배)와 지글거림이 여기서 나온다.
#:
#: 무엇으로: 자유 파라미터를 **가속도**로 두고 두 번 적분해 궤적을 만든다. 그러면
#: 사용자가 요구한 세 가지 거동이 그대로 표현되고 (정지 a=v=0, 직선 a=0·v≠0,
#: 가속 a≠0), **위치와 속도의 연속성이 벌점이 아니라 구조로** 보장된다. 다음
#: 프레임이 두 양을 계승받는다는 뜻이다. 남는 불연속은 가속도뿐이고 그것은
#: `lam_smooth`(격자 위 1 차 차분 L2)가 그대로 **저크 벌점**이 된다.
#:
#: 덤: 두 번 적분은 1/f² 저역통과라, 같은 크기의 가속도가 만드는 위치 흔들림이
#: 400 Hz 에서 20 Hz 의 1/400 이다. 난동이 표현 자체로 비싸진다.
MOTION = False
#: 움직임 모드의 가장 고운 격자. 3 차 B-스플라인은 격자 간격 T 위에서 대략 1/(2T)
#: 위를 죽이므로 5 ms 는 100 Hz 가 상한이다 — 성문·포먼트의 미세구조를 담기에는
#: 거칠다 (사용자: "성대 진동, 포먼트에 대한 피팅이 너무 열악해 … 해상도를 높이거나").
#: 2 ms 로 내리면 250 Hz 까지 담기는 대신 150~400 Hz 난동이 다시 표현 가능해지므로,
#: **`MOTION_L2` 로 고운 층의 진폭을 눌러** 필요할 때만 쓰게 한다.
MOTION_MIN_GRID_MS = 2.0
#: 층별 L2 (움직임 모드). 각 층의 계수 에너지를 **해상도에 비례한 무게**로 문다 —
#: 고운 층일수록 비싸다. 그래서 거친 층이 담을 수 있는 것은 거친 층이 담고, 고운
#: 층은 그것으로 안 되는 곳에만 쓰인다 (웨이블릿 계수에 L2 를 거는 것과 같은 취지).
#:
#: 왜 필요한가: 적합 궤적이 `analyze` 의 물리 추정에서 너무 멀리 간다 — 실측
#: (`out/L6/s040`) `fric_gain` +685 %, `nasal_gain` +442 %, `bw4` +413 %, `tilt` +202 %.
#: 프레임 간 떨림(§48 이 잡았다)과는 **다른 종류의 과도한 움직임**이고, 그쪽은
#: `lam_prior`·`PRIOR_W` 가, 이쪽(층의 진폭)은 이 항이 맡는다.
MOTION_L2 = 0.0

#: **경계의 매끄러운 벽** (유사퍼텐셜). 경계가 있는 파라미터는 시그모이드로
#: 재매개화되는데, 값이 경계에 붙으면 `σ′` 가 죽어 **기울기가 사라진 채 고착**된다 —
#: 실측(`out/L12/s040`)에서 `jitter` 가 상한 0.01 에 중앙 0.00983(범위의 98 %)으로
#: 붙었고 `shimmer` 는 하한에 붙었다. §10.2 가 `obstacle` 에서 경고한 것과 같은
#: 함정이고, 이 프로젝트의 "발산" 중 지금 남아 있는 유일한 형태다.
#:
#: 처방은 내부점법의 로그 장벽과 같은 취지다 — 경계 **안쪽**에 매끄러운 반발 벽을
#: 두어 거기 닿기 전에 되밀고, 벽 바깥(=중앙부)에서는 아무 일도 하지 않는다.
#: 유사퍼텐셜이 딱딱한 중심부를 매끄러운 유효 퍼텐셜로 갈아 끼우되 바깥 척도의
#: 물리는 그대로 두는 것과 같은 구성이다. `u` 는 로짓이므로
#: |u| > BOUND_U 에서만 이차로 문다 (σ(4) = 0.982).
BOUND_W = 0.0

#: **반복마다 잡음 씨앗을 새로 뽑는다** — 손실의 기댓값(잡음 실현에 대한)을 최소화한다.
#:
#: 씨앗을 고정하면 난수열이 적합 내내 같다. 그러면 적합기는 제어열(내전·폐압·협착)과
#: 지터·시머 세기를 흔들어 **그 한 벌의 난수**를 목표의 무작위 요동에 끼워 맞출 수 있다.
#: 실측(out/L25, 제어열은 그대로 두고 씨앗만 1~3 으로 바꿔 재렌더):
#:
#:     s040  포락 0.480 → 0.513~0.562   corr 0.207 → 0.33~0.38   phase 0.571 → 0.80~0.92
#:     s101  포락 0.715 → 0.770~0.844   corr 0.084 → 0.16~0.30   phase 0.621 → 0.79~0.99
#:
#: 즉 파형 항 손실의 40~250 % 가 **실현 끼워 맞춤**이다. 그 끼워 맞춤이 물리적으로 없는
#: 흔들림이다 — 치찰음 한복판에서 내전이 20 ms 사이 0.42 → 0.07 로 떨어졌다 되오르며 마찰
#: 구동을 20 ms 간격으로 끊는다(사용자가 "치찰음이 세로로 토막" 이라 한 것, MEASUREMENTS §50).
#:
#: 씨앗을 매번 바꾸면 특정 실현에만 좋은 흔들림은 기댓값에서 상쇄되어 기울기를 못 받는다.
#: 손실이 잡음 때문에 회차마다 흔들리므로 최선 스냅샷·정체 판정은 손실의 지수이동평균
#: (`RESEED_EMA`)으로 한다. 균형 측정·이득 보정·최종 렌더는 씨앗 0 그대로다.
RESEED = False
RESEED_EMA = 0.1

#: **무성 마찰에서 성대가 떨면 문다** — 목표가 무성 마찰인 프레임에서 합성의 성문 떨림 진폭²의 평균.
#:
#: 실측(MEASUREMENTS §50.9): `L34/s040` 의 ㅊ(0.71~0.80 s) 에서 떨림 진폭이 0.28(모음 1.05),
#: 유성 마스크 100 %. 그 떨림이 배음과 성문 주기 AM 으로 마찰 위에 F0 를 실어 **치찰음을 F0 로
#: 썬다** — 성대만 멈추면 치찰음 고역 포락의 F0 대역 변조 과잉이 +9.6 → −0.5 dB 로 사라진다.
#: 손실은 이것을 못 본다: 무성 구간 목표의 저역은 밴드 바닥 아래라 떨림이 새도 오차가 없고,
#: F0 토막은 포락 오차 0.13 dB 로만 보인다(§50.2).
#:
#: 마스크는 분석 트랙의 `fricative & ~voiced` 에서 유성 프레임 ±10 ms 를 뺀 것 — 경계의 유성
#: 전이는 자유다. 기울기는 문턱 압력을 거쳐 **내전을 낮추는 쪽**으로 흐른다(벌린 성문은 문턱이
#: 높다: 내전 0.8 → 1.8, 0.3 → 4.7 cmH₂O). 폐압을 낮추는 길도 있지만 그건 마찰 유량을 줄여
#: 포락 항이 막는다. 0 이면 끈다. 균형 몫은 `BAL_W["unvoiced"]`.
UNVOICED_W = 0.0
#: 무성 벌점이 비켜 가는 유성 경계 여유 [프레임 = ms]. 10 이면 s101 에서 성대를 멈추게 한 것이 내전의
#: 시간상수(15 ms)를 타고 이웃 모음 가장자리로 번져 비마찰 끊김이 12 → 38 로 늘었다(§50.16).
UNVOICED_EDGE = 10

#: **조용한 구간의 넘침 벌점** (MEASUREMENTS §51.11). 목표가 정점 −`QUIET_DB` 아래인 10 ms 창에서, 합성 수준이
#: 목표보다 `QUIET_MARGIN_DB` 넘게 크면 그 초과 dB 의 제곱(부드러운 무릎)을 문다. 0 이면 끈다.
#:
#: 왜: 포락 SC 는 선형 크기라 정점 −50 dB 아래 구간을 사실상 보지 못하고, dB 항도 대역 바닥에 걸려 무음을 못 본다.
#: 그래서 발화 끝·시작 앞의 숨소리가 목표보다 7~9 dB 크게 남았다(`L52/s101` 끝 1351~1420 ms: 0~0.5 kHz +7.7,
#: 6~12 kHz +6.2; `L49/s040` 개시 앞 156~215 ms +7.2) — 사용자가 짚은 "발화 끝·무음의 엉뚱한 잡음띠" 다.
#: 합성이 목표보다 **작은** 쪽은 묻지 않는다(바닥 잡음은 `--floor` 가 채운다).
QUIET_W = 0.0
#: **원본에 없는 튐 벌점** (MEASUREMENTS §52.463, `scripts/diag/jumps.py` A 층과 같은 정의). 사용자: *"어떠한 것도 물리적으로 jumping 이 있으면
#: 안 돼"*. 포락 손실의 가장 짧은 창은 256 표본(5.3 ms)이라 그 안에서 에너지만 맞으면 1~3 ms 의 클릭이 공짜였다 — 적합기는 모자란 마찰·녹음 클릭을
#: 주기 하나의 보정 고역이나 한 틀 계단으로 메웠다(§52.462). 대역(`TRANS_BANDS`)마다 0.5 ms 포락 e 와 ±5 ms 평균 대비 솟음 p 를 재고, 합성이
#: 목표의 ±1.5 ms 최대보다 **수준으로 `TRANS_L0` dB, 솟음으로 `TRANS_P0` dB 를 둘 다** 넘는 몫만 문다 — 목표에도 있는 튐(파열 개방·녹음 사건)은
#: 공짜고, 모자란 쪽도 안 묻는다. 여백은 자의 문턱(ΔL 3, Δp 6)보다 낮게 두어 적합기가 문턱 앞에서 물러서게 한다.
TRANS_W = 0.0
TRANS_BANDS = ((100.0, 1500.0), (1500.0, 6000.0), (6000.0, 12000.0), (12000.0, 20000.0))
TRANS_WIN_MS, TRANS_HOP_MS, TRANS_MATCH_MS, TRANS_BASE_MS = 0.5, 0.125, 1.5, 5.0
TRANS_L0, TRANS_P0 = 1.5, 3.0
#: 단계마다 첫 `TRANS_RAMP` 회 동안 튐 벌점 무게를 0 → 1 로 올린다 (§52.463). 튐이 많은 출발점(038 W3a, 튐 42)에서 처음부터 다 걸었더니 적합기가 50 회 안에
#: 고역을 뭉개는 쪽으로 가 포락이 93.8 → 68.6 % 로 무너졌다 (튐은 12.6 → 0.1 ms). 0 이면 경사 없음.
TRANS_RAMP = 0
TRANS_FLOOR_DB = 60.0
#: 경첩 폭 [dB] `TRANS_KNEE` 와 **새는가** `TRANS_LEAK`. 새지 않는 경첩(기본)은 z>0 에서 z³/(z²+k²), 아래는 0 — 문턱 아래 기울기가
#: **정확히 0** 이면서 0 에서 C² 다(z³/k² 로 붙는다; `_soft_over` 주석의 헤시안 진단 때문에 relu 는 안 쓴다). 멀리서는 z 처럼 자라 제곱하면
#: 예전과 같은 z² 다. `TRANS_LEAK = True` 는 §52.463 ~ §52.471 판들의 softplus(폭 k) — 되살리기용.
#:
#: 줄다리기 진단(§52.472, W17a): softplus 가 문턱 아래로 **새는** 기울기가 이 항 기울기의 81 %였다. 0.44~0.48 s(ㅅ→ㅣ)는 문턱을 넘은 표본이
#: 1280 개 중 0 개인데 이 항이 협착 `a_c` 를 포락의 38 배 힘으로 닫고 있었고, 0.48~0.72 s 에서 f3/f4 를 −0.65/+0.68 로 밀었다. 잡음 구간은 합성과
#: 목표가 **다른 실현**이라 문턱 근처 봉우리가 우연히 자주 생긴다 — 한쪽 벌점이 제 문턱 앞에서부터 잡음 에너지를 누르고 있었다.
TRANS_KNEE = 1.0
TRANS_LEAK = False
#: **잦아드는 유성 꼬리의 결손 벌점** (MEASUREMENTS §52.420). `QUIET_W` 의 거울 — 목표가 정점 −45 ~ −`TAIL_FLOOR_DB` dB 인
#: **유성** 창에서 합성이 목표보다 작으면 문다. C2 1.44~1.50 s 의 꼬리(−55 ~ −66 dBFS, 정점 −9)는 다른 항들의 바닥에 걸려
#: 없애도 값이 거의 안 들어, 적합기가 목소리를 끄거나(내전 0.07) 줄여(−15 dB) 버렸다 — 귀에는 끊김이다.
TAIL_W = 0.0
TAIL_FLOOR_DB = 62.0
#: 꼬리로 보는 위 문턱 [정점 −dB]. 10 ms 창에서 C2 1.41~1.49 s 꼬리가 정점 −35 ~ −46 dB 다.
TAIL_TOP_DB = 30.0

#: **위상 항의 상한 주파수** [Hz] (MEASUREMENTS §51.15). 0 이면 전 대역. 배음 위상 분산(`glottis.HARM_PHASE_JIT`)을
#: 켜면 그 시작 주파수 위의 합성 배음 위상은 **설계상 난수**다(씨앗을 매 회차 새로 뽑으면 매번 다르다). 거기서 목표
#: 위상과의 거리를 재면 기울기가 난수가 되고, 배음 차수 k 만큼 f0 로 증폭되어 흘러 펄스 정렬을 무너뜨린다 — 3 단계에서
#: 펄스 척도가 0.3 → 0.96 으로 가고 포락이 8~10 점 떨어졌다(`L52`·`L54`·`L58`, lr 0.05 고정). 배음 위상 분산이 없던
#: `L25` 에서는 3 단계가 포락을 90.43 → 91.64 로 올렸다.
PHASE_FMAX = 0.0

#: 기식 MVF 를 적합하지 않는다(`copyfit --mvf` 가 값을 박는다). v2.1 의 모든 판에서 적합 MVF 가 하한 2 kHz 로
#: 갔다 — 목표 s040 의 MVF 는 ≈ 6 kHz 이고(§50.17) 감사의 모음 주기성은 s101 에서 1.5 kHz 위가 목표보다 잡음이
#: 많다(0.23/0.08/0.03 대 0.41/0.21/0.17). 적합기가 기식을 2~5 kHz 의 포락 채움재로 쓰고 있다.
#: Legacy API switch: freeze speaker-scope constants only. CLI locks explicitly
#: supplied names; source aperiodicity and recording calibration are separate.
#:
#: 왜: 성도 길이와 후두 구조는 한 사람의 것이지 문장의 것이 아니다. 그런데 발화마다 따로 적합하면
#: 그 자유도가 발화별 실현 오차를 빨아들인다 — 실측(`out/L86`, 같은 화자 두 문장): 고역 극 대역폭
#: `hf_log_bw` 가 **2.96**(= 대역폭 19 배) 벌어졌고, 이상와 영점 `pir_log_f` 2.30, `pir_depth` 1.87,
#: `log_mvf` 1.59 다. 해부가 문장마다 그렇게 바뀔 리 없다.
SPEAKER_LOCK = False

#: **포먼트마다의 제 구역** [Hz] (MEASUREMENTS §51.38). 이름 -> (하한, 상한).
#:
#: 왜: 사용자: *"f1, f2, f3 이 사는 주파수 중 겹치는 게 몇이나 되지? 각자의 영역을 정확히 배정하면
#: 그럴 문제도 없을 거 아니야."* 재 보니 `ParamSpec` 의 범위가 `f1`~`f8` **전부 12 kHz 까지** 열려
#: 있었다. 그래서 적합된 `f4` 가 `s040` 에서 **7321 Hz** 까지 갔다 — 목표에서 관측한 1~99 % 구간은
#: 3876~5426 Hz 다. 관측은 순서를 한 번도 안 뒤집는데(F_k > F_{k+1} 인 프레임 0.0 %) 제어는 아무
#: 데나 갈 수 있었다. 구역을 주면 그 난동이 **구조적으로** 불가능해진다.
#:
#: 값은 `scripts/speaker_profile.py --formant-bands` 가 목표 분석의 1~99 % 구간에 여유를 두어 만든다.
FORMANT_BAND: dict[str, tuple[float, float]] = {}

#: **포먼트마다의 Q 구역** (MEASUREMENTS §51.39). 이름(`f1`…) -> (Q 하한, Q 상한).
#:
#: **지금은 쓰지 않는다.** 모음 프레임에서 낸 Q 를 전 구간에 걸었더니 출발점의 26~65 % 가 구역
#: 밖이 되어 1 단계부터 6.5 점이 무너졌다(`L97`). 유성 마스크를 두거나 벌점으로 다시 만들 것.
#: 대역폭을 `f/Q` 로 가두므로 주파수가 움직여도 날카로움의 상한·하한이 유지된다.
#:
#: 왜: 사용자가 `s040` 1.138 s 에서 *"f1과 f2가 확고히 분리가 되어서 중간에 골이 있음에도 우리는
#: 하나로 거의 퉁쳐져 있다"* 고 짚었다. 재 보니 모음 프레임의 Q 중앙값이
#:
#:     F1 관측 9.7 / 적합 **4.1**    F2 관측 7.4 / 적합 10.9    F3 관측 9.1 / 적합 6.2    F4 관측 10.5 / 적합 8.4
#:
#: 로, **F1 이 2.4 배 뭉개져** 그 치마가 위의 골을 메운다. 실제로 `bw1`·`bw2` 를 반으로 줄이면
#: F1–F2 골 깊이가 6.1 → 8.8 dB 로 목표(8.0)를 넘는다. 지금은 `ParamSpec` 이 대역폭을 20~3000 Hz 로
#: 열어 두어 Q 가 1.5 까지 내려간다 — 생리적으로 그런 포먼트는 없다.
#: **코퍼스에서 채웠다** (§52.100, 60 파일 프레임별 Q = f/bw). 중앙 / 10 % / 90 % / 사분범위 반:
#:
#:     q1  4.5  1.7   9.9  2.4      q2  6.4  3.0  13.6  2.6
#:     q3  9.2  4.9  19.4  3.6      q4 11.8  6.2  25.2  4.7
#:
#: 아래 값은 그 10~90 분위에 여유(0.85 / 1.40)를 준 것이다 — 무릎이 부드러우므로 분위 밖도 금지가
#: 아니라 벌점이다. 기록에 남은 `bw4` 2526 Hz 는 `f4` 4657 Hz 에서 **Q = 1.84** 인데, 코퍼스 q4 의
#: 10 % 분위가 6.2 다 — 관측된 적이 없는 자리다. Q 는 주변분포로 못 구하므로 **프레임별**로 쟀다.
Q_BAND: dict[str, tuple[float, float]] = {
    "f1": (1.45, 13.86), "f2": (2.55, 19.04), "f3": (4.17, 27.16), "f4": (5.27, 35.28),
}
#: 상자 안쪽에서 **손대지 않는** 구간의 비율 (로그 공간, 0~1). 0.8 이면 범위의 안쪽 80 % 는 항등이다.
QB_CORE = 0.8

MVF_FROZEN = False

#: **펄스 잠금** (MEASUREMENTS §51.16). 켜면 성문 위상을 적합된 f0 의 적분이 아니라 **목표 녹음의 성문 폐쇄
#: 시각**에서 만든다: 이웃한 두 폐쇄 사이를 한 주기로 보고 위상을 0→2π 로 선형으로 잇는다(그 간격이 2~25 ms 인
#: 구간만; 나머지는 제어 f0 로 잇는다). 전역 오프셋 하나(`pulse_phi0`)만 학습해 LF 폐쇄 시점과 분석기 표시의
#: 관례 차이를 흡수한다.
#:
#: 왜: 폐쇄 시각은 잡음의 실현이 아니라 **목표에서 관측되는 결정적 정보**이고(§51.2 의 시머와 같은 부류),
#: 적합기는 이미 그것을 `pulse_loss` 로 맞추려 하고 있었다 — 다만 f0 궤적을 통해 간접으로 맞추느라 실패했다.
#: 실측: 저역(1 kHz 아래) 파형의 20 ms 창 상관이 최적 지연을 주면 0.93 인데 0 지연에서는 0.72~0.85 이고,
#: 목표 펄스의 |오프셋| 중앙값이 0.6~0.7 ms (주기의 20 %) 였다(§51.10). 5.3 ms 창으로 재는 포락 점수는 주기
#: 안의 펄스 위치에 민감하므로 이것이 남은 오차의 큰 몫이다 — 프레임별·대역별 최적 이득을 줘도 89 % 에서
#: 막혔다(§51.2 의 잠재 회복량).
#:
#: 켜면 `f0_target` 은 위상을 만들지 않으므로(배음 개수·기울기·생리 문턱에만 남는다) 적합 대상에서 뺀다 —
#: 안 그러면 관측되지 않는 자유도가 떠돈다. 펄스 항도 항등적으로 0 이라 끈다.
PULSE_LOCK = False
#: **대역별 상관(주기 동기) 손실** (MEASUREMENTS §52.83). 견학에서 가져온 것 — HiFi-GAN 의 다주기 판별자(MPD)는
#: 파형을 주기 p 로 접어 보며 위상·주기성을 직접 문다. 복사합성에서는 판별자를 학습시킬 필요가 없다: 목표가 있으니
#: **대역마다 파형 상관을 직접 재면** 된다.
#:
#: 기존 `corr_loss` 는 **전대역**이고 무릎이 고정 0.90 이라 두 가지를 못 한다 — 저역 에너지가 상관을 지배해
#: 1.5 kHz 위의 붕괴(실측 0.00~0.19, §52.79)를 보지 못하고, 0.90 을 넘은 창에는 기울기가 아예 없다.
#: 그리고 고정 문턱 자체가 틀렸다: 대역마다 **맞출 수 있는 최대**가 다르다 (목표 자신의 주기 상관이 상한이고
#: 이 화자는 <1.5k 0.97, 1.5–3k 0.40~0.55, 3–6k 0.26~0.34 다).
#:
#: 그래서 무릎을 **목표 자신의 그 창·그 대역 주기 상관 × `PCORR_CEIL_FRAC`** 로 둔다. 넘을 수 없는 값을
#: 요구하지 않으므로 잡음 구간에서 헛되이 끌지 않는다. 0 이면 끈다.
#:
#: **켜는 조건이 있다.** 상관은 시각 오차 δ 에 대해 `cos(2πfδ)` 라 **한 주기를 넘으면 진동한다** — 즉 지형이
#: 울퉁불퉁해져 옵티마이저가 헤맨다. 시험으로 확인했다: 2/8/24 표본을 밀면 손실이 0.0001 / 1.06 / **0.64** 로
#: 단조가 아니다. 안전한 범위는 그 대역 최고 주파수에서 **1/8 주기 안**이고, 3 kHz 면 0.04 ms 다.
#: 지금 잔여 지연은 0.147~0.186 ms (§52.81) 이므로 중·고역 항은 아직 **켜면 안 된다** — 먼저 `--pulse-lock
#: --pulse-refine` 으로 시각을 기제로 맞추고, 잔여 지연이 0.05 ms 아래로 내려온 뒤에 켠다.
#: 그래서 기본 무게가 저역에 치우쳐 있고(`PCORR_BAND_W`), 전체 기본값은 0 이다.
PCORR_W = 0.0
PCORR_CEIL_FRAC = 0.85       # 상한의 이 비율까지만 요구한다
PCORR_BAND_W: tuple[float, ...] = (0.5, 1.0, 1.0)   # PHASE_BANDS 와 같은 순서 — 망가진 중역에 무게를 준다
PCORR_TAPS = 257             # 대역 통과 FIR 길이 (48 kHz 에서 5.4 ms)


#: **위상 정합률** (MEASUREMENTS §52.79·§52.80) — 새 자의 첫 항목이다. 포락 점수(멜 크기의 전역 L2 비)는
#: 위상을 직접 재지 않아서, 1.5 kHz 위의 파형 상관이 0.05 인 판과 0.5 인 판을 구별하지 못한다.
#:
#: 재는 법: 대역마다 20 ms 창의 **실수 파형 상관**을 지연 0 에서 재고, 같은 창에서 **목표 자신의 한 주기 뒤**와의
#: 상관(지역 F0 로 ±10 % 훑기)을 상한으로 나눈다. 목표가 그 대역에서 비주기적이면 상한이 낮으므로, 100 % 는
#: "물리적으로 맞출 수 있는 만큼 다 맞췄다" 는 뜻이고 잡음 실현 때문에 닿을 수 없는 값이 아니다.
#: 실측 상한은 이 화자에서 <1.5k 0.97~0.98, 1.5–3k 0.40~0.55, 3–6k 0.26~0.34 다.
#:
#: **왜 주기 상관이 옳은 상한인가.** 목표 t = p + n (주기 p, 잡음 n; 세기 P, N), 모델 y = p + n′ (잡음의 *통계*는
#: 맞히되 실현 n′ 은 다르다) 이면 ⟨t,y⟩ = P 이고 |t| = |y| = √(P+N) 이라 r = P/(P+N) 이다. 목표를 한 주기 민 것과의
#: 상관도 같은 P/(P+N) 이다. 그러므로 **주기 상관이 곧 "잡음 실현을 빼고 맞출 수 있는 최대"** 다.
#: 목표 자신을 넣으면 100 % 를 넘는다 (실측 102~410 %) — 잡음 실현까지 같기 때문이고, 그것은 모델이 닿을 수
#: 없는 자리다. 그러니 이 자에서 100 % 는 "맞출 수 있는 것을 다 맞췄다" 는 뜻이지 완벽한 복제가 아니다.
PHASE_BANDS: tuple[tuple[float, float], ...] = ((0.0, 1500.0), (1500.0, 3000.0), (3000.0, 6000.0))
PHASE_WIN_MS = 20.0
PHASE_HOP_MS = 5.0
PHASE_LEVEL_PCT = 60.0       # 이 분위보다 조용한 창은 뺀다 (무음에서 상관은 뜻이 없다)


#: **잠금 위상 되먹임 보정** (MEASUREMENTS §52.80). `PULSE_LOCK` 은 목표 **복사 파형**의 폐쇄 표시에 **음원** 위상을 건다.
#: 그 둘 사이에는 성도의 군지연이 있고, 그것은 모음마다 0.2~0.4 ms 씩 달라지므로 전역 오프셋 하나(`pulse_phi0`)로는
#: 못 흡수한다. 실측: 창마다 최적 지연의 10/90 % 가 ±0.2~0.45 ms 이고, 그 지연 하나만 주면 1.5–3 kHz 상관이
#: 0.00 → 0.52 로 **주기 상한(0.40~0.55)까지** 올라간다 — 모양은 이미 맞고 시각만 틀렸다는 뜻이다.
#:
#: 그래서 단계 사이에 렌더한 소리를 목표와 견줘 **창마다 최적 지연을 재고, 그만큼 잠금 위상을 앞당긴다.**
#: 저역(`REFINE_LP_HZ` 아래)에서만 재는데, 그 대역의 상관이 0.93~0.98 로 모호하지 않기 때문이다. 값은
#: 중앙값 거르기 + 이동평균으로 다듬고 `REFINE_MAX_MS` 로 자른다 — 빠른 성분은 잡음이고, 우리가 쫓는 것은
#: 조음에 따라 느리게 움직이는 군지연이다. 0 이면 끈다.
#: **주기별 배음 보정** (MEASUREMENTS §52.268). H1~H`HCORR_K` 의 복소 진폭을 **성문 주기마다** 적합한다.
#: 왜: 남은 오차의 거의 전부가 H1~H5 에 있고(§52.267: 위상 +2.11, 크기 +2.02, H6 위는 +0.09), **부분 수정은 모두 상쇄**됐다
#: (시각만 −0.5, H1~H2 만 −1.28, 지터 끄기 −1.88). 크기와 위상을 **함께** 움직여야 이득이 난다.
#: 어떻게: 성문 유량 미분에 Σ_k [a_{c,k}·cos(2πk·φ) + b_{c,k}·sin(2πk·φ)] 를 더한다(φ = 주기 안 위치). 성도 앞이라
#: 성도 응답을 그대로 타고, 물리적으로 '주기마다 달라지는 성문 유량 성분' 이다. 0 이면 끈다.
#: **주기별 배음 보정을 저차원으로 묶는다** (MEASUREMENTS §52.362, 사용자 A/B 로 확인).
#:
#: 사용자가 절제판 일곱을 듣고 *"nohcorr_fit만 유일하게 안 들려"* 라고 했다 — 유성 구간이 갈라져
#: 들리는 것의 원인이 `hcorr` 다. 구조를 재 보면 까닭이 분명하다: `hcorr` 의 **배음 사이 상관이
#: 0.000** 이고 유효 차원이 배음 58 중 **90 %에 33~35 개**다. 한 주기 안에서 배음들이 각자 따로 논다.
#:
#: 한 성대에서 나온 소리는 모든 배음이 같은 폐압·같은 성문 주기로 **함께** 출렁인다. 청각은 그
#: 공통 변조(공통 운명, Bregman 1990)를 단서로 부분음을 한 소리로 묶는다. 배음마다 주기마다
#: 독립된 이득을 주면 그 단서가 부서져 **크기 스펙트럼은 맞는데 소리가 갈라진다.** 소리에서 잰
#: 배음 사이 상관(`scripts/diag/harmcoh.py`): 목표 0.606, `nohcorr` **0.696**(안 갈라짐),
#: `N2` 0.560, `N3` 0.543, `L12` 0.461.
#:
#: 그래서 (2, K, C) 를 자유롭게 두는 대신 **(2, K, r) × (2, r, C)** 로 인수분해한다. 배음 축의
#: 자유도가 r 로 줄어 배음들이 **r 개의 공통 모양**으로만 움직인다. 덤으로 파라미터가 K·C 에서
#: r·(K+C) 로 준다 — K=58, C=974, r=4 면 112,984 → **8,256 (93 % 감소)**. 그 수는 `hcorr` 가
#: 표본당 파라미터를 3.52 로 만든 주범이기도 했다(실시간화의 걸림돌).
#:
#: 0 이면 예전대로 전부 자유다.
HCORR_RANK = 0

HCORR_K = 0
HCORR_L2 = 1e-3            # 보정 크기의 L2 — 성도가 할 일을 이 항이 대신 하지 않게 살짝 문다
#: **높은 배음일수록 비싸게** (MEASUREMENTS §52.297). 보정이 고역에 바닥을 까는 까닭은 그것이 **싼 길**이기
#: 때문이다 — 음원을 날카롭게 하면(Rd·기울기) 저역까지 통째로 움직여 포락 손실이 크게 늘지만, 보정은 저역을
#: 건드리지 않고 고역만 채울 수 있다. 실측: 보정 에너지의 32 % 가 H47~H58(16~20 kHz)에 있고, 그것을 반으로
#: 줄이면 주기 깊이가 절반쯤 돌아온다(§52.296).
#:
#: 그래서 `HCORR_L2_KNEE` 위의 배음에 L2 가중을 선형으로 키워 **그 싼 길을 막는다**. 보정은 원래 H1~H5 의
#: 오차를 고치려고 만든 것이다(§52.267) — 거기서는 값이 그대로다.
HCORR_L2_KNEE = 0          # 이 배음 번호 위로 가중이 는다 (0 이면 균일)
HCORR_L2_SLOPE = 0.0       # 배음 하나마다 가중이 이만큼 는다
#: **보정을 폐쇄 둘레에만 놓는다** (MEASUREMENTS §52.299). 벌점은 싼 길의 *결과*를 나무랄 뿐 길을 막지
#: 못했다 — `PCYC_W` 1.0 으로도 고역 주기 깊이가 1.6~2.5 dB 에 머물렀다(원본 5.9~11.3). 그래서 **구조로**
#: 막는다: 보정 신호에 폐쇄(φ=0)를 중심으로 한 올림 코사인 창을 곱해, 주기 한가운데는 **원리적으로**
#: 건드릴 수 없게 한다. 물리적으로도 맞다 — 주기마다 달라지는 성문 유량 성분은 폐쇄 국면에 몰려 있다.
#:
#: 값은 창의 반폭(주기에 대한 비). 0.25 면 폐쇄 앞뒤 25 %%만 남고 한가운데 절반이 0 이 된다. 0 이면 끈다.
#: 너무 좁히면 보정이 원래 할 일(H1~H5 오차, §52.267)을 못 하므로 넉넉히 잡는다.
HCORR_WIN = 0.0
#: 창을 **이 배음 위에만** 씌운다 (0 이면 전부). MEASUREMENTS §52.306: 창을 전 배음에 씌우니 12~20 kHz 는
#: 원본과 맞는데(11.69/5.53 대 11.26/5.87) 7~9 kHz 가 11.94 로 **두 배 넘게 넘치고** 6~10 kHz 포락이 71 로
#: 무너졌다. 그 대역은 성도의 F5~F8 사다리가 실제 공진을 갖는 곳이라 보정이 주기 가운데에서도 할 일이 있다.
#: 배음 k 는 약 k·f0 (이 화자 345 Hz) 이므로 k=26 이 약 9 kHz 다.
HCORR_WIN_K = 0
#: **창의 중심을 성문 폐쇄(te)에 둔다** (MEASUREMENTS §52.418). 보정의 위상 좌표 φ=0 은 `pulse_phase + pulse_phi0` —
#: 엔진의 LF 위상과 같고, LF 에서 φ=0 은 **열림**이다. 폐쇄(여기가 들뜸 순간)는 te = 0.47~0.79 주기 뒤다 (Rd 0.5~2.7).
#: `HCORR_WIN` 은 φ=0 을 폐쇄로 보고 짜여 있어 **열림 둘레**에 보정을 모았다 — 실측 S3 에서 보정 몫의 4~17 kHz 가
#: 주기 접기로 0.41~0.50 에 서고(원본 고역은 0.16~0.19, 우리 LF 폐쇄 0.19) 고역이 폐쇄에 안 모였다.
#: 켜면 창의 중심과 보정 기저의 기준을 표본마다 **그 순간 Rd 의 te** 로 옮긴다: ang = 2πk(φ − te).
HCORR_WIN_TE = False
#: 유성 틀의 내전 바닥 (0 = 끔). `control()` 참조 (§52.420).
VOICED_ADD_FLOOR = 0.0

#: **방 잔향 꼬리** (MEASUREMENTS §52.428). 사용자: *"방 내부의 리버브가 조금 있는 거 같아."* 코퍼스 60 파일의 급격한 꺼짐 43 곳에서
#: 1~4 kHz 가 꺼진 뒤 감쇠를 RT60 으로 환산하면 10/25/50 % = 210/271/380 ms — 마른 목소리는 몇 ms 면 사라진다. C2 1.42~1.50 s 의
#: 꼬리(150 ms 에 40 dB, RT60 ≈ 230 ms)가 그 기울기다. `room.py` 의 추정 IR 은 초기 반사(첫 20 ms)만 잡고, 합성 잡음 꼬리는 파형 상관을
#: 낮춘다며 빠져 있었다(§23.4) — 그래서 적합기가 잔향을 **성대로** 흉내 냈다(꼬리에서 목소리를 켜고 끄는 지름길).
#:
#: 사슬 순서대로 목소리(× 이득) 뒤, 방 IR·대역 제한·바닥 앞에 둔다: y ← y + y ⊛ h, h(t) = 백색 잡음(고정 씨앗) × exp(−6.91 t / RT)
#: (t ≥ `LR_ONSET_MS`), Σh² = 10^(g/10) (잔향/직접 에너지 비). RT 와 g 두 스칼라만 적합한다 (로그 영역).
#: **머리 · 몸통 · 마이크 거리** (§52.527, `copyfit --head-fir`). 사용자: *"측정이 화자랑 딱 붙어있는 게 아니니, 물리적 거리도 고려해야 해. 화자로부터
#: 20cm 정도로 가정하자."* 관 모형의 출력은 입 · 코 유량의 시간 미분(먼 장 단극) 이었다. 실제 머리 스캔(SONICOM, 동아시아 젊은 여성) 을 2 mm 격자에 넣은
#: 상반성 계산에서 입 둘레 → 20 cm 마이크 전달 G 를 구해, h = G/(jω) 를 출력에 거는 고정 FIR (`out/_tmp/3d/head_fir.py`) — 머리의 배플 · 회절,
#: 몸통 반사. 직접 경로 지연은 뺀다 (펄스 시각 정렬 유지). 자유 변수 없음. 값은 npz 경로 (h, pre: 비인과 쪽 탭 수).
HEAD_FIR = None
LATE_REVERB = False
LR_RT0 = 0.30          # 초기 RT60 [s] (코퍼스 25~50 % 사이)
LR_G0_DB = -15.0       # 초기 잔향/직접 에너지 비 [dB]
LR_ONSET_MS = 5.0      # 꼬리 시작 (초기 반사는 room IR 몫)
#: **잔향을 녹음 상수로 고정한다** (MEASUREMENTS §52.444). 방은 녹음 사슬의 성질이라 발화마다 맞출 값이 아니다 — 0.3~0.6 s 구간 판에서는 두 값이
#: 정해지지 않아 적합기가 RT60 을 상한 2 s, 잔향/직접 −6 dB 로 올려 긴 꼬리로 빈 곳을 메웠다(CRa·K1a). 고정값은 코퍼스 측정(급격한 꺼짐 43 곳,
#: RT60 중앙 380 ms, §52.428)과 C2 전체 판 적합(C2Qa 357 ms / −11.6 dB, C2Qb 319 ms / −11.4 dB)에서.
LR_FIXED = False
LR_LEN_S = 0.8
#: **보이스 바 세기** (§52.433) — 켜면 적합기의 전역 스칼라(로그)로 벽 방사 이득을 맞춘다. 초기값은 로그 이득.
VOICE_BAR = False
VB_LOG_G0 = math.log(0.05)
#: **보이스 바 세기를 화자 상수로 고정** (MEASUREMENTS §52.447). 벽 방사의 세기는 볼·목 벽의 질량·탄성이 정한다 — 발화마다 맞출 값이 아니다.
#: 적합하게 두면 폐쇄가 없는 구간에서 입을 반쯤 닫고(1−oral_open) 200 Hz 공진을 저역 보강에 썼다(CRa +16 dB). 성대 음원이 폐쇄에서 살아 있는
#: 판(P3a, 유성 폐쇄 펄스)의 적합값 ≈ 0 dB 가 근거다.
VB_FIXED = False

#: **기관 운동 사전** (MEASUREMENTS §52.425). 사용자: *"항상 값은 확률 분포적으로 해야 하는 거 알지? 의도적으로 빠르게 할 수도
#: 있는 거잖아"* · *"해부학적으로 검증된 것들을 search 해서"*. 기관 매개변수의 `MPRIOR_LAG_MS` 차분에 스튜던트 t (자유도 `MPRIOR_NU`)
#: 의 음의 로그 가능도를 건다 — 꼬리가 두꺼워 빠른 동작을 **비싸게** 할 뿐 막지 않는다.
#:
#: 눈금 = (문헌의 가장 빠른 측정) / (t_ν 의 99 분위). 가장 빠른 동작을 분포의 99 % 자리에 둔다.
#:   adduction: 성대 외전 최대 각속도 441 °/s, 최대 성문각 51° (Dailey et al. 2005, 내시경). 가정: adduction 0~1 이 성문각 51°~0° 에
#:              선형으로 대응. → 8.6 /s → 5 ms 에 0.043 = 99 분위 → 눈금 0.043/4.54 = 0.0095.
#:   a_c (log): 혀끝의 가장 빠른 폐쇄·개방 = 탄음 ≈ 20 ms (20~50). 모음 협착 3 cm² → 접촉 0.05 cm² (log 4.1) 를 그 절반 10 ms 에.
#:              → 5 ms 에 2.05 = 99 분위 → 눈금 0.45.
#: 분석기로 잰 코퍼스 궤적은 이 둘의 움직임을 못 잰다(자 검증: 참값 상관 +0.30·+0.25) — 그래서 문헌에서 온다.
MPRIOR_W = 0.0
MPRIOR_LAG_MS = 5.0
MPRIOR_NU = 3.0
MPRIOR_SCALE = {"adduction": 0.0095, "a_c": 0.45}
MPRIOR_LOG = frozenset(("a_c",))
#: **이 화자의 코퍼스 사전** (§52.427) — 역모형(소리 → 기관 매개, 합성 참값 상관 adduction .91·a_c .67·velum .86)을 220 파일에
#: 적용해 잰 5 ms 차분의 분포. 눈금은 검증에서 잰 꼬리 과소 추정(99 분위 참/추정)으로 보정했다. 셋을 **함께**(다변량 t) 건다 —
#: 상관이 신경·기계 결합이다: 내전–협착 +0.22 (모음 개시에 입이 열리며 성대가 닫힌다), 내전–연구개 +0.07, 협착–연구개 +0.07.
MPRIOR_CORPUS = False
MPRIOR_C_NAMES = ("adduction", "a_c", "velum")
MPRIOR_C_SCALE = (0.0088, 0.038, 0.0099)
MPRIOR_C_CORR = ((1.0, 0.223, 0.072), (0.223, 1.0, 0.068), (0.072, 0.068, 1.0))
MPRIOR_C_NU = 1.5
#: **유성 틀 내전 수준의 분포 사전** (MEASUREMENTS §52.442). 운동 사전(`MPRIOR_*`)은 내전의 **변화**만 비싸게 해서, 적합기가
#: 모음까지 통째로 내전 0.12~0.14(게이트 0.10 바로 위, 숨 섞인 발성)에 폐압 17~18 cmH2O 로 옮겨 가는 것을 막지 못했다(P1a).
#: 같은 모음 스펙트럼을 보통 발성으로도 숨 섞인 발성으로도 낼 수 있는 자리에서 적합기가 기식이 많은 쪽으로 샜고, 그 성문으로는
#: 폐쇄 중 구강압이 곧바로 폐압까지 차 보이스 바가 죽는다. 수치는 이 화자 코퍼스 220 파일에 역모형(합성 참값 상관 .89)을 적용해
#: 잰 **유성 틀 내전**: 중앙 0.44, 10/90 % 0.29/0.58 (§52.426). 로짓 영역 스튜던트 t(ν 3): 중앙 logit 0.44 = −0.24, 90 % 폭
#: ±0.6 을 t_3 의 90 분위(1.638)에 둔 눈금 0.37. 두꺼운 꼬리 — creak(0.6~0.8)·숨 섞인 개시도 비쌀 뿐 막지 않는다. 무성 틀에는 안 건다.
ADD_PRIOR_W = 0.0
ADD_PRIOR_MU = -0.24
ADD_PRIOR_S = 0.37
ADD_PRIOR_NU = 3.0
#: **치찰 틀 협착 면적의 분포 사전** (MEASUREMENTS §52.446, `analyze.SIB_OBS` 가 싣는 `track.sibilant` 틀만). log(a_c) 에 스튜던트 t(ν 3):
#: 중앙 log 0.1 cm², 눈금 0.5 → 90 % 구간 ≈ 0.044~0.23 cm² (문헌 0.05~0.2, Stevens 1998). 좁히면 성문 기식은 압력 몫 a_c²/(a_c²+Ag²) 로 물리대로
#: 줄고 치찰은 협착 제트가 낸다. 꼬리가 두꺼워 넓은 협착(/ㅎ/ 같은 기식)도 비쌀 뿐 막지 않는다.
#: **폐압의 생리 사전** (MEASUREMENTS §52.487). 대화·낭독의 성문하압은 5–10 cmH2O (크게 말하면 15–20; Holmberg, Hillman & Perkell 1988,
#: Titze 1994). 말소리 틀(유성·마찰)의 log 폐압에 스튜던트 t(ν 3): 중앙 ln 7, 눈금 0.3 (t₃ 90 % ≈ 4.3–11.4 cmH2O). 이어 적합이 분석값 묶음
#: (`lam_prior`, `PRIOR_W["p_sub"]`)을 풀면 폐압이 이득과 겹치는 방향으로 17–20 cmH2O 까지 부풀어 고역을 밝히는 데 쓰였다 (WPB·WB2).
PSUB_PRIOR_W = 0.0
PSUB_PRIOR_MU = math.log(7.0)
PSUB_PRIOR_S = 0.3
PSUB_PRIOR_NU = 3.0
#: **말소리 폐압 상한 — 단단히** (§52.530, `copyfit --psub-max P`). 약한 사전을 꺼 둔 판들(KWF_m13 · n1–n3)의 유성 틀 폐압은 중앙 14.5 cmH2O,
#: 4 분의 1 이 제어 상한 15 에 붙어 있었다 — 대화 말소리는 여성 보통 ≈ 6, 크게 ≈ 9 ± 2 cmH2O (Holmberg, Hillman & Perkell 1988). 적합이 폐압으로
#: 떨림 문턱(KWF_n3: 화자 상수를 생리 범위로 자른 뒤 고음 문턱 8–15)과 고역 밝기를 메운 것이다. 켜면 제어 범위의 상한을 이 값으로 바꾸고, 출발
#: 판의 폐압 곡선은 0.95 × 상한 위만 잘라 시그모이드 끝에 붙어 기울기를 잃지 않게 한다.
PSUB_MAX = None
#: **음원 손잡이의 범위 — 단단히** (§52.536, `copyfit --src-bounds`). 사용자: *"성대 주기문제, 생리 수준을 과도한 무브먼트 문제를 명확히 해결해야 할 거야.
#: 범위 제한, 손실함수 조정을 해봐"*. `yang_00000000` 0.451–3.271 s 를 `recipes/base.argv` 로 맞춘 판(`out/fit1`)의 유성 틀에서 `voice_gain` 이
#: −17 … +20 dB, `tilt` 가 −11.8 … +11.9 dB/oct (8.7 % 가 상한 +12 에 붙음), `rd_offset` 이 ±1.5 의 양 끝까지 갔다 — 폐압 13 cmH2O(대화의 두 배)로
#: 밝힌 고역을 기울기로 다시 깎는 퇴화 쌍이다. 아래 값은 **모형의 선택**이다: `voice_gain` ±12 dB (진폭 4 배), `tilt` 는 분석 기본 +2 dB/oct 에서 ±6,
#: `rd_offset` ±1.0. 인체 측정 범위를 옮긴 것이 아니다. 켜면 그 열의 제어 범위를 바꾸고, 출발 판은 새 범위의 양 끝 2.5 % 안으로 눌러 넣는다
#: (`PSUB_MAX` 와 같은 까닭 — 시그모이드 끝에 붙으면 기울기를 잃는다).
SRC_BOUNDS: dict[str, tuple[float, float]] = {}
SRC_BOUNDS_DEFAULT = {"voice_gain": (-12.0, 12.0), "tilt": (-4.0, 8.0), "rd_offset": (-1.0, 1.0)}
SIB_PRIOR_W = 0.0
SIB_AC_MU = math.log(0.10)
SIB_AC_S = 0.5
SIB_AC_NU = 3.0
#: 치찰 구간 **양 끝 이만큼 [ms] 안에서 사전 무게를 0 → 1 로 올린다** (올림 코사인). 0 이면 예전처럼 구간 전체에 같은 무게.
#:
#: 줄다리기 진단(§52.472, 038 W17a 0.445~0.47 s): [ɕ] 끝에서 성문이 가장 벌어지며(내전 0.14) 목표가 **전 대역 10~20 dB** 세지는데, 치찰 표지가
#: 0.467 s 까지 이어져 사전이 a_c 를 0.1 cm² 로 포락의 30 배 힘으로 붙잡았다 — 협착이 안 열리니 기류를 늘릴 길이 없어 합성은 −8~−20 dB. 표지는
#: 음향(마찰이 문턱 아래로 떨어질 때)으로 끝나는데 그때는 협착이 이미 열리는 중이다. 조음 전이는 10~20 ms 걸린다.
SIB_PRIOR_EDGE_MS = 0.0
#: **파열 개방 속도의 분포 사전** (MEASUREMENTS §52.456, `voice.RELEASE_RATE`). 파열마다 속도 R [cm²/s] 하나를 적합하고, log R 에 조음 위치 셋의
#: 혼합(같은 무게) 스튜던트 t(ν 3)를 건다 — 위치를 미리 가르지 않고 소리가 고르게 한다. 중앙: Stevens (1998) 양순 100, 치조 50, 연구개 25 cm²/s.
#: 눈금 0.3: 한국어 연구개 개방 최고 속도의 변동 계수 0.16~0.28 (Song, Kim & Cho 2023, 화자·범주별 SD/평균) 에 폭(너비) 불확실을 더한 값.
#: 두꺼운 꼬리 — 의도적으로 빠르거나 느린 개방도 비쌀 뿐 막지 않는다. 초기값은 가운데(치조) 50.
RELEASE_PRIOR_W = 0.0
#: **기식 최대 유성 주파수(MVF)의 분포 사전** (MEASUREMENTS §52.458). 적합 MVF 는 늘 하한 2 kHz 쪽으로 가서(v2.1 이래, W2a 2261 Hz) 기식이 모음의
#: 2~9 kHz 배음 사이를 메웠다(§52.457: 기식을 빼면 4–6 kHz HIR +5 dB). 이 화자 코퍼스 79 파일 유성 무리에서 잰 MVF (HIR ≥ 6 dB 의 위 끝,
#: `scripts/diag/corpus_mvf.py`): log 평균 ln 4480 Hz, log 표준편차 0.43 (10/50/90 % = 2/5/6 kHz). log MVF 에 스튜던트 t(ν 3) — 고정(`--mvf`)이 아니라
#: 분포라 약한 모음이 많은 발화는 낮게, 강한 모음은 높게 갈 수 있다.
MVF_PRIOR_W = 0.0
MVF_MU = math.log(4480.0)
MVF_S = 0.43
MVF_NU = 3.0
RELEASE_MU = (math.log(100.0), math.log(50.0), math.log(25.0))
RELEASE_S = 0.3
RELEASE_NU = 3.0
RELEASE_R0 = 50.0
#: 같은 틀의 협착 면적 바닥 [cm²] (0 = 끔), 그리고 틀을 고르는 목표 주기성 문턱.
VOICED_AC_FLOOR = 0.0
VOICED_FLOOR_PER = 0.6
#: 보정을 **이 배음 아래에서는 끈다** (사용자 지적 *"배음이 분리돼서 들려. 하모닉하지 못해"*, §52.325).
#: 보정은 배음마다 **주기마다 독립인 복소 진폭**이라, 들리는 낮은 배음의 위상을 매 주기 제멋대로
#: 돌린다. 실측: 배음 위상을 k 의 2차식으로 편 잔차 흩어짐이 H1~H6 에서 목표 0.529 인데 우리는
#: 0.652 (+23 %), H6~H12 은 0.614 대 0.716. 보정을 끄면 0.409/0.518 로 **목표보다도 모여** 든다.
#: 배음이 한 성문 폐쇄에서 나온 것으로 들리려면 그 위상이 한 순간에 모여야 한다 — 그것이 융합의
#: 단서다. 0 이면 전 배음에 건다.
HCORR_KMIN = 0
#: **목표가 마찰인 주기에서는 보정의 고역을 끈다** (MEASUREMENTS §52.462). 보정은 성문 유량의 주기 간 변화인데, `121` "마신" 의 ㅅ 양 끝에서
#: 적합기가 마찰 잡음이 모자란 몫을 **떨림이 끊기기 직전 주기와 다시 시작하는 첫 주기**(성문 떨림 진폭이 남은 주기 — `voice.HCORR_GATED` 가 막지
#: 못한다)의 6~10 kHz 보정으로 메웠다. 보정은 펄스에 묶인 배음이라 그 주기 하나에 고역이 모여 2~3 ms 의 클릭이 됐다 (원본보다 +7 dB; 그 두
#: 주기만 끄면 사라지고, 이웃 주기를 끈 대조판은 그대로). 켜면 목표의 마찰 틀(`track.fricative`·`track.sibilant`)에 한 틀이라도 걸친 주기에서
#: `HCORR_FRIC_HZ` 위 배음의 보정을 **구조적으로** 0 으로 둔다 — 벌점이 아니라 표현을 없앤다. 낮은 배음(유성 몫)은 그대로다.
#: 경계는 `engine.declick.SPLIT_HZ` 와 같은 1.5 kHz.
HCORR_FRIC_GATE = False
HCORR_FRIC_HZ = 1500.0
#: **이 주파수 아래 배음은 보정을 표현하지 못한다** (MEASUREMENTS §52.473). 주기마다 그 주기의 f0 로 k·f0 < `HCORR_FMIN_HZ` 인 배음의 계수를
#: 구조적으로 0 으로 둔다 (`HCORR_KMIN` 은 배음 번호라 f0 가 180~430 Hz 로 움직이는 발화에서 경계가 1.4~3.4 kHz 로 흔들린다). 보정이 들리는
#: 배음의 위상을 주기마다 돌려 갈라짐을 냈고(§52.325·471), 벌점(`--hcorr-plock`, `--phsync 30`)으로는 막히지 않았다(§52.335·471). 물리만 판
#: W17e 가 이 대역을 이미 맞추므로(0.1~2 kHz 결손 ~0) 보정은 그 위의 남은 몫만 맡는다. 0 이면 끈다.
HCORR_FMIN_HZ = 0.0
#: **이 주파수 위 배음도 보정을 표현하지 못한다** (§52.473). 물리(W17e)를 붙잡고 보정만 적합하니 보정 크기가 H1~H40 에 거의 평평했고(음원 영역의
#: 주기마다 임펄스), 물리 음원이 약한 4~9 kHz 에서 +10~27 dB 넘쳤다(W18c). 보정이 올린 포락 12.6 점은 거의 전부 1.5 kHz 아래에서 왔다(1.5 kHz 아래를
#: 막은 W18d 는 +0.45 점) — 보정은 저역 배음의 미세 크기만 맡고 고역은 물리에 둔다. 0 이면 끈다.
HCORR_FMAX_HZ = 0.0
#: **물리를 붙잡고 보정만 적합한다** (MEASUREMENTS §52.473). 켜면 `fit()` 의 최적화 대상이 주기별 보정 계수뿐이다 — 제어열(w·d), 전역 이득,
#: 펄스 위상, 고역·잔향 상수, 파열 속도는 `--init` 판 값 그대로. 물리만 판(W17e)이 갈라짐 없이 섰으니 보정은 **남은 몫**만 맡는다; 함께 풀면 물리
#: 손잡이가 보정에 기대어 무뎌졌다(§52.471). 펄스 위상 다듬기(`PULSE_REFINE`)도 건너뛴다 — 물리의 시각이다. 균형 가중은 제어열까지 넣어 잰다(예전 판과
#: 같은 눈금).
FREEZE_CONTROLS = False
#: **보정은 주기 경계에서 이어진다** (MEASUREMENTS §52.463). 보정은 주기마다 따로인 푸리에 계수라, 주기 i 의 끝 값 Σa_k(i) 와 i+1 의 시작 값
#: Σa_k(i+1) 이 달라 **모든 성문 열림 순간에 한 표본 계단**이 섰다 (W1b 308 경계, 계단/보정 rms 중앙 0.9, 상위 10 % 2.5; LF 음원 자체는 그 자리에서
#: 연속). 사용자: *"어떠한 것도 물리적으로 jumping 이 있으면 안 돼"* — 한 주기의 끝과 다음 주기의 시작은 같은 순간이다. 켜면 계수를 주기 가운데(φ=0.5)
#: 에서는 그 주기 값, 경계에서는 이웃과 반반이 되게 선형으로 이어 붙인다(값 연속). 저장된 계수의 뜻(주기 가운데의 값)은 그대로다.
HCORR_CONT = False
#: **낮은 배음의 위상만 묶는다** (MEASUREMENTS §52.334). `HCORR_KMIN` 은 보정을 통째로 껐는데,
#: 그러면 포락을 8 점 잃는다(95.09 → 87.12) — 낮은 배음의 **크기 보정**이 점수를 지고 있기 때문이다.
#: 그런데 결함은 크기가 아니라 **위상**이다: 보정이 주기마다 독립인 복소수라 배음의 위상을 매 주기
#: 돌려 놓고, 그래서 배음이 한 성문 폐쇄에서 나온 것으로 안 들린다(§52.325).
#:
#: 그러므로 크기는 열어 두고 위상만 묶는다. 배음마다 주기에 걸친 **합성 벡터 길이**
#: R_k = |Σ_c z_k(c)| / Σ_c |z_k(c)| 를 보아 (1 이면 모든 주기가 같은 위상, 0 이면 흩어짐)
#: `1 − R_k` 를 문다. 크기와 무관하고 미분 가능하다. 0 이면 끈다.
HCORR_PLOCK = 0.0
HCORR_PLOCK_K = 12         # 이 배음 아래에만 건다 (들리는 대역)
#: **구강 과도음 이벤트의 크기를 적합한다** (MEASUREMENTS §52.307). `--click-events` 는 크기를 손으로 주는데,
#: 알맞은 값을 찾으려고 재렌더를 세 번씩 훑어야 했다. 뱅크가 `nn.Parameter` 이고 엔진이 이벤트별 이득을 받으므로
#: 적합기가 고르게 두는 것이 맞다. 로그 이득이라 음수가 못 된다. 끄면 손으로 준 크기 그대로다.
TRANSIENT_FIT = False
#: 그 이득을 **잰 값 근처로 묶는** 사전 (MEASUREMENTS §52.312). 그냥 풀어 두면 적합기가 클릭을 **끈다** —
#: 실측: 고정 크기가 솟음 +13.2 dB 인데 이득을 적합하니 **+6.7 dB** 로 내려갔다(목표 +20.6). 멜 포락 손실에
#: 클릭을 보상하는 항이 없고, 0.4 ms 어긋난 과도음은 없느니만 못하기 때문이다. 크기는 코퍼스에서 **잰** 값이므로
#: (§52.305) 자유 파라미터가 아니라 **출발점**이다 — 로그 이득의 제곱을 문다. 0 이면 끈다.
TRANSIENT_PRIOR = 0.0
#: **이전 주기와의 일관성** (사용자 지시, MEASUREMENTS §52.274). 보정은 주기마다 독립이라 한 주기에서 다음 주기로 마음대로
#: 도약할 수 있다. 그 도약이 광대역 클릭이 된다 — 실측(`ihk121`): 437~477 ms 에서 주기 간 도약이 평소의 3~4 배(5.7~9.2)로
#: 뛰고, 사용자가 **그 구간부터 지지직거린다**고 들었다. 성대 조직 상태는 한 주기 만에 통째로 바뀌지 않으므로 물리에도 맞다.
#: 주기 방향 1 차 차분의 제곱 평균을 문다. 0 이면 끈다.
HCORR_TV = 0.0
#: **이웃 배음과의 일관성** (사용자 지시의 주파수 축 판, MEASUREMENTS §52.280). 보정은 배음마다도 독립이라 이웃 배음이
#: 제멋대로 움직인다 — 그것이 **빗살**이다. 실측: K 를 12 → 26 으로 키우니 전체 포락은 97.3 → 98.7 인데 6~10 kHz 빗살
#: 초과가 +0.158(문턱 0.05 의 3 배)로 튀어 문지기가 폐기를 냈다. 성도 응답은 배음 사이에서 매끄러우므로 물리에도 맞다.
#: 배음 방향 1 차 차분의 제곱 평균을 문다. 0 이면 끈다.
HCORR_KTV = 0.0
#: **주기 안에서 뾰족할 것** (MEASUREMENTS §52.294~296). 보정이 고역의 펄스 동기를 없애는 것이 실측됐다 —
#: 같은 제어열에서 보정을 끄면 7~20 kHz 의 주기 안 출렁임이 6.0~9.8 dB(원본 5.9~11.3)인데, 켜면 1.5~2.1 dB 로
#: 주저앉는다. 멜 dB 오차가 **평평한 해를 더 좋아하기** 때문이다(뾰족한 목표의 중앙값에 맞추는 상수가 절대오차
#: 평균을 최소화한다). `HCORR_TV`·`HCORR_KTV` 는 **창 사이** 일관성일 뿐 주기 안 모양을 안 지킨다.
#:
#: 그래서 보정이 **주기 가운데(성문 폐쇄에서 먼 곳)에 놓는 에너지의 비율**을 문다. 창을 sin²(πφ) 로 잡으면
#: (폐쇄 φ=0, 1 에서 0, 한가운데서 1) 그 비율이 닫힌 꼴로 나온다:
#:
#:     ∫ sin²(πφ)·s² dφ / ∫ s² dφ = ½·[1 − Σ_{k≥2}(a_k a_{k−1} + b_k b_{k−1}) / Σ_k (a_k² + b_k²)]
#:
#: 즉 **이웃 배음 계수의 정규화된 상관**이다. 1 이면 배음들이 한 점에 모여 뾰족하고, 0 이면 제각각이라 주기에
#: 고르게 퍼진다. `HCORR_KTV` 도 같은 상관을 보상하지만 **정규화가 없어** 적합기가 높은 k 를 줄이는 쪽으로
#: 값을 싸게 치울 수 있다 — 그래서 KTV 1.0 으로도 고역이 평평했다. 이 항은 크기와 무관하므로 그 길이 막힌다.
#: 0 이면 끈다.
HCORR_GAP = 0.0
PULSE_REFINE = 0
#: 다듬기마다 위상 오프셋을 한 주기 n 등분으로 다시 훑는다 (0 이면 끈다, §52.478).
PHI0_RESCAN = 0
#: 실험 (§52.484): 위상 오프셋 훑기를 건너뛰고 이 값 [rad] 으로 고정한다 (None 이면 훑는다).
PHI0_FIXED = None
#: **음높이 맞춤** (자기 진동 성대, `voice_td.GLOTTIS = "vf"`, MEASUREMENTS §52.488). 성대의 f0 는 긴장 명령을 그대로 따르지 않는다
#: (W02 정적 변수로 명령 220 → 210 Hz, 폐압·성도 부하에 따라 더 움직인다). 합성을 돌려 주기를 재고(`voice_td.TDPath.measure_f0`),
#: 유성 틀마다 긴장 배율을 목표 f0 / 합성 f0 로 곱한다 — 이만큼 되풀이한다. 적합 시작과 단계마다 다시 맞춘다 (제어가 바뀌면 f0 가 옮겨 간다).
VF_LOCK_ITERS = 3
#: **바깥 음높이 고리와 그 배율을 버린다** (§52.530, `copyfit --no-vf-lock`). 고리의 긴장 배율 `vf_qcorr` (상한 ±28 % — 근거 없는 보조 배율) 은
#: 판마다 이어져 m13 에서 0.94–1.28 이었다. 몸체 구동에서는 음높이를 구동 박자가 정하는데도 이 배율이 틀마다 덮개 긴장을 바꿔 덮개의 고유 음높이가
#: 박자에서 벗어났고, 덮개가 박자와 맥놀이해 성문 유량 지터 3.7 % (원본 음성 0.93 %) · 출력 HNR 11.9 dB (원본 15.1) — 사용자가 들은 "변조".
#: 배율 1 이면 유량 지터 1.17 %, 출력 지터 1.28 % · 시머 5.6 % · HNR 14.7 dB (같은 제어, 재적합 없이; 잡음을 꺼도 · 감쇠비를 0.15 로 올려도 · 쉼 틈을
#: 넓혀도 3.7 % 그대로였다). 켜면 고리를 돌리지 않고, 출발 판의 배율을 복원하지 않는다.
VF_QCORR_RESET = False
#: **성문 역산 항** (§52.492, `copyfit --ga-ref 판 --ga-w W`). 운동학판(같은 관, 성문 면적을 직접 준 판 — 포락 88–91 %)의 성문 면적을 기준으로,
#: 성대판의 성문 면적을 **주기 크기 창(`GA_WIN_MS`)의 평균(열림·직류)과 RMS(떨림 폭)** 로 맞춘다 — 파형을 그대로 견주면 시각에 민감해 거친
#: 지형이 된다. 운동학판을 성문 상태의 추정기로 쓰는 것이고, 소리는 여전히 자기 진동 성대가 낸다. 유성 틀만.
GA_W = 0.0
GA_REF = None              # (n,) 48 kHz 기준 성문 면적 [cm²]
GA_WIN_MS = 5.0
#: **주기 시각 맞춤** (자기 진동 성대, §52.491, `copyfit --vf-cycle-lock N`). 포락(5.3 ms 멜 선형 크기)은 창이 한 주기와 비슷해서 **성문 펄스가
#: 창 어디에 떨어지는지**에 크게 흔들린다 — 펄스를 원본에 잠근 운동학판 86–91 %, 따로 도는 성대판 62–79 % 의 큰 몫. 원본의 주기 시각
#: (`_pp` 위상이 2πk 를 지나는 때 = 펄스 표시 + 구간 오프셋)에 합성의 닫힘(주기마다 성문 면적이 가장 가파르게 줄어드는 때 = 주된 들뜸)을 맞춘다:
#: 짝지은 어긋남 e 만큼 그 앞 주기 T 의 긴장을 T/(T − γe) 배 (주기 ∝ 1/Q). 이만큼 되풀이한다. 원본의 주기별 길이(지터)를 내는 **긴장 제어열**이다
#: — 합성 뒤에 얹는 보정이 아니라 실시간에도 입력으로 줄 수 있는 값이다.
VF_CYCLE_LOCK = 0
#: **위상 고정 고리** (§52.493, `copyfit --vf-pll`). 켜면 `VF_CYCLE_LOCK` 의 표본률 배율 대신 풀이기 안의 고리(`tube_td.PLL_GAINS`)가
#: 성문 닫힘을 목표 시각표에 맞춘다 — 배율은 적합이 다른 변수를 움직이면 낡았지만(판마다 ±20 점), 고리는 풀 때마다 지금 변수에 맞춘다.
#: `vf_cycle_lock` 은 그때 목표 시각표의 **닫힘 → 소리 들뜸 오프셋**만 (주기마다, 이웃 `VF_PLL_SMOOTH` 주기 중앙값으로) 다시 잰다.
VF_PLL = False
#: **성대 정적 배율의 해부 범위** (§52.494, `copyfit --vf-anat W`). 배율(VTL 남성 정적 변수 대비)을 적합하면 구간마다 보상 손잡이가 됐다 —
#: VKA 길이 ×0.24 (막부 0.3 cm) · 두께 ×2.75 (아래 질량 0.66 cm), VKB 두께 ×3.1 · 감쇠 ×0.26, VKC 길이 ×1.05 · 두께 ×0.8. 성인 여성:
#: 막부 길이 ~1.0 cm (Titze 1994; 남성 1.5–1.6) ↔ VTL 1.3·√Q → ×0.55–0.9; 안쪽 면 두께 ~0.25–0.35 cm ↔ 0.3 → ×0.7–1.15; 질량·강성은 조직 부피
#: (길이 × 두께 × 깊이) 를 따라 ×0.4–0.9; 감쇠비는 문헌 폭이 넓어 ×0.5–2. 범위 안은 0, 밖은 log 거리의 제곱 / 0.05².
VF_ANAT_W = 0.0
VF_ANAT = dict(len=(0.55, 0.90), thick=(0.70, 1.15), mk=(0.40, 0.90), damp=(0.5, 2.0))
#: N 줄 보–막 성대(모드 3, §52.504) 화자 상수의 생리 범위 — 길이·두께 배율(Titze 1989 여성 척도 대비), 층간 결합 배율(Serry K_c 대비; 점막 전단
#: 100–1000 Pa / 두께 0.5–1 mm 로 어림한 1e5–2e6 N/m³), 세로 조직 감쇠비(연조직 손실 계수), 갑상피열근 불룩함 이득. 사전이 없던 첫 판(BMA_p1)은
#: 이 상수들이 적합기의 같은 보폭으로 떠돌았다. 무게는 `VF_NS_ANAT_W`.
VF_NS_ANAT = dict(len=(0.8, 1.3), thick=(0.7, 1.3), kc=(1.0, 10.0), zeta=(0.05, 0.3), bulge=(0.02, 0.5), shear=(0.3, 3.0))
VF_NS_ANAT_W = 1.0
#: **음량 맞춤** 되풀이 수 (§52.504, `copyfit --vf-level-lock`). 성대 모형을 바꾸면 (모드 3) 폐압·f0 에 따른 음량이 달라 옛 폐압 제어로는 틀
#: 음량이 ±5–8 dB 어긋났다 (BMR1: "어" 구간 +5–8, 0.2 s −8) — 오차 에너지의 77 % 가 틀 수준이었다. 음높이 맞춤처럼 렌더해서 틀 음량(±10 ms)
#: 차의 **모양**(중앙을 뺀 것 — 전체 크기는 이득 몫)을 폐압 두 배당 `VF_PS_DB2` dB 로 비적합 배율에 옮긴다.
VF_LEVEL_LOCK = 0
