VF_FORCE_PITCH = False
VF_LEVEL_STEP = 0.35
VF_LEVEL_MAX = 0.9
VF_PLL_SMOOTH = 5
VF_PLL_OFF0_MS = 0.5       # 오프셋 첫 값 [ms] — 첫 잼에서 고쳐진다
VF_LOCK_EVERY = 25         # 적합 단계 안에서 이 회차마다 주기 시각을 다시 맞춘다 (0 이면 단계 사이에만)
VF_LOCK_REFRESH = 3        # 그때의 반복 수
VF_CYCLE_GAIN = 0.5
VF_CYCLE_STEP = 0.06       # 한 번에 고치는 폭 [log] — 0.7·0.1 은 넘쳐 오르내렸다 (VKB 0.43 → 1.1 → 0.3 → 0.54 ms)
