VF_STATIC_FIT = False
VF_LOCK_STEP = 0.15        # 한 번에 고치는 폭 [log] (≈ 260 cents) — 떨림이 무너진 틀이 섞여도 발산하지 않게
VF_LOCK_MAX = 0.25         # 긴장 배율의 범위 [log] (×0.78 – ×1.28). 0.5 에서는 성대가 음역을 건너뛰거나 불규칙하게 떠는 틀의 f0 를 잘못 재
