#: 넓힌 것이다. 각 열에서 σ `SRC_MOVE_MS` 가우시안 추세를 뺀 빠른 몫에 스튜던트 t(ν `SRC_MOVE_NU`, 눈금 `SRC_MOVE_SCALE`), 유성 틀 평균의 합.
