#: 상관이 모호하다는 뜻이지 그 값이 지연이라는 뜻이 아니다. 실측(`ihdmp0` 첫 보정): 보정 90 % 값 +0.50 ms 가 **전부** 450~560 ms 한 구간의
#: 끝 걸림 18 창(+0.583 ms, 상관 중앙 0.654)에서 나왔고 나머지 창은 −0.08~+0.02 ms 였다. 거르기가 그것을 110 ms 에 펴서 펄스 위상을
#: 0.5 ms 밀었고, 거의 같은 1 단계 상태에서 2.1 시작 포락이 74.95 와 69.16 으로 갈렸다.
#: **그러나 버리면 더 나쁘다** (§52.257 보론 4): 그 구간의 참 지연이 실제로 0.6 ms 를 넘어서(`ihdmprep` 는 같은 창이 안쪽 +0.2 ms),
#: 버리면 그 구간을 아예 안 고친다. `ihfix0` 2.1 끝 87.22 대 `ihab0` 89.17 (−1.95), 씨앗 셋의 2.1 시작이 모두 0.5~0.7 점 낮았다.
#: 그래서 기본은 **예전 거동(False)** 이고, 끝 걸림은 세어 찍기만 한다. True 는 `--refine-drop-edge` 로만 켠다.
