#: **주기 단위 시각 보정** (MEASUREMENTS §52.267). 기존 보정은 20 ms 창·5 ms 간격으로 재고 40 ms 이동평균으로 다듬는다 —
#: 한 주기가 2.9 ms 인데 **주기보다 성긴 자**라 주기별 어긋남을 원리적으로 못 본다. 실측(`ihfp2`): 주기별 시각 어긋남이
#: rms 0.035 ms(주기의 1.15 %)이고, 그것이 H4~H5 주기별 위상 산포의 **47~75 %** 를 설명한다.
#:
#: 켜면 목표의 성문 주기마다 배음 위상차를 k 에 대한 직선으로 맞춰(Δφ_k ≈ 2π·k·δt/T) 그 주기의 δt 를 직접 얻고,
#: 주기 중심에서 보간해 잠금 위상을 warp 한다. 평활하지 않는다 — 주기별 성분이 목적이다.
REFINE_CYCLE = False
REFINE_CYCLE_K = 10        # 시각 추정에 쓰는 배음 수 (저역이 신뢰도가 높다)
REFINE_CYCLE_MED = 3       # 이상값만 거르는 짧은 중앙값 (1 이면 끈다)
REFINE_DUMP = ""             # 진단: 비어 있지 않으면 보정마다 창별 지연·상관·끝 걸림을 <접두>_refine<k>.npz 로 떨군다 (§52.256)
#: **펄스 미끄러짐 수리** (MEASUREMENTS §52.523). 창별 보정은 25 ms 중앙값 + 40 ms 평활 + ±`REFINE_MAX_MS` 라 10–30 ms 짜리 큰 어긋남을
#: 잡음으로 지운다. 발화 전체 038 판(KWF_q1)은 유성 창의 8 % 가 원본 주기에 대해 1.5–4 ms 미끄러진 채(0 지연 저역 상관 −0.8–0.4, 옮기면 0.87–0.97)
#: 남았고, A 구간 포락이 구간 판보다 20 점 낮은 주된 몫이었다(구간 판은 0 %). 일반 보정 뒤에 12 ms 창·2.5 ms 간격으로 그 자리 주기의
#: ±반 주기 안 최적 지연을 재고, **0 지연 상관 < SLIP_C0 이면서 최적 상관 > SLIP_CB** 인 창이 이어진 구간만 그 지연으로 국소 보정한다
#: (가장자리 SLIP_TAPER_MS 경사). 렌더 → 재기 → 수리를 미끄러진 창이 줄지 않을 때까지 SLIP_ITERS 번까지. 0 이면 끈다.
REFINE_SLIP_ITERS = 0
#: **위상 보정의 변화율 상한** (§52.525). 창별 보정·미끄러짐 수리는 잠금 위상을 시간축으로 당기거나 민다 (n → n + d(n)). d 가 급하게 변하면 그 대응이 거꾸로 가고,
#: 단조로 만들려던 `maximum.accumulate` 가 위상을 평평하게 만들어 **위상이 멈췄다** — m7 의 펄스 위상에 이웃 대비 +609 % · +538 % 주기 (목소리가 ~15 ms 끊김)와
#: −93 % 주기가 27 개 (원본 Praat 2 개), 사용자: *"진폭이 굉장히 왔다갔다 해서 마치 렉 걸린 소리"*. 보정량을 표본마다 ±`PHASE_WARP_RMAX` 로 슬루 제한한다 — 대응의
#: 기울기가 1 ± r 에 머물러 위상이 멈추지 않고, 보정 때문에 주기 길이가 r 넘게 바뀌지 않는다 (자연 지터 1–3 %).
PHASE_WARP_RMAX = 0.05
#: **비틀기 양의 매끈함** [ms] (§52.532). 사용자: *"창마다 경계조건은 있지? 이전창의 끝의 파라미터가 같고, 미분 가능해야 하는 거"*. 다듬기는 20 ms 창 ·
#: 주기마다 잰 어긋남을 직선으로 이어 위상을 당겼다 — 창 중심마다 비틀기 기울기가 꺾여 구동 순간 진동수가 계단으로 뛰었다 (m21 의 ɕʰ · iː · tɕʰ ·
#: 무음에서 1 ms 에 20–180 Hz, 원본 Praat 주기가 없는 자리 30 군데). 슬루 제한 뒤 이 σ 의 가우시안으로 고른다 — 위치 · 기울기 모두 이어지고
#: (C∞), 양의 핵이라 기울기 상한 r 은 그대로 지켜진다.
PHASE_WARP_SMOOTH_MS = 3.0


_WARP_FS = 48000.0                      # 구동 위상의 표본률 (적합기가 만들 때 맞춘다)


def _warp_phase(ph: np.ndarray, d: np.ndarray, rmax: float = None) -> np.ndarray:
    """잠금 위상 ph 를 n → n + d(n) [표본] 으로 당긴다 — d 를 표본마다 ±rmax 로 슬루 제한해 대응을 단조·완만하게 (§52.525)."""
    r = PHASE_WARP_RMAX if rmax is None else rmax
    n = len(ph)
    dc = np.empty(n)
    acc = float(d[0])
    for i in range(n):
        acc += min(max(float(d[i]) - acc, -r), r)
        dc[i] = acc
    if PHASE_WARP_SMOOTH_MS > 0.0:
        from scipy.ndimage import gaussian_filter1d
        dc = gaussian_filter1d(dc, PHASE_WARP_SMOOTH_MS * 1e-3 * _WARP_FS, mode="nearest")
    src = np.clip(np.arange(n) + dc, 0.0, n - 1.0)
    return np.maximum.accumulate(np.interp(src, np.arange(n), ph))
#: **구동 박자의 정규화** (§52.530, `copyfit --pulse-regular`). 사용자: *"KWF_m13은 음색이 비슷한 반열까지는 왔는데, 변조가 낀 느낌"*.
#: 몸체 구동 성대는 펄스 위상(원본 닫힘 검출에서 만들고 판마다 다듬어 이어 온 것)을 따라 떤다. m13 의 그 위상은 주기 지터가 모음별 2.6–95 %
#: (중앙 6.3 %) 로, 원본 음성의 지터 0.93 % (Praat 국소 지터, 모음 가운데 70 %) 의 7 배였다 — 400 Hz 의 주기 2.5 ms 에서 닫힘 검출 오차 0.1 ms 가 곧
#: 4 % 다. 성대가 검출 잡음을 그대로 따라 합성 지터 2.6 % · 시머 12.9 % · HNR 11.4 dB (원본 0.93 · 7.8 · 15.1), 출력 포락의 20–80 Hz 변조가 원본보다
#: 2–8 dB 셌다 (거칠기 대역). 닫힘 시각만 Whittaker 로 고르는 것은 닫힘을 0.25 ms rms 옮겨도 지터가 2.4 % 에 머물렀다 (`_whittaker`). 그래서
#: **주기 길이는 원본의 Praat 주기점** (To PointProcess (periodic, cc), 120–600 Hz — 파형 상관으로 이은 주기라 국소 지터가 원본 그대로) 에서,
#: **정렬은 지금 위상과의 느린 차이** (마디 안 정규화 가우시안 σ `PULSE_REGULAR_ALIGN_MS`) 에서 가져온다: 새 위상 = φ_Praat + 저역(φ_지금 − φ_Praat).
#: 마디(이웃 간격 1.6–16 ms, 비 0.7–1.4, 5 주기 이상) 밖은 지금 위상, 경계는 5 ms 로 섞고 마디 끝에 남는 정수 주기는 뒤쪽 위상에 넘긴다
#: (2π 의 정수배는 성대 구동에 같다).
PULSE_REGULAR = False
PULSE_REGULAR_ALIGN_MS = 15.0
#: 닫힘 이동의 상한 [ms rms] — 닫힘 검출 잡음의 크기 (Whittaker 판, 진단용).
PULSE_REGULAR_DMAX_MS = 0.25
#: 마디 (원본 Praat 주기점) 밖 구동 진동수의 매끈함 [ms, 가우시안 σ] (§52.532) — 성대 긴장이 정하는 진동수는 1 ms 에 수십 Hz 씩 뛰지 않는다 (사람의
#: 가장 빠른 음높이 변화는 ~100 ms 에 12 반음, Xu & Sun 2002 JASA 111 — 300 Hz 에서 ~3 Hz/ms). 앞 판에서 이어 받은 위상의 꺾임 (옛 다듬기의 창
#: 이음) 도 여기서 고른다. m21 의 위상에서 1 ms 에 20 Hz 넘게 뛰는 자리: σ 1.5 ms 16 군데, 3 ms 4, 5 ms 2 (둘 다 원본 Praat 주기점 안 — 원본 자신의
#: 주기 변화). 마디 안 (원본 주기점이 있는 곳) 은 원본 주기 길이 그대로다.
PULSE_FREQ_SMOOTH_MS = 5.0


def _whittaker(t: np.ndarray, lam: float) -> np.ndarray:
    """Σ (s − t)² + λ Σ (Δ³ s)² 의 해 (띠 행렬) — 3 차 차분: 주기의 고른 변화(억양의 미끄러짐)는 벌하지 않고 주기 사이 들쭉날쭉함만."""
    from scipy.sparse import diags, identity
    from scipy.sparse.linalg import spsolve
    n = t.size
    if n < 5 or lam <= 0.0:
        return t.copy()
    D = diags([-1.0, 3.0, -3.0, 1.0], [0, 1, 2, 3], shape=(n - 3, n))
    return spsolve((identity(n) + lam * (D.T @ D)).tocsc(), t)


def phase_jitter(ph: np.ndarray, fs: float, t0: float, t1: float) -> float:
    """누적 위상의 2πk 지남 시각으로 잰 국소 지터 [%] (t0–t1 s)."""
    k = np.floor(ph / (2.0 * np.pi))
    ii = np.flatnonzero(np.diff(k) > 0) + 1
    if ii.size < 3:
        return float("nan")
    m = 2.0 * np.pi * k[ii]
    t = (ii - 1 + (m - ph[ii - 1]) / np.maximum(ph[ii] - ph[ii - 1], 1e-12)) / fs
    c = t[(t >= t0) & (t <= t1)]
    if c.size < 5:
        return float("nan")
    T = np.diff(c)
    return float(np.mean(np.abs(np.diff(T))) / T.mean() * 100.0)


def _label_runs(m: np.ndarray):
    """참인 이어진 구간마다 번호 (1 부터) — (라벨 배열, 구간 수)."""
    lab = np.zeros(m.size, np.int64)
    q = 0
    prev = False
    for i, v in enumerate(m):
        if v and not prev:
            q += 1
        if v:
            lab[i] = q
        prev = bool(v)
    return lab, q


def regularize_pulse_phase(ph: np.ndarray, target: np.ndarray, fs: float) -> tuple[np.ndarray, dict]:
    """`PULSE_REGULAR` (위 설명). ph (N,) 누적 위상 [rad], target (원본 파형) → (새 위상, 보고)."""
    import parselmouth as _pm
    from parselmouth.praat import call as _call
    from scipy.interpolate import PchipInterpolator
    from scipy.ndimage import gaussian_filter1d
    n = ph.size
    snd = _pm.Sound(np.asarray(target, np.float64), fs)
    pp = _call(snd, "To PointProcess (periodic, cc)", 120, 600)
    npt = int(_call(pp, "Get number of points"))
    P = np.array([_call(pp, "Get time from index", i + 1) for i in range(npt)]) * fs
    P = P[(P >= 0) & (P < n - 1)]
    T = np.diff(P)
    ok = (T > 0.0016 * fs) & (T < 0.016 * fs)
    segs, i = [], 0
    while i < T.size:
        if ok[i]:
            j = i
            while j + 1 < T.size and ok[j + 1] and 0.7 < T[j + 1] / T[j] < 1.4:
                j += 1
            if j - i >= 4:
                segs.append((i, j + 1))
            i = j + 1
        else:
            i += 1
    run = np.full(n, np.nan)
    shift = np.zeros(n)                                         # 마디 끝에 남은 정수 주기 (뒤쪽 위상에)
    sg = PULSE_REGULAR_ALIGN_MS * fs / 1000.0
    S = 0.0
    fast = []
    nseg = 0
    for a, b in segs:
        pts = P[a:b + 1]
        n0, n1 = int(np.ceil(pts[0])), int(np.floor(pts[-1]))
        if n1 - n0 < 8:
            continue
        nseg += 1
        shift[n0:] = S
        ref = ph[n0:n1 + 1] + S
        k0 = np.round(np.interp(pts[0], np.arange(n), ph + S) / (2.0 * np.pi))
        phP = PchipInterpolator(pts, 2.0 * np.pi * (k0 + np.arange(pts.size)))(np.arange(n0, n1 + 1))
        d = ref - phP
        dl = gaussian_filter1d(d, sg, mode="nearest")
        run[n0:n1 + 1] = phP + dl
        fast.append(d - dl)
        m = np.round((run[n1] - (ph[n1] + S)) / (2.0 * np.pi))
        S += 2.0 * np.pi * m
        shift[n1 + 1:] = S
    base = ph + shift
    w = np.isfinite(run).astype(np.float64)
    # **이어 붙이는 자리도 미분 가능하게** (§52.531). 사용자: *"창마다 경계조건은 있지? 이전창의 끝의 파라미터가 같고, 미분 가능해야 하는 거"*.
    # 위상을 5 ms 에 섞었더니 마디 안팎 위상의 분수 주기 차가 순간 진동수의 튐이 됐다 (m21 0.054 · 0.350 s 에서 1 ms 에 700–1500 Hz). 이제는
    # 순간 진동수를 섞고 (C∞ 가우시안 창, 마디 끝 진동수는 바깥으로 이어 늘린다) 적분한 뒤, 원본 정렬은 느린 보정 (σ `PULSE_REGULAR_ALIGN_MS`) 으로만 —
    # 위상 · 진동수 모두 이어진다. 정수 주기 차는 마디마다 덜어 낸다 (2π 의 정수배는 구동에 같다).
    fb = np.gradient(ph)                                                    # (base 의 2π 계단은 미분하지 않는다)
    if PULSE_FREQ_SMOOTH_MS > 0.0:
        fb = gaussian_filter1d(fb, PULSE_FREQ_SMOOTH_MS * 1e-3 * fs, mode="nearest")
    lab, nl = _label_runs(w > 0)
    fr_ = np.full(n, np.nan)
    for q in range(1, nl + 1):                                              # 마디 안에서만 미분 (바깥 NaN 과 섞지 않는다)
        iq = np.flatnonzero(lab == q)
        if iq.size >= 2:
            fr_[iq] = np.gradient(run[iq])
    fin = np.flatnonzero(np.isfinite(fr_))
    if fin.size >= 2:
        fr_ext = np.interp(np.arange(n), fin, fr_[fin])
        ws = gaussian_filter1d(w, 0.004 * fs)
        f_new = ws * fr_ext + (1.0 - ws) * fb
        f_new = np.maximum(f_new, 2.0 * np.pi * 40.0 / fs)                 # 40 Hz 아래로는 안 내려간다 (단조)
        phi = ph[0] + np.concatenate([[0.0], np.cumsum(0.5 * (f_new[1:] + f_new[:-1]))])
        e = np.zeros(n)
        for q in range(1, nl + 1):
            m_ = lab == q
            dq = run[m_] - phi[m_]
            e[m_] = dq - 2.0 * np.pi * np.round(np.median(dq) / (2.0 * np.pi))
        num = gaussian_filter1d(e * w, sg, mode="nearest")
        den = gaussian_filter1d(w, sg, mode="nearest")
        corr = num / np.maximum(den, 1e-6) * ws
        out = np.maximum.accumulate(phi + corr)
    else:
        out = base
    fr = np.concatenate(fast) / (2.0 * np.pi) if fast else np.zeros(1)
    return out, dict(n=nseg, cover=float(w.mean()), fast_rms=float(np.sqrt(np.mean(fr ** 2))), npt=int(P.size))


SLIP_C0, SLIP_CB, SLIP_GAIN = 0.4, 0.7, 0.3    # 0 지연 상관 상한, 최적 상관 하한, 최적 − 0 지연 하한
SLIP_LP_HZ = 1000.0
SLIP_WIN_MS, SLIP_HOP_MS, SLIP_TAPER_MS = 12.0, 2.5, 5.0


#: 진단용 — 2.x 단계를 이 개수만큼 돌고 멈춘다 (0 이면 끝까지). 2.1 끝의 상태를 저장해 LF·물리 적합의 오차 지도를 같은 조건에서 견준다 (§52.57).
STOP_AFTER_STAGE = 0

#: **한 파라미터만 격자 하한 아래로 푼다** (MEASUREMENTS §51.19). `copyfit --fast 이름` 이 이 집합을 채우고,
#: `MOTION_MIN_GRID_MS` 를 1 ms 로 낮춘 뒤 나머지 파라미터는 전부 2 ms 층에서 잠근다(`MOTION_SLOW`).
#:
#: 왜: 목표 모음의 **저역 수준이 60~150 Hz 로 흔들린다** — 150~500 Hz 대역 수준의 변조 RMS 가 목표 7.04 dB
#: 인데 적합은 2.23 dB 이고, 같은 모델을 씨앗만 바꾼 천장 쌍도 2.56 dB 다(분석 자체의 몫). 그 흔들림을 만드는
#: 손잡이는 **시머**(주기별 진폭)뿐이다: 시머를 0.18 로 올리면 4.87 dB 가 나온다. 그런데 시머는 확률 변수라
#: 실현이 목표와 달라 점수는 오히려 떨어진다(85.95 → 83.40). 목표의 **펄스별 진폭은 관측 가능한 결정적
#: 정보**이므로(§51.2) `voice_gain` 으로 따라가야 하는데, 그것이 2 ms 격자(`MOTION_MIN_GRID_MS`)에 막혀
#: 60~150 Hz 를 낼 수 없었다. F0 ≈ 290 Hz 면 한 주기가 3.4 ms 라 **주기별 진폭은 1 ms 격자가 있어야** 표현된다.
#: `voice_gain` 은 성문 배음에만 곱하므로(잡음 제외) 이것을 풀어도 잡음을 썰지 않는다.
MOTION_FAST: set[str] = set()

#: **정체하면 학습률을 그 자리에서 올린다** (사용자 지시, MEASUREMENTS §52.97).
#:
#: 사용자: *"항상 하는 말인데, lr을 고정하라는 게 아니라, 정 확률이 낮게 수렴하려고 하면 lr을 동적으로
#: 올리라는 뜻이야."* 낮은 값에서 개선이 멈추는 것은 **지역 최소를 의심할 자리**이고, 그때 필요한 것은
#: 그 자리에서 탈출시키는 것이다. 처음부터 큰 고정 lr 을 쓰는 것과 다르다 — 그러면 초반이 불안정해지고
#: 잘 내려가던 판까지 흔든다.
#:
#: 거동: `LR_BUMP_PATIENCE` 회 동안 의미 있는 개선이 없고, 그 시점의 **포락이 `LR_BUMP_ENV` 아래**이면
#: 옵티마이저와 스케줄러의 기준 lr 을 `LR_BUMP_FACTOR` 배로 올리고 계속 돌린다. 최대 `LR_BUMP_MAX` 번.
#: 최선 스냅샷은 그대로 유지되므로 **올려서 나빠지면 그 판은 버려지고 원래 최선이 남는다** — 손해가 없다.
#: 0 회로 두면 예전 거동이다.
#: 올린 뒤에는 **쓸 시간을 줘야 한다.** 실측(M55): 2.1 단계는 반복이 200 인데 정체가 150 회쯤 오므로
#: 인내 40 을 세고 나면 남은 반복이 10 회뿐이라 상향이 장식이 된다. 그래서 한 번 올릴 때마다
#: `LR_BUMP_EXTRA` 회를 **연장**한다 (단계 예산 밖). 최선 스냅샷이 남으므로 연장이 헛돌아도 손해는 없다.
#: 전역·제어 단계 보폭의 배율 (§52.504). 자기 진동 성대의 실제 손실에서 부호 걸음 시험 (θ − s·sign(g)) 은 VTL·모드 3 모두 s ≤ 3e-3 에서만 손실을
#: 줄이고 0.01 이상에서는 늘렸다 (VTL 제어 격자 0.01: +0.08, 0.03: +0.68) — 적합기의 보폭 0.015–0.04 는 이 거친 지형에 10 배쯤 크다.
LR_SCALE = 1.0
LR_BUMP_MAX = 3
LR_BUMP_FACTOR = 2.0
LR_BUMP_PATIENCE = 25
LR_BUMP_EXTRA = 120
#: **효과가 없으면 더 올리지 않는다.** 실측(M57 1 단계): 상향이 두 번 걸렸는데 포락이 66.02 → 66.09 로
#: 꿈쩍 안 했다 — 1 단계는 전역 스칼라 50 개뿐이라 그 값이 **구조적 한계**이지 지역 최소가 아니다.
#: 그런 자리에서 3 × 120 = 360 회를 낭비하면 안 된다. 직전 상향 뒤 포락이 이만큼도 안 올랐으면
#: 그 단계에서는 상향을 멈춘다 (단계를 아는 대신 **결과로** 판정하므로 일반적이다).
LR_BUMP_MIN_GAIN = 0.20
LR_BUMP_ENV = 90.0         # 이 포락 % 위면 올리지 않는다 (사용자의 2.1 단계 기준)
LR_BUMP_TOL = 3e-4         # 개선 판정 (상대)
#: **단계 초반 이 회차까지는 상향하지 않는다** (MEASUREMENTS §52.264). 격자를 갈아 끼우면 새 층이 0 에서 시작해 손실이 잠깐 오른다 —
#: 그 과도를 `LR_BUMP_PATIENCE` 회 정체로 읽어 **정확히 25 회째에** 상향이 걸린다(실측 18 건 중 7 건, 모두 2.3·2.4). 그 상향은
#: 포락을 3~6 점 떨어뜨렸다(`ihfc1` 2.3: 시작 89.23 -> 단계 최선 86.14). 진짜 정체는 112~296 회에 걸리므로 50 이면 둘이 갈린다.
#: 0 이면 끈다(예전 거동).
LR_BUMP_WARMUP = 0
#: 상향할 때 코사인을 남은 예산 위에 다시 짠다 (§52.256). False = 예전 거동(기준값만 두 배, 주기는 그대로 — 연장 구간에서 되오른다).
#: 예전 판(`ihncod` 등)을 **비트 단위로 재현**해 코드 차이를 가를 때만 끈다.
BUMP_RESCHED = True


#: **고역에서 자리를 지키는 포먼트에 매우 강한 벌점** (사용자 지시, MEASUREMENTS §52.106).
#:
#: 사용자: *"6000Hz 위로 포먼트가 일정하게 30ms 이상일 때 매우 강한 벌점을 매겨."*
#: 표적은 잡음 바닥이 아니라 **스펙트럼 봉우리**다 — 스펙트로그램에서 고역에 가로로 그어지는 줄은
#: 한자리에 머무는 공명이고, 실제 음성의 고역은 난류라 그런 것이 없다.
#:
#: 재는 법 (셋을 곱한다):
#:  1. **봉우리인가** — 이웃 `HFLINE_PEAK_BINS` 빈의 이동평균보다 `HFLINE_PEAK_DB` 이상 솟았는가.
#:  2. **자리를 지키는가** — 그 빈의 로그 크기가 `HFLINE_MS` 창에서 표준편차 `HFLINE_STD_DB` 아래인가.
#:  3. **소리가 있는가** — 그 프레임 대역 정점 대비 `HFLINE_FLOOR_DB` 위인가 (무음은 어디나 일정하다).
#:
#: 셋이 겹친 만큼만 문다. 세기는 **매우 강하게** 둔다 — 이미 귀와 눈으로 확인된 결함이므로 점수와
#: 맞바꿀 대상이 아니다. `BAL_FIXED` 에 넣어 GradNorm 이 가중을 건드리지 못하게 한다 (§51.26, §52.91).
HFLINE_W = 30.0
HFLINE_FMIN = 6000.0       # 이 위를 본다 [Hz]
HFLINE_MS = 30.0           # 이 길이 이상 자리를 지키면 문다
HFLINE_STD_DB = 1.5        # 창 표준편차가 이보다 작으면 "일정"
HFLINE_FLOOR_DB = 35.0     # 프레임 대역 정점 대비 이보다 조용한 빈은 뺀다
HFLINE_PEAK_DB = 3.0       # 이웃 평균보다 이만큼 솟아야 봉우리
HFLINE_PEAK_BINS = 9       # 봉우리 판정에 쓰는 이웃 폭 (512 창이면 약 844 Hz)
HFLINE_FFT = 512

#: **난류 사전 밖으로 나간 몫** (사용자 지시, MEASUREMENTS §52.332·339). 코퍼스에서 뽑은 화자의
#: 와류 사전(`profiles/yang_turb.npz`, `scripts/turbbasis.py`)에 우리 난류를 비추어, 사전이 설명하지
#: 못하는 잔차가 **목표보다 큰 만큼만** 문다(한쪽).
#:
#: 왜 크기 공간인가: 같은 자료의 90 % 를 담는 성분 수가 복소 24, **크기 11**, 로그 89 다. 위상은
#: 와류의 종류가 아니라 매번 다른 실현이고, 로그는 골짜기의 난수를 확대한다. **난류의 구조는 선형
#: 크기에 있지 dB 에 있지 않다** — 그래서 이 항만은 dB 가 아니라 크기로 잰다.
#:
#: 왜 종류를 가르나: 기식 기저로 유성이 95.5 % 설명되는데(성문 난류 하나) 마찰은 62.8 % 다(딴것).
#: 유성 프레임은 성문 사전, 무성 프레임은 마찰 사전으로 본다.
TURB_BASIS_W = 0.0
TURB_BASIS_PATH = "profiles/yang_turb.npz"
TURB_BASIS_LO, TURB_BASIS_HI = 5000.0, 20000.0
TURB_BASIS_MARGIN = 0.01   # 이만큼의 초과는 봐 준다 (실현 잡음)

#: **자마다 제 대역의 손잡이만 움직인다** (MEASUREMENTS §52.472). 6 kHz 위만 재는 항(`ROUTE_HF_TERMS`)의 기울기는
#: F1~F4 의 주파수·대역폭(`ROUTE_HF_PARAMS`)으로 **가지 않는다**.
#:
#: 줄다리기 진단(`scripts/diag/tug.py`, 038 물리만 판 W17a): 수렴점에서 f2~f4 를 미는 힘의 대부분이 이 항들이었다 —
#: 0.76~1.06 s 의 f2 에 `hfline` −2.4 · `hfenv` −1.4 · `hfcomb` −0.94 인데 포락은 −0.067(35 배), 0.48~0.72 s 의 f3/f4 에
#: `hfcomb` +1.1/−1.0 인데 포락은 +0.07/−0.02. 에너지 0.1 %인 대역의 **무늬**가 1~5 kHz 를 만드는 손잡이를 쥐고 f3 를
#: 4.9 kHz 로 밀어 f4 와 엇갈리게 했고, 그 대가로 2~4 kHz 배음이 10~17 dB 모자랐다. 포먼트 치마가 고역 수준을 바꾸는 것은
#: 물리지만, **자리는 제 대역의 에너지가 정하고** 고역의 결과는 고역 손잡이(F5~F8·고역 극영점·보조 극·잡음·음원 고역)가
#: 떠맡는 분업이다. 구현: 두 번 역전파 — 이 항들은 제어열 u 의 해당 열을 0 으로 가리는 훅을 달고, 나머지는 그대로.
ROUTE_HF = False
ROUTE_HF_TERMS = ("hfline", "hfcomb", "hfband", "hfenv", "vstripe", "cons_hf", "hfrip", "hfsep", "turb")
ROUTE_HF_PARAMS = ("f1", "f2", "f3", "f4", "bw1", "bw2", "bw3", "bw4")

#: **두 번째 패턴: 같은 무늬가 주파수축으로 되풀이되는 것** (사용자 지시, §52.106).
#:
#: 사용자: *"패턴이 총 두 개야. 시간 축을 따라 거의 움직이지 않는 경우, 같은 무늬가 특정 주파수 축으로
#: 반복되는 경우, 두 경우를 모두 고려해서 30ms 이후부터는 강한 패널티를 줘야 해."*
#:
#: 재는 법: `HFLINE_FMIN` 위 로그 스펙트럼을 주파수축으로 추세 제거한 뒤, `HFCOMB_HZ` 범위의 간격마다
#: 정규화 자기상관을 내고 그 최댓값을 취한다 — 특정 간격으로 무늬가 되풀이되면 크다. 그 값을
#: **`HFLINE_MS` 창으로 시간 평균**해서 **지속되는 것만** 센다 (짧게 스치는 것은 안 문다).
#: 6 kHz 위에는 실제 음성의 배음 구조가 거의 없으므로, 거기서 뚜렷한 빗살은 우리가 만든 것이다.
#: **6 kHz 위 주파수축 상관** 벌점 (사용자 지시: "주파수 축으로 6kHz 이후에 상관관계를
#: 조사하고, 거기에 따라 벌점을 부과해").
#:
#: 고역을 프레임마다 세로로 보고, 추세를 뺀 뒤 **주파수 지연**에 대한 정규화 자기상관을 잰다.
#: 같은 무늬가 주파수를 따라 되풀이되면 그 간격의 지연에서 상관이 솟는다.
#:
#: 실측 (`scripts/diag/fcorr.py`, 음절 0.451~1.293 s, 6 kHz 위, 큰 프레임만):
#:
#:   | 지연 | 100 Hz | 1000 Hz | 2000 Hz | 3000 Hz | 4000 Hz |
#:   |---|---|---|---|---|---|
#:   | 목표 | 0.372 | −0.024 | −0.008 | −0.037 | −0.002 |
#:   | 판 `ffap` | 0.224 | **+0.104** | +0.055 | **+0.097** | +0.036 |
#:
#: **목표는 긴 지연 상관이 없는데 우리는 1 kHz·3 kHz 간격으로 스스로를 되풀이한다.** 예전 형태는
#: 지연을 2000 Hz 까지만 보고 **최댓값을 0.30 절대 문턱**에 걸어서 (우리 값 ~0.10) 한 번도 안
#: 걸렸다. 그래서 (i) 지연 범위를 6 kHz 까지 넓히고, (ii) **목표의 프로파일을 기준**으로,
#: (iii) 최댓값이 아니라 **지연마다 넘은 만큼을 비례해서** 문다.
HFCOMB_W = 30.0
HFCOMB_HZ = (150.0, 6000.0)   # 되풀이 간격을 찾는 범위 [Hz]
HFCOMB_LAGS = 24              # 그 범위를 로그 간격으로 이만큼 표본한다
HFCOMB_MARGIN = 0.03          # 목표보다 이만큼 넘으면 문다
HFCOMB_KNEE = 0.02            # 무릎 폭 (매끈하게)
#: **가장 나쁜 지연 몇 개**를 따로 문다. 아티팩트는 특정 간격(실측 1 kHz·3 kHz)에 몰려 있는데
#: 지연 24 개의 평균만 보면 그 봉우리가 희석된다 — 실측(`ctl`): 벌점을 켜도 1 k/3 k 초과가
#: +0.110/+0.145 로 안 내려갔다(평균값은 0.0160 → 0.0061 로 내려갔는데도). 그래서 평균과
#: **상위 K 지연의 평균**을 섞는다.
HFCOMB_TOPK = 4
HFCOMB_TOPK_MIX = 0.6         # 0 = 평균만, 1 = 상위 K 만
#: **대역을 갈라서 본다** (MEASUREMENTS §52.326). `_fcorr` 는 6 kHz~나이퀴스트를 통째로 한 번에
#: 상관시키므로, 빗살이 10~16 kHz 에만 몰려 있어도 넓은 평균에 희석돼 손실이 못 본다. 문지기는
#: 대역으로 갈라 보므로 **문지기가 폐기를 내는데 손실은 0 에 가까운** 상태가 된다 — 실제로
#: `HFCOMB_W = 30` 이 켜져 있는데 10-16k Δ빗살 +0.231(문턱 0.05)로 폐기가 났다.
#: 빈 튜플이면 예전처럼 통째로 본다.
HFCOMB_BANDS: tuple[tuple[float, float], ...] = ((6000.0, 10000.0), (10000.0, 16000.0),
                                                 (16000.0, 24000.0))
HFCOMB_BAND_MIX = 0.7         # 0 = 대역 평균만, 1 = 가장 나쁜 대역만

#: **고역 대역 모양** (사용자 지시 "6 kHz 위를 자로 재고 거기 맞춰 벌점을 매겨라" 의 포락 판).
#: 6~20 kHz 는 총 에너지의 **0.1 %** 라 에너지 가중 포락 항이 원리적으로 못 본다. 실측(§52.170):
#: `hfeq2` 의 녹음 EQ 는 ±12 dB 한계의 **80 % 에서 멈춰** 있는데도 14.5~17 kHz 가 **+7.1 dB** 초과,
#: 17~20 kHz 가 −3.6 dB 결손이다 — **능력이 아니라 가중의 문제**다. 그래서 대역마다 프레임별 평균 dB 를
#: 재고, **프레임마다 로그주파수 위 1 차 기울기를 뺀 뒤** 목표의 같은 양과 견준다.
#:
#: 기울기를 빼는 까닭: 전체 이득과 기울기는 이미 포락·`tilt`·녹음 EQ 가 맞추고 있다. 여기서 또 물면
#: **이중으로 세는** 것이고, 그 방향으로 기울기가 두 배가 되어 저역을 망가뜨린다. 남기는 것은 **모양**뿐이다.
#: 목표 기준이라 자기 자신과 견주면 정확히 0 이다 (`test_hfband` 가 잡는다).
#: **고역 포락 손실** (사용자 지시의 자와 같은 것, MEASUREMENTS §52.283). `HFENV_LO` 위 멜 대역만 골라 dB 오차를 재고
#: **그 대역들 안에서만 평균**한다 — 에너지 가중이 아니므로 그 대역의 에너지가 0.004 % 여도 벌점이 제 몫을 받는다.
#:
#: 왜 기존 두 항이 안 되나: `BAND_BALANCE` 는 대역 **개수**만 균등하게 만들 뿐 대역 안 에너지 차이는 그대로 둬서
#: 8 kHz 몫이 오히려 준다(0.0039 → 0.0025 %). `HFBAND_W` 는 프레임마다 **기울기를 빼고 모양만** 보는데, 지금 고역은
#: 기울기와 절대 수준 자체가 어긋나 있어 모양만 맞추면 엉뚱한 해로 간다(8 kHz 위 포락 53 → −69, 실측 §52.282).
#: 이 항은 **사용자가 판정에 쓰는 자**(`scripts/diag/hfenv.py`)와 같은 양을 문다 — 자와 손실이 같아진다.
HFENV_W = 0.0
HFENV_LO = 8000.0          # 이 위 멜 대역만 본다 [Hz]
HFENV_KNEE = 0.5           # 이 dB 안쪽은 봐준다 (실현 잡음 수준)
#: **떨림 맞춤 항** (유성/무성 분리, §52.505, `copyfit --voicing W`). 5 ms 틀의 저역(< 1.5 kHz) 주기성을 원본과 맞춘다 — 사용자가 되풀이한
#: 기본("유성과 무성 구간이 분리가 안 된다"). 포락 항은 짧은 자음과 떨림의 유무를 거의 보지 못했다 (C 의 모음 사이 ㄱ 에서 떨림이 끊겨도,
#: B 의 ㄲ 폐쇄에 떨림이 새도 점수가 거의 안 움직였다). 균형(GradNorm)이 깎지 않게 `BAL_FIXED` 에 둔다.
VOICING_W = 0.0
#: **음높이 항** (§52.529, `copyfit --pitch-w W`). 사용자: *"항상 말하지만, 그런 정체는 대부분 손실함수의 문제 아니야? 잘 바꿔봐."* 자기 진동 성대(KWF_n1)
#: 의 긴장은 적합 제어 `f0_target` 에서 나오는데(Q = 표(f0_target) × 바깥 고리 배율), 손실에 합성음의 음높이를 재는 항이 없어 그 제어에 음높이
#: 기울기가 없었다 — 바깥 고리(`vf_pitch_lock`, 배율 ±28 % 에서 잘림)만 일하다 잘린 끝에 붙어 오차 중앙 ~100 cents 에서 멈췄다.
#: 원본 · 합성 모두 같은 측정기 (`_voicing_track` 의 저역 정규 자기상관): 원본 유성 틀(주기성 ≥ 0.6)의 주기 L_t, 합성은 L_t 의 0.8–1.25 배 창에서
#: 부드러운 최대 위치(온도 `PITCH_TEMP`) — 창을 목표 둘레로 가둬 옥타브를 잘못 잡지 않는다. (log L_s − log L_t)² 를 합성 주기성(떼어 냄)으로
#: 무게 — 떨지 않는 틀은 이 항 대신 발성 문턱 항이 맡는다.
PITCH_W = 0.0
PITCH_TEMP = 0.02
#: **발성 문턱 항** (§52.529, `copyfit --pth-w W --pth-map npz`). 자기 진동 성대는 문턱(분기) 아래에서 떨지 않고, 그때 포락 · 배음 · 주기성 항은
#: 폐압 · 내전에 거의 기울기를 주지 않는다 (떨지 않는 성대를 조금 바꿔도 소리가 그대로) — n1 이 원본 유성 틀의 절반을 무성으로 둔 채 멈춘 까닭.
#: 모형 자신에서 잰 문턱 지도 (`out/_tmp/vf/pth_sweep.py`: f0 · 내전 · 수렴 · 갑상피열근 격자, 폐압을 천천히 올려 떨림이 시작되는 폐압) 를 보간해,
#: 원본 유성 틀에서 폐압이 1.2 × 문턱을 넘게 (log 경첩 제곱). 무성 틀은 성문 벌림 명세(`--art-larynx`)가 맡는다. 성대 음원 보조 항 (허용).
PTH_W = 0.0
PTH_MAP = None
PTH_MARGIN = 1.2
VOICING_TEMP = 0.05
HFBAND_W = 0.0
HFBAND_HZ = (6000.0, 20000.0)
HFBAND_N = 8              # 로그 등간격 대역 수 (녹음 EQ 의 `HF_EQ_N` 과 같은 촘촘함)
HFBAND_KNEE = 0.5         # 이 dB 안쪽은 봐준다 — 실현 잡음(같은 궤적·다른 씨앗)이 그만큼이다
HFBAND_LIVE_DB = 35.0     # 대역 정점 대비 이보다 조용한 프레임은 뺀다

#: **코덱 대역폭 트랙** (MEASUREMENTS §52.206). 방송 코덱이 구간마다 대역폭을 **20 kHz ↔ 17.5 kHz** 로 바꾼다 — `yang_00000000`
#: 음절 구간은 처음 약 0.2 s 가 20.0~20.3 kHz, 그 뒤는 17.4~18.0 kHz 다. 엔진은 늘 19 kHz 위까지 내므로 17.5 kHz 구간에서 목표에
#: 없는 고역을 만들고, 그 경계가 모든 판의 세로줄 문지기 "최악 고정 줄 17.6~18.9 kHz" 로 남았다.
#:
#: 이것은 화자가 아니라 **녹음 사슬의 시변 성질**이라 적합하지 않고 **목표에서 분석한다**(펄스처럼). 프레임마다 12~15 kHz 평균보다
#: `CODEC_DROP_DB` 떨어진 상태가 `CODEC_RUN_BINS` 칸 이어지는 `CODEC_MIN_HZ` 위 첫 자리를 차단으로 잡고, 조용한 프레임은 이웃에서
#: 채운다. `synth()` 끝에서 씌운다 — `render()` 가 `synth()` 를 부르므로 적합 손실과 최종 wav 에 같게 든다.
#:
#: 씌우는 방법은 **선형 위상 FIR 묶음의 표본별 교차감쇠**다. 처음에는 STFT(2048·512) 마스크로 했는데 **판이 망가졌다**
#: (§52.212): 2.1 단계 끝에서 포락 −1.65/−1.84, 선폭 0.180 → 0.304, 배음 사이 2.752 → 3.547. 42.7 ms 창으로 프레임마다
#: 다른 마스크를 씌우면 겹쳐 더하기가 그 길이만큼 울려 배음 구조를 망친다. 그래서 차단이 다른 FIR 을 `CODEC_ANCHORS`
#: 마다 미리 만들어 놓고 표본마다 가장 가까운 둘을 섞는다 — 블록이 없으니 울림도 없고, 합성곱이라 기울기도 그대로 흐른다.
#: (4 차 IIR 저역통과로는 17.5 → 20 kHz 가 0.19 옥타브뿐이라 −9 dB 밖에 못 깎는다.)
#: **녹음 사슬의 고정 대역 상한** [Hz]. 0 이면 끈다 (MEASUREMENTS §52.291).
#:
#: `CODEC_TRACK` 과 다르다. 저것은 프레임마다 차단을 **추정**하므로 "이 프레임엔 고역 에너지가 없다" 를
#: "사슬이 잘랐다" 로 오인해 중앙 17.7 kHz 까지 내려갔다. 이 벽은 **발화와 무관한 상수**다 — 코퍼스 12 파일
#: 전부에서 21 kHz 가 20 kHz 보다 25~30 dB 아래이고, 20.0 → 20.2 kHz 사이 200 Hz 에서 21 dB 가 떨어진다.
#: 리샘플러/코덱의 반앨리어싱 필터다. 우리 합성에 이 벽이 없어서 위 두 멜 대역의 오차가 11.5·6.2 dB 로
#: 나머지(약 1.1 dB)의 열 배였다.
BAND_LIMIT_HZ = 0.0
#: **녹음 사슬의 저역 차단** [Hz] (MEASUREMENTS §52.401). 마이크·프리앰프는 저역을 자른다 — 원본은 60 Hz 아래가
#: −94~−100 dB 로 비어 있는데 우리는 −82 dB 였다(주로 `hcorr` 의 주기 경계 계단). 대역 상한과 같은 자리(방 뒤, 바닥 앞)에
#: **영위상** 버터워스 크기 `1/sqrt(1+(fc/f)^(2n))` 로 씌운다 — 펄스 시각을 밀지 않는다. 0 이면 끈다.
#: **기구로 지은 과도음** (MEASUREMENTS §52.402, docs/CLICKS.md). `engine/clickwave.py` 가 관 속 음원 자리에서 입술 방사까지
#: 계산한 파형 (n,) 이다. 입술에서 나온 소리이므로 **방사 뒤, 방·마이크·바닥 앞**에 더한다 — 템플릿 이벤트처럼 성도를
#: 한 번 더 지나면 안 된다. `copyfit --events-wave` 가 채운다. 적합 대상이 아니다(상수).
DIRECT_EVENTS = None
BAND_LIMIT_LO_HZ = 0.0
BAND_LIMIT_LO_ORDER = 2
BAND_LIMIT_TAPS = 513      # 선형 위상, 전이폭 약 200 Hz @48 kHz — 실측한 벽과 같은 모양
CODEC_TRACK = False
#: **실제 AAC 코덱을 적합 고리에** (MEASUREMENTS §52.523, `copyfit --codec-aac 64k`). 038 원본은 방송 코덱을 거친 녹음이다 — 코덱의 지각 양자화가
#: 고역 미세 구조를 지운다 (코덱 없는 여성 녹음 EARS 줄 0.08–0.18 → AAC 64k 0.0–0.04; 합성 q1 0.20 · 0.24 · 0.11 → 0.08 · 0.05 · 0.04, 원본
#: 0.06 · 0.09 · 0.02). `CODEC_TRACK` 은 시변 대역 차단만 흉내 내 이것을 못 한다. 합성 끝에서 ffmpeg AAC 로 부호화·복호화한 소리로 손실을 재고,
#: 기울기는 코덱을 항등으로 보고 흘린다 (y + (AAC(y) − y).detach()). 사용자: *"당장은 코덱을 넣고 진행하고, 적합이 끝나면 코덱을 제거하자"* —
#: `render()` (결과 파일)는 코덱 없이, `render_codec()` 는 코덱을 거쳐 낸다. 빈 문자열이면 끈다. 값은 비트율.
CODEC_AAC = ""
CODEC_FFMPEG = r"C:\Users\PC\AppData\Local\Microsoft\WinGet\Packages\Gyan.FFmpeg_Microsoft.Winget.Source_8wekyb3d8bbwe\ffmpeg-9.0.1-full_build\bin\ffmpeg.exe"
CODEC_NFFT = 2048          # 목표에서 차단을 **분석**할 때만 쓴다 (렌더에는 안 쓴다)
CODEC_HOP = 512
CODEC_EDGE_HZ = 150.0
CODEC_MIN_HZ = 15000.0
CODEC_DROP_DB = 30.0
CODEC_RUN_BINS = 20
CODEC_LEVEL_PCT = 40.0
CODEC_ANCHORS: tuple[float, ...] = (17400.0, 18200.0, 19200.0, 20300.0, 24000.0)   # FIR 묶음의 차단 [Hz]
CODEC_TAPS = 513           # 선형 위상 FIR 길이 (10.7 ms @48 kHz, 전이폭 약 200 Hz)

#: **주기 안 포락** (MEASUREMENTS §52.213). 포락 일치율은 3~6.5 kHz 에 목표 에너지의 0.8 % 밖에 안 주면서 오차의 26.6 % 를
#: 거기서 받는다. 그 오차는 고정 EQ 로 89~91 % 가 남는 **시간 변동**이고, 성문 펄스에 맞춰 겹쳐 보면 정체가 하나다 —
#: 우리 3~4.5 kHz 는 목표보다 빨리 죽고(실효 폭 238 → 336) 4.5~6.5 kHz 는 늦게 죽는다(273 → 239). 즉 **펄스 사이 골 깊이**가
#: 어긋나 있다. 마루 계수로는 목표 5.25 / 4.17 dB 에 우리가 6.89 / 6.38 dB 다.
#:
#: 그래서 대역마다 **주기 안 포락 곡선**을 목표와 견준다. 대역 해석 신호(FFT 로 한쪽 스펙트럼만 남긴다)의 크기를 성문
#: 펄스로 `PCYC_M` 칸에 겹쳐 평균하고, 자기 평균으로 나눠 **모양만** dB 로 본다 — 수준은 포락 항이 이미 본다.
#:
#: **한쪽으로만 문다** (§52.215). 잰 결함은 늘 한 방향이다 — 우리 골이 목표보다 깊다(마루 계수 6.89 / 6.38 대 목표
#: 5.25 / 4.17). 그러므로 **우리 곡선이 목표보다 낮은 만큼만**, 그것도 `PCYC_KNEE_DB` 를 넘는 만큼만 문다. 양쪽을 다 물면
#: 적합기가 폭 말고 음원·보조극까지 동원해 주기 안 모양을 **맞춰 버리고**(가중 0.4 에서 어긋남 0.256 dB — 폭만으로 닿는
#: 한계 2.31 보다 훨씬 아래) 포락을 −1.84 잃었다. 사용자가 경고한 "끝으로 미는" 모습이라 무릎과 한쪽 물기로 막는다.
PCYC_W = 0.0
PCYC_BANDS: tuple[tuple[float, float], ...] = ((3000.0, 4500.0), (4500.0, 6500.0))
PCYC_M = 32               # 주기를 나눌 칸
PCYC_EDGE_HZ = 250.0      # 대역 가장자리 올림 코사인 폭 — 급한 벽은 울린다
PCYC_KNEE_DB = 1.0        # 목표보다 이만큼 낮은 것까지는 봐 준다
PCYC_SOFT_DB = 0.3        # 무릎을 뭉개는 폭
PCYC_LEVEL_PCT = 40.0     # 조용한 주기는 뺀다
#: 주기의 **뒤쪽 이만큼은 안 본다.** 다음 펄스의 앞울림(대역 제한이 만드는 되번짐)은 대역폭에 따라 달라서, 여기까지 물면
#: "골이 얕다" 를 "펄스 직전이 낮다" 로 잘못 읽는다 (통제 시험에서 d 가 +7.4 dB 까지 튀었다). 실제 음절에서도 목표 곡선이
#: 주기의 약 70 % 지점부터 다시 오른다 — 골까지만 보고 멈춘다.
PCYC_TAIL_SKIP = 0.30
#: **반대쪽 — 우리 울림이 목표보다 늦게 죽는 만큼** (MEASUREMENTS §52.385~387). `PCYC_W` 는 §52.215 에서
#: *골이 목표보다 깊은* 쪽만 물게 만들었는데, 사용자가 듣는 흐릿함이 있는 4.5~6 kHz 는 **반대 방향**이다 —
#: 울림이 주기 내내 이어져 골이 **얕다**. 실측(`scripts/diag/ringdecay.py`, 합성 공진기로 눈금을 맞췄고
#: §52.213 의 독립 측정과 목표값 273 Hz 가 일치): 목표의 유효 폭 4.5-6k **273 Hz** 에 우리는 38~182 Hz 로
#: 전 판이 좁다. 손잡이 여섯(폭 하한·보정 창·보정 범위·분산·배음 지터·잡음원)을 다 시험했으나 어느 것도
#: 이 값을 못 옮겼다 — 막으면 적합기가 다른 길로 주기를 채운다. 그러므로 **손실이 그 양을 봐야** 한다.
#:
#: 두 쪽은 표본마다 배타적이다(한 칸에서 우리가 목표보다 낮거나 높거나 하나다). 그래서 대역을 가르지 않고
#: 함께 걸어도 §52.215 가 겨눈 3~4.5 kHz 쪽 동작은 바뀌지 않는다. 0 이면 끈다.
PCYC_UP_W = 0.0
PCYC_UP_KNEE_DB = 1.0     # 목표보다 이만큼 높은 것까지는 봐 준다

#: **세로 줄무늬 벌점** (사용자 지적, MEASUREMENTS §52.191~194). *"음원에 지직거리는 성분이 있어. 13~16 kHz 에 걸친
#: 아티팩트 탓일 가능성이 매우 높아."* 스펙트로그램에서 고역이 17~50 ms 간격으로 번쩍이는 세로 띠다. 대역마다 에너지
#: 궤적(`_hf_db`, 2.67 ms 간격)에서 `VSTRIPE_TREND_MS` 추세를 빼고 남은 **빠른 변동의 표준편차**를 재서, 그것이
#: **목표보다 큰 만큼만** 문다(한쪽). 실측(`scripts/diag/vstripe.py`): 목표 12-14.5 / 14.5-17 kHz 2.33 / 2.15 dB 에 비해
#: `p96b` +0.75 / +1.59, `hres5` +1.49 / +2.18 dB 다.
#:
#: 출처를 끝까지 못 찾았다 — 제어 움직임·잡음·배음 위상 난수·구조 깃발 10 개·앨리어싱·펄스 불규칙·여분 고역 극 폭이 모두
#: 기각됐다(12~14.5 kHz 만 `aux*`·`azr*` 로 확인). 그래서 **결함을 맞는 축에서 재고 거기에 벌점을 건다** — 적합기가 가진
#: 어떤 손잡이로든 줄이게 한다. 대역은 에너지가 거의 없어 포락이 못 보는 곳이라 균형 밖(`BAL_FIXED`)에 둔다.
VSTRIPE_W = 0.0
VSTRIPE_BANDS: tuple[tuple[float, float], ...] = (
    (9000.0, 12000.0), (12000.0, 14500.0), (14500.0, 17000.0), (17000.0, 20000.0))
VSTRIPE_TREND_MS = 60.0
VSTRIPE_KNEE_DB = 0.1

#: **협화 적분** 항 (사용자 제안, MEASUREMENTS §52.183). *"각 구간 주기의 절반만큼 음원을 적분한 값이 최소가
#: 되도록 했을 때 가장 협화적이다. 다 넣으라는 게 아니고 아주 약간의 기여만 섭동처럼 가해 보자."*
#:
#: 주기 j (길이 T_j) 안의 모든 시작점 τ 에서 I(τ) = ∫_τ^{τ+T_j/2} x dt 를 재고
#:
#:     Q_j = E_τ[I²] / ((T_j/2)² · E_j[x²])        (무차원; DC 1, 백색잡음 2/(T·fs), k 차 배음 (2/πk)² 홀수 · 0 짝수)
#:
#: 을 dB 로 둔다. 길이 T/2 상자 적분은 **짝수 배음에서 정확히 0** 이다. 실측(§52.183): 이 음절에서 목표와 판의
#: **중앙값은 ±0.2 dB 안**으로 거의 같고, 나쁜 주기 쪽(90 분위)만 `p96b` 가 +0.36 dB 높다. 그래서 전체를
#: 낮추지 않고 **주기마다 목표보다 덜 협화적인 만큼만** 문다(한쪽). 원본보다 더 협화적으로 미는 것은
#: 사용자가 배음 사이에 대해 경고한 것과 같은 오차가 된다. 가중은 섭동 수준(0.01~0.05)으로만 쓴다.
#: 사용자 지시로 **기본을 켠다** — "확실히 그냥 책임값을 1로 둬도 될 정돈데 1로 놓지?" (§52.235).
CONS_W = 1.0
CONS_M = 64                # 주기당 시작점 수
CONS_KNEE_DB = 0.5
CONS_MARGIN_DB = 0.0
CONS_LEVEL_PCT = 40.0
#: **주파수 보정 반주기 협화** (사용자 제안, MEASUREMENTS §52.195~196). *"고주파 배음들은 손실 기여도가 많이 떨어질
#: 거야"* — T/2 상자 적분의 크기는 1/f 라 13~16 kHz 가 −36 dB 로 눌려 **측정에서부터 지워진다.** *"주파수 범위를 정하고
#: 그 주파수를 곱하는 방법도 있어. 값이 주파수에 반비례하니까 최저 주파수를 곱하면 보간이 되잖아."*
#:
#: 주파수를 곱하는 것은 시간 영역 미분이고, **미분을 T/2 동안 적분하면 정확히 반주기 차이**다. 그래서 닫힌 식 하나다:
#:
#:     Q_band(주기 j) = E_τ|y(τ + T_j/2) − y(τ)| / √E_j[y²],   y = [CONS_HF_LO, CONS_HF_HI] 대역통과한 신호
#:
#: **절댓값으로 잰다** (사용자: *"해당 척도는 항상 절댓값으로 접근해야 해. 음수도 갈 수 있어서."*). 0 근처 기울기가
#: 끊기지 않게 √(D² + ε²) 를 쓴다. 제곱보다 드문 큰 봉우리에 덜 끌린다.
#:
#: 응답 |2·sin(πfT/2)|² 에 1/f 가 없어 대역 안 모든 주파수가 같은 몫이고, 대역 밖(저역)은 영향이 없다. 기존 협화 항과
#: 같이 **주기마다 목표보다 덜 협화적인 만큼만** 문다(한쪽).
CONS_HF_W = 0.0
CONS_HF_LO = 5600.0        # 실측(§52.196): 5.6~17 kHz 에서 모든 판이 목표보다 +0.70~+1.65 dB, 주기 54~65 % 로 가장 잘 갈렸다
#: 상한은 **20 kHz** 로 둔다 — 사용자 지시 "앞으로는 20 kHz 까지 무조건 계산하도록 해". 17 kHz 에서 끊으면
#: 목표가 코덱으로 20 kHz 까지 내는 구간을 자가 못 본다 (§52.206).
CONS_HF_HI = 20000.0
CONS_HF_TAPS = 401

#: **배음 사이** 항 (사용자 지시, MEASUREMENTS §52.182). *"target 은 안정적이고 자극적으로 들리는데 fit 는
#: 퍼져 들리고 미세 구조가 불안하다. 배음이 아니라 배음의 사이를 봐야 한다. 반치폭만큼 벗어난 부분을
#: 분석하고 피팅시켜라."* 그리고 *"사이를 0 으로 만들면 또 오차가 심해진다. 원본과 대조해서 정할 일이다."*
#:
#: **주기 동기 접기**: 목표 펄스 p_j 사이를 정확히 `IH_M` 표본으로 다시 뜨면 F0 흔들림이 사라진다. 거기에
#: 정수 `IH_C` 주기의 periodic Hann 을 씌우면 k 차 배음은 bin C·k 에 떨어지고, **완전 주기 신호는
#: |bin − C·k| ≥ 2 에서 해석적으로 0** 이다(periodic Hann 변환의 정수 bin 영점). 그러니 반치폭 밖의
#: 에너지는 모형 없이 곧바로 "비주기" 로 읽힌다. 실측(§52.182) — 3~4.5 kHz / 4.5~6.5 kHz:
#:
#:     HIR (선 대비 사이)  목표 28.3 / 21.1 dB,  p96b −5.5 / −2.8
#:     선 넓음 (Hann 초과) 목표 0.14 / 0.36 dB, p96b +0.57 / +1.18   (지터 약 1 % 에 해당)
#:
#: 세 양을 **목표와 대조**한다 (최소화가 아니다): (1) 사이 수준 − 선 수준 [dB], (2) 선 넓음 [dB],
#: (3) 사이 수준의 주기 간 흔들림. 잡음 실현이 다르므로 대역·창마다 기대 표준편차(4.343/√n)를 무릎으로 둔다.
INTERHARM_W = 0.0
#: **1 단계(전역 스칼라)에서는 배음 사이 항을 끈다** (MEASUREMENTS §52.258). 1 단계는 전역 스칼라만 푸는데 이 항이 켜져 있으면
#: 손실이 배음 사이·선폭이 작은 분지(포락 62 %, 주기상관 0.74)를 더 낮게 쳐서(1 단계 끝 손실 5.14 대 5.49) `pulse_phi0`·`open_damp`
#: 같은 전역 구조를 그쪽으로 끌고 간다 — 씨앗 하나로 2.1 끝이 −2 점. 제어 격자가 생기는 2.1 부터 켠다. 기본 False (A/B 전).
IH_SKIP_GLOBAL = False
IH_M = 128                 # 주기당 표본 (접은 영역)
IH_C = 8                   # 창 길이 [주기] — 사이 bin 은 ±2 … ±(C−2)
IH_HOP = 2                 # 창 간격 [주기]
IH_SMOOTH = 5              # 창 방향 평활 (힘에서) — 실현 잡음을 줄인다
IH_BAND_HZ = (500.0, 9000.0)
IH_BANDS = 8               # 로그 등간격
IH_PERIOD_TOL = 0.25
IH_LEVEL_PCT = 40.0
IH_LINE_W = 1.0            # (2) 선 넓음의 몫
IH_STAB_W = 0.5            # (3) 흔들림의 몫
#: periodic Hann 변환의 ±1 bin 힘은 중심의 1/4 이다 — 선 넓음은 **이것을 뺀 초과분**으로 둔다
#: (`scripts/diag/interharm.py` 와 같은 정의). 완전 주기 신호에서 0 이 된다.
IH_HANN_SIDE_DB = 10.0 * math.log10(0.25)

#: **조화 공진 식 제약** (사용자 지시: *"조화 공진 제약을 확실하게 걸어라. 그냥 식으로 이식할 수 있도록"*).
#: 주기 여기가 공진기를 지나면 k 차 배음의 크기는 **식으로** 정해진다:
#:
#:     A_k [dB] = S(k·F0) + Σ_i 20·log10 |H_i(e^{jω_k})|,   ω_k = 2π·k·F0/fs
#:     H_i(z) = (1 + a1 + a2) / (1 + a1 z⁻¹ + a2 z⁻²),  r = exp(−π B_i / fs),  a1 = −2r·cos(2π F_i/fs),  a2 = r²
#:
#: (엔진의 `tviir.resonator_coeffs` 와 **같은 식**이다.) 목표 배음 크기 A_k 는 접은 스펙트럼에서 곧바로
#: 읽고, 제어값의 F_i·B_i 로 공진 곡선을 계산해 뺀 나머지가 **음원 S 로 설명되는 매끈한 곡선**이어야 한다.
#: 음원은 모르므로 창마다 log f 의 2 차식을 가중 최소제곱으로 빼서 불변으로 만든다. 렌더 없이 제어값에
#: 곧바로 걸리므로 대역폭을 "퍼티" 로 쓰는 해(§52.179 — 모든 판이 bw1~3 을 1.3~2.1 배로 넓힌다)를 막는다.
HRES_W = 0.0
HRES_FMAX = 5500.0         # 이 위 배음은 안 본다 (f1~f4 밖의 극·영점이 지배한다)
HRES_KNEE_DB = 3.0         # 식 밖 요소(보조 극·영점·비강)의 몫은 봐준다
HRES_HIR_DB = 10.0         # 배음이 사이보다 이만큼은 솟아야 관측으로 친다
HFCOMB_R = 0.30               # 목표가 없을 때 쓰는 절대 문턱 (적합에서는 안 쓰인다)
HFCOMB_DETREND_BINS = 15

#: **문지기를 목표 기준으로 잰다** (0 = 절대값 그대로, 1 = 목표의 값을 빼고 넘은 만큼만).
#:
#: 실측 (음절 0.451~1.293 s):
#:
#:   | 무엇 | hfline | hfcomb |
#:   |---|---|---|
#:   | 목표(녹음) | 0.00437 | 0.00187 |
#:   | 기준선 판 | **0.00044** | 0.00179 |
#:   | harm-jit 0 판 (문지기 폐기) | 0.01331 | 0.02630 |
#:
#: 우리 판은 **녹음보다 hfline 이 10 배 적다**. 절대값을 최소화하는 형태라 아티팩트를 막는 것을
#: 넘어 **녹음에 실제로 있는 고역 구조까지 지운다** — 6 kHz 위 가로줄 최대 길이가 목표 70.7 ms
#: 대 우리 22.7 ms 인 것과 같은 현상이다(§52.117). 1 로 두면 "녹음보다 더 심할 때만" 문다.
#: 아티팩트 판(0.0133 대 0.0044)은 여전히 세게 물리므로 문지기의 힘은 그대로다.
#:
#: **기본은 0 이다** — 절대 문턱은 사용자가 지시한 규칙이므로 A/B 로 확인한 뒤에 바꾼다.
HFLINE_REF = 0.0
HFCOMB_REF = 0.0      # 주파수축 추세 제거 폭 (512 창이면 약 1.4 kHz)           # 10.7 ms 창 · 홉 128 (2.7 ms) — 30 ms 가 11 프레임


#: **보고용 대역 경계** [Hz] (사용자 지시, §52.70). 포락 점수를 이 경계로 갈라 함께 찍는다.
#: 6 kHz 아래는 포먼트가 지배하고, 6~10 kHz 는 마찰·기식의 몸통, 10 kHz 위는 고차 극 사다리와
#: 잡음 바닥이 지배해 **적합의 경향이 서로 다르다** — 한 숫자로 묶으면 그 차이가 안 보인다.
#: 손실은 바꾸지 않는다 (보고 전용). 손실을 대역별로 저울질하는 것은 따로 결정할 일이다.
REPORT_BAND_EDGES: tuple[float, ...] = (6000.0, 10000.0)


#: **근육군 결합(협응) 벌점** (MEASUREMENTS §52.68·§52.69). 성도의 자유도는 서로 독립이 아니다 — 한 신경이
#: 여러 파라미터를 동시에 움직인다. 반회후두신경(RLN) 하나가 두께·내전·외전을 쥐고, 후두 높이 하나가 성도 길이·
#: 이상와 깊이·후두실을 같이 바꾼다. 실측: 분석기가 목표에서 잰 궤적에서 adduction–p_sub 상관이 +0.52 인데
#: (세게 말하면 폐압을 올리며 더 붙인다) 적합은 −0.12~+0.18 로 그 협응을 깨뜨렸다.
#:
#: 벌점은 **목표에서 잰 협응 방향**(군마다 상위 `n_dim` 주성분) 밖으로 나가는 빠른 움직임만 문다. 관측 자체가 가진
#: 직교 성분을 빼고 그 초과분만 세므로 "화자보다 더 협응하라"고 강요하지 않는다. 0 이면 끈다.
SYNERGY_W = 0.0
#: 군 이름 -> (파라미터, 근육 자유도). 자유도는 해부학에서 온다 — 혀는 이설근·설골설근/경돌설근·고유근으로 3,
#: 입술의 돌출·오므림은 구륜근 하나로 1, 인두·연구개는 수축근과 구개거근으로 2, 내후두근은 TA(두께)·LCA/IA(내전)로 2,
#: 후두 높이는 올림/내림 길항 하나로 1.
SYNERGY_GROUPS: dict[str, tuple[tuple[str, ...], int]] = {
    "tongue": (("f1", "f2", "a_c", "c_place"), 3),
    "lips": (("f3", "front_len", "obstacle"), 1),
    "pharynx": (("velum", "nasal_gain", "f1"), 2),
    "larynx_intrinsic": (("adduction", "p_sub", "rd_offset"), 2),
    "larynx_height": (("f4", "bw4", "tract_gain"), 1),
}
#: 협응을 볼 때 뺄 추세의 길이 [ms]. 음절 윤곽은 협응의 대상이 아니다 (그건 조음 계획이다).
SYNERGY_TREND_MS = 100.0
#: 협응 눈금의 바닥 — 열의 rms 대비 이 비율 아래로는 안 내려간다 (§52.94). 관측이 거의 안 움직이는 열을
#: 1e-9 로 나누다가 손실이 2e21 로 폭발한 적이 있다.
SYNERGY_SCALE_FLOOR = 0.02


#: **움직임 예산** (MEASUREMENTS §51.20). 사용자: *"무브먼트가 너무 과해. 억제시킬 방안을 찾아봐."*
#:
#: 제어열이 얼마나 흔들려도 되는지에는 두 개의 독립된 기준이 있다.
#:
#: * **관측** — 포먼트·대역폭은 분석기가 목표에서 실제로 잰 궤적이 있다. 적합이 그것보다 빨리 흔들리면
#:   그건 조음이 아니라 적합기의 난동이다. `MOVE_RATE_REL` 배까지만 허용한다.
#: * **생리** — 음원 손잡이(`voice_gain`·`tilt`·`rd_offset`·`p_sub`·`adduction`)에는 관측 궤적이 없다.
#:   대신 생리적 크기가 있다: 모달 발성의 시머는 9 % ≈ **0.75 dB**, 음원 기울기는 발성 노력이라 한 음절
#:   안에서 몇 dB/oct 씩 튀지 않고, 폐압은 호흡이라 더 느리다. `MOVE_CAP` 이 그 상한이다 [파라미터 단위].
#:
#: 느린 음절 윤곽은 정당하므로 **빠른 성분만** 문다 — σ `MOVE_SMOOTH_MS` 가우시안으로 추세를 뺀 나머지의
#: 유성 구간 rms 가 상한을 넘는 만큼(부드러운 무릎)의 제곱. 실측(§51.20): `L53/s040` `voice_gain` 빠른 σ
#: 0.81 dB, `L53/s101` 1.77, `L62/s040` 3.12, `L25/s040` 는 `p_sub` 0.85 (상한 0.30).
MOVE_W = 0.0
MOVE_SMOOTH_MS = 8.0
MOVE_CAP = {"voice_gain": 1.0, "tilt": 0.6, "rd_offset": 0.10, "p_sub": 0.30, "adduction": 0.05}
MOVE_RATE_REL = 1.3
#: **L1 움직임 예산** (사용자 지적 *"formant의 과도한 drift"*, MEASUREMENTS §52.328). 위의 `MOVE_RATE_REL`
#: 은 로그차의 **RMS**(L2)를 문다. RMS 는 큰 전이 몇 개가 지배하므로, 같은 총량을 **여러 프레임에 얇게
#: 펴 놓아도** 값이 그대로다 — 실측: 우리 판의 L2 는 관측의 0.83~0.96 인데 L1(평균 절대 변화)은
#: 0.98~1.17, 낮은 배음 보정을 끈 판은 **1.42~1.85** 다. 즉 예산은 통과하면서 포먼트가 **쉬지 않고
#: 흐른다**. 실제 조음은 "대체로 가만히 있다가 이따금 옮겨 간다" 이므로 L1 이 그 성질을 문다
#: (L1 은 희소성을 밀어 전이를 몇 군데로 모은다). 0 이면 끈다.
MOVE_RATE_L1 = 0.0
MOVE_RATE_L1_REL = 1.05    # 관측 L1 의 이 배까지 봐 준다
MOVE_RATE_PARAMS = ("f1", "f2", "f3", "f4", "bw1", "bw2", "bw3", "bw4")
#: **무성 구간의 움직임 가중** (사용자 지적, MEASUREMENTS §52.337). 지금 예산은 유성 프레임만 본다
#: (`_move_voi`). 그래서 무성 구간에서 적합기가 포먼트를 마음대로 훑는다 — 사용자가 짚은 두 스윕
#: 구간을 뜯어 보니 2.063~2.131 s 는 **유성 0/68 프레임**이었고, 거기서 f3 가 관측 165 Hz 대
#: 우리 **1969 Hz**(11.9 배)를 지나갔다. 무성이라 조화 구조가 없어 손실이 포먼트 자리를 거의 못 보고,
#: 그 자유가 곧 스윕이 된다. 분석 궤적은 무성 구간에서도 매끈하게 이어져 있으므로 그것에 묶으면 된다.
#: 0 이면 예전대로 유성만, 1 이면 무성도 같은 무게로 본다.
MOVE_UNVOICED = 0.0

#: **요동만 허용하는 제어** (MEASUREMENTS §51.22). 여기 적힌 파라미터는 값에서 자기 추세(σ `FAST_ONLY_MS`
#: 가우시안)를 빼고 쓴다 — 느린 수준 윤곽을 만들 수 없고 **빠른 요동만** 낸다. 유성 마스크도 곱한다.
#:
#: 왜: `voice_gain` 은 목표의 주기별 진폭(시머 실현)을 따라가라고 만든 손잡이인데(§51.2), 적합기는 그것을
#: **전체 소리 크기의 주된 수단**으로 썼다 — 0 으로 두면 포락이 86 → 39 %로 무너진다. 그러면서 구간별
#: ms 당 변화가 모음 0.90 dB, 치찰음 경계 **1.24 dB**(한 주기에 4 dB)까지 갔고, 분석에는 대응하는 관측이
#: 아예 없다(0.00). 사용자가 "치찰음 근방에서 흔들림" 이라고 들은 것이 이것이다. 크기의 느린 윤곽은
#: 폐압·성도 이득처럼 **관측에 묶인** 제어가 져야 한다.
FAST_ONLY: set[str] = set()
FAST_ONLY_MS = 8.0

#: **마찰 안에서는 공명을 붙잡는다** (MEASUREMENTS §51.30). 켜면 `HOLD_PARAMS` 의 제어가 마찰 구간
#: **하나하나의 안쪽에서 상수**가 된다 — 그 구간에서의 제 평균(로그)으로 끌어당기고, 가장자리
#: `HOLD_RAMP_MS` [ms] 에 걸쳐 풀어 준다. 전이(협착을 만들고 푸는 동작)는 그대로 자유롭다.
#:
#: 왜: 사용자가 되풀이해 지적한 "치찰음 근방의 흔들림" 이 마찰 **안**에 있다. `out/L7` 은 사용자가
#: 치찰음이 좋다고 한 유일한 판인데, 마찰 프레임 안에서 `f3`·`f4` 의 ms 당 |Δ| 중앙값이 0.003 / 0.005 %
#: 로 사실상 얼어 있었고 변화의 상위 10 % 가 전체의 95 / 91 % 였다 — 가장자리에서만 움직였다. 같은 자로
#: 잰 `L53` 은 0.055 / 0.041 %, `L85` 는 0.296 / 0.088 % 에 상위 10 % 몫이 20~25 % 로, 마찰 내내
#: 움직인다. 그것도 1 ms 잔떨림이 아니라 **구간을 가로지르는 완만한 쓸림**이라(가우시안 평활로는
#: 중앙값이 안 줄고 σ8 에서 오히려 0.296 → 0.319 % 로 늘었다) 평활이 아니라 **고원**이 답이다.
#:
#: 물리도 같은 말을 한다. 마찰은 협착을 **유지**하는 동작이고(Browman & Goldstein 의 제스처 고원),
#: 난류는 무작위라 목표의 그 실현을 성도 공명으로 따라갈 수 없다. 실제로 마찰 구간에 백색 떨림을
#: 심으면 어느 손실 항도 내려가지 않는다(4 % 떨림에 env_db +0.19 %) — 움직임은 상을 받아서가 아니라
#: **말리지 않아서** 남아 있다. 그래서 벌점이 아니라 **구조**로 막는다.
#:
#: 비용은 심어서 쟀다 (`out/_tmp/sibfreeze.py`: 적합된 제어열을 구간 고원으로 갈아 끼우고 재렌더).
#: 포먼트·대역폭만 붙잡으면 `L53/s040` −0.00, `L85/s040` −0.06, `L85/s101` −0.01 % 다. 제약을 건
#: 최적해의 손실은 이 사영점의 손실보다 클 수 없으므로(사영점이 실행 가능하다) 이것이 상한이다.
#: 반대로 `tract_gain`·`a_c` 까지 붙잡으면 −0.07 ~ **−0.58 %** 로 뛴다 — 마찰의 **세기 윤곽**은
#: 진짜 정보다. 그래서 `HOLD_PARAMS` 는 공명(포먼트·대역폭)만이다. 참고로 전 구간을 σ8 로 평활하면
#: −0.46 ~ −0.76 % 이므로, 증거가 없는 구간에만 거는 것이 전역 평활보다 10 배 싸다.
#: **어택 항** (MEASUREMENTS §51.31). 목표의 고역이 급히 서는 자리에서 **서는 크기**를 맞춘다.
#:
#: 왜: 파열은 통째로 빠져 있다. 목표의 2~8 kHz 는 3 ms 안에 13~31 dB 서는데 합성은 −7.5 ~ +9.2 dB
#: 다(`out/_tmp/burst2.py`, 두 파일 일곱 자리). 파열 **뒤** 10 ms 의 수준은 ±3 dB 로 맞으니 문제는
#: 레벨이 아니라 **모서리**다. 그런데 지금 손실은 그 모서리를 볼 수 없다 — 멜 홉이 5.3 ms 이고
#: `_expect` 가 난류 빈을 25 ms 로 평활한다. 파열은 폐쇄 위치의 주 단서라(Stevens; Blumstein &
#: Stevens 1979) 명료도에 직접 걸린다.
#:
#: 잡음에 속지 않는 이유: 대역 에너지를 `ATTACK_SMOOTH_MS` 로 고르고 **오르는 쪽만** 센다. 난류의
#: 무작위 요동은 기울기의 평균이 0 이라 상쇄되지만 파열은 한쪽으로 13~31 dB 다. 그리고 가중이
#: 목표가 실제로 서는 자리(`ATTACK_MIN_DB` 위)에 몰려 있어 정상 구간은 거의 안 본다.
ATTACK_W = 0.0
#: 어택을 **대역마다** 따로 맞춘다 (MEASUREMENTS §51.43). 한 덩어리로 재면 대역이 따로 서도
#: 손실이 모르는데, 실측으로 마찰 시작이 대역 사이에서 14.5~18.5 ms 어긋난다(감사의
#: `치찰 대역 시작 어긋남`). 셋을 각각 맞추면 같이 서야 한다.
ATTACK_BANDS = ((2000.0, 4000.0), (4000.0, 8000.0), (8000.0, 16000.0))
ATTACK_BAND = (2000.0, 8000.0)
ATTACK_RISE_MS = 3.0
ATTACK_SMOOTH_MS = 1.5
ATTACK_MIN_DB = 6.0
ATTACK_FLOOR = 0.05

#: **파열 자리에서만 제어 해상도를 푼다** (MEASUREMENTS §51.31). `MOTION_SLOW` 로 묶인 파라미터라도
#: `ControlTrack.bursts` 의 ±`BURST_WIN_MS` 안에서는 고운 층의 계수를 살린다.
#:
#: 왜: 손실이 모서리를 보게 해도(=`ATTACK_W`) 제어가 3 ms 계단을 만들 수 없으면 소용이 없다.
#: 지금은 `--slow a_c=10` 등으로 모든 조음 손잡이가 10~20 ms 격자에 묶여 있다. 반대로 전역으로
#: 풀면 사용자가 지적한 난동이 돌아온다 — 그래서 **증거가 있는 자리에서만** 푼다. 마찰 안에서
#: 붙잡는 `HOLD_FRIC` 과 같은 원리의 반대쪽이다.
BURST_FINE = False
#: **관측이 빠르게 움직이는 곳도 연다** (MEASUREMENTS §51.37). 분석 궤적의 포먼트가 ms 당
#: `MOVE_FINE_PCT` % 넘게 움직이는 프레임 둘레 ±`BURST_WIN_MS` 에서도 고운 층을 살린다.
#:
#: 왜: 사용자가 `L91/s040` 의 0.395~0.447 s 를 "포먼트 무브먼트가 괴상하다" 고 짚었다. 재 보면
#: **목표 F2 가 2300 → 1333 → 2417 Hz 를 60 ms 안에** 오가는데(자음 폐쇄의 전이) 우리 제어는
#: `--slow f2=20` 에 묶여 그 골을 못 만든다 — 454~462 ms 에서 **3.21 Bark** 어긋난다. 파열만
#: 여는 것으로는 부족하다. 관측 궤적이 "여기서 빨리 움직인다" 고 말하는 자리를 함께 연다.
#: 0 이면 끈다.
MOVE_FINE_PCT = 0.0
MOVE_FINE_PARAMS = ("f1", "f2", "f3")
#: 그 자리의 창 반폭 [ms]. 파열(`BURST_WIN_MS` = 20)보다 좁다 — 파열은 앞의 폐쇄를 만들 자리가
#: 필요하지만 전이는 제자리에서 빨라지면 된다. 넓게 잡으면 파일의 65 % 가 열려 (실측) 사용자가
#: 지적한 난동이 돌아온다.
MOVE_FINE_WIN_MS = 6.0
#: 그 자리에서 **출발점 평활도 끈다** — 반폭 [ms]. 0 이면 끈다. `_fast_obs_mask` 참조.
BASE_SMOOTH_KEEP_FAST = 8.0
#: 20 ms 로 잡았다 — 손으로 밀어 넣어 보니 파열 앞 20 ms 를 닫으면 엔진이 7.5~19.9 dB 를 낸다
#: (`out/_tmp/burstable.py`). 창이 그보다 좁으면 닫을 자리가 없다.
BURST_WIN_MS = 20.0
BURST_PARAMS = ("a_c", "tract_gain", "aspiration", "obstacle", "front_len", "adduction")

HOLD_FRIC = False
#: 마찰이 **끝나는** 쪽에서 붙잡기가 풀리는 거리 [ms].
HOLD_RAMP_MS = 15.0
#: 마찰이 **시작하는** 쪽의 거리 [ms]. 두 가장자리는 대칭이 아니다 — 협착은 빨리 서고 천천히 풀린다.
#:
#: 사용자: *"치찰음 포먼트가 실제 음원보다 늦게 적용되고"*. 실측(목표 녹음의 마찰 구간 3 개, 2.5~16 kHz
#: 무게중심이 고원값 ±5 % 안에 드는 시각): **시작 뒤 2·5·14 ms**, **끝 앞 0·0·35 ms**. 그런데 램프를
#: 양쪽 다 15 ms 로 두면 시작 쪽에서 공명이 15 ms 동안 고원에 못 닿는다 — 감사의 "치찰 대역 시작
#: 어긋남" 이 M1 에서 17.5~18.5 ms (기준 12) 였던 것이 이것이다. 들어가는 쪽만 5 ms 로 줄인다.
HOLD_RAMP_IN_MS = 5.0
#: 붙잡을 제어. **치찰음의 공명은 포먼트가 아니라 앞공동이 만든다** (`_front_cavity`:
#: f_p = c/4·front_len) — 그런데 `front_len`·`obstacle` 이 빠져 있어서 마찰 안에서 자유롭게
#: 흔들렸다. 사용자: *"치찰음 단에서 흔들림으로 인한 긴 주기의 노이즈가 있고"*. 둘을 더한다.
#: `a_c` 는 넣지 않는다 — 그것은 공명이 아니라 잡음의 세기라 구간 안에서 변해야 한다.
HOLD_PARAMS = ("f1", "f2", "f3", "f4", "bw1", "bw2", "bw3", "bw4",
               "front_len", "obstacle")
#: **마찰 안에서 세기 쪽 제어를 저역통과한다** (§51.57). 사용자: *"치찰음 세로 토막 나는 걸
#: 고치고 부드럽게 스무딩하는 걸론 안 되냐? 자꾸 음원들이 쳐 끊기잖아."*
#:
#: 실측(`M14/s101`, 마찰 대역 포락의 변조 스펙트럼): 20~40 Hz 에서 목표 1.56 dB 인데 우리가
#: **2.66 dB (1.70 배)**, 40~80 Hz 도 1.29 배다. 25~50 ms 주기로 끊긴다는 뜻이고 그것이 세로 토막이다.
#: 그 흔들림을 나르는 것은 `a_c` 다 — 마찰 안 20~80 Hz 로그 변조가 0.18 로 다른 제어의 4 배다.
#:
#: **그런데 그 흔들림은 관측에 이미 있다** (관측 0.156 → 적합 0.182, 적합은 17 % 만 더한다).
#: `--slow a_c=10` 은 **보정분만** 묶으므로 분석 출발점의 흔들림은 그대로 통과한다 — 그래서
#: 지금껏 평활이 안 먹었다. 여기서는 **렌더되는 제어**(출발점+보정)를 마찰 구간 **안에서만**
#: 가우시안으로 깎는다.
#:
#: σ 12 ms 는 30 Hz 를 −22 dB 로 죽이면서 10 Hz 는 −2.5 dB 만 깎는다. 목표가 실제로 가진
#: 8~20 Hz 윤곽(우리는 오히려 **모자란다**: 0.65~0.80 배)을 지우지 않는 것이 중요하다.
HOLD_SMOOTH_PARAMS = ("a_c", "obstacle", "tract_gain")
HOLD_SMOOTH_MS = 12.0

#: **마찰 전이의 사각지대** (사용자 지적, MEASUREMENTS §52.339). 사용자가 짚은 스윕이 **전부**
#: 마찰이 시작되기 직전의 전이에 있었다 — 최악 넷(2.121·2.741·1.429·2.219 s)이 각각 마찰 구간의
#: 9·44·34·13 ms 앞이다.
#:
#: **까닭은 그 자리가 어느 자에도 안 걸리는 사각지대이기 때문이다.** 유성 구간은 조화 구조가 손실에
#: 포먼트 자리를 알려 주고, 마찰 구간은 `HOLD_FRIC` 가 공명을 고원 값으로 붙잡는다. 그런데
#: **유성도 마찰도 아닌** 프레임(실측 261 개, 9.3 %)에는 셋 다 없다 — 조화 구조가 없어 포락 손실이
#: 포먼트 자리를 거의 못 보고, `_hold` 의 마스크 밖이고, 움직임 예산은 `_move_voi` 라 유성만 본다.
#: 그 자유가 곧 스윕이다. 실측 |Δlog| 는 관측 대비 유성 **0.61**, 마찰 1.64, 사각지대 **2.75** 배다.
#: 2.717~2.784 s 는 관측 f1 범위가 **0 Hz**(완전 정지)인데 우리는 700 Hz 를 훑었다.
#:
#: **`MOVE_UNVOICED`(§52.337)로는 못 고친다** — 그것은 전 구간 가중평균 예산의 가중일 뿐이고, 실측
#: 값이 이미 상한의 0.61~0.75 라 손실 기여가 전체의 0.5 % 다. 4 % 구간의 스윕은 넓은 평균에
#: 희석된다 (§52.326 의 빗살과 같은 실패다).
#:
#: 그래서 손실이 아니라 **구조로** 묶는다 — `_hold` 와 같은 재파라미터화다. 사각지대 안에서 공명의
#: **모양**을 분석 궤적의 모양으로 갈아 끼우고, **수준**(구간 평균 오프셋)만 적합기에게 남긴다:
#: 관측이 정지면 우리도 정지하고, 관측이 실제로 전이하면(2.055~2.129 s 는 관측 f2 범위가 1996 Hz 다)
#: 같은 모양으로 따라간다. 양끝 `HOLD_GAP_RAMP_MS` 에서 풀어 유성 쪽과 매끄럽게 잇는다.
HOLD_GAP = False
HOLD_GAP_RAMP_MS = 8.0
#: **기준 모양을 쓰기 전에 깎는 정도** [ms]. 0 이면 분석 궤적을 그대로 쓴다.
#:
#: 사각지대의 관측을 그대로 믿으면 안 된다 — 그 자리엔 조화 구조가 없어 추적기가 광대역 과도음에
#: 공진을 억지로 맞춘다 (§52.329 가 파열에서 찾은 것과 같다). 실측: 2.055~2.130 s (유성 0/75) 의
#: 관측 f2 는 프레임당 **중앙 26.3 Hz** 로 쉬지 않고 흐르는데, 유성 구간의 관측 중앙은 3.10 이다.
#: 그 자리의 목표 소리는 오히려 조용하다(처프 몫 0.005). 반면 2.717~2.785 s 의 관측은 완전 정지
#: (0.0 Hz)다 — 즉 사각지대의 관측은 믿을 수 있는 곳과 아닌 곳이 섞여 있다.
#:
#: 실제 조음 전이는 수십 ms 규모라 느리다. σ 12 ms 는 30 Hz 를 −22 dB 로 죽이면서 10 Hz 는
#: −2.5 dB 만 깎으므로(`HOLD_SMOOTH_MS` 와 같은 근거), 추적기의 요동은 지우고 전이는 남긴다.
#: 구간 **안에서만** 깎는다 — 바깥 값이 새어 들어오면 수준이 끌려간다.
HOLD_GAP_SMOOTH_MS = 12.0
#: **구간이 길수록 더 깎는다** — σ 는 `max(HOLD_GAP_SMOOTH_MS, 이 몫 × 구간 길이)` 다.
#:
#: 사각지대가 길수록 손실이 포먼트 자리를 못 보는 시간이 길고 추적기도 그만큼 오래 헤맨다.
#: 실측(제어열만 갈아 끼우고 다시 렌더, 2.121 s 의 처프 몫 / 전체 포락):
#:
#:   σ 12 ms → 0.061 / 95.18    σ 30 ms → 0.028 / 95.15    σ 60 ms → **0.017 / 95.13**
#:
#: **σ 를 다섯 배로 키우는 값이 포락 0.05 점**이다. 견줄 것은 같은 제어를 전 구간에서 σ 25 ms 로
#: 깎은 판인데, 그것은 처프를 0.006 까지 내리는 대신 포락을 **7.3 점**(95.60 → 88.27) 잃는다.
#: 즉 사각지대에서는 관측의 세부를 거의 다 버려도 점수를 안 잃는다 — 애초에 그 구간에 조화 구조가
#: 없어 포락 손실이 포먼트 자리를 못 보기 때문이고, 그것이 이 결함의 원인이기도 했다.
#: **그 자유는 점수를 벌지 못하면서 스윕만 만든다.**
#:
#: 0.8 이면 실측한 구간들에서 75 프레임 → σ 60 ms, 33 프레임 → σ 26 ms 다. 0 이면 끈다.
HOLD_GAP_SMOOTH_FRAC = 0.8
#: 붙잡을 제어. `HOLD_PARAMS` 와 같은 공명 손잡이다 — 세기(`a_c`·`fric_gain`)는 넣지 않는다.
#: 사각지대는 조음이 마찰을 향해 **움직이는** 자리라 세기는 변해야 한다.
HOLD_GAP_PARAMS = ("f1", "f2", "f3", "f4", "bw1", "bw2", "bw3", "bw4",
                   "front_len", "obstacle")

#: **미래를 보는 레이놀즈 전이** (MEASUREMENTS §51.24). 사용자: *"어차피 지금 하는 건 예측이 아니고
#: 피팅이니까 그냥 미래 정보도 가져다 써. 미래 데이터에 난류 조짐이 보이면 레이놀즈 현상이 일어나는
#: 방향으로, 그 조짐이 없어지면 꺼지는 방향으로 패널티를 부과해."*
#:
#: 엔진의 마찰 구동은 레이놀즈 수의 문턱(`noise.RE_CRIT` = 1800)을 넘어야 켜진다 — 물리적으로 옳지만
#: **문턱은 기울기가 거의 없는 벽**이라, 적합기가 그 벽의 어느 쪽에 있는지를 스펙트럼 오차만으로
#: 찾아가기 어렵다. 목표에는 난류가 언제 켜지고 꺼지는지가 **이미 적혀 있다**(고역/저역 비). 피팅이므로
#: 그 정보를 미래까지 당겨 써도 된다: 앞으로 `RE_LEAD_MS` 안에 난류가 오면 Re 를 문턱 위로 밀고,
#: 앞뒤로 그만큼 안에 난류가 없으면 문턱 아래로 민다. 협착이 **미리 좁아지기 시작**해야 개시가 자연스럽고
#: (조음은 목표에 앞서 움직인다), 끝난 뒤에는 확실히 꺼져야 꼬리 잡음이 남지 않는다.
RE_LEAD_W = 0.0
RE_LEAD_MS = 25.0
RE_MARGIN = 0.15          # 문턱의 ±15 % 까지 밀어붙인다
#: **아티팩트 벌점** — 목표가 **어두운 칸에서 우리가 소리를 내는** 만큼을 문다.
#:
#: 사용자: *"아티팩트가 아직도 남는데 … 아티팩트 자체에 처벌을 강하게 걸어."* `QUIET_W` 는
#: 10 ms 창이 통째로 조용할 때만 본다 — 그런데 실제로 들리는 아티팩트는 **한 프레임 안의
#: 어두운 대역**에 난다 (실측 §51.50: 마찰 가장자리 11.3 kHz 에서 우리 −54 dB, 목표 −78 dB).
#: 그 칸은 프레임 전체로 보면 조용하지 않으므로 `QUIET_W` 가 못 잡는다.
#:
#: 재는 법: 멜 dB 에서 **그 프레임의 정점보다 `ARTIFACT_DARK_DB` 아래인 칸**만 골라,
#: 우리가 목표보다 `ARTIFACT_MARGIN_DB` 넘게 큰 만큼을 문다. 부족한 쪽은 안 문다 —
#: 그건 포락 항의 일이고, 아티팩트는 **없던 소리를 내는 것**이라 한쪽만 본다.
#: 골라내기와 넘침 둘 다 부드럽게(시그모이드·softplus) 깐다 — 꺾이면 기울기가 죽는다.
ARTIFACT_W = 0.0
ARTIFACT_DARK_DB = 20.0
ARTIFACT_MARGIN_DB = 3.0

QUIET_DB = 45.0
QUIET_MARGIN_DB = 2.0

#: **녹음 바닥 잡음을 합성에 고정으로 더한다.** 목표의 가장 조용한 10 % 프레임의 파워 스펙트럼
#: (잡음 제거기 `noise_profile` 과 같은 방법)을 모양·수준 그대로 쓴다. 적합하지 않는다 — 목소리가
#: 아니라 녹음의 성질이다.
#:
#: 없으면 적합기가 무음의 녹음 바닥(−75 dB)을 **목소리로 흉내 낸다.** 실측(out/L35/s040, 발화 전
#: 0.02~0.18 s): 폐압 6.3 cmH₂O, 내전 0.13 으로 성문을 열어 두고 모음의 66 배 기식을 고정된 성도
#: 공명(920/1500/3100/4280 Hz)에 통과시켰다. 수준은 목표와 −75.1 dB 로 같지만 질감은 **공명 줄**
#: 이다 — 녹음 바닥은 평평한 잡음이라 목표에는 줄이 없다. 사용자가 본 "평평한 줄" 의 한 출처다
#: (MEASUREMENTS §50.15). 바닥을 따로 주면 무음에서 폐압을 0 으로 내릴 수 있다.
#: 난수는 엔진 씨앗(`cfg.seed`)을 따른다 — `RESEED` 면 매번 새 실현이다.
FLOOR_NOISE = False
#: 바닥을 잴 때 **무음으로 치는 기준** [dB] — 프레임 정점에서 이만큼 아래 (`_floor_shape`).
FLOOR_QUIET_DB = 45.0
#: **바닥을 파일 전체에서 잰다** (MEASUREMENTS §52.401). 구간 안의 "무음"(정점 −45 dB) 프레임에는 첫 유성 전의 클릭과
#: 숨소리가 섞여 바닥이 −63.9 dB 로 잡혔는데, 실제 녹음 바닥은 −72 dB 근처다(구간 앞 0.45 s 의 중앙 −70, 10 분위 −74).
#: 8~10 dB 과한 정상 잡음이 말 밑과 폐쇄 구간을 메워 "물 흐르는 소리" 로 들렸다. `FLOOR_REF` 는 **목표와 같은 단계**
#: (파일 전체를 잡음 제거한 신호)여야 한다. 그 신호의 가장 조용한 `FLOOR_REF_PCT` % 프레임을 쓴다.
FLOOR_REF = None
FLOOR_REF_PCT = 5.0

#: **학습률 스케줄.** "cos" = 단계마다 코사인 감쇠 한 번(lr → 0.05·lr, 예전 거동).
#: "sgdr" = 감쇠형 웜 리스타트 코사인 (Loshchilov & Hutter 2017, SGDR).
#:
#: 사용자: *"아무래도 로컬 미니멈이 너무 많은 게 문제인 듯하다."* 코사인 한 번이면 lr 이
#: 단조로 줄어 한 번 들어간 골짜기에서 나올 힘이 없다. SGDR 은 한 단계 안에서 lr 을
#: `SGDR_CYCLES` 번 다시 올려 골짜기 벽을 넘을 기회를 준다. 정점은 주기마다
#: `SGDR_DECAY` 배로 낮춘다 — 뒤 주기일수록 탐색보다 다듬기다. 최선 스냅샷(씨앗을 바꾸면
#: 지수이동평균)은 주기를 가로질러 지키므로, 재시동이 해를 망쳐도 잃지 않는다.
#: `RESEED` 의 확률적 손실과 함께 쓰면 담금질(annealed Langevin)에 가깝다.
SCHED = "cos"
SGDR_CYCLES = 3
SGDR_DECAY = 0.7
BOUND_U = 4.0

#: 위상 가중을 올리는 데 쓰는 구간 (위상 단계 예산의 비율). 0 이면 예전처럼 계단.
PHASE_RAMP = 0.0

#: **손실 항의 기울기 균형** (GradNorm 계열, Chen et al. 2018 의 단순형).
#:
#: 왜: 항마다 눈금이 제각각이라 가중이 뜻을 잃었다. 모든 항을 가중 1 로 두고 제어열에
#: 대한 기울기 크기를 재면(`yang_00000040` 0.2~0.9 s, 짧은 적합 뒤):
#:
#:     corr 59.9 %   phase 19.1 %   pulse 4.6 %   sharp 3.4 %   hnr 3.1 %
#:     subf0 2.9 %   **env_db(주 목적) 2.9 %**   sc 1.8 %   flux 1.3 %   env_sc 0.8 %
#:     **prior 0.0 % (1.4e-4)   smooth 0.0 % (8.3e-5)**
#:
#: 기본값이 `--corr 2` 이므로 실제로는 **파형 상관이 스펙트럼 포락보다 약 40 배 세게**
#: 적합을 끈다. 포먼트·스펙트럼 피팅이 열악했던 이유이고, 물리 사전은 자릿수 다섯 개
#: 아래라 사실상 없어서 `fric_gain` 이 초기 추정의 +685 %로 달아났다.
#:
#: 무엇을: 각 적합 단계 시작에서 항마다 기울기 규범 g_i 를 재고, 유효 가중을
#: `BAL_W[i] * g_포락 / g_i` 로 둔다. 그러면 BAL_W 는 **"포락 대비 영향력"** 이라는 한
#: 가지 뜻만 갖는다. 항을 켜고 끄는 것은 여전히 각 플래그(`--corr` 등)가 한다 —
#: 균형은 켜진 항의 눈금만 맞춘다.
BALANCE = False
#: `corr` 는 포락과 같은 몫이다 — 0.5 로 두었더니 끊김이 21 → 47 로 돌아왔다 (`out/L16`).
BAL_W: dict[str, float] = {
    "pulse": 0.3, "phase": 1.0, "corr": 1.0, "hnr": 0.5,
    "harmonic": 1.0,
    "sharp": 0.3, "subf0": 0.3, "flux": 0.3, "cont": 0.3,
    "prior": 0.3, "smooth": 0.2, "unvoiced": 0.5, "quiet": 0.3, "move": 1.0, "relead": 1.0,
    "gesture": 0.5, "delta": 1.0, "formant": 1.0, "ripple": 1.0,
    # 주기 안 구조는 포락 점수의 17~33 점이다 (§52.109). env 와 **같은 몫**에서 출발한다.
    "fastfit": 1.0,
    # 빗살은 포락이 못 보는 축이다 — env 와 같은 몫에서 출발한다.
    "comb": 1.0,
}
#: **균형 가중의 상한** (몫의 배수). GradNorm 은 `가중 = 몫 × ‖∇env‖ / ‖∇항‖` 인데, 목표가 **원리적으로 못 맞추는
#: 양**이면 그 항의 기울기가 0 에 가까워 분모가 사라지고 가중이 폭주한다. 실측(MEASUREMENTS §52.243): 치찰음
#: 구간에서 `flux` 가 **41.1**(모음 판은 1.22), `unvoiced` 13.5 로 부풀어 포락을 밀어냈다 — 잡음의 프레임 간 변화는
#: 난수라 맞출 수가 없기 때문이다. 그래서 몫의 `BAL_MAX` 배를 넘지 못하게 한다. 0 이면 상한 없음(예전 동작).
BAL_MAX = 20.0
#: **균형 가중을 재지 않고 정해 준다** (MEASUREMENTS §52.258). 단계 시작에 한 번 재는 기울기 비는 **상태**에 민감하다 — 같은 조건·같은
#: 씨앗에서 잠금 위상 보정만 다른 두 판이 harmonic 0.421 대 1.37 이었다. 여기 있는 항은 그 값을 그대로 쓰고, 없는 항은 예전처럼 잰다.
BAL_PRESET: dict[str, float] = {}

#: **균형에서 빼는 항** (MEASUREMENTS §51.26). GradNorm-lite 는 `가중 = 몫 × ‖∇env‖ / ‖∇항‖` 로 정하는데,
#: **제약 항**(상한 안에 있으면 값도 기울기도 0)은 분모가 0 에 가까워 가중이 폭주한다 — 실측 `L76/s101` 에서
#: 움직임 예산의 가중이 **1.23e+04** 가 됐고 포락이 85.7 → 72.8 로 무너졌다. 이 항들은 `copyfit` 이 준 세기를
#: 그대로 쓴다. (`--init` 과 `prior` 도 같은 병이다, §51.16 정정.)
#: `corr`·`pcorr` 도 같은 병이다 (§52.91). 둘 다 **무릎 아래만 무는 힌지**라 만족되면 값도 기울기도 0 이다.
#: 실측: `--pulse-lock` 을 켜면 위상이 고정되어 상관 항의 기울기가 작아지고, GradNorm 이 그것을 맞추려
#: `corr` 가중을 **0.077 → 11.9 (154 배)** 로 올려 손실을 지배했다 (M35 대 M37). 그 결과 포락이 2.4 점 낮았다.
#: 잠금은 상관 항이 걸려던 시각을 이미 기제로 강제하므로, 그 위에서 가중까지 폭주하면 이중으로 잘못된다.
BAL_FIXED = frozenset(("move", "quiet", "tail", "mprior", "relead", "gesture", "event", "artifact", "corr", "pcorr",
                       "hfenv", "voicing", "acons",
                       "hfline", "hfcomb", "hfsep", "hfband", "interharm", "cons", "vstripe", "cons_hf",
                       "pcyc", "phsync", "turb", "logbin"))
#: 다중 해상도. 켜면 `set_grid` 가 격자를 **갈아 끼우지 않고 층을 쌓는다** — 20 / 10 /
#: 5 ms 의 B-스플라인을 동시에 두고 더한다. 거친 층이 제스처를, 고운 층이 미세구조를
#: 싣고 **모든 층이 C²** 다. DMP (Ijspeert; 음성 적용은 Parrell 2019) 가 임계감쇠
#: 2 차 점끌개 위에 강제항을 국소 기저의 가중합으로 펼치는 것과 같은 구성이고,
#: 계층적 B-스플라인(Forsey & Bartels 1988)의 표준 형태이기도 하다.
#:
#: 왜 층을 쌓아야 하는가: 갈아 끼우면 고운 격자가 거친 궤적을 **다시 표현**해야 하고,
#: 그 과정에서 거친 층이 갖고 있던 권한이 흩어진다. 쌓으면 거친 층은 그대로 서 있고
#: 고운 층은 잔차만 맡는다 — 생 이중적분(`out/L7`)이 2.1 단계에서 멈춰 버린 것과
#: 같은 조건수 문제를 피한다.
MOTION_MULTI = True

#: **액션의 기저** (MEASUREMENTS §51.25). 사용자: *"아직도 이상한 움직임들이 많은데... 액션 부분을
#: 수정해야 하나? 속도/가속도로는 도저히 안 되는 거 같기도 하고."*
#:
#: `"bspline"` (예전) 은 격자점의 **값**을 자유도로 둔다. 3 차 B-스플라인이라 위치·속도·가속도가 연속이지만,
#: **매끄러움은 흔들림을 막지 못한다** — 격자점들이 번갈아 오르내리면 매끄럽게 흔들리는 궤적이 그대로
#: 표현된다. 정칙화(`MOTION_L2`, `lam_smooth`)는 그 크기를 줄일 뿐 종류를 막지는 못한다.
#:
#: `"target"` 은 조음 문헌의 표준인 **목표 근사**다 (Birkholz 2011 `papers/2011_Birkholz_model_based_
#: articulatory_trajectories`, Saltzman & Munhall 의 과제 동역학, Xu 의 qTA). 격자값은 이제 **목표**이고,
#: 궤적은 그 목표를 향한 **임계감쇠 3 차 응답**이다:
#:
#:     x(t) = (h_τ * ZOH(목표))(t),   h_τ(t) = t² e^{−t/τ} / (2τ³)  (인과적, 단위 이득, 과충격 없음)
#:
#: 그러면 목표가 바뀌지 않는 동안 궤적은 **단조로운 접근**뿐이다 — 흔들림이 표현 자체가 안 된다. 흔들리려면
#: 목표가 번갈아 바뀌어야 하고, 목표의 개수는 격자가 정한다. τ 는 그 조음기의 시간상수이고 이미 생리로
#: 잰 표가 있다(`PARAM_TAU_PHYS`: 협착 2 ms, 포먼트 5~6, 후두 15, 호흡 30). 커널이 인과적이라 궤적이
#: 목표보다 **늦게** 따라가는 것도 물리적으로 맞다.
MOTION_MODE = "bspline"
#: 목표 근사에서 τ 를 못 찾은 파라미터의 기본 시간상수 [ms].
TARGET_TAU_DEFAULT = 8.0

#: **제스처 벌점** — 이웃 목표의 차에 거는 **L1** (MEASUREMENTS §51.25). 0 이면 끈다.
#:
#: 왜 L2 가 아니라 L1 인가: 실측으로 조음의 속도는 **드문드문**하다 — 목표 녹음의 F1 은 속도 첨도 32.7,
#: 변화량의 41 % 가 상위 10 % 프레임에 몰려 있다(멈춤–이동–멈춤). 우리 적합은 첨도 1.6, 30 % 로 **가우시안과
#: 같다** — 쉬지 않고 고르게 흔든다. 사용자가 들은 "이상한 움직임" 이 이것이다. L2(`lam_smooth`)는 큰 변화를
#: 벌하므로 움직임을 **고르게 펴고**, L1 은 변화의 **개수**를 벌하므로 몇 번의 큰 전이와 긴 멈춤으로 몬다
#: (전변동 정칙화의 조각상수 해). 조음 음운론의 제스처가 바로 그 모양이다.
GESTURE_W = 0.0

#: **자음 목표의 협착 명세** (§52.487, `copyfit --art-cons W`). 음소 목표는 적합 변수라 적합기가 폐쇄 목표를 조금씩 열어 스펙트럼을 맞췄다
#: (WQB ㄲ: 폐압 사전·목표 보존 뒤에도 구강 최소 면적 0.013–0.05 → 이어 적합 0.06–0.14 cm²). /k/ 는 정의상 연구개 **폐쇄**다 — 조음
#: 음운론의 협착 정도(Browman & Goldstein)를 제약으로 건다: 폐쇄음·비음·파찰음의 폐쇄 몫(구간의 앞 20–60 %)에서 구강 최소 면적
#: ≤ `ART_CLOSE_A`, 마찰음의 가운데(20–80 %)에서 `ART_FRIC_A` 안. 벌점은 log 면적의 경계 밖 거리의 제곱. 면적은 궤적(목표 근사 뒤)에서 잰다.
ART_CONS_W = 0.0
#: **조음 앞섬** (§52.489). 목표 근사 핵 t²e^(−t/τ) 는 계단에 대해 ~2.67τ 뒤에 절반에 닿는다 — 목표 경계를 음향 경계(MFA)에 두면 조음기가
#: 음향보다 20–50 ms 늦게 움직여, 협착 명세 창에서 폐쇄가 안 이루어졌고 적합기는 경계를 30 ms 앞당겨 폐쇄를 억지로 일찍 만들었다(WRA 터짐).
#: 운동 명령은 음향보다 앞선다: 조음기마다 궤적을 `ART_LEAD`·τ 만큼 앞당겨 음향 경계가 전이의 가운데에 오게 한다. 0 이면 끈다.
ART_LEAD = 2.67
#: 연구개도 음소 목표로 (§52.489, `copyfit --art-velum`): 비음(m n ŋ ɲ) 목표 열림 `ART_VELUM_NASAL`, 다른 자음 닫힘 0, 모음·쉼은 제어열 중앙값에서.
#: 끄면 연구개는 틀마다 자유 제어 — 협착 명세가 비음 ㄴ 의 입을 막는데 연구개가 안 열려 입안 압력이 차올라 터졌다 (WRA).
ART_VELUM = False
ART_VELUM_NASAL = 0.8
ART_LABELS = None          # ART_SEGMENTS 와 나란한 음소 기호 (MFA)
NASAL_LABELS = ("m", "n", "ŋ", "ɲ")
#: 이어 적합에서 저장된 음소 목표를 버리고 MRI 자세에서 다시 출발할 음소 기호 (§52.519 — 자세 대응을 고친 음소, 예: ("ɲ",)).
ART_RESET_LABELS: tuple = ()
FF_TENSE_INIT = 0.5        # 된소리 음소의 가성대 내전 목표 초기값 (`voice_td.LARYNX`)
ART_CLOSE_A = 0.005
ART_FRIC_A = (0.03, 0.25)
#: 모음은 **열린** 조음이다 — 모음 구간 가운데(20–80 %)에서 관 전체(입술 칸 제외)의 최소 면적 ≥ `ART_VOWEL_A` (§52.491). 없으면 W02 목표가
#: 모음 중에 인두를 마찰 크기로 좁혀 (WNA ɨ: 칸 9–10 에 0.14–0.16 cm²) 모음 중 난류 터짐이 났다.
ART_VOWEL_A = 0.0          # 0 이면 끔 — `copyfit --art-vowel A` (0.25 cm²)
#: **조음 자리** (§52.507, `copyfit --art-place`). 협착 명세는 "구강 어딘가(관의 30 % → 입술)" 의 최소 면적만 봐서 ㄱ 을 입술이나 혀끝으로
#: 닫아도 통과했다. W02 MRI 자음 자세(a·i·u 맥락)를 대리 모형에 넣어 협착 칸을 쟀다 (28 칸, 0 성문 · 27 입술): 입술 27 · 치 25 · 치조 24–25 ·
#: 후치조 21–23 · 경구개 19–22 · 연구개 16–18 · 목젖 14–17. 폐쇄·마찰은 그 **자리 창 안**의 최소 면적으로 재고, 창 밖(성문 첫 칸 빼고, 창 ±1 칸
#: 여유)은 `ART_ELSE_A` 위로 열려 있어야 한다 — 다른 자리에서 닫거나 마찰을 내는 보상을 막는다 (MRI 자세의 창 밖 최소 0.13–0.5 cm²).
ART_PLACE = False
ART_PLACE_WIN = {"labial": (26, 27), "dental": (24, 26), "alveolar": (23, 26), "postalveolar": (20, 24), "alveolopalatal": (21, 26),
                 "palatal": (18, 23), "velar": (14, 19), "uvular": (13, 18)}
ART_ELSE_A = 0.1
#: 녹음 기준 협착 정도 (`ART_PLACE` 와 함께): 원본 3–10 kHz 가 이웃 모음 중앙보다 이만큼 꺼진 틀만 폐쇄, 파찰음은 이만큼 밝은 틀을 마찰로 [dB].
#: 038 실측 (이웃 모음 대비 최저): ㄲ −24 · ㅈ −21 · A ㄱ −17 · C ㄱ −11 · ㅊ −2.
ART_CLOSE_DB = 15.0
#: 모음 틀의 입술 칸 하한 [cm²] (비원순, 원순) — W02 MRI 모음 자세의 입술 면적: 원순 0.21–0.29 (y · u · o), 비원순 0.63 이상 (§52.522)
ART_VOWEL_LIP_A = (0.4, 0.15)
ROUNDED_LABELS = ("o", "u", "w", "ø", "y", "ɥ", "ɔ", "ʊ")
#: **모음의 입술 내밂 범위** [VTL LP, cm] (§52.527, `--art-cons` 와 함께). 사용자: *"입술 관련 근육은 잘 반영됐나?"* — KWF_m7 은 평순 ʌ 에서 내밂
#: +0.52 · +0.79 · +0.77 (W02 MRI 원순 o 0.65 · u 0.79 와 같은 크기), ɨ 에서 −0.98 (범위 끝) 로 관 길이를 맞췄다. W02 MRI 자세: 평순 a 0.02 · e −0.02 ·
#: i −0.05 · E: −0.17, 원순 o 0.65 · u 0.79. 평순 [lo, hi], 원순 [lo, hi]. 관에 들어가는 값(생리 평활 뒤)에 건다.
ART_VOWEL_LP = ((-0.3, 0.3), (0.4, 1.0))
ART_NASAL_CLOSE_DB = 10.0  # 비음의 폐쇄 판정 (§52.522) — 고역만, 이웃 모음 대비 꺼짐
ART_CLOSE_LF_DB = 12.0     # 폐쇄의 저역 꺼짐 (§52.511) — 038 ㄲ 폐쇄 −18 ~ −34, 개방 직후 모음 첫머리 −10 ~ −5, A ㄱ −3 ~ −5 dB
ART_FRIC_DB = 5.0
#: 폐쇄 증거가 없는 폐쇄음(모음 사이 유성 연음 등)이 자리 창 안에서 지켜야 할 최소 면적 [cm²]. 유성 유량 ~200 cm³/s 에서 0.1 cm² 의 압력 강하는
#: ρv²/2 ≈ 2 cmH2O 라 떨림이 이어진다 (0.05 이면 ≈ 9 — 폐압을 넘는다).
ART_OPEN_A = 0.1
#: 개방 뒤 (§52.514): 녹음상 마지막 폐쇄 틀에서 `ART_REL_MS` 지난 뒤로는 자리 창 안이 ≥ `ART_REL_A` cm² (파열·기식의 좁은 열림은 허용, 닫힘만 막는다).
ART_REL_MS = 5.0
ART_REL_A = 0.02
#: 녹음 기준 성문 상태 (`ART_LARYNX` · `ART_PLACE`, §52.509): 벌림 틀의 내전 상한 (0.08 → 뒤쪽 틈 ~2.2 mm), 모음 틀의 내전 하한 (0.25 → ~0.5 mm 아래).
ART_ABD_ADD = 0.08
ART_ADD_VOICED = 0.25
#: **성문 내전도 음소 목표로** (§52.507, `copyfit --art-larynx`). 조음기만 목표 근사로 묶고 내전은 틀마다 자유였다 — 성문 벌림은 음소에 딸린
#: 제스처다 (무성 자음의 벌림, 기식음의 큰 벌림, 모음의 모음; Löfqvist 1980, Browman & Goldstein 1992 의 성문 제스처). 목표 초기값은 제어열의
#: 그 구간 중앙값, τ 는 `PARAM_TAU_PHYS["adduction"]`.
ART_LARYNX = False
#: **음소 목표 조음** (§52.487, `copyfit --phoneme-targets`, `voice_td.ARTIC = "w02"`). [(t0, t1, W02 자세 이름 또는 None), …] (구간 기준 초).
#: 조음기(vtl_*)는 틀마다 적합하지 않는다 — 음소마다 목표 하나(정규화 z = (값 − 중립)/범위), 경계 시각은 정렬 ± `ART_BND_MS` 안에서 적합,
#: 궤적 = 목표 계단(경계는 폭 `ART_EDGE_MS` 시그모이드) → 조음기별 시상수의 임계감쇠 3 차 응답 (`PARAM_TAU_PHYS`, 목표 근사 모형).
ART_SEGMENTS = None
#: 음소 목표가 조음기 궤적을 낼지 (§52.522, 거짓이면 `copyfit --art-free`). 거짓이면 음소 구간은 **협착·자리·성문 명세**(`art_cons_loss`)에만 쓰고 조음기는
#: 틀별로(생리 범위·속도 한계 안에서) 푼다 — 음소마다 자세 하나인 목표 근사는 자유도가 모자라 2.2 단계가 40–60 % 에 묶였고, 목표를 끄자 명세도 함께 꺼져
#: 'n' 이 안 닫히고 ŋ · ㄲ 이 연구개 창 밖에서 닫혔다.
ART_TARGETS = True
ART_BND_MS = 30.0
ART_EDGE_MS = 2.0
ART_INIT_FROM_TRACK = False     # 참이면 모든 목표를 제어열의 구간 중앙값에서 (다듬기 패스 — 앞 판의 적합 궤적을 잇는다)

#: **스펙트럼 전이 항** (MEASUREMENTS §51.29). 목표와 합성의 **로그 멜 시간 미분**(Furui 의 회귀형 델타)을
#: 맞춘다. 0 이면 끈다.
#:
#: 왜: 손실 전수 조사에서 지금 손실은 **포먼트 전이가 20 ms 뭉개져도, 자음이 20 ms 밀려도 반응하지 않는다**
#: (env 변화 < 2 %). 반면 F0 3 %·음원 기울기 3 dB/oct 에는 55~60 % 반응한다. 즉 **정상 구간의 스펙트럼**만
#: 보고 **변화**를 안 본다. 그런데 Furui(1986)는 최대 스펙트럼 전이 구간이 음절 식별에 필요한 정보를 담는다고
#: 했고, 포먼트 전이는 조음 위치의 주 단서다. 최근 음성 향상 연구들도 자음 전이·파열·마찰 대역이 정상 모음보다
#: 언어 정보를 불균형하게 많이 담으며, 시간-주파수 가중 손실이 자음 복원을 개선한다고 보고한다.
#:
#: 델타는 ±`DELTA_K` 프레임의 회귀 계수다 (Furui 1986): Δ(t) = Σ_{k} k·x(t+k) / Σ k². 멜 프레임 간격이
#: 1.33 ms 이므로 K=8 이면 ±10.6 ms — 전이의 시간 규모다.
DELTA_W = 0.0
DELTA_K = 8
#: 전이 가중의 바닥 — 전이가 없는 칸도 이만큼은 본다 (목표 |Δ| 평균 대비).
DELTA_FLOOR = 0.2

#: **구간 균형 가중** (MEASUREMENTS §51.29). 켜면 포락 dB 항의 프레임 가중을 구간 종류(모음·마찰·비음·
#: 조용함·전이)마다 **같은 총량**이 되게 맞춘다. 0 이면 끈다(지금까지의 거동 = 길이에 비례).
#:
#: 왜: dB 항은 발화 전체의 평균이라 60 ms 짜리 마찰음(프레임의 4 %)은 묻힌다 — 실측에서 마찰 이득을 2 배
#: (+6 dB) 로 틀려도 손실이 2 % 미만으로 움직였다. 자음은 길이에 비해 정보가 많다.
SEG_BALANCE = 0.0

#: **대역 균형 가중** (MEASUREMENTS §51.29). 포락 dB 항의 멜 빈을 로그 간격 `BAND_GROUPS` 개 묶음으로 나누고
#: 묶음마다 평균한 뒤 묶음끼리 평균한다. 0 이면 예전처럼 빈 수에 비례한다.
#:
#: 왜: **소리 변화 1 dB 당** 손실 반응을 재면 음원 기울기 40.1, F0 30.5, F1 22.2 인데 **F2 8.3, F3 6.3,
#: 포먼트 전이 4.7, 자음 타이밍·레벨 0** 이다. 같은 크기의 소리 변화인데 반응이 0~40 배로 벌어진다 — 멜 빈이
#: 저역에 몰려 있고(멜 척도) 고역 오차가 그 수에 묻히기 때문이다. 음운 정체는 F2·F3 와 전이가 지고 있다.
BAND_BALANCE = 0.0
BAND_GROUPS = 8

#: **포먼트 자리 항** (MEASUREMENTS §51.29). 대역마다 목표와 합성의 **스펙트럼 무게중심**(Bark)을 맞춘다.
#: 0 이면 끈다.
#:
#: 왜: 손실에는 "포먼트" 라는 개념이 없다. 전대역 스펙트럼 거리는 **바꾼 빈의 수**에 지배되므로, 전 대역을
#: 조금씩 바꾸는 F0·음원 기울기가 봉우리 하나를 옮기는 F2 보다 항상 크게 잡힌다 — 소리 변화 1 dB 당 반응이
#: 기울기 40.1 / F0 30.5 / F1 22.2 대 **F2 8.3 / F3 6.3 / 전이 4.7** 이다. 대역 가중을 바꿔도 이 순서는 안
#: 뒤집힌다(실측: 대역 균형을 켜면 F2 9.0 → 7.2 로 오히려 준다). 모음의 정체는 포먼트 **자리**가 지므로
#: 자리를 직접 재는 항을 따로 둔다.
#:
#: 무게중심은 Chistovich 의 중심 무게 효과(3~3.5 Bark 안의 포먼트 쌍은 하나로 합쳐 들린다)와 같은 좌표이고,
#: 미분 가능하며 봉우리 찾기처럼 불연속이 아니다. 대역은 F1·F2·F3 의 탐색 범위다.
FORMANT_W = 0.0
FORMANT_BANDS = ((200.0, 1100.0), (800.0, 3000.0), (2000.0, 4500.0))

#: **공진 돌출 항** (MEASUREMENTS §51.33). 대역마다 **봉우리 − 골** 깊이를 목표와 맞춘다. 0 이면 끈다.
#:
#: 왜: 사용자는 *"원본은 공진이 매우 잘 느껴져서 자극적으로 딱 청취가 되는데, 우리가 만든 거는 퍼진
#: 소리 같고 산란이 많이 일어난 듯한 목소리, 가까이에서 듣는 느낌이 아니야"* 라고 했다. 켑스트럼
#: 포락(리프터 2 ms)에서 포먼트 봉우리와 이웃 골의 차를 재면 그대로 나온다 (`out/_tmp/prominence.py`,
#: 목표 / 합성 중앙 [dB]):
#:
#:     `L86/s040`  F1 17.7 / 19.9 (**+2.3**)   F2 9.5 / 7.5 (**−2.0**)   F3 8.7 / 5.7 (**−3.0**)
#:     `L86/s101`  F1 11.8 / 15.2 (+3.4)       F2 8.0 / 6.5 (−1.5)       F3 8.3 / 5.9 (−2.4)
#:
#: **F1 은 과하게 솟고 F2·F3 은 눌린다.** 3 dB 넘게 얕은 창이 F2 30~34 %, F3 38~43 % 고 최악은
#: −14.6 / −18.2 dB 다. 세 가지 청취 지적이 모두 여기로 모인다 — 공진이 안 서면 모음 정체가 흐려지고
#: (어눌함), 그 대역의 잡음 바닥이 상대적으로 도드라져 기식이 **따로** 들리고, 전체가 퍼져 들린다.
#:
#: 손실이 이것을 못 보는 이유는 §51.29 와 같다 — 멜 빈이 저역에 몰려 있어 소리 변화 1 dB 당 반응이
#: F1 22.2 / F2 8.3 / F3 6.3 이다. 적합기는 빈이 많은 F1 쪽에 정확도를 쓴다. 그래서 **깊이를 직접
#: 재는 항**을 따로 둔다. 자리를 재는 `FORMANT_W` 와 짝이다 (자리 + 깊이 = 공진).
#:
#: 부드러운 최대·최소는 log-sum-exp 다 — `PROM_BETA` [1/dB] 가 클수록 날카롭다. 유성 프레임만 본다.
#: **고역 물결 손실** `HFRIP_W` (MEASUREMENTS §51.53). 포락 손실은 **멜 띠** 위에서 재는데, 12 kHz 의 멜 띠는
#: 폭이 516 Hz, 17 kHz 는 750 Hz 다. 그런데 목표 고역 구조의 반높이 폭은 **281 Hz** 다 —
#: 즉 **포락 손실은 고역의 마루와 골을 한 띠 안에서 평균 내 버려 아예 못 본다.**
#:
#: 그래서 영점·마루 손잡이를 켜 줘도 적합기가 쓸 이유가 없었다. `M14` 에서 깊이의 중앙값이
#: **0.02** (거의 꺼짐) 이고 상한에 닿는 프레임이 0 % 였다. 사용자: *"영점 극도 더 강화해야 해."*
#: 손잡이의 범위가 아니라 **손실이 문제**다 — mix=1 이면 −18 dB 까지 파진다 (§51.51).
#:
#: 재는 법: 2048 점 스펙트럼의 dB 를 주파수 축에서 **띠통과**한다 — 좁은 평활(`HFRIP_NARROW_HZ`)
#: 이 F0 빗살(200 Hz 간격)을 지우고, 넓은 평활(`HFRIP_WIDE_HZ`)을 빼면 1~2 kHz 주기의 물결만
#: 남는다. 프레임마다 그 rms 를 재서 목표보다 **모자란 만큼**을 문다. 넘치는 쪽도 1/4 로 문다 —
#: 안 그러면 잡음의 무작위 요동까지 좇아 과적합한다.
HFRIP_W = 0.0
HFRIP_BAND = (4000.0, 16000.0)
HFRIP_NARROW_HZ = 400.0
HFRIP_WIDE_HZ = 1600.0
HFRIP_FFT = 2048
HFRIP_OVER = 0.25

#: **위상 단계의 조기 종료** (MEASUREMENTS §51.43). 최선값이 이만큼 정체하면 멈춘다. 0 이면 끈다.
#:
#: 왜: 위상 단계는 400 반복(한 판의 29 %)인데, 적합기가 `best` 스냅샷을 복원하므로 이 단계가 망친
#: 것은 어차피 버려진다. 실측(`M1/s040`): 2.4 단계 끝 89.47 / 82.74 -> 위상 단계 끝 85.79 / 66.90,
#: 그런데 최종 보고는 89.73 / 82.95 다. 즉 400 반복이 통째로 버려졌다.
#:
#: **그런데 60 은 틀린 값이었다** (§51.52). 위상 단계는 펄스 정렬을 갈아엎느라 **먼저 크게 파고
#: 나중에 갚는다**. `M1/s101` 의 궤적:
#:
#:     [0] 86.93 -> [100] **79.98** -> [200] 85.94 -> [250] 88.33 -> [399] **88.72**
#:
#: 손실도 1.334 -> 1.705 -> 1.268 -> 1.197 로 같은 모양이다. 회복에 **200 반복**이 걸리는데 60 에서
#: 끊으면 갚는 것을 영영 못 받는다 — `M13`·`M14`·`M15` 가 61 회에서 멈춰 `M1` 보다 1.7~3.1 점을
#: 잃었다. 사용자: *"속도 개선은 나중에 할 테니, 네가 할 수 있는 최대로 정확한 모델을 만들어."*
#: 그래서 **끈다**. 되살릴 거라면 250 아래로는 두지 않는다.
PHASE_PATIENCE = 0

#: **고역만 따로 적합하는 단계** (MEASUREMENTS §51.44). 반복 수. 0 이면 끈다.
#:
#: 사용자: *"고역만 따로 피팅을 해야 할 수준이다. 고역 피팅 매커니즘을 싹다 엎고 다시해라."*
#: 움직임 단계가 끝난 뒤 제어 궤적을 얼리고 **고역 전역 손잡이만**(`self.hf`: 고역 EQ·고역 극 위치·
#: 대역폭·이상와 영점·MVF·음원 EQ) `HF_STAGE_FMIN` 위의 멜 띠만 보는 손실로 적합한다. 궤적을 안
#: 건드리므로 저역을 망칠 수 없고, 열이 하나도 안 는다.
#: **펄스 이벤트 층** (MEASUREMENTS §51.45). 관측이 급히 움직이는 자리마다 **계단 하나**를 얹는다.
#: 계단은 `EVENT_FADE_MS` 안에 다 오르므로 B-스플라인 격자·τ·출발점 평활의 제약을 받지 않는다.
#:
#: 사용자: *"원래는 잠잠히 있다가 순간적으로 움직여야 하는 무브먼트가 많았는데, 우리가 괜히
#: 정규화를 걸어서 그게 스무스해지면서 인지 가능한 왜곡으로 변질된 게 아닌가 … 이벤트 파라미터가
#: 필요한가 생각을 하게 되네."* 실측이 그대로다 — 우리 기계의 최소 10~90 % 상승은 31 ms 인데
#: (격자 16 + τ 11 + 출발점 평활 24, 제곱합) 목표의 F2 는 가장 빠른 1 % 에서 **4~5 ms** 만에 20 %
#: 를 움직인다. 4 ms 도약은 자음 경계로 지나가지만 31 ms 글라이드는 미끄러짐으로 들린다.
#:
#: Each observed control/event pair gets one coefficient, not an event-by-control
#: matrix. Unchanged controls receive no event freedom.
EVENT_W = 0.0
#: **`front_len` 과 `obstacle` 이 빠져 있었다** (§51.54). 치찰음의 공명은 포먼트가 아니라 **앞공동**이
#: 만든다 (`_front_cavity`: f_p = c/4L_front). 그런데 `front_len` 은 `--slow front_len=20` 으로 σ 20 ms
#: 가우시안에 묶여 있고 계단 층도 없었다. 실측(`M1/s040` 0.69 s 의 /s/): 목표의 2.5~16 kHz 무게중심이
#: 690 -> 700 ms 에 6424 -> **11358 Hz** 로 한 프레임에 뛰는데, 우리는 5508 -> 6281 -> 7231 -> 9869 로
#: **40 ms** 에 걸쳐 미끄러진다. 사용자가 되풀이해 말한 *"치찰음 포먼트가 실제 음원보다 늦게 적용되고"*
#: 가 이것이다 — 붙잡기 램프(§51.48)를 고쳐도 남았던 이유다.
EVENT_PARAMS = ("f1", "f2", "f3", "f4", "a_c", "tract_gain", "front_len", "obstacle")
#: 계단의 **10~90 % 상승 시간** [ms]. 사용자: *"이벤트 파라미터의 페이드를 1-2 ms 정도로 바꿔야 할 듯"*,
#: 그리고 앞서 *"펄스라고 해서 불연속적으로 움직이게 하라는 게 아니야. 다만, 페이드인/아웃이 매우 짧은
#: 그런 형태겠지."* 로지스틱의 척도는 여기서 나온다 — s = 상승 / (2·ln 9).
#: 그 뒤 *"이벤트 파라미터를 더 강화해야 할 거 같고(더 세고 빠른 펄스)"* 라 해서 1.0 으로 줄인다 —
#: 1 ms 프레임에서 계단이 두 프레임에 다 오르는 값이고, 그보다 빠르면 격자에서 그냥 불연속이다.
EVENT_FADE_MS = 1.0
#: Nearby changes merge within each control, without merging reversals.
EVENT_MIN_GAP_MS = 12.0
#: 덩어리의 **총 도약**(로그 비)이 이보다 작으면 이벤트를 두지 않는다 — 진짜 분기만 잡는다.
#: 0.12 -> 0.08 ("더 세고 빠른 펄스"): 12 % 도약은 한 반음 반이라 자음 경계의 작은 것들을 놓쳤다.
EVENT_MIN_JUMP = 0.08
#: **이벤트를 액션 신호로 쓰면 강하게 벌한다** (MEASUREMENTS §51.45). 사용자: *"만약 펄스 신호를
#: 액션 신호로 구현하려는 조짐이 보이면 강한 벌점을 부과해."*
#:
#: 둘로 막는다. (1) 이벤트 하나의 크기를 그 자리에서 **관측된 도약**의 `EVENT_CAP_REL` 배 안으로
#: 가둔다 — 관측이 안 뛴 자리에서는 계단도 못 선다. (2) L1 을 걸어 쓰지 않는 이벤트는 0 으로 간다.
#: 벌점이라 `BAL_FIXED` 에 넣어 균형에서 뺀다(§51.26 의 1.2e+04 폭주를 피한다).
#: **벌점은 대칭이어야 한다** (사용자: *"액션을 이벤트에 피팅하거나 이벤트를 액션으로 피팅하거나
#: 둘 다 벌점이 부여되는 대칭성이 있는지도 봐야 해"*). 한쪽만 걸면 최적화가 반대쪽으로 새기만 한다 —
#: 실제로 이벤트 크기만 벌했더니 적합기가 이벤트를 안 쓰고 **부드러운 층으로 완만하게** 올렸다.
#:
#:   (가) 이벤트 -> 액션: 이벤트 크기가 그 자리의 관측 도약 × `EVENT_CAP_REL` 를 넘으면 벌한다.
#:   (나) 액션 -> 이벤트: **이벤트 자리에서 부드러운 층이 움직이면** 벌한다. 도약은 계단이 져야 한다.
EVENT_PEN_W = 80.0
#: 1.2 -> 2.0. 상한은 **관측된 도약의 몇 배까지 계단이 설 수 있는가**다. 관측 궤적 자체가 분석기의
#: 평활을 거쳐 이미 완만해져 있으므로, 목표의 진짜 도약은 관측보다 크다 — 위 무게중심 실측이 그
#: 증거다(관측 궤적은 40 ms 에 걸쳐 오르는데 소리는 10 ms 에 뛴다). 2 배까지 허용한다.
EVENT_CAP_REL = 2.0
EVENT_L1 = 0.05
#: (나) 의 창 반폭 [ms] 과 공짜 폭 — 이 안에서 부드러운 층이 이만큼 넘게 움직이면 벌한다.
EVENT_RAMP_MS = 10.0
EVENT_RAMP_FREE = 0.20
#: (나) 쪽 가중 — 같은 비율의 위반이면 (가) 와 비슷한 값이 되도록 맞춘다.
EVENT_RAMP_W = 3.0

HF_STAGE_ITERS = 0
HF_STAGE_FMIN = 4000.0

PROM_W = 0.0

#: **배음 사이 결맞음** (MEASUREMENTS §52.362, §52.381). 사용자가 여러 번 보고한 갈라짐의 자를
#: 그대로 손실로 옮긴 것이다 — 주기마다 배음 진폭 [dB] 을 뽑고, 배음마다 시간 평균을 뺀 뒤
#: **배음 사이 상관**을 목표의 그것과 맞춘다 (`engine/coherence.py`).
#:
#: 왜 필요한가: `hcorr` 는 (크기·위상) × 배음 58 × 주기 974 의 자유 배열이라 배음 사이 상관이
#: 0.000 이다. 한 성대에서 나온 소리는 모든 배음이 같은 폐압·같은 주기로 함께 출렁이는데
#: (공통 운명, Bregman 1990) 그 단서가 부서져 **크기는 맞는데 소리가 갈라진다.** 지금 손실에는
#: `--hcorr-tv`(주기 방향)·`--hcorr-ktv`(배음 방향)·`--hcorr-gap`(주기 안 배치)만 있고
#: **"58 개 배음이 함께 출렁이는가" 를 직접 무는 항이 없다.**
#:
#: **최소화가 아니라 일치다** — 목표보다 높아지는 것도 틀렸다 (§52.371 의 `--hcorr-gap` 1.0 이
#: 지나쳐 나빠진 전례). 그래서 목표값과의 차를 제곱으로 문다.
#:
#: 자와 같은 양을 보는지는 합성 정답으로 확인했다 (`tests/engine/test_coherence.py`,
#: `scripts/diag/harmcoh_check.py`): 참 상관과 최대 0.10, 진단 자와 최대 0.046, 순서는 정확하다.
HCOH_W = 0.0
#: 고역 둘을 더 둔다 (MEASUREMENTS §51.43). 손실이 4.8 kHz 위의 **구조**를 한 번도 요구하지 않아서
#: 적합기가 고역 극의 대역폭을 범위의 넓은 끝(×2.43)까지 밀어 평평하게 만들고 있었다 — 켑스트럼
#: 포락의 봉우리−골이 5~10 kHz 에서 목표 11.8 dB 대 합성 6.6 dB 다. 극을 새로 풀 것이 아니라
#: **이미 있는 전역 손잡이(`hf_log_bw`)에게 구조를 요구**하면 된다. 열이 하나도 안 는다.
PROM_BANDS = ((250.0, 1300.0), (900.0, 3000.0), (2000.0, 4800.0),
              (4800.0, 10000.0), (10000.0, 16000.0))
PROM_BETA = 3.0

#: **파라미터별 가장 고운 층** [ms] (움직임 모드). 여기 적힌 파라미터는 그보다 고운 층에서
#: 움직이지 못한다 — 그 층의 해당 열을 0 으로 둔다.
#:
#: 왜: 사용자가 들은 치찰음의 "원인 모를 노이즈" 를 `out/L7` 만 피했다. `L7` 은 매개화가
#: 너무 세서 점수는 무너졌지만, 마찰 구간에서 소음 계열 파라미터가 1 ms 마다 제 값의
#: 몇 %씩 움직이는지 재면 (s040 / s101):
#:
#:     fric_gain   L6 19.28/9.79   **L7 0.18/0.01**   L18 5.32/5.23
#:     tract_gain  L6 19.84/11.75  **L7 0.08/0.07**   L18 5.81/3.37
#:     aspiration  L6  5.57/7.36   **L7 0.14/0.08**   L18 0.87/0.96
#:     a_c (필터)   L6  8.30/9.89   **L7 1.74/2.67**   L18 3.20/4.53
#:
#: **`L7` 은 잡음 이득이 고요하면서 필터(`a_c`)는 여전히 움직였다.** 사용자가 앞서 말한
#: "치찰음은 노이즈는 그대로 방출하고 필터만 움직여야 한다" 가 거기서 우연히 실현돼
#: 있었다. 그 성질만 가져온다 — 잡음 이득은 거친 층(20 ms, B-스플라인이면 ~25 Hz
#: 위를 죽인다)에서만 움직이고, 필터는 고운 층까지 그대로 쓴다. 전부 얼린 `L7` 은
#: s101 에서 오히려 나빴으므로(마찰 150~400 Hz 변조 5.76 배) 전부를 가져오지는 않는다.
MOTION_SLOW: dict[str, float] = {}

#: **파라미터별 시상수** [ms] — 적합기가 더하는 **보정분**을 파라미터마다 그 조음기의
#: 관성으로 저역통과한다 (가우시안, σ = 시상수). 비면 끈다.
#:
#: 왜: 사용자 — *"사실상 모든 파라미터에 각각 존재해야 하는 거 알지? 거의 모든 파라미터가
#: 궤적이 각각 다를 거 아니야."* 궤적 자체는 이미 파라미터마다 따로다 (`w` 의 열마다
#: B-스플라인). 그런데 **빠르기의 상한이 공유**돼 느려야 할 것들이 빨라졌다. 궤적 변조
#: 에너지의 90 %가 드는 주파수 (`yang_00000040`, 분석 초기값 → 적합 `out/L25`):
#:
#:     p_sub      4.9 → **31.7 Hz**   (6.5 배 — 폐압이 30 Hz 로 흔들린다)
#:     adduction  6.3 → **16.9 Hz**
#:     f3/f4     20   → 35~38 Hz
#:
#: 분석이 잰 출발점(`u0`)은 그대로 두고 **보정분만** 거른다 — 측정된 세부(예: f0 의 실제
#: 흔들림)는 보존하고, 적합기가 다른 것을 흉내 내려고 느린 변수를 떠는 것만 막는다.
#: 가우시안 σ 의 −3 dB 모서리는 약 0.13/σ 이므로 30 ms ≈ 4.4 Hz, 15 ms ≈ 8.8 Hz,
#: 5 ms ≈ 27 Hz, 2 ms ≈ 66 Hz. 값은 생리에서 잡았다 (호흡 < 후두 < 조음 < 폐쇄·개방).
PARAM_TAU_MS: dict[str, float] = {}

#: **출발점(`u0`)도 조음 대역으로 거른다** — `MOTION_SLOW` 에 적힌 파라미터의 분석 궤적을 가우시안
#: σ = `BASE_SMOOTH` × (그 파라미터의 가장 고운 층 ms) 로 저역통과한다. 0 이면 끈다.
#:
#: 왜: `MOTION_SLOW`·`PARAM_TAU_MS` 는 적합기가 더하는 **보정분**만 묶는다. 제어는 `u0 + 보정분` 이라
#: 분석 궤적의 프레임별 흔들림은 그대로 지나간다. 실측(`L48/s101`, 유성 조각의 궤적 스펙트럼): 분석
#: F2·F3·F4 의 움직임 에너지 가운데 **22~30 % 가 20~60 Hz** 에 있고(포먼트 추적기의 잡음), 20 ms 층만
#: 허용한 적합 궤적도 29~40 % 로 그대로다. 그 흔들림이 종속 가지의 고역 수준(∝ ΠF_k²)을 흔들어 모음
#: 고역 5~12 kHz 의 20~60 Hz 변조를 목표보다 +12.4 dB(s101)·+8.4 dB(s040) 크게 만들었다 — 음원 쪽
#: (배음 위상 분산·기식·지터·시머)을 0 으로 해 다시 렌더해도 ±0.5 dB 안이었고, F1~F4·대역폭만 σ 9 ms
#: 로 펴면 +3.9 / +3.3 dB 로 내려갔다(`out/_tmp/ablate.py`). 20 ms 층의 가우시안 대응은 σ ≈ 0.45 × 20 ms
#: (20 Hz 에서 −5 dB, 40 Hz 에서 −22 dB). 폐쇄·개방 시각을 쥔 `BASE_SMOOTH_KEEP` 은 거르지 않는다.
BASE_SMOOTH = 0.0
#: **출발점을 생리 시상수로 거른다** (§52.536, `copyfit --base-tau`). `BASE_SMOOTH` 는 `MOTION_SLOW` 의 열만 보는데, 기본 조리법에서 출발점의
#: 빠른 흔들림은 그 밖의 열에 있었다 — `out/fit1/init` (반복 0) 의 생리 모서리 두 배 위 에너지 몫: `p_sub` 7.6 %, `bw1–4` 2.6–6.1 %,
#: `rd_offset` 4.1 %, `tension` 4.0 %, `adduction` 3.3 %. 보정분은 `PARAM_TAU_MS` 로 걸러지지만 출발점은 그대로 지나가 적합 판에 남는다.
#: 여기 적힌 열의 출발점을 `PARAM_TAU_PHYS` 의 같은 σ 로 거른다. 관측이 빠른 틀(`_fast_obs_mask`)은 지킨다. 폐쇄·개방 시각을 쥔 `a_c`·
#: `oral_open`·`tract_gain` 과 `f0_target`, 포먼트 자리는 거르지 않는다.
BASE_TAU = False
BASE_TAU_PARAMS = ("bw1", "bw2", "bw3", "bw4", "p_sub", "rd_offset", "tension", "adduction")

#: 마찰 소스 고역 절벽(`FricationNoise.log_lp_ratio`, 정점의 1.6~6.4 배)을 파일 전역으로 적합한다.
#: 그동안 "적합기가 건드리지 않는 내부값" 이었다 — 그러면 치찰음 12~19 kHz 수준을 폐압·협착(제트 속도)
#: 으로만 움직일 수 있어, 폐압을 느리게 묶은 판에서 치찰음이 7~22 dB 어두워졌다(§51.8).
FRIC_LP_FIT = False
BASE_SMOOTH_KEEP = frozenset(("a_c", "oral_open", "f0_target"))
PARAM_TAU_PHYS: dict[str, float] = {
    "a_c": 2.0,                                              # 폐쇄·개방은 빠르다
    "f0_target": 3.0,                                        # 억양 (지터는 따로 있다)
    "f1": 6.0, "f2": 5.0, "f3": 5.0, "f4": 5.0,              # 포먼트 전이
    "front_len": 8.0, "obstacle": 8.0,
    "bw1": 10.0, "bw2": 10.0, "bw3": 10.0, "bw4": 10.0,
    "ap1_f": 10.0, "ap2_f": 10.0, "ap3_f": 10.0,             # 올패스 위상차 — 성도 성질이라 대역폭과 같은 빠르기
    "ap1_r": 10.0, "ap2_r": 10.0, "ap3_r": 10.0,
    "nasal_f": 10.0, "nasal_f2": 10.0, "nasal_f3": 10.0, "nasal_z": 10.0,
    "velum": 15.0, "oral_open": 15.0, "back_leak": 15.0,
    "adduction": 15.0,                                       # 후두
    "vf_ta": 20.0,                                           # 갑상피열근 (몸체–덮개 성대, §52.500)
    "rd_offset": 20.0, "tilt": 20.0, "tract_gain": 20.0,
    "p_sub": 30.0,                                           # 호흡
    "jitter": 30.0, "shimmer": 30.0,
    # ── 아래는 **조음기가 아니다** (MEASUREMENTS §52.237·240). 보정 극·영점은 스펙트럼을 다듬는 자유도이지
    # 조음이 아니므로 조음기보다 느려야 한다. 실측: 이 열들이 25 ms 보다 빠르게 떠서 고역 배음마다 측파대를
    # 만들고(배음 사이 HIR −3 dB) 세로선을 만든다(세로 결맞음 0.52 대 목표 0.11). 43 열을 전부 얼리면 둘 다
    # 사라지고(0.041 · HIR 1.72), 30 ms 평활로는 절반만 잡힌다. 그래서 **40 ms** 로 둔다.
    **{f"aux{k}_mix": 40.0 for k in range(1, 8)},
    **{f"azr{k}{s_}": 40.0 for k in (1, 2, 3) for s_ in ("_mix", "_f")},
    **{f"hzr{k}{s_}": 40.0 for k in (1, 2, 3) for s_ in ("_mix", "_f")},
    **{f"hzp{k}{s_}": 40.0 for k in (1, 2, 3, 4) for s_ in ("_mix", "_f")},
    # 잡음 이득과 곁가지는 조음을 따라간다 — 후두·조음기 눈금.
    "aspiration": 15.0, "fric_gain": 15.0, "front_q": 10.0,
    "lat_mix": 15.0, "lat_bw": 10.0, "nasal_damp": 15.0, "nasal_gain": 15.0,
    # 관 모드의 조음 손잡이 (§52.475). 없으면 1 ms 마다 떨어 포먼트가 1 ms 당 50~185 Hz 흔들렸다(갈라짐 σ 0.49).
    **{f"art{k}": 8.0 for k in range(1, 7)},
    # 고차 조음 성분(art7–10, 공간 해상도 ~1.5 cm)은 느리게 — 8 ms 로 두었더니 패스를 거듭하며 4–8 kHz 공명이 모음 한가운데서 고리 모양으로
    # 떠돌았다 (§52.481, 스펙트로그램). 고역 공명의 자리는 잡되 주기마다 쫓지는 못하게.
    **{f"art{k}": 25.0 for k in range(7, 11)}, "c_place": 8.0,
    # 성도 길이 = 후두 높이·입술 내밂 — 느리다. 15 ms 로 두었더니 모음 안에서 ±0.6 cm 를 4–30 Hz 로 흔들어 모든 공명(특히 고역)이 물결쳤다
    # (§52.481, 스펙트로그램 A5_c2·B5_b2). 60 ms.
    "tract_len": 60.0,
    "pulse_shift": 10.0,                                     # 펄스 위상 연속 보정 (§52.480) — 분석기 편향은 천천히 움직인다
    "fold_skew": 15.0,                                       # 속도 몫 — 후두 눈금 (§52.481)
}
#: 위 표에서 **조음기가 아닌** 열 — 보정 극·영점, 올패스, 잡음 이득·곁가지 (§52.237·240 에서 더했다).
#: `copyfit --tau-spectral-off` 가 이것만 빼서 그 전의 표로 되돌린다. 포락이 3 점 떨어진 원인을 가르는 절제용이다 (§52.256).
PARAM_TAU_SPECTRAL = frozenset(
    [f"aux{k}_mix" for k in range(1, 8)]
    + [f"{p_}{k}{s_}" for p_ in ("azr", "hzr", "hzp") for k in (1, 2, 3) for s_ in ("_mix", "_f")]
    + ["hzp4_mix", "hzp4_f"]
    + [f"ap{k}{s_}" for k in (1, 2, 3) for s_ in ("_f", "_r")]
    + ["aspiration", "fric_gain", "front_q", "lat_mix", "lat_bw", "nasal_damp", "nasal_gain"])
#: **표에 없는 파라미터의 시상수** [ms]. 0 이면 끈다 (= 지금까지의 동작: 상한 없음).
#:
#: 이 표는 나중에 더한 파라미터를 못 따라왔다 — `aux*`·`azr*`·`hzr*`·`hzp*`·`lat_bw`·`voice_gain`
#: 이 **하나도 없어서** `--param-tau` 를 켜도 그것들만 빠르기 상한 없이 자유롭게 떤다.
#: 실측(§52.176, `p96b` 제어열의 150~400 Hz 흔들림 [dB]):
#:
#:     hzr2_f 87.6  hzp2_f 86.9  hzp1_f 86.3  hzr1_f 85.0  hzp3_f 84.0  hzr3_f 77.6  lat_bw 70.8
#:     ---- 여기서 28 dB 떨어진다 ----
#:     f4 42.7  f0_target 42.2  bw3 36.7  voice_gain 36.2
#:
#: `hz*_f` 는 0~20 Hz 대비 19 dB 밖에 차이가 안 난다 — **사실상 백색**이다. 5~6 kHz 의 극이
#: 300 Hz 로 떨면 그 치마가 3~4.5 kHz 에 측파대를 만들고, 그것이 그 대역 초과 비주기성의
#: 가장 큰 몫이다(절제로 +2.6 dB).
#:
#: **표에 없으면 무제한이 되는 구조가 잘못이다.** 새 파라미터가 늘 표보다 먼저 들어온다.
#: 그래서 못 찾으면 **가장 느린 조음기 쪽**으로 떨어지게 한다 — 틀려도 안전한 쪽이다.
#: (`TARGET_TAU_DEFAULT` 8.0 이 이미 같은 뜻으로 쓰이고 있다, 2093 줄.)
PARAM_TAU_PHYS_DEFAULT = 15.0     # 표에 없는 손잡이는 후두 눈금으로 — 새 손잡이가 무제한으로 떨지 않게 (§52.475)

#: **올패스 위상차 체인의 씨앗** (MEASUREMENTS §52.227). `tract._allpass` 와 제어열 `ap1~3_f/_r` 은 예전부터 있었지만
#: 분석이 0 으로 두고 `DEFAULT_PARAMS` 에도 없어 **한 번도 켜진 적이 없다.** 게다가 `ap*_f` 는 로그 파라미터라
#: 초기값 0 이면 `self.names` 에서 아예 빠진다 — 목록에 넣어도 안 걸리는 구조였다.
#:
#: 이것이 필요한 까닭: 실측된 배음 위상 오차는 **주기마다 흔들리는 몫**과 **배음마다 늘 같은 몫**으로 갈리는데
#: (§52.227), 후자가 `p96b` 에서 −13~−32°, `ihncod` 에서 H1 −18.5° · H7~H8 −17~−20° 다. 고정분은 **결정적인 위상
#: 응답 오차**이므로 올패스로 정확히 지울 수 있다. 그리고 올패스는 `|H| ≡ 1` 이라 **크기를 하나도 안 건드린다** —
#: 이 저장소의 다른 손잡이들이 모두 크기·시간 구조를 조이며 위상을 대가로 치른 것과 달리(§52.226) 직교한다.
ALLPASS_SEED_HZ: tuple[float, ...] = (700.0, 2000.0, 4000.0)
ALLPASS_SEED_R = 0.30

#: **펄스 동기 배음 위상** (MEASUREMENTS §52.222·228). 포락 점수는 창이 5.3 ms(주기의 1.8 배)뿐이라 사실상 배음 위상의
#: 자다 — 실측 위상 오차 12° 를 목표에 넣으면 포락이 94.93 % 로 우리 94.60 과 거의 같다. 그런데 기존 `phase_loss` 는
#: **절대 STFT 위상**을 재서, 펄스 시각의 ±0.021 ms 흔들림만으로도 3 kHz 에서 23° 가 생긴다. 그 흔들림은 귀에도 자에도
#: 무해한데 항은 그것을 고치려 들어 판이 −2.4~−4.4 점 났다.
#:
#: 그래서 **펄스를 원점으로** 잰다. 주기마다 `PHSYNC_M` 칸으로 다시 뜬 뒤 k·F0 의 복소 진폭을 내고, 목표와의 교차
#: 스펙트럼에서 **주기 공통 군지연을 먼저 빼고** 남은 위상만 문다(공통 지연 = 펄스 표시의 흔들림). 크기는 안 본다 —
#: 무게로만 쓴다. `PHSYNC_FMAX` 위는 `glottis.HARM_PHASE_JIT` 이 설계상 난수라 보지 않는다 (§52.223).
PHSYNC_W = 0.0
#: **칸별 dB 제곱 오차** (MEASUREMENTS §52.412). 포락 점수와 기존 dB 항은 5.3 ms · 멜 격자라 배음을 분해하지 못하고, 고역 멜 대역
#: (1~2 kHz 폭)에서 빗살과 같은 크기의 잡음을 같은 에너지로 평균한다 — 흐릿함·배음 자리의 잡음을 원리적으로 못 본다(§52.411).
#: 그래서 1024 창(21 ms, 배음 분해)에서 **프레임 × FFT 칸마다** dB 차를 제곱한다. 대역마다 제 바닥(그 대역 원본 최대 −60 dB).
#: 원본이 **배음인 칸**은 칸 그대로, **잡음인 칸**은 5 칸 × 3 프레임 평활 통계끼리 — 잡음 실현을 칸마다 맞추라고 하면
#: 적합기가 결정적 보정으로 잡음 모양을 베낀다(`hcorr` 가 잡음 발생기가 된 길). 가르는 무게는 목표의 조화 우세도 `_harm_w`.
LOGBIN_W = 0.0
LOGBIN_FFT = 1024
LOGBIN_FLOOR_DB = 60.0
LOGBIN_BANDS: tuple[tuple[float, float], ...] = ((0.0, 1000.0), (1000.0, 3000.0), (3000.0, 6000.0), (6000.0, 10000.0),
                                                  (10000.0, 16000.0), (16000.0, 20000.0))
PHSYNC_K = 12              # H1~H12
PHSYNC_M = 64              # 주기당 다시 뜨는 표본 (2·K 보다 넉넉히)
PHSYNC_FMAX = 1500.0       # 이 위 배음은 **주기마다** 재지 않는다 (0 이면 전부 잰다)
PHSYNC_LEVEL_PCT = 40.0    # 조용한 주기는 뺀다
PHSYNC_MEAN_FMAX = 6000.0
PHSYNC_MEAN_W = 1.0        # 고정분 항의 상대 무게 (주기별 항을 1 로 놓았을 때)
#: **기본 시상수를 씌우지 않을 파라미터.** `voice_gain` 은 성문 배음만의 **주기별** 이득이다 —
#: 그것이 잡는 시머는 F0 율(347 Hz)의 변조라 15 ms 로 묶으면 항이 존재할 이유가 없어진다.
#: "빠를 자격은 조음기에만" 이라는 원칙의 예외이고, 그 까닭은 조음기가 아니라 **성문**이기 때문이다.
PARAM_TAU_PHYS_FAST = frozenset(("voice_gain",))
#: `--slow-noise` 가 쓰는 묶음.
SLOW_NOISE = {"fric_gain": 20.0, "tract_gain": 20.0, "aspiration": 20.0}
#: `--noise-global` 이 쓰는 묶음. **잡음 이득을 시간 제어가 아니라 화자 눈금으로 만든다.**
#:
#: 왜: 사용자가 들은 "10 kHz 위 전부가 배음 없이 평탄하다" 는 **마찰(앞공동) 잡음이 모음
#: 구간으로 샌 것**이었다. 유성 프레임 10 kHz 위에서 경로별로 재면(`out/L21`) 앞공동이
#: 성문 경로보다 9~17 dB 위였고, `fric_gain` 을 끄면 s101 의 10~12 kHz 가 −12.6 dB 로
#: 떨어진다. 엔진은 이미 물리로 막고 있다 — 마찰 구동이 레이놀즈 수와 `0.1 / a_c` 로
#: 게이트되어 열린 모음은 조용하다. 그런데 그 위에 **시간에 따라 움직이는** `fric_gain` 을
#: 곱하니, 손실이 고역을 보게 되자(밴드별 바닥) 적합기가 물리가 줄인 마찰을 이득으로
#: 되살려 가장 싼 광대역 채움재로 썼다.
#:
#: `fric_gain`·`aspiration` 은 분석 초기값이 전 구간 상수(1.0)이고 `GLOBAL_PARAMS` 라
#: 전역 오프셋이 있다. 움직임 층에서 그 열을 **모든 층에서** 막으면 정확히 전역 스칼라 하나가
#: 된다 — 마찰의 시간 구조는 협착(`a_c`)·레이놀즈 수·방전이 정하고, 적합기는 `a_c` 를
#: 움직여 마찰을 켜고 끈다. 사용자가 처음부터 말한 "노이즈는 물리대로, 필터만 움직인다" 다.
#: `tract_gain` 은 음절 따라 레벨이 변해야 하므로 느리게만 둔다.
#: 비강 가지의 이득(`nasal_damp`·`nasal_gain`)도 느리게 둔다 — 마찰 이득을 막았더니
#: 적합기가 그리로 옮겨 가 `nasal_damp` 가 60 Hz 위에 80 %를 두었다 (`out/L22/s040`).
#: 이득 계열은 전부 느리거나 전역이어야 하고, 빨리 움직일 자격은 조음기에만 있다.
