# 프레임별 적합의 **한 걸음 크기**(raw 좌표). Adam 은 기울기 크기와 무관하게 lr 만큼
# 걷기 때문에, 모든 파라미터에 같은 lr 을 주면 F0 가 한 걸음에 11 % 씩 뛴다(실측:
# 그래서 2 단계가 52 % -> 8 % 로 무너졌다). 성문 위상은 누적합이라 F0 를 한 프레임
# 흔들면 그 뒤 전부가 흔들린다. 물리적으로 말이 되는 분해능으로 걸음을 잘라 준다.
STEP: dict[str, float] = {
    # **음향 곡률로 잰 값** (MEASUREMENTS §51.27). Adam 은 좌표마다 기울기를 정규화하므로 한 걸음의 크기가
    # |Δw| ≈ η 로 일정하고, raw 좌표에서는 |Δu| = η·STEP 이다. 최적점 근처에서 L ≈ L* + ½ΣH_ii Δu_i² 이므로
    # **한 걸음이 손실을 바꾸는 양은 ½H_ii η² STEP_i²** — 즉 Adam 은 기울기 규모만 고르게 할 뿐 곡률
    # 불균형은 고치지 못한다. 균형 조건은 STEP_i ∝ 1/√H_ii 다.
    #
    # 같은 raw 걸음 δ=0.025 에서의 |Δ포락| D_i 를 두 파일에서 재어(기하평균) H_ii ∝ D_i 를 얻었다. D 가 δ²
    # 에 비례함을 확인했다(δ 를 2 배 하면 3.2~4.6 배, 이론 4). 잰 값: f0 5.18, adduction 1.83, f1 0.80,
    # voice_gain 0.69, p_sub 0.69, tract_gain 0.22, f2 0.18, bw1 0.036, f3 0.014, rd_offset 0.008.
    #
    # **줄이기만 한다.** 둔감한 쪽의 걸음을 키우면 손실은 안 나빠지지만 그 파라미터가 표류한다 — 식이
    # 예측한 f3 의 표류가 100 걸음에 62 % 였다. 그래서 STEP_i = min(예전, C/√D_i) 만 적용한다.
    # 효과(한 걸음의 |Δ포락|): adduction 1.586 → 0.083, p_sub 2.622 → 0.149, voice_gain 1.503 → 0.191.
    # 표류 예측도 함께 줄어든다: p_sub 이 100 걸음에 1.84 → 0.50 cmH₂O (관측된 떠돎이 ±2~3 이었다).
    "f0_target": 0.10, "adduction": 0.17, "p_sub": 0.27, "voice_gain": 0.27, "tract_gain": 0.48,
    "f1": 0.25, "f2": 0.25, "f3": 0.3, "f4": 0.3,
    "bw1": 0.5, "bw2": 0.5, "bw3": 0.5, "bw4": 0.5,
    "velum": 0.5, "oral_open": 0.5, "a_c": 0.5, "front_len": 0.3,
    "lat_mix": 0.5, "lat_bw": 0.3,
    "jitter": 0.5, "shimmer": 0.5,
    "nasal_f": 0.3, "nasal_f2": 0.3, "nasal_f3": 0.3, "nasal_z": 0.3,
}
STEP_DEFAULT = 1.0

