def _stft(x: torch.Tensor, n: int, win: torch.Tensor) -> torch.Tensor:
    return torch.stft(x, n_fft=n, hop_length=n // 4, win_length=n, window=win,
                      center=True, return_complex=True, pad_mode="reflect")


def mel_bank(n_fft: int, fs: float, n_mels: int = 80,
             fmin: float = 60.0, fmax: float | None = None) -> torch.Tensor:
    """삼각 멜 필터뱅크 (n_mels, n_fft//2+1). 포락 일치율용."""
    fmax = fmax or fs / 2
    def hz2m(f): return 2595.0 * np.log10(1.0 + f / 700.0)
    def m2hz(m): return 700.0 * (10.0 ** (m / 2595.0) - 1.0)
    m = np.linspace(hz2m(fmin), hz2m(fmax), n_mels + 2)
    f = m2hz(m)
    bins = np.fft.rfftfreq(n_fft, 1.0 / fs)
    w = np.zeros((n_mels, len(bins)))
    for i in range(n_mels):
        lo, ct, hi = f[i], f[i + 1], f[i + 2]
        left = (bins - lo) / max(ct - lo, 1e-9)
        right = (hi - bins) / max(hi - ct, 1e-9)
        w[i] = np.clip(np.minimum(left, right), 0.0, None)
        s = w[i].sum()
        if s > 0:
            w[i] /= s
    return torch.as_tensor(w, dtype=torch.float32)


@dataclass
class FitReport:
    env: float                         # 포락 일치율 % (멜 크기의 스펙트럼 수렴도)
    fine: float                        # 정밀 일치율 % (선형 다해상도)
    db: float                          # 멜 대역 평균 |오차| dB — 가장 읽기 쉬운 값
    per_size: dict[int, float]
    loss: float
    iters: int
    history: list[tuple[float, float]] = field(default_factory=list)
    #: 대역별 포락 일치율 % — `REPORT_BAND_EDGES` 로 가른다 (§52.70). 비면 안 쟀다는 뜻이다.
    bands: dict[str, float] = field(default_factory=dict)

    def __str__(self) -> str:
        per = " ".join(f"{n}:{v:.1f}" for n, v in sorted(self.per_size.items()))
        bd = ("  대역 " + " ".join(f"{k} {v:.1f}" for k, v in self.bands.items())) if self.bands else ""
        return (f"포락 {self.env:5.2f}%  정밀 {self.fine:5.2f}%   평균오차 {self.db:.2f} dB  "
                f"(손실 {self.loss:.4f}, {self.iters} 회)  [{per}]{bd}")



def ih_fold_positions(pulses, fs: float, n: int, m: int = IH_M):
    """주기 j 를 m 표본으로 다시 뜰 **표본 위치** (주기 수, m). 반환 (i0, frac, 주기 길이 [s]).

    위치 = (p_j + (q/m)·(p_{j+1} − p_j))·fs. 선형 보간 가중은 미분 가능하게 쓰도록 떼어 준다.
    """
    p = np.asarray(pulses, dtype=np.float64)
    per = np.diff(p)
    pos = (p[:-1, None] + per[:, None] * (np.arange(m)[None, :] / m)) * fs
    pos = np.clip(pos, 0.0, n - 1.000001)
    i0 = np.floor(pos).astype(np.int64)
    return i0, pos - i0, per


def resonator_db(F: torch.Tensor, B: torch.Tensor, freq: torch.Tensor, fs: float) -> torch.Tensor:
    """엔진의 디지털 공진기(`tviir.resonator_coeffs`, DC 이득 1) 크기응답 [dB] — **닫힌 식**.

    F, B : (..., P)  극 중심·대역폭 [Hz]
    freq : (..., K)  볼 주파수 [Hz]
    반환 : (..., K)  P 개 극의 dB 합
    """
    r = torch.exp(-math.pi * B / fs)
    a1 = -2.0 * r * torch.cos(2.0 * math.pi * F / fs)
    a2 = r * r
    b0 = 1.0 + a1 + a2
    w = (2.0 * math.pi * freq / fs).unsqueeze(-2)                     # (..., 1, K)
    a1, a2, b0 = a1.unsqueeze(-1), a2.unsqueeze(-1), b0.unsqueeze(-1)  # (..., P, 1)
    re = 1.0 + a1 * torch.cos(w) + a2 * torch.cos(2.0 * w)
    im = a1 * torch.sin(w) + a2 * torch.sin(2.0 * w)
    den = (re * re + im * im).clamp_min(1e-30)
    return (10.0 * torch.log10((b0 * b0).clamp_min(1e-30) / den)).sum(-2)


def _codec_lowpass(fc: float, fs: float, taps: int | None = None) -> np.ndarray:
    """차단 `fc` 의 선형 위상 FIR 저역통과 (창 방식, Blackman). `fc` 가 나이퀴스트 이상이면 **항등**이다."""
    taps = CODEC_TAPS if taps is None else taps
    if fc >= 0.5 * fs - 1.0:
        h = np.zeros(taps)
        h[taps // 2] = 1.0
        return h
    m = np.arange(taps) - taps // 2
    wc = 2.0 * math.pi * fc / fs
    h = np.sinc(m * (wc / math.pi)) * (wc / math.pi) * np.blackman(taps)
    return h / h.sum()


def restore_hcorr(fitter, z) -> str:
    """저장된 **주기별 배음 보정**을 되살린다 (MEASUREMENTS §52.295).

    `copyfit.py` 는 `hcorr`·`hcorr_scale`·`hcorr_c0` 를 `_track.npz` 에 넣어 왔지만 **아무도 읽지
    않았다.** 그래서 `--init --no-fit` 재렌더가 보정 없는 소리를 냈다 — 같은 판이 포락 98.78 대
    74.58 로 갈렸다. `restore_pulse_state` (§52.249) 와 같은 종류의 구멍이다.

    `hcorr` 는 `_hcorr_prepare` 가 만드는데 그것이 `_hc_c0` 를 **복원된 펄스 위상**에서 잡으므로
    이 함수는 반드시 `restore_pulse_state` **뒤에** 부른다. 모양이 다르면 겹치는 만큼만 옮기고
    그 사실을 문자열로 돌려준다 — 조용히 틀린 소리를 내지 않기 위해서다.
    """
    if "hcorr" not in getattr(z, "files", ()):
        return "주기별 배음 보정: 저장된 값 없음"
    a = np.asarray(z["hcorr"], dtype=np.float64)
    if a.size == 0:
        return "주기별 배음 보정: 저장된 값 없음 (크기 0)"
    if HCORR_K <= 0:
        return f"주기별 배음 보정: 저장값 {a.shape} 이 있으나 HCORR_K = 0 이라 안 쓴다"
    fitter._hcorr_prepare()
    if fitter.hcorr is None:
        return f"주기별 배음 보정: 저장값 {a.shape} 이 있으나 이번 판에서 못 켰다"
    dst = fitter.hcorr
    grew = ""
    if a.shape[1] > dst.shape[1] or a.shape[2] > dst.shape[2]:
        # **저장된 만큼 자리를 넓힌다.** `_hc_c0` 도 파일 것으로 되돌리므로 색인이 어긋나지 않는다.
        # 여기서 자르면 판의 끝 주기들이 통째로 보정 없이 울린다.
        shp = (2, max(a.shape[1], dst.shape[1]), max(a.shape[2], dst.shape[2]))
        grew = f"  (자리를 {dst.shape[1]}×{dst.shape[2]} 에서 {shp[1]}×{shp[2]} 로 넓혔다)"
        dst = torch.zeros(shp, dtype=dst.dtype, device=dst.device, requires_grad=True)
        fitter.hcorr = dst
    k, c = a.shape[1], a.shape[2]
    with torch.no_grad():
        dst.zero_()
        dst[:, :k, :c] = torch.as_tensor(a, dtype=dst.dtype, device=dst.device)
    if "hcorr_scale" in z.files:
        fitter._hc_scale = float(np.asarray(z["hcorr_scale"]).reshape(-1)[0])
    if "hcorr_c0" in z.files:
        fitter._hc_c0 = int(np.asarray(z["hcorr_c0"]).reshape(-1)[0])
    return (f"주기별 배음 보정 복원: H1~H{k} × 주기 {c} 개, 눈금 {fitter._hc_scale:.4g}" + grew)


def restore_pulse_state(fitter, z) -> str:
    """저장된 **펄스 잠금 상태**를 되살린다 — 재렌더가 적합 당시 소리를 재현하게 (MEASUREMENTS §52.249).

    적합은 목표 폐쇄 시각에서 샘플률 펄스 위상을 만들고(`_build_pulse_phase`), 전역 오프셋 `pulse_phi0` 를 훑고,
    단계마다 `refine_pulse_phase` 로 그 위상을 고친다. 예전에는 `pulse_phi0` 만 저장해서 `--init --no-fit` 재렌더가
    **보정 전 위상**으로 소리를 냈고, 적합 당시와 파형 상관 0.72, 시간 어긋남 −2.75 ms, 1.5~3 kHz 위상 정합률
    91.7 % → −73.3 % 로 달라졌다.

    z: `np.load` 결과처럼 키로 읽히는 것. 반환: 한 줄 보고. 옛 판(키 없음)이면 경고 문구를 돌려준다.
    """
    msgs = []
    files = set(getattr(z, "files", None) or list(z.keys()))
    if "pulse_phi0" in files:
        with torch.no_grad():
            fitter.pulse_phi0.fill_(float(np.asarray(z["pulse_phi0"])))
        fitter._phi0_restored = True        # `fit_staged` 의 오프셋 훑기가 이 값을 덮지 않게 (§52.466)
        msgs.append(f"pulse_phi0 {float(fitter.pulse_phi0.item()):+.3f} rad")
    pp = np.asarray(z["pulse_phase"], dtype=np.float64) if "pulse_phase" in files else np.zeros(0)
    cur = getattr(fitter, "_pulse_phase", None)
    if pp.size and cur is not None:
        n = int(cur.shape[-1])
        if pp.size >= n:
            fitter._pulse_phase = torch.as_tensor(pp[None, :n], dtype=torch.float64, device=cur.device)
        else:
            fitter._pulse_phase = torch.as_tensor(np.pad(pp, (0, n - pp.size), mode="edge")[None, :],
                                                  dtype=torch.float64, device=cur.device)
        msgs.append(f"보정된 펄스 위상 {pp.size} 표본")
    elif cur is not None:
        msgs.append("**보정된 펄스 위상이 저장돼 있지 않다** (옛 판) — 재렌더가 적합 당시와 어긋날 수 있다 (§52.249)")
    if PULSE_REGULAR and getattr(fitter, "_pulse_phase", None) is not None:
        ph0 = fitter._pulse_phase[0].detach().cpu().numpy()
        tgt = fitter.target[0].detach().cpu().numpy().astype(np.float64)
        ph1, rep = regularize_pulse_phase(ph0, tgt, float(fitter.fs))
        fitter._pulse_phase = torch.as_tensor(ph1[None, :], dtype=torch.float64, device=fitter._pulse_phase.device)
        msgs.append(f"구동 박자 정규화 (§52.530): 원본 Praat 주기점 {rep.get('npt', 0)} 개 · 마디 {rep.get('n', 0)} 개 (덮음 {100 * rep.get('cover', 0):.0f} %), "
                    f"지금 위상의 빠른 흔들림 {rep.get('fast_rms', 0):.3f} 주기 rms 를 버림")
    return "펄스 잠금 상태 복원: " + (", ".join(msgs) if msgs else "해당 없음")


def detrend_quadratic(R: torch.Tensor, x: torch.Tensor, w: torch.Tensor, ridge: float = 1e-6):
    """행마다 x 의 2 차식을 가중 최소제곱으로 빼고 나머지를 돌려준다. R, x, w : (W, K)."""
    Bm = torch.stack([torch.ones_like(x), x, x * x], -1)               # (W, K, 3)
    Bw = Bm * w.unsqueeze(-1)
    G = Bw.transpose(-1, -2) @ Bm + ridge * torch.eye(3, dtype=R.dtype, device=R.device)
    rhs = Bw.transpose(-1, -2) @ R.unsqueeze(-1)
    beta = torch.linalg.solve(G, rhs)
    return R - (Bm @ beta).squeeze(-1)

def sib_edge_weights(mask: np.ndarray, edge_frames: float) -> np.ndarray:
    """치찰 표지 `mask` 의 연속 구간마다 양 끝 `edge_frames` 틀 안에서 0 → 1 로 오르는 올림 코사인 무게 (`SIB_PRIOR_EDGE_MS`).

    끝 틀(구간 밖과 맞닿은 틀)이 가장 가볍고, 가장자리에서 `edge_frames` 틀 들어간 곳부터 1 이다. 짧은 구간은 양쪽 경사가 겹쳐 가운데도 1 에 못 닿는다.
    """
    m = np.asarray(mask, bool)
    w = m.astype(np.float64)
    if edge_frames <= 0 or not m.any():
        return w
    d = np.diff(np.r_[0, m.astype(int), 0])
    for s, e in zip(np.flatnonzero(d == 1), np.flatnonzero(d == -1)):
        k = np.arange(s, e)
        dist = np.minimum(k - s, e - 1 - k) + 0.5                   # 가장 가까운 끝까지 [틀]
        r = np.clip(dist / edge_frames, 0.0, 1.0)
        w[s:e] = 0.5 - 0.5 * np.cos(np.pi * r)
    return w


class CopySynthFitter:
    def __init__(self, engine, target: np.ndarray, sr: int, init: ControlTrack,
                 params: tuple[str, ...] = DEFAULT_PARAMS,
                 lam_smooth: float = 3e-3, lam_prior: float = 1e-4,
                 lam_l1: float = 0.0,
                 phase_weight: float = 0.0, pulse_weight: float = 1.0,
                 n_mels: int = 48, device: str = "cpu",
                 room_ir: np.ndarray | None = None,
                 harmonic_weight: float | None = None,
                 locked_constants: tuple[str, ...] = (),
                 initial_gain_db: float | None = None,
                 initial_pulse_phi0: float = 0.0,
                 formant_band: dict[str, tuple[float, float]] | None = None):
        # **엔진도 같은 장치로 옮긴다** (MEASUREMENTS §52.90). 예전에는 적합기 텐서만 옮기고 엔진은 CPU 에 뒀다 —
        # 그래서 `--device cuda` 는 성문 표(`rd_grid`)에서 장치 불일치로 죽었다. 옵션이 있는데 동작하지 않았다.
        self.eng = engine.to(device) if hasattr(engine, "to") else engine
        self.hop = engine.cfg.hop
        self.fs = engine.cfg.sample_rate
        global _WARP_FS
        _WARP_FS = float(self.fs)                    # 구동 위상 비틀기의 매끈함 σ 를 표본으로 (§52.532)
        self.device = device
        self.lam_smooth, self.lam_prior = lam_smooth, lam_prior
        self.lam_l1 = float(lam_l1)
        self.phase_weight = phase_weight
        self.pulse_weight = pulse_weight
        self.harmonic_weight = float(HARMONIC_W if harmonic_weight is None else harmonic_weight)
        if not math.isfinite(self.harmonic_weight) or self.harmonic_weight < 0:
            raise ValueError("harmonic_weight must be finite and nonnegative")
        if initial_gain_db is not None and not math.isfinite(initial_gain_db):
            raise ValueError("initial_gain_db must be finite")
        if not math.isfinite(initial_pulse_phi0):
            raise ValueError("initial_pulse_phi0 must be finite")
        constants = engine_parameters(engine)
        self.locked_constants = frozenset(locked_constants)
        unknown = self.locked_constants - constants.keys()
        if unknown:
            raise ValueError(f"Unknown locked constants: {sorted(unknown)}")
        self.harmonic = None
        self._bal: dict = {}          # 균형 모드의 유효 가중 (비면 원래 가중)
        self._collect = False         # True 면 loss() 가 항을 self._terms 에 모은다
        self._termw = {}              # 그때의 항별 무게 (진단 `term_breakdown`)
        self._terms: dict = {}
        self.room_ir = (None if room_ir is None else
                        torch.as_tensor(np.asarray(room_ir, np.float32), device=device))
        self._last_pulse = float("nan")
        self._last_flux = float("nan")
        self._flux_db = None
        self.flux_live = None
        self._mel_err = self._mel_raw_db = self._harm_db = None
        self.sizes = list(FFT_SIZES)

        # 녹음의 원래 나이퀴스트. **손실에서 그 위를 보면 안 된다.**
        # 44.1 kHz 녹음을 48 kHz 로 올리면 22.05~24 kHz 가 정확히 비어 있고, 게다가
        # 그 아래 16~22 kHz 도 녹음 장비의 안티에일리어싱이 만든 값이다. 그걸 목표로
        # 두면 적합기가 "저 위를 비워라" 를 물리 파라미터로 달성하려 들고, 그 왜곡이
        # 8~12 kHz 를 10 dB 어둡게 만들었다(실측: 남성 /사/).
        # 손실 압축을 거친 음원은 sr 이 48 kHz 여도 대역이 잘려 있다 (orphan 코퍼스
        # 실측: 전부 20 kHz 에서 급락). 그 빈 대역을 손실이 보는 것은 원리적으로 나쁘다.
        #
        # **그런데 자동 검출은 채택하지 않는다.** `turbulence.effective_bandwidth` 를
        # 만들어 재 봤더니 녹음에서는 정확했지만(20.1 kHz) 합성 신호의 자연스러운 고역
        # 롤오프를 컷으로 오인했다(9.96 → 조건을 두 번 조인 뒤에도 11.1 kHz). 잘못 자르면
        # **진짜 신호를 버린다** — 20~21.6 kHz 를 안 보는 이득보다 손해가 크다.
        # 그 함수는 진단용으로 남기고, 여기서는 표본화율만 쓴다.
        self.f_max = min(0.5 * float(sr), 0.5 * self.fs) * 0.90
        if sr != self.fs:
            from scipy.signal import resample_poly
            g = math.gcd(int(sr), int(self.fs))
            target = resample_poly(target, self.fs // g, int(sr) // g)
        # **분석이 붙여 준 부가 정보(성문 펄스·유성 마스크)를 같이 옮긴다.** 새로
        # ControlTrack 을 만들면서 빠뜨리면 조용히 기본값(빈 배열)이 되고, 마찰 이득
        # 보정이 아무 일도 안 하게 된다 (실측: 남 /사/ 무성부가 −40.8 dB 인 채로 시작).
        self.track = ControlTrack(init.values.copy(), init.frame_ms, list(init.events),
                                  pulses=np.asarray(getattr(init, "pulses", np.zeros(0))).copy(),
                                  voiced=np.asarray(getattr(init, "voiced",
                                                            np.zeros(0, dtype=bool))).copy(),
                                  fricative=np.asarray(getattr(init, "fricative",
                                                               np.zeros(0, dtype=bool))).copy(),
                                  bursts=np.asarray(getattr(init, "bursts",
                                                            np.zeros(0, dtype=int))).copy(),
                                  sibilant=np.asarray(getattr(init, "sibilant",
                                                              np.zeros(0, dtype=bool))).copy())
        self.track["residual_mix"] = 0.0
        n = self.track.n_frames * self.hop
        t = np.zeros(n)
        t[:min(n, len(target))] = target[:min(n, len(target))]
        self.target = torch.as_tensor(t, dtype=torch.float32, device=device).unsqueeze(0)

        if SIB_ABDUCT > 0.0 and np.asarray(getattr(self.track, "sibilant", np.zeros(0))).size:
            # 치찰 틀의 내전 초기값을 낮춘다 (§52.481) — 분석의 발성 문턱 바닥이 유성 꼬리가 걸친 ㅅ 틀까지 0.35 이상으로 올려 두었다.
            sib = np.asarray(self.track.sibilant, bool)[:self.track.values.shape[0]]
            ia = INDEX["adduction"]
            self.track.values[:sib.size, ia] = np.where(sib, np.minimum(self.track.values[:sib.size, ia], SIB_ABDUCT),
                                                        self.track.values[:sib.size, ia])
        if PSUB_MAX is not None:
            ip = INDEX["p_sub"]
            v = self.track.values[:, ip].copy()
            k = 0.95 * float(PSUB_MAX)
            n_over = int((v > k).sum())
            # 0.95 × 상한 위만 자른다 — 그 아래는 그대로 (예전 tanh 는 상한 아래 값까지 판마다 다시 눌러 이어 갈수록 폐압이 깎였다: n5 → n6 11.3 → 10.0)
            self.track.values[:, ip] = np.minimum(v, k)
            print(f"  말소리 폐압 상한 {PSUB_MAX:g} cmH2O (단단히): 출발 판 폐압 상한 넘은 틀 {n_over} 개를 눌렀다 "
                  f"(중앙 {np.median(v[v > 1]):.1f} → {np.median(self.track.values[:, ip][v > 1]):.1f})", flush=True)
        for nm, (lo, hi) in SRC_BOUNDS.items():
            sp = PARAMS[nm]
            if not (sp.lo <= lo < hi <= sp.hi) or sp.log:
                raise ValueError(f"Source bound for {nm} must narrow its linear control range {sp.lo}..{sp.hi}: {(lo, hi)}")
            i = INDEX[nm]
            m = 0.025 * (hi - lo)
            v = self.track.values[:, i]
            n_out = int(((v < lo + m) | (v > hi - m)).sum())
            self.track.values[:, i] = np.clip(v, lo + m, hi - m)
            print(f"  음원 범위 {nm} [{lo:g}, {hi:g}] (단단히): 출발 판 {n_out} 틀을 안으로 눌렀다", flush=True)
        base = torch.as_tensor(self.track.values, dtype=torch.float64, device=device)
        self.base = base
        self.names = [p for p in params
                      if not (PARAMS[p].log and float(base[:, INDEX[p]].abs().min()) == 0.0)]
        self.cols = torch.tensor([INDEX[p] for p in self.names], device=device)
        self.specs = [PARAMS[p] for p in self.names]
        if PSUB_MAX is not None:
            import dataclasses as _dcp
            self.specs = [(_dcp.replace(sp, hi=float(PSUB_MAX)) if nm == "p_sub" else sp) for nm, sp in zip(self.names, self.specs)]
        if SRC_BOUNDS:
            import dataclasses as _dcs
            self.specs = [(_dcs.replace(sp, lo=float(SRC_BOUNDS[nm][0]), hi=float(SRC_BOUNDS[nm][1])) if nm in SRC_BOUNDS else sp)
                          for nm, sp in zip(self.names, self.specs)]
        bands = FORMANT_BAND if formant_band is None else formant_band
        if bands:
            # **포먼트마다 제 구역을 준다** (MEASUREMENTS §51.38).
            import dataclasses as _dc
            self.specs = [(_dc.replace(sp, lo=max(sp.lo, bands[nm][0]),
                                       hi=min(sp.hi, bands[nm][1]))
                           if nm in bands else sp)
                          for nm, sp in zip(self.names, self.specs)]
            if any(sp.lo >= sp.hi for sp in self.specs):
                raise ValueError("Formant bands must overlap the control bounds")
        u0 = torch.stack([self._to_raw(base[:, INDEX[p]], sp)
                          for p, sp in zip(self.names, self.specs)], 1)
        if MOTION and BASE_SMOOTH > 0.0 and MOTION_SLOW:
            u0 = self._smooth_base(u0)
        if BASE_TAU:
            u0 = self._smooth_base_tau(u0)
        self.u0 = u0.detach()
        self.scale = torch.tensor([STEP.get(n, STEP_DEFAULT) for n in self.names],
                                  dtype=torch.float64, device=device)
        self.n_frames = u0.shape[0]
        self.stride = 1
        self.w = torch.zeros_like(u0).requires_grad_(True)   # (Tc, P_fit) 격자 위 증분
        self.w_coarse: list = []        # 다중 해상도의 굳은 거친 층들 (여전히 학습된다)
        self.d = torch.zeros(len(self.names), dtype=torch.float64, device=device,
                             requires_grad=True)          # 파라미터별 전역 오프셋
        self.w_ev = None
        if EVENT_W > 0.0:
            self._build_events(device)
        # 과도음 이벤트별 로그 이득 (`TRANSIENT_FIT`). 이벤트가 없으면 만들지 않는다.
        self.tr_gain = None
        _ne = len(getattr(self.track, "events", ()) or ())
        if TRANSIENT_FIT and _ne > 0:
            self.tr_gain = torch.zeros(_ne, dtype=torch.float64, device=device,
                                       requires_grad=True)
            print(f"  과도음 이득 적합: 이벤트 {_ne} 개", flush=True)
        # 파열별 개방 속도 log R [cm²/s] (`RELEASE_PRIOR_W`, voice.RELEASE_RATE)
        self.rel_log_r = None
        from . import voice as _voice_rr
        _rb = np.asarray(getattr(self.track, "bursts", np.zeros(0, dtype=int)), int)
        if _voice_rr.RELEASE_RATE and _rb.size:
            self.rel_log_r = torch.full((int(_rb.size),), math.log(RELEASE_R0), dtype=torch.float64, device=device,
                                        requires_grad=True)
            print(f"  파열 개방 속도: 파열 {_rb.size} 곳 ({', '.join(str(int(x)) for x in _rb)} 틀), 초기 {RELEASE_R0:g} cm²/s, "
                  f"창 −{_voice_rr.RELEASE_PRE_MS:g}~+{_voice_rr.RELEASE_POST_MS:g} ms", flush=True)
        self.d_mask = torch.tensor([1.0 if n in GLOBAL_PARAMS else 0.0
                                    for n in self.names], dtype=torch.float64,
                                   device=device)
        self.prior_w = torch.tensor([PRIOR_W.get(n, 1.0) for n in self.names],
                                    dtype=torch.float64, device=device)
        # 자유 포먼트만. F5~F8 은 `_formant_tracks` 가 c/(2L) 사다리로 만들므로
        # 순서가 구조적으로 보장된다 — 벌점을 걸 대상이 아니다.
        self.f_idx = [i for i, n in enumerate(self.names)
                      if len(n) == 2 and n[0] == "f" and n[1].isdigit()]
        self.log_gain = torch.zeros(1, dtype=torch.float64, device=device,
                                    requires_grad=True)
        self.rv_log_rt = torch.full((1,), math.log(LR_RT0), dtype=torch.float64, device=device, requires_grad=True)
        self.vb_log_g = torch.full((1,), VB_LOG_G0, dtype=torch.float64, device=device, requires_grad=True)
        self.rv_g_db = torch.full((1,), LR_G0_DB * math.log(10.0) / 20.0, dtype=torch.float64, device=device,
                                  requires_grad=True)          # 이름과 달리 **로그 진폭** (Adam 걸음이 dB 로 너무 작았다)
        if initial_gain_db is not None:
            with torch.no_grad():
                self.log_gain.fill_(initial_gain_db * math.log(10.0) / 20.0)

        # 목표의 성문 폐쇄 시각 -> 샘플 색인 (있으면 위상 고정에 쓴다)
        pl = np.asarray(getattr(init, "pulses", np.zeros(0)), dtype=np.float64)
        pl = pl[(pl >= 0.0) & (pl * self.fs < n - 1)]
        self.pulse_idx = torch.as_tensor((pl * self.fs).astype(np.int64), device=device)
        self.pulse_phi0 = torch.full((1,), initial_pulse_phi0, dtype=torch.float64,
                                     device=device, requires_grad=True)
        self._pulse_phase = self._build_pulse_phase() if PULSE_LOCK else None
        self._hcorr_raw = None     # (2, K, C) 주기별 배음 보정 — `HCORR_K` 참조
        self._hc_u = self._hc_v = None   # 저차원 인수 — `HCORR_RANK` 참조
        self._hc_c0 = 0
        self._hc_scale = 1.0
        self.wins = {k: torch.hann_window(k, device=device) for k in FFT_SIZES}
        # 포락은 **짧은 창**에서 잰다. 1024 (21 ms) 는 F0 240 Hz 의 하모닉을 분해하므로
        # 그 위의 멜은 포락이 아니라 하모닉 정렬을 재게 된다.
        # 256 (5.3 ms, 분해능 187 Hz) 이면 하모닉이 뭉개져 순수한 포락이 남는다.
        self.mel = mel_bank(MEL_FFT, self.fs, n_mels, fmax=self.f_max).to(device)
        # 선형 SC 도 같은 상한을 쓴다.
        self.bin_max = {k: int(math.ceil(self.f_max / (self.fs / k))) + 1 for k in FFT_SIZES}
        # 목표의 조화/잔차 분해. 위상 항(조화부만 본다)과 크기 항(난류부는 기대
        # 스펙트럼으로 본다)이 같은 것을 쓰므로 한 번만 만든다.
        # **η 를 먼저 정한다.** 아래의 모든 크기·로그가 이 값을 쓴다. 목표의 평균
        # 크기에 비례시키므로 녹음 레벨과 무관하게 같은 뜻을 갖는다. 여기 한 번만
        # 쓰는 `.abs()` 는 `no_grad` 안이라 기울기가 없다.
        with torch.no_grad():
            _m = _stft(self.target, MEL_FFT, self.wins[MEL_FFT]).abs().mean()
            self.mag_eta = float(MAG_ETA_REL * _m.clamp_min(1e-12))
        self._har_res = self._decompose_target()
        self._floor_amp = None
        if FLOOR_NOISE:
            self._floor_amp = self._floor_shape()
        with torch.no_grad():
            self._harm_w = {k: self._harmonic_weight(k) for k in FFT_SIZES}
            self._noise_w = {k: (1.0 - self._harm_w[k]) for k in FFT_SIZES}
            self._sm_frames = {k: max(1, int(round(NOISE_EXPECT_MS
                                                   / (1000.0 * (k // 4) / self.fs))))
                               for k in FFT_SIZES}
            raw = {k: self._cabs(_stft(self.target, k, self.wins[k]))[:, :self.bin_max[k]]
                   for k in FFT_SIZES}
            self.tgt_S = {k: self._expect(v, k) for k, v in raw.items()}
            self.tgt_M = self.mel[:, :self.tgt_S[MEL_FFT].shape[1]] @ self.tgt_S[MEL_FFT]
            self.tgt_Mdb = self._db(self.tgt_M)
            self.db_floor = float(self.tgt_Mdb.max()) - DB_RANGE
            self.db_floor_band = self._band_floor(self.tgt_Mdb)
            if self._floor_amp is not None and FLOOR_REC_MARGIN_DB > 0.0:
                self._lower_floor_to_recording()

        self._prepare_corr()
        self.prior_mask = torch.ones_like(self.u0)
        if self.harmonic_weight > 0:
            from .harmonic import HarmonicMagnitudeLoss
            f0 = np.asarray(self.track["f0_target"], dtype=np.float64)
            voiced = self.track.voiced if self.track.voiced.size else f0 > 0
            fricative = (self.track.fricative if self.track.fricative.size
                         else np.zeros_like(f0, dtype=bool))
            self.harmonic = HarmonicMagnitudeLoss(
                self.target[0].cpu().numpy(), self.fs, self.hop, f0, voiced, fricative,
                fmax=min(HARM_FMAX, self.f_max), device=device, pulses=self.track.pulses)
            covered = torch.as_tensor(self.harmonic.coverage, device=device)
            for i, name in enumerate(self.names):
                if name in ("bw1", "bw2", "bw3", "bw4"):
                    # Smoothed-envelope BW is an initializer, not an observation.
                    # Keep the temporal/physical constraints, not this biased anchor.
                    center = self.base[:, INDEX[f"f{name[2:]}"]]
                    in_band = (center > 0) & (center <= min(self.harmonic.fmax, HARM_PRIOR_FMAX))
                    self.prior_mask[:, i] = (~(covered & in_band)).to(self.prior_mask.dtype)
        # **화자의 고역 손실은 적합 대상이다.** `log_extra_bw`(고차 극 보정의 대역폭
        # 배율)와 `log_front_bw`(앞공동 대역폭 배율)는 `nn.Parameter` 인데 어느
        # 옵티마이저 목록에도 없어서 영원히 0(= 배율 1)에 머물렀다 (§37.3 이 지적).
        # 고차 극이 고정 위치라 화자의 고역을 맞출 수단이 사실상 이 둘뿐인데 그마저
        # 잠겨 있었다 — 실측으로 8.9 kHz 가 −5.5 dB, 15.9 kHz 가 −4.7 dB 모자란다.
        enabled = dict(log_extra_bw=True, log_front_bw=True, log_mvf=not MVF_FROZEN,
                       hf_log_df=_tract_mod.HF_FIXED, hf_log_bw=_tract_mod.HF_FIXED,
                       hf_eq_db=self.eng.tract.output_eq_enabled,
                       pir_log_f=_tract_mod.HF_FIXED,
                       pir_depth=_tract_mod.HF_FIXED,
                       tro_log_f=_tract_mod.HF_FIXED and self.eng.tract.tro_f0 > 0.0,
                       tro_depth=_tract_mod.HF_FIXED and self.eng.tract.tro_f0 > 0.0,
                       fric_log_lp_ratio=FRIC_LP_FIT,
                       open_damp=_tract_mod.OPEN_DAMP, open_f1=_tract_mod.OPEN_DAMP,
                       glottis_hjit_log=_glottis_mod.HJIT_FIT,
                       glottis_disp_log=_glottis_mod.DISP_FIT,
                       glottis_src_eq_db=_glottis_mod.SRC_EQ,
                       glottis_src_eq_hf_db=_glottis_mod.SRC_EQ_HF,
                       td_log_ag_max=_voice_mod.TD_TUBE and (__import__("formant_ml.engine.voice_td", fromlist=["x"]).GLOTTIS != "vf"
                                                             or __import__("formant_ml.engine.voice_td", fromlist=["x"]).VF_BODY_DRIVE),   # 몸체 진폭이 쓴다 (§52.524)
                       td_log_vf_chink=_voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).GLOTTIS == "vf",
                       td_log_ff_area=_voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).LARYNX,
                       **{k: _voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).GLOTTIS == "vf" and VF_STATIC_FIT
                          for k in ("td_log_vf_len", "td_log_vf_thick", "td_log_vf_mk", "td_log_vf_damp")},
                       **{k: _voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).VF_NS
                          for k in ("td_log_ns_len", "td_log_ns_thick", "td_log_ns_kc", "td_log_ns_zeta", "td_log_ns_bulge", "td_log_ns_shear")},
                       **{k: _voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).VF_NS
                          and bool(getattr(__import__("formant_ml.physics.beam_membrane", fromlist=["x"]), "LR_FOLDS", False))
                          for k in ("td_ns_lr_q", "td_ns_lr_m")},
                       td_log_noise_g=_voice_mod.TD_TUBE and not __import__("formant_ml.engine.voice_td", fromlist=["x"]).TIE_NOISE,
                       td_log_noise_c=_voice_mod.TD_TUBE,
                       td_log_epi_area=_voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).EPI_ON,
                       td_log_contact_eps=_voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).EPS_FIT,
                       **{k: _voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).ARTIC == "maeda"
                          for k in ("td_log_sc_ph", "td_log_sc_or", "td_log_sc_area")},
                       **{k: _voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).ARTIC == "w02"
                          for k in ("td_log_w02_len",) if not __import__("formant_ml.engine.voice_td", fromlist=["x"]).W02_ANAT},
                       **{f"td_w02a_{i}": _voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).ARTIC == "w02"
                          and __import__("formant_ml.engine.voice_td", fromlist=["x"]).W02_ANAT
                          and not __import__("formant_ml.engine.voice_td", fromlist=["x"]).W02_AGE for i in range(13)},
                       **{k: _voice_mod.TD_TUBE and __import__("formant_ml.engine.voice_td", fromlist=["x"]).ARTIC == "w02"
                          and __import__("formant_ml.engine.voice_td", fromlist=["x"]).W02_ANAT
                          and __import__("formant_ml.engine.voice_td", fromlist=["x"]).W02_AGE
                          for k in ["td_w02_age"] + [f"td_w02d_{i}" for i in range(13)]})      # 단면 배율은 얼린다 — 적합기가 성문 손실을 메우려 ×1.9–2.7 로 부풀렸다 (§52.486)
        self.constant_parameters = {name: constants[name] for name, on in enabled.items() if on}
        if SPEAKER_LOCK:
            self.locked_constants |= {name for name in constants
                                      if parameter_scope(name) == "speaker"}
        self.hf = [p for name, p in self.constant_parameters.items()
                   if name not in self.locked_constants]
        self._project_ns_bounds(verbose=True)
        if initial_gain_db is None:
            self.calibrate_gain()

    def _project_ns_bounds(self, verbose=False):
        from . import voice_td as vt
        if _voice_mod.TD_TUBE and vt.GLOTTIS == "vf" and vt.VF_NS:
            changed = self.eng.td.project_ns_bounds()
            if verbose and changed:
                print("  NS hard-bound projection (same rendered constants): "
                      + ", ".join(f"{k} {a:.6g} -> {b:.6g}" for k, (a, b) in changed.items()), flush=True)

    def acoustic_constants(self) -> dict:
        return capture_calibration(
            self.eng, gain_db=self.gain_db(),
            pulse_phi0=float(self.pulse_phi0.detach().item()),
            room_ir=None if self.room_ir is None else self.room_ir.detach().cpu().numpy())

    def constant_budget(self) -> dict:
        all_params = engine_parameters(self.eng)
        return {scope: {
            "fitted": {name: p.numel() for name, p in self.constant_parameters.items()
                       if parameter_scope(name) == scope and name not in self.locked_constants},
            "locked": {name: all_params[name].numel() for name in sorted(self.locked_constants)
                       if parameter_scope(name) == scope}}
            for scope in ("speaker", "recording", "utterance")}

    # ------------------------------------------------------- 재매개화
    @staticmethod
    def _to_raw(v: torch.Tensor, spec) -> torch.Tensor:
        lo, hi = spec.lo, spec.hi
        if spec.log:
            x = (torch.log(v.clamp_min(1e-9)) - math.log(lo)) / (math.log(hi) - math.log(lo))
        else:
            x = (v - lo) / (hi - lo)
        return torch.log(x.clamp(1e-4, 1 - 1e-4) / (1 - x.clamp(1e-4, 1 - 1e-4)))

    @staticmethod
    def _to_val(u: torch.Tensor, spec) -> torch.Tensor:
        x = torch.sigmoid(u)
        lo, hi = spec.lo, spec.hi
        if spec.log:
            return torch.exp(math.log(lo) + x * (math.log(hi) - math.log(lo)))
        return lo + x * (hi - lo)

    def _delta(self) -> torch.Tensor:
        """격자 위 증분 -> 프레임별 raw 증분.

        `MOTION` 이 꺼져 있으면 선형 보간, 켜면 선택한 B-스플라인/목표 근사다.
        """
        w = self._expand(self._mask_slow(self.w))
        for c in self.w_coarse:
            w = w + self._expand(self._mask_slow(c))
        if PARAM_TAU_MS:
            w = self._smooth_cols(w)
        w = w * self.scale
        self._w_smooth = w
        if EVENT_W > 0.0 and getattr(self, "w_ev", None) is not None:
            # **계단은 평활 뒤에 더한다** — τ·열 평활을 안 받아야 4 ms 안에 오른다.
            w = w.index_add(1, self._ev_cols,
                            self._ev_basis * self.w_ev.unsqueeze(0) * EVENT_W)
        return w

    def _smooth_base(self, u0: torch.Tensor) -> torch.Tensor:
        """분석 출발점을 `MOTION_SLOW` 의 층에 맞춰 가우시안 저역통과 (σ = `BASE_SMOOTH` × 층 ms, 끝은 복제)."""
        fm = float(self.track.frame_ms)
        out = u0.clone()
        for i, n in enumerate(self.names):
            ms = MOTION_SLOW.get(n, 0.0)
            # 무한대 = 파일 전역 상수(`NOISE_GLOBAL`) — 층이 하나도 없다. 출발점도 상수라 거를 것이 없다.
            if not (0.0 < ms < float("inf")) or n in BASE_SMOOTH_KEEP:
                continue
            sig = BASE_SMOOTH * ms / fm
            half = max(1, int(math.ceil(3.0 * sig)))
            t = torch.arange(-half, half + 1, dtype=u0.dtype, device=u0.device)
            ker = torch.exp(-0.5 * (t / sig) ** 2)
            ker = (ker / ker.sum()).view(1, 1, -1)
            x = torch.nn.functional.pad(u0[:, i].view(1, 1, -1), (half, half), mode="replicate")
            sm = torch.nn.functional.conv1d(x, ker)[0, 0]
            keep = self._fast_obs_mask(u0.shape[0], u0.dtype, u0.device)
            out[:, i] = sm * (1.0 - keep) + u0[:, i] * keep
        return out

    def _smooth_base_tau(self, u0: torch.Tensor) -> torch.Tensor:
        """`BASE_TAU_PARAMS` 열의 출발점을 `PARAM_TAU_PHYS` 의 σ 로 가우시안 저역통과 (끝은 복제). 관측이 빠른 틀은 그대로 둔다."""
        fm = float(self.track.frame_ms)
        out = u0.clone()
        keep = self._fast_obs_mask(u0.shape[0], u0.dtype, u0.device)
        done = []
        for i, n in enumerate(self.names):
            if n not in BASE_TAU_PARAMS:
                continue
            sig = PARAM_TAU_PHYS.get(n, PARAM_TAU_PHYS_DEFAULT) / fm
            half = max(1, int(math.ceil(3.0 * sig)))
            t = torch.arange(-half, half + 1, dtype=u0.dtype, device=u0.device)
            ker = torch.exp(-0.5 * (t / sig) ** 2)
            ker = (ker / ker.sum()).view(1, 1, -1)
            x = torch.nn.functional.pad(u0[:, i].view(1, 1, -1), (half, half), mode="replicate")
            sm = torch.nn.functional.conv1d(x, ker)[0, 0]
            out[:, i] = sm * (1.0 - keep) + u0[:, i] * keep
            done.append(n)
        print(f"  출발점 생리 평활 (BASE_TAU): {', '.join(done) or '없음'}", flush=True)
        return out

    def _build_events(self, device) -> None:
        """Allocate one scalar per observed control/event, in raw fitting units."""
        observed = torch.stack([self._to_raw(self.base[:, INDEX[name]], spec)
                                for name, spec in zip(self.names, self.specs)], 1)
        ev = build_control_events(
            self.track, self.names, observed.detach().cpu().numpy(), params=EVENT_PARAMS,
            rate_pct=MOVE_FINE_PCT, min_gap_ms=EVENT_MIN_GAP_MS,
            min_jump=EVENT_MIN_JUMP, fade_ms=EVENT_FADE_MS)
        if ev.columns.size == 0:
            # **말없이 돌아가지 않는다.** 이 저장소의 상습 실패가 "켰는데 아무것도 안 생겼다" 이다.
            print(f"  이벤트 층: 계단 0 개 — 아무 제어도 문턱(도약 {EVENT_MIN_JUMP:g}, "
                  f"간격 {EVENT_MIN_GAP_MS:g} ms)을 넘지 못했다. EVENT_W 는 아무 일도 안 한다", flush=True)
            return
        _per = {self.names[i]: int(c) for i, c in
                zip(*np.unique(ev.columns, return_counts=True))} if ev.columns.size else {}
        print(f"  이벤트 층: 계단 {ev.columns.size} 개 "
              + (", ".join(f"{k} {v}" for k, v in _per.items()) or "없음"), flush=True)
        self._ev_basis = torch.as_tensor(ev.basis, dtype=torch.float64, device=device)
        self._ev_cols = torch.as_tensor(ev.columns, dtype=torch.long, device=device)
        self.w_ev = torch.zeros(ev.columns.size, dtype=torch.float64, device=device,
                                requires_grad=True)
        self._ev_n = ev.columns.size
        self._ev_jump = torch.as_tensor(ev.jumps, dtype=torch.float64, device=device)
        self._ev_idx = torch.as_tensor(ev.indices, dtype=torch.long, device=device)

    def _fast_obs_mask(self, T: int, dtype, device) -> torch.Tensor:
        """**관측이 빠르게 움직이는 프레임은 출발점을 안 뭉갠다** (MEASUREMENTS §51.44).

        `BASE_SMOOTH` 는 출발점의 흔들림을 막으려고 넣었는데, 목표가 실제로 가진 **빠른 도약까지**
        지웠다. 실측: `--base-smooth 0.45` (σ 9 ms) 만으로 10~90 % 상승이 24 ms 아래로 못 내려가고,
        20 ms 격자(16 ms)·τ 5 ms(11 ms)까지 겹치면 **31 ms** 다. 그런데 목표의 F2 는 가장 빠른 1 %
        에서 **4~5 ms** 만에 20 % 를 움직인다. 4 ms 도약은 자음 경계로 들리고 지나가지만 31 ms
        글라이드는 음높이가 미끄러지는 것으로 또렷이 들린다 — 사용자가 지적한 "괜히 정규화를 걸어서
        인지 가능한 왜곡으로 변질된" 것이 이것이다.

        `MOVE_FINE_PCT` 가 0 이면 예전처럼 전부 뭉갠다.
        """
        if MOVE_FINE_PCT <= 0.0 or BASE_SMOOTH_KEEP_FAST <= 0.0:
            return torch.zeros((T,), dtype=dtype, device=device)
        if getattr(self, "_fobm", None) is not None and self._fobm.shape[0] == T:
            return self._fobm.to(dtype)
        fo = self._fast_obs_frames()
        m = np.zeros(T)
        if fo.size:
            half = max(1, int(round(BASE_SMOOTH_KEEP_FAST / float(self.track.frame_ms))))
            for i in fo:
                m[max(int(i) - half, 0):int(i) + half + 1] = 1.0
        self._fobm = torch.as_tensor(m, dtype=dtype, device=device)
        return self._fobm

    def _smooth_cols(self, w: torch.Tensor) -> torch.Tensor:
        """열(파라미터)마다 `PARAM_TAU_MS` 의 시상수로 가우시안 저역통과. 끝은 복제로 채운다."""
        fm = float(self.track.frame_ms)
        out = w
        groups: dict[float, list[int]] = {}
        for i, n in enumerate(self.names):
            tau = PARAM_TAU_MS.get(n, 0.0)
            if tau > 0.0:
                groups.setdefault(float(tau), []).append(i)
        for tau, cols in groups.items():
            sig = tau / fm                                   # 프레임 단위 σ
            half = max(1, int(math.ceil(3.0 * sig)))
            t = torch.arange(-half, half + 1, dtype=w.dtype, device=w.device)
            ker = torch.exp(-0.5 * (t / sig) ** 2)
            ker = (ker / ker.sum()).view(1, 1, -1)
            idx = torch.tensor(cols, device=w.device)
            x = w[:, idx].t().unsqueeze(1)                   # (C, 1, T)
            x = torch.nn.functional.pad(x, (half, half), mode="replicate")
            y = torch.nn.functional.conv1d(x, ker)[:, 0].t()  # (T, C)
            out = out.index_copy(1, idx, y)
        return out

    def _mask_slow(self, q: torch.Tensor) -> torch.Tensor:
        """`MOTION_SLOW` 에 적힌 파라미터를 그보다 고운 층에서 0 으로 둔다."""
        if not (MOTION and MOTION_SLOW):
            return q
        grid_ms = self.track.frame_ms * self.n_frames / max(q.shape[0] - 1, 1)
        keep = torch.tensor([0.0 if MOTION_SLOW.get(n, 0.0) > grid_ms + 0.5 else 1.0
                             for n in self.names], dtype=q.dtype, device=q.device)
        if not BURST_FINE:
            return q * keep
        near = self._burst_coeffs(q.shape[0], q.dtype, q.device)
        if near is None:
            return q * keep
        col = torch.tensor([1.0 if n in BURST_PARAMS else 0.0 for n in self.names],
                           dtype=q.dtype, device=q.device)
        # 파열 창 안에서는 느린 층 마스크를 무시한다 (`BURST_FINE` 참조).
        return q * torch.clamp(keep.unsqueeze(0) + near.unsqueeze(1) * col.unsqueeze(0), max=1.0)

    def _fast_obs_speed(self) -> np.ndarray:
        """프레임별 관측 속도 — `MOVE_FINE_PARAMS` 가운데 최대 |Δ log| [%/ms]."""
        if getattr(self, "_fos", None) is not None:
            return self._fos
        T = int(self.base.shape[0])
        out = np.zeros(T)
        for nm in MOVE_FINE_PARAMS:
            if nm not in INDEX:
                continue
            x = np.asarray(self.track[nm], dtype=np.float64)[:T]
            if x.size < 4 or not np.all(x > 0):
                continue
            d = np.abs(np.diff(np.log(x))) * 100.0 / float(self.track.frame_ms)
            out[:-1] = np.maximum(out[:-1], d)
        self._fos = out
        return out

    def _fast_obs_frames(self) -> np.ndarray:
        """분석 궤적이 ms 당 `MOVE_FINE_PCT` % 넘게 움직이는 프레임. `MOVE_FINE_PCT` 참조."""
        if getattr(self, "_fof", None) is not None:
            return self._fof
        T = int(self.base.shape[0])
        out = np.zeros(T, bool)
        for nm in MOVE_FINE_PARAMS:
            if nm not in INDEX:
                continue
            x = np.asarray(self.track[nm], dtype=np.float64)[:T]
            if x.size < 4 or not np.all(x > 0):
                continue
            d = np.abs(np.diff(np.log(x))) * 100.0 / float(self.track.frame_ms)
            out[:-1] |= d > MOVE_FINE_PCT
        self._fof = np.flatnonzero(out)
        return self._fof

    def _burst_coeffs(self, kc: int, dtype, device) -> torch.Tensor | None:
        """이 층의 계수 가운데 파열 창(±`BURST_WIN_MS`) 안에 있는 것 = 1."""
        b = np.asarray(getattr(self.track, "bursts", np.zeros(0, dtype=int)), int)
        fo = self._fast_obs_frames() if MOVE_FINE_PCT > 0.0 else np.zeros(0, dtype=int)
        if b.size == 0 and fo.size == 0 or kc < 2:
            return None
        key = (kc, str(device), dtype)
        if getattr(self, "_bc_key", None) == key:
            return self._bc
        pos = np.arange(kc) * (self.n_frames - 1) / max(kc - 1, 1)
        fm_ = float(self.track.frame_ms)
        m = np.zeros(kc)
        if b.size:
            m = np.maximum(m, (np.abs(pos[:, None] - b[None, :]).min(1)
                               <= BURST_WIN_MS / fm_).astype(np.float64))
        if fo.size:
            m = np.maximum(m, (np.abs(pos[:, None] - fo[None, :]).min(1)
                               <= MOVE_FINE_WIN_MS / fm_).astype(np.float64))
        self._bc_key, self._bc = key, torch.as_tensor(m, dtype=dtype, device=device)
        return self._bc

    def _expand(self, w: torch.Tensor) -> torch.Tensor:
        if w.shape[0] == self.n_frames and not MOTION:
            return w
        if MOTION and MOTION_MODE == "target":
            return self._target_approach(w)
        if MOTION:
            return self._bspline(w)
        return torch.nn.functional.interpolate(
            w.t().unsqueeze(0), size=self.n_frames, mode="linear",
            align_corners=True)[0].t()

    def _target_kernels(self, dtype, device):
        """파라미터를 τ 로 묶고 임계감쇠 3 차 커널을 만든다 -> [(열 색인, 커널)]. `MOTION_MODE` 참조."""
        key = (str(device), dtype)
        if getattr(self, "_tk_key", None) == key:
            return self._tk
        fm = float(self.track.frame_ms)
        groups: dict[float, list[int]] = {}
        for i, n in enumerate(self.names):
            tau = float(PARAM_TAU_PHYS.get(n, TARGET_TAU_DEFAULT))
            groups.setdefault(max(tau, 0.5), []).append(i)
        out = []
        for tau, cols in groups.items():
            s = tau / fm
            L = max(3, int(math.ceil(7.0 * s)))
            t = torch.arange(L, dtype=dtype, device=device)
            h = (t * t) * torch.exp(-t / s)
            h = h / h.sum().clamp_min(1e-12)
            out.append((torch.tensor(cols, device=device), h.flip(0).view(1, 1, -1)))
        self._tk_key, self._tk = key, out
        return out

    def _target_approach(self, w: torch.Tensor) -> torch.Tensor:
        """격자 **목표값** -> 프레임 궤적. 영차유지 뒤 임계감쇠 3 차 응답 (`MOTION_MODE == "target"`)."""
        tc, n = w.shape[0], self.n_frames
        pos = torch.arange(n, device=w.device, dtype=w.dtype) * (tc - 1) / max(n - 1, 1)
        idx = pos.floor().long().clamp(0, tc - 1)
        zoh = w[idx]                                     # (T, P) 목표는 구간마다 상수
        out = zoh
        for cols, h in self._target_kernels(w.dtype, w.device):
            x = zoh.index_select(1, cols).t().unsqueeze(0)          # (1,C,T)
            pad = h.shape[-1] - 1
            x = torch.nn.functional.pad(x, (pad, 0), mode="replicate")
            c = x.shape[1]
            y = torch.nn.functional.conv1d(x, h.expand(c, 1, -1), groups=c)[0].t()
            out = out.index_copy(1, cols, y)
        return out

    def _bspline(self, w: torch.Tensor) -> torch.Tensor:
        """격자 값 -> 프레임 값, **균일 3 차 B-스플라인** (C²).

        선형 보간은 격자점마다 **가속도가 불연속**이라 난류 진폭의 계단을 만든다
        (HANDOFF §11.1 이 `phones.min_jerk` 를 만들며 실측한 것이고, 그때 적합기에는
        안 붙였다). 3 차 B-스플라인은 위치·속도·가속도가 전부 연속이므로 다음
        구간이 앞 구간의 속도와 가속도를 **계승**한다 — 사용자가 요구한 "한 창에서
        정적 물리 변수가 아니라 움직임을 기술한다" 가 이 형태다.

        **생 이중적분(자유 파라미터를 가속도로) 은 먼저 시험했고 실패했다.** 국소
        수정에 가속도 쌍극자가 필요해 조건수가 나쁘고, 격자를 촘촘히 해도 한
        격자점의 권한이 사라진다 — 실측(`out/L7`)에서 2.1 단계 68.30 에서 2.4 단계
        69.79 로 **격자 정교화가 아무 일도 못 했다** (같은 설정의 `out/L6` 은
        83.92 → 91.34). B-스플라인은 기저가 국소라 그 병이 없고, `w` 가 여전히
        값이므로 `STEP`·`PRIOR_W`·`scale` 눈금을 그대로 쓸 수 있다.
        """
        tc, n = w.shape[0], self.n_frames
        u = torch.linspace(0.0, float(tc - 1), n, device=w.device, dtype=w.dtype)
        i0 = torch.floor(u).clamp(0, tc - 1)
        f = (u - i0).unsqueeze(1)
        i0 = i0.long()

        def at(k):
            return w[(i0 + k).clamp(0, tc - 1)]

        f2, f3 = f * f, f * f * f
        b0 = (1.0 - 3.0 * f + 3.0 * f2 - f3) / 6.0
        b1 = (4.0 - 6.0 * f2 + 3.0 * f3) / 6.0
        b2 = (1.0 + 3.0 * f + 3.0 * f2 - 3.0 * f3) / 6.0
        b3 = f3 / 6.0
        return b0 * at(-1) + b1 * at(0) + b2 * at(1) + b3 * at(2)

    def _u(self) -> torch.Tensor:
        return self.u0 + self._delta() + self.d * self.d_mask

    def set_grid(self, grid_ms: float) -> int:
        """제어 격자 간격을 바꾼다. 현재 해를 보간해서 옮기므로 이어서 최적화된다."""
        if MOTION:
            grid_ms = max(float(grid_ms), MOTION_MIN_GRID_MS)
        stride = max(1, int(round(grid_ms / self.track.frame_ms)))
        tc = max(2, int(math.ceil(self.n_frames / stride)))
        if MOTION and MOTION_MULTI:
            # **층을 쌓는다.** 같은 해상도를 다시 요구받으면(격자 하한에 걸린 경우)
            # 층을 늘리지 않는다 — 같은 기저를 두 번 두면 중복 매개화가 된다.
            if self.w.shape[0] == tc:
                self.stride = stride
                return tc
            # **프레임 해상도의 층은 쌓지 않고 버린다.** 초기 `w` 는 1 ms 격자라,
            # 그것을 층으로 남기면 프레임별 자유가 그대로 살아 있어 움직임 매개화가
            # 무의미해진다 (실측: 그 층을 남겼을 때 `nasal_f3` 의 48 %가 60 Hz 위였다).
            if self.w.shape[0] < self.n_frames:
                self.w_coarse.append(self.w)
            self.w = torch.zeros(tc, self.w.shape[1], dtype=self.w.dtype,
                                 device=self.w.device).requires_grad_(True)
            self.stride = stride
            return tc
        with torch.no_grad():
            old = self.w.detach()
            new = torch.nn.functional.interpolate(
                old.t().unsqueeze(0), size=tc, mode="linear", align_corners=True)[0].t()
        self.w = new.clone().requires_grad_(True)
        self.stride = stride
        return tc

    def control(self) -> torch.Tensor:
        u = self._u()
        self._u_live = u              # `ROUTE_HF` 의 훅 자리 — 합성이 실제로 쓴 u
        cols = torch.stack([self._to_val(u[:, i], s) for i, s in enumerate(self.specs)], 1)
        if FAST_ONLY:
            cols = self._fast_only(cols)
        if HOLD_FRIC:
            cols = self._hold(cols)
        if HOLD_GAP:
            cols = self._gap(cols)
        if Q_BAND:
            cols = self._q_band(cols)
        c = self.base.clone().index_copy(1, self.cols, cols).unsqueeze(0)
        if ART_SEGMENTS is not None and ART_TARGETS:
            # 음소 목표가 낸 궤적을 먼저 얹는다 — 내전도 목표가 낼 때(`ART_LARYNX`) 아래 유성 바닥이 그 위에 걸리게 (§52.507)
            c = self._art_override(c)
        if VOICED_ADD_FLOOR > 0.0 and self.track.voiced.size:
            # **유성 틀에서는 성문을 벌려 목소리를 끄는 길을 막는다** (MEASUREMENTS §52.420). 끊김 구간(C2 1.42~1.50 s)에서
            # 적합기가 내전을 0.07 까지 내려(게이트 0.10 밑) 목소리를 기식 잡음으로 바꿨다 — 분석이 넣어 준 유성 초기값을
            # 다듬기 80 회 만에 다시 버렸다. 매끈한 바닥: floor + softplus(k(x − floor))/k — 바닥 아래에서도 기울기가 흐른다.
            if getattr(self, "_vaf_mask", None) is None or self._vaf_mask.shape[0] != c.shape[1]:
                self._vaf_mask, self._vac_mask = self._periodic_voiced_masks(c)
            ia = INDEX["adduction"]
            x = c[0, :, ia]
            fl = VOICED_ADD_FLOOR
            xs = fl + torch.nn.functional.softplus((x - fl) * 40.0) / 40.0
            c = c.clone()
            c[0, :, ia] = torch.where(self._vaf_mask, xs, x)
            if VOICED_AC_FLOOR > 0.0:
                # 같은 틀에서 **협착으로 음량을 깎는 길**도 막는다: 1.438~1.442 s 에서 a_c 가 2.3 → 0.35 cm² 로 몇 ms 좁혀져
                # 한 주기가 −20 dB 로 빠졌다(미세한 끊김). 입이 실제로 닫히는 비음 머머(분석 velum > 0.3)는 뺀다.
                ic = INDEX["a_c"]
                y_ = c[0, :, ic]
                fc = VOICED_AC_FLOOR
                ys = fc + torch.nn.functional.softplus((y_ - fc) * 20.0) / 20.0
                c[0, :, ic] = torch.where(self._vac_mask, ys, y_)
        self._last_ctrl = c                      # 움직임 예산이 본다 (float64 그대로)
        return c.to(torch.float32)

    def _fast_only(self, cols: torch.Tensor) -> torch.Tensor:
        """`FAST_ONLY` 열에서 추세를 빼고 유성 마스크를 곱한다 — 빠른 요동만 남는다."""
        idx = [i for i, n in enumerate(self.names) if n in FAST_ONLY]
        if not idx:
            return cols
        if getattr(self, "_fo_ker", None) is None:
            sig = FAST_ONLY_MS / float(self.track.frame_ms)
            half = max(1, int(math.ceil(3.0 * sig)))
            t = torch.arange(-half, half + 1, dtype=cols.dtype, device=cols.device)
            k = torch.exp(-0.5 * (t / sig) ** 2)
            self._fo_ker = (k / k.sum()).view(1, 1, -1)
            v = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), float)
            T = int(cols.shape[0])
            if v.size < T:
                v = np.pad(v, (0, T - v.size))
            self._fo_voi = torch.as_tensor(v[:T], dtype=cols.dtype, device=cols.device)
        half = (self._fo_ker.shape[-1] - 1) // 2
        out = cols
        for i in idx:
            x = cols[:, i]
            xx = torch.nn.functional.pad(x.view(1, 1, -1), (half, half), mode="replicate")
            trend = torch.nn.functional.conv1d(xx, self._fo_ker.to(x.dtype))[0, 0]
            out = out.index_copy(1, torch.tensor([i], device=cols.device),
                                 ((x - trend) * self._fo_voi).unsqueeze(1))
        return out

    def _q_band(self, cols: torch.Tensor) -> torch.Tensor:
        """`Q_BAND` 에 적힌 포먼트의 대역폭을 `f/Qmax` ~ `f/Qmin` 안으로 부드럽게 가둔다."""
        if getattr(self, "_qb", None) is None:
            pairs = []
            for nm, (qlo, qhi) in Q_BAND.items():
                bw = f"bw{nm[1:]}"
                if nm in self.names and bw in self.names:
                    pairs.append((self.names.index(nm), self.names.index(bw),
                                  float(qlo), float(qhi)))
            self._qb = pairs
        if not self._qb:
            return cols
        # **유성 프레임에만 건다.** 코퍼스 Q 는 유성 프레임에서 쟀다 (`f0 > 0`). 무성 구간의 대역폭은
        # 그 분포의 대상이 아닌데 상자를 통째로 걸었더니 렌더가 무너졌다 — 실측 포락 **22 %** (M60/M61).
        if getattr(self, "_qb_voi", None) is None:
            v = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), bool)
            T = int(self.base.shape[0])
            if v.size < T:
                v = np.pad(v, (0, T - v.size))
            self._qb_voi = torch.as_tensor(v[:T].astype(np.float64), device=cols.device)
        vm = self._qb_voi[:cols.shape[0]].to(cols.dtype)
        out = cols
        for i_f, i_b, qlo, qhi in self._qb:
            fk = out[:, i_f]
            lo, hi = fk / qhi, fk / qlo          # Q 가 크면 대역폭이 작다
            b = out[:, i_b]
            # **안쪽에서는 항등이어야 한다.** 예전에는 로그 공간에서 `tanh` 로 접었는데, tanh 는 중앙
            # 말고는 어디서나 압축한다 — 범위 절반 지점에서 7.6 % 가 줄어, 상자 **안**의 값까지 바뀌었다
            # (동일성 시험이 99.0 → 98.4 로 잡았다). 그래서 `|z| ≤ QB_CORE` 는 손대지 않고 그 밖만
            # 포화시킨다. C¹ 로 이어 붙이므로 기울기가 끊기지 않고, `|g| < 1` 이라 상자는 그대로 지켜진다.
            mid, half = torch.sqrt(lo * hi), 0.5 * torch.log(hi / lo)
            z = torch.log(b.clamp_min(1e-6) / mid) / half.clamp_min(1e-9)
            c = QB_CORE
            over = (z.abs() - c).clamp_min(0.0)
            g = torch.sign(z) * (torch.minimum(z.abs(), torch.full_like(z, c))
                                 + (1.0 - c) * torch.tanh(over / (1.0 - c)))
            y = mid * torch.exp(half * g)
            y = vm * y + (1.0 - vm) * b                  # 무성 구간은 손대지 않는다
            out = out.index_copy(1, torch.tensor([i_b], device=cols.device), y.unsqueeze(1))
        return out

    @staticmethod
    def _runs(mask: np.ndarray) -> list[tuple[int, int]]:
        """참인 구간을 (시작, 끝) 으로 모은다 — 끝은 포함이다."""
        out, i, T = [], 0, mask.shape[0]
        while i < T:
            if not mask[i]:
                i += 1
                continue
            j = i
            while j + 1 < T and mask[j + 1]:
                j += 1
            out.append((i, j))
            i = j + 1
        return out

    @classmethod
    def _ramp_mask(cls, mask: np.ndarray, d_in: np.ndarray, d_out: np.ndarray,
                   r_in: float, r_out: float) -> np.ndarray:
        """구간마다 양끝 램프로 0 → 1 → 0 을 만든다.

        **램프 합보다 짧은 구간은 램프를 비례로 줄인다** (§52.339). 고정 램프를 쓰면 짧은 구간이
        고원에 한 번도 못 닿아 붙잡기가 조용히 헐거워진다 — 실측한 마찰 구간 7·13·17 ms 는
        램프 합 20 ms 보다 짧아 m 의 최대가 0.47 이었다.
        """
        m = np.zeros(mask.shape[0], dtype=np.float64)
        for i, j in cls._runs(mask):
            L = float(j - i + 1)
            a, b = r_in, r_out
            if L < a + b:
                s = L / (a + b)
                a, b = max(a * s, 1e-9), max(b * s, 1e-9)
            m[i:j + 1] = np.minimum(np.clip(d_in[i:j + 1] / a, 0.0, 1.0),
                                    np.clip(d_out[i:j + 1] / b, 0.0, 1.0))
        return m

    @staticmethod
    def _edge_dist(mask: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        """구간 시작 쪽·끝 쪽 가장자리까지의 거리 [프레임]. 구간 밖은 0."""
        T = mask.shape[0]
        d_in, d_out = np.zeros(T), np.zeros(T)
        run = 0.0
        for i in range(T):
            run = run + 1.0 if mask[i] else 0.0
            d_in[i] = run
        run = 0.0
        for i in range(T - 1, -1, -1):
            run = run + 1.0 if mask[i] else 0.0
            d_out[i] = run
        return d_in, d_out

    @classmethod
    def _seg_ops(cls, mask: np.ndarray, m: np.ndarray):
        """구간 평균을 뽑는 가중 P 와 구간 소속 S. 가중이 0 인 구간은 마스크에서 뺀다."""
        cols_r = []
        for i, j in cls._runs(mask):
            w = np.zeros(mask.shape[0])
            w[i:j + 1] = m[i:j + 1]
            if w.sum() > 0:
                cols_r.append(w / w.sum())
            else:
                m[i:j + 1] = 0.0
        if not cols_r:
            return None, None
        P = np.stack(cols_r, 1)                          # (T, R) 구간 평균 가중
        return P, (P > 0).astype(np.float64)             # (T, R) 구간 소속

    def _hold_setup(self, dtype, device) -> None:
        """마찰 구간마다의 고원 마스크와 구간 평균 연산자. `HOLD_FRIC` 참조."""
        T = int(self.base.shape[0])
        fm = np.asarray(getattr(self.track, "fricative", np.zeros(0, dtype=bool)), bool)
        if fm.size < T:
            fm = np.pad(fm, (0, T - fm.size))
        fm = fm[:T]
        fm_ms = float(self.track.frame_ms)
        # 두 가장자리까지의 거리 [프레임] — 비마찰 프레임은 0. 시작 쪽과 끝 쪽을 **따로** 센다.
        d_in, d_out = self._edge_dist(fm)
        r_in = max(1.0, HOLD_RAMP_IN_MS / fm_ms)
        r_out = max(1.0, HOLD_RAMP_MS / fm_ms)
        m = self._ramp_mask(fm, d_in, d_out, r_in, r_out)
        # 구간마다 열 하나. 고원 값은 **m 으로 가중한** 구간 평균이라 가장자리가 끌어내리지 않는다.
        P, S = self._seg_ops(fm, m)
        self._hold_m = torch.as_tensor(m, dtype=dtype, device=device)
        if P is not None:
            self._hold_P = torch.as_tensor(P, dtype=dtype, device=device)
            self._hold_S = torch.as_tensor(S, dtype=dtype, device=device)
        else:
            self._hold_P = self._hold_S = None
        self._gap_setup(fm, dtype, device)
        self._hold_idx = [i for i, n in enumerate(self.names) if n in HOLD_PARAMS]
        self._hold_sidx = [i for i, n in enumerate(self.names) if n in HOLD_SMOOTH_PARAMS]
        sig = HOLD_SMOOTH_MS / float(self.track.frame_ms)
        half = max(1, int(math.ceil(3.0 * sig)))
        ker = np.exp(-0.5 * (np.arange(-half, half + 1) / sig) ** 2)
        self._hold_ker = torch.as_tensor(ker / ker.sum(), dtype=dtype,
                                         device=device).view(1, 1, -1)
        self._hold_half = half
        # 마찰 안에서만 건다 — 가장자리 램프는 붙잡기와 같은 `m` 을 쓴다.
        self._hold_sm = torch.as_tensor(m, dtype=dtype, device=device)

    def _gap_setup(self, fm: np.ndarray, dtype, device) -> None:
        """**사각지대** — 유성도 마찰도 아닌 구간의 마스크와 구간 평균 연산자. `HOLD_GAP` 참조."""
        T = int(self.base.shape[0])
        vm = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), bool)
        if vm.size < T:
            vm = np.pad(vm, (0, T - vm.size))
        gap = ~vm[:T] & ~fm[:T]
        d_in, d_out = self._edge_dist(gap)
        r = max(1.0, HOLD_GAP_RAMP_MS / float(self.track.frame_ms))
        mg = self._ramp_mask(gap, d_in, d_out, r, r)
        P, S = self._seg_ops(gap, mg)
        self._gap_m = torch.as_tensor(mg, dtype=dtype, device=device)
        if P is not None:
            self._gap_P = torch.as_tensor(P, dtype=dtype, device=device)
            self._gap_S = torch.as_tensor(S, dtype=dtype, device=device)
        else:
            self._gap_P = self._gap_S = None
        self._gap_idx = [i for i, n in enumerate(self.names) if n in HOLD_GAP_PARAMS]
        # 분석 궤적(관측)의 로그. `self.base` 는 적합 내내 안 바뀌는 출발점이다.
        runs = self._runs(gap)
        self._gap_obs = {}
        for i in self._gap_idx:
            lo = np.log(np.maximum(
                self.base[:, INDEX[self.names[i]]].detach().cpu().numpy(), 1e-9))
            lo = self._gap_smooth(lo, runs)
            self._gap_obs[i] = torch.as_tensor(lo, dtype=dtype, device=device)

    def _gap_smooth(self, lo: np.ndarray, runs: list[tuple[int, int]]) -> np.ndarray:
        """사각지대 구간 **안에서만** 기준 모양을 깎는다. `HOLD_GAP_SMOOTH_MS` 참조."""
        base = HOLD_GAP_SMOOTH_MS / float(self.track.frame_ms)
        if (base <= 0.0 and HOLD_GAP_SMOOTH_FRAC <= 0.0) or not runs:
            return lo
        out = lo.copy()
        for a, b in runs:
            seg = lo[a:b + 1]
            if seg.size < 3:
                continue
            sig = max(base, HOLD_GAP_SMOOTH_FRAC * seg.size)   # 긴 구간일수록 세게 깎는다
            if sig <= 0.0:
                continue
            half = max(1, int(math.ceil(3.0 * sig)))
            k = np.exp(-0.5 * (np.arange(-half, half + 1) / sig) ** 2)
            k /= k.sum()
            pad = np.pad(seg, (half, half), mode="edge")   # 구간 밖 값은 안 섞는다
            out[a:b + 1] = np.convolve(pad, k, mode="valid")
        return out

    def _gap(self, cols: torch.Tensor) -> torch.Tensor:
        """사각지대 안에서 공명의 **모양**을 관측으로 갈아 끼우고 **수준**만 남긴다.

        `_hold` 가 마찰 안에서 값을 구간 고원으로 붙잡는 것과 같은 재파라미터화인데, 붙잡는
        대상이 상수가 아니라 **관측 궤적의 모양**이다. 사각지대는 조음이 마찰을 향해 실제로
        움직이는 자리라 상수로 두면 틀린다 — 실측 2.055~2.129 s 의 관측 f2 범위는 1996 Hz 다.
        구간 평균 오프셋만 적합기에게 남기므로 유성 쪽 수준과 이어 맞추는 자유는 그대로다.
        """
        if getattr(self, "_gap_m", None) is None:
            self._hold_setup(cols.dtype, cols.device)    # 사각지대 채비도 여기서 선다
        if self._gap_P is None or not self._gap_idx:
            return cols
        mg, P, S = (self._gap_m.to(cols.dtype), self._gap_P.to(cols.dtype),
                    self._gap_S.to(cols.dtype))
        out = cols
        for i in self._gap_idx:
            lx = torch.log(cols[:, i].clamp_min(1e-9))
            lo = self._gap_obs[i].to(cols.dtype)
            off = S @ (P.transpose(0, 1) @ (lx - lo))    # 구간마다 제 평균 오프셋
            y = torch.exp(lx * (1.0 - mg) + (lo + off) * mg)
            out = out.index_copy(1, torch.tensor([i], device=cols.device), y.unsqueeze(1))
        return out

    def _hold(self, cols: torch.Tensor) -> torch.Tensor:
        """마찰 구간 안에서 `HOLD_PARAMS` 를 그 구간의 고원 값으로 끌어당긴다."""
        if getattr(self, "_hold_m", None) is None:
            self._hold_setup(cols.dtype, cols.device)
        if not self._hold_idx or self._hold_P is None:
            return cols
        m = self._hold_m.to(cols.dtype)
        P, S = self._hold_P.to(cols.dtype), self._hold_S.to(cols.dtype)
        out = cols
        # 세기 쪽 제어: 고원으로 끌지 않고 **마찰 안에서만 저역통과**한다 (HOLD_SMOOTH_PARAMS).
        if self._hold_sidx:
            ker = self._hold_ker.to(cols.dtype)
            h = self._hold_half
            for i in self._hold_sidx:
                x = cols[:, i]
                lx = torch.log(x.clamp_min(1e-9))
                z = torch.nn.functional.pad(lx.view(1, 1, -1), (h, h), mode="replicate")
                sm = torch.nn.functional.conv1d(z, ker)[0, 0]
                y = torch.exp(lx * (1.0 - m) + sm * m)
                out = out.index_copy(1, torch.tensor([i], device=cols.device), y.unsqueeze(1))
            cols = out
        for i in self._hold_idx:
            x = cols[:, i]
            lx = torch.log(x.clamp_min(1e-9))
            plateau = S @ (P.transpose(0, 1) @ lx)       # 구간마다 제 평균으로 채운다
            y = torch.exp(lx * (1.0 - m) + plateau * m)
            out = out.index_copy(1, torch.tensor([i], device=cols.device), y.unsqueeze(1))
        return out

    def _rms(self, x: torch.Tensor, mask: np.ndarray | None) -> float:
        if mask is None or not mask.any():
            return float(x.pow(2).mean().sqrt()) + 1e-12
        i = np.flatnonzero(np.repeat(mask, self.hop)[:x.shape[-1]])
        return float(x[..., i].pow(2).mean().sqrt()) + 1e-12

    def calibrate_gain(self) -> float:
        """초기 이득을 닫힌 형태로 준다. **유성/무성을 따로 맞춘다.**

        하나의 이득만 맞추면 유성과 무성 중 한쪽이 반드시 크게 어긋난다. 마찰 세기는
        `fric_gain` 이 정하는데 그 초기값이 1.0 이고, 실측과의 차이가 40 dB 를 넘으면
        경사 하강으로는 못 간다 (한 걸음이 상한 64 = 36 dB 안에서 움직인다). 실제로
        남 /사/ 는 마찰부가 −42.8 dB 인 채로 시작해 끝까지 못 따라잡았다.
        그래서 전체 이득은 **유성 프레임**에서, `fric_gain` 은 **무성 프레임**에서
        각각 닫힌 형태로 준다.
        """
        voi = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)))
        if voi.shape[0] != self.n_frames:
            voi = np.zeros(0, dtype=bool)
        # `fric_gain` 은 **마찰 프레임**에서만 잰다. 폐쇄(비음 머머 등)를 섞으면
        # 조용한 구간까지 마찰로 메우려 든다.
        fri = np.asarray(getattr(self.track, "fricative", np.zeros(0, dtype=bool)))
        if fri.shape[0] != self.n_frames:
            fri = ~voi if voi.size else np.zeros(0, dtype=bool)
        unv = fri
        with torch.no_grad():
            self.eng.reset()
            y = self.eng(self.control(), self.track.events, 0.0)["audio"]
            m = voi if voi.any() else None
            r = self._rms(self.target, m) / self._rms(y, m)
            self.log_gain.copy_(torch.tensor([math.log(r)], dtype=torch.float64,
                                             device=self.device))
            if unv.any() and "fric_gain" in self.names:
                self.eng.reset()
                y = self.eng(self.control(), self.track.events, 0.0)["audio"] * r
                need = self._rms(self.target, unv) / self._rms(y, unv)
                j = self.names.index("fric_gain")
                sp = self.specs[j]
                g0 = float(self._to_val(self.u0[:, j], sp).median())
                tgt = float(np.clip(g0 * need, sp.lo + 1e-3, sp.hi - 1e-3))
                # raw 좌표의 전역 오프셋으로 넣는다 (프레임별 모양은 보존)
                d = float(self._to_raw(torch.tensor([tgt], dtype=torch.float64), sp)[0]
                          - self._to_raw(torch.tensor([g0], dtype=torch.float64), sp)[0])
                self.d[j] = d / max(float(self.d_mask[j]), 1.0) if self.d_mask[j] else 0.0
                if not self.d_mask[j]:      # fric_gain 은 전역 대상이어야 한다
                    self.d[j] = d
        return self.gain_db()

    # ------------------------------------------------------------ 손실
    def _hcorr_prepare(self) -> None:
        """주기별 배음 보정을 켠다. 세기 눈금은 **보정 없이 한 번 렌더한 음원 du 의 rms** 로 잡는다."""
        if HCORR_K <= 0 or self._pulse_phase is None:
            return
        if self.hcorr is not None or getattr(self, "_hc_u", None) is not None:
            return
        with torch.no_grad():
            self.eng.reset()
            pp = CopySynthFitter._pp(self)
            out = self.eng(self.control(), self.track.events, 0.0, pulse_phase=pp)
            du = out.get("du")
            self._hc_scale = float(du.double().pow(2).mean().sqrt()) if du is not None else 1.0
            u = (pp[0] / (2.0 * math.pi)).detach()
            self._hc_c0 = int(torch.floor(u.min()).item())
            n_c = int(torch.floor(u.max()).item()) - self._hc_c0 + 2
        K = int(HCORR_K)
        r = int(HCORR_RANK)
        if r > 0:
            r = min(r, K, n_c)
            # `u` 는 배음 기저(고정 씨앗의 작은 난수), `v` 는 0 에서 출발한다 — 곱이 0 이라
            # **출발점이 예전과 같고**, ∂(uv)/∂v = u ≠ 0 이라 기울기가 흐른다.
            g = torch.Generator(device="cpu").manual_seed(20260918)
            u0 = torch.randn((2, K, r), generator=g, dtype=torch.float64) / math.sqrt(K)
            self._hc_u = u0.to(self.device).requires_grad_(True)
            self._hc_v = torch.zeros((2, r, n_c), dtype=torch.float64,
                                     device=self.device, requires_grad=True)
            print(f"  주기별 배음 보정: H1~H{K} × 주기 {n_c} 개, **계수 {r} 개로 묶음** "
                  f"(파라미터 {2 * r * (K + n_c)} 개, 자유 형태였다면 {2 * K * n_c}, "
                  f"눈금 {self._hc_scale:.4g})", flush=True)
        else:
            self.hcorr = torch.zeros((2, K, n_c), dtype=torch.float64,
                                     device=self.device, requires_grad=True)
            print(f"  주기별 배음 보정: H1~H{K} × 주기 {n_c} 개 "
                  f"(파라미터 {2 * K * n_c} 개, 눈금 {self._hc_scale:.4g})", flush=True)

    def _hcorr_kw(self) -> torch.Tensor | float:
        """배음 번호에 따른 L2 가중 (1, K, 1). `HCORR_L2_SLOPE` 가 0 이면 1.0 (스칼라)."""
        if HCORR_L2_SLOPE <= 0.0:
            return 1.0
        key = (self.hcorr.shape[1], float(HCORR_L2_KNEE), float(HCORR_L2_SLOPE))
        if getattr(self, "_hc_kw_key", None) != key:
            k = torch.arange(1, self.hcorr.shape[1] + 1, dtype=self.hcorr.dtype,
                             device=self.hcorr.device)
            w = 1.0 + HCORR_L2_SLOPE * (k - HCORR_L2_KNEE).clamp_min(0.0)
            self._hc_kw_key = key
            self._hc_kw = w.reshape(1, -1, 1)
        return self._hc_kw

    def wave_loss(self, y: torch.Tensor) -> torch.Tensor:
        """`WAVE_W` (§52.479): 저역(`WAVE_LO`–`WAVE_HI` Hz) 파형의 상대 제곱 오차 ‖lp(y) − lp(t)‖² / ‖lp(t)‖².
        포락(5.3 ms 창)은 주기 안의 에너지 톱니 — 배음 상대 위상 — 까지 본다. 크기 항들은 위상을 못 보고, 위상은 포락 안에서만 간접으로
        끌려 적합기가 배음 위상이 어긋난 골짜기에 머문다. 펄스 잠금으로 시각이 맞춰진 뒤의 다듬기용이다."""
        n = y.shape[-1]
        nf = 1 << int(math.ceil(math.log2(n)))
        key = (n, nf)
        if getattr(self, "_wave_key", None) != key:
            f = torch.fft.rfftfreq(nf, 1.0 / self.fs).to(self.target.device)
            m = ((f >= WAVE_LO) & (f <= WAVE_HI)).to(torch.float64)
            self._wave_mask = m
            T = torch.fft.rfft(self.target[0, :n].to(torch.float64), nf) * m
            self._wave_T = T
            self._wave_E = float((T.abs() ** 2).sum())
            self._wave_key = key
        Y = torch.fft.rfft(y[0].to(torch.float64), nf) * self._wave_mask
        return ((Y - self._wave_T).abs() ** 2).sum() / max(self._wave_E, 1e-20)

    def _ensure_room(self) -> None:
        """방 FIR 탭을 미리 만든다 — 늦게(첫 합성에서) 만들면 그 전에 뜬 스냅샷과 최적화 목록의 순서가 어긋나 복원이 깨졌다
        (전체 발화 다듬기의 lr 탐침: 960 탭 대 파열 개방 속도 2 개)."""
        if ROOM_FIR_MS > 0.0:
            K = int(ROOM_FIR_MS * self.fs / 1000.0)
            if getattr(self, "room_theta", None) is None or self.room_theta.shape[0] != K:
                self.room_theta = torch.zeros(K, dtype=torch.float64, device=self.target.device, requires_grad=True)

    def _room_fir(self, y: torch.Tensor) -> torch.Tensor:
        """`ROOM_FIR_MS` (§52.479): 방을 **결정적** FIR 로 — y + y ⊛ h, h (직접음 뒤 1 표본부터 ROOM_FIR_MS 까지) 를 적합한다.
        무작위 잡음 꼬리는 원본의 방과 실현이 달라 포락에 천장을 만든다(−13.5 dB 면 82.6 %). 방은 선형 시불변이라 발화 전체에 한 벌이다."""
        self._ensure_room()
        K = self.room_theta.shape[0]
        h = ROOM_FIR_SCALE * self.room_theta
        k0 = int(ROOM_FIR_START_MS * self.fs / 1000.0)
        if k0 > 0:
            h = torch.cat([torch.zeros(min(k0, K), dtype=h.dtype, device=h.device), h[k0:]])
        n = y.shape[-1]
        nf = 1 << int(math.ceil(math.log2(n + K + 1)))
        H = torch.fft.rfft(torch.cat([torch.zeros(1, dtype=h.dtype, device=h.device), h]), nf)
        tail = torch.fft.irfft(torch.fft.rfft(y.to(torch.float64), nf) * H, nf)[..., :n]
        return (y.to(torch.float64) + tail).to(y.dtype)

    def _room_fir_penalty(self) -> torch.Tensor | float:
        """h 의 감쇠 사전 — 늦은 탭일수록 비싸게 (exp(t/τ), τ = RT/6.91): 방의 꼬리는 지수로 잦아든다."""
        th = getattr(self, "room_theta", None)
        if th is None or ROOM_FIR_W <= 0.0:
            return 0.0
        t = torch.arange(1, th.shape[0] + 1, dtype=th.dtype, device=th.device) / self.fs
        w = torch.exp(t * 6.91 / ROOM_FIR_RT)
        return ROOM_FIR_W * ((ROOM_FIR_SCALE * th * w) ** 2).sum()

    def _head_fir(self, y: torch.Tensor) -> torch.Tensor:
        """머리 · 몸통 · 거리 FIR (`HEAD_FIR`) — y (1, N), FFT 합성곱, 비인과 쪽 `pre` 탭만큼 당긴다."""
        if getattr(self, "_hfir", None) is None:
            Z = np.load(HEAD_FIR)
            self._hfir = (torch.as_tensor(Z["h"], dtype=torch.float32), int(Z["pre"]))
        h, pre = self._hfir
        h = h.to(y.device, y.dtype)
        N = y.shape[-1]
        L = N + h.numel()
        nf = 1 << int(np.ceil(np.log2(L)))
        Y = torch.fft.irfft(torch.fft.rfft(y, nf) * torch.fft.rfft(h, nf), nf)
        return Y[..., pre:pre + N]

    def _late_reverb(self, y: torch.Tensor) -> torch.Tensor:
        """방 잔향 꼬리를 더한다 (`LATE_REVERB`). y (1, N)."""
        L = int(LR_LEN_S * self.fs)
        if getattr(self, "_lr_noise", None) is None or self._lr_noise.device != y.device:
            g = torch.Generator().manual_seed(1234)
            self._lr_noise = torch.randn(L, generator=g, dtype=torch.float64).to(y.device)
            t = torch.arange(L, dtype=torch.float64, device=y.device) / self.fs
            self._lr_t = t
            o = LR_ONSET_MS / 1000.0
            self._lr_ramp = ((t - o) / 0.003).clamp(0.0, 1.0)
        rt = torch.exp(self.rv_log_rt).clamp(0.05, 2.0)
        env = torch.exp(-6.91 * self._lr_t / rt) * self._lr_ramp
        h = self._lr_noise * env
        h = h / torch.sqrt((h * h).sum() + 1e-20) * torch.exp(self.rv_g_db)
        n = y.shape[-1]
        nf = 1 << int(math.ceil(math.log2(n + L)))
        Y = torch.fft.rfft(y.to(torch.float64), nf)
        H = torch.fft.rfft(h, nf)
        tail = torch.fft.irfft(Y * H, nf)[..., :n]
        with torch.no_grad():
            self._last_rv = (float(rt), float(self.rv_g_db) * 20.0 / math.log(10.0))
        return (y.to(torch.float64) + tail).to(y.dtype)

    def _te_samples(self, ctrl: torch.Tensor, n: int) -> torch.Tensor:
        """표본마다 LF 폐쇄 시각 te (주기 비, 0~1) — 그 순간의 Rd 에서 (`HCORR_WIN_TE`)."""
        if getattr(self, "_te_tab", None) is None:
            rds = np.linspace(0.2, _glottis_mod.rd_max(), 101)
            tes = [float(np.argmin(_glottis_mod.glottal_pulse(float(r)))) / 4096.0 for r in rds]
            self._te_tab = (torch.tensor(rds, dtype=torch.float32, device=ctrl.device),
                            torch.tensor(tes, dtype=torch.float32, device=ctrl.device))
        rg, tg = self._te_tab
        c = ctrl[0].detach().to(torch.float32)
        add = c[:, INDEX["adduction"]].clamp(0.0, 1.0)
        rd = (0.3 + 2.4 * (1.0 - add) ** 1.5 + c[:, INDEX["rd_offset"]]).clamp(0.212, _glottis_mod.rd_max())
        pos = ((rd - rg[0]) / (rg[-1] - rg[0]) * (len(rg) - 1)).clamp(0, len(rg) - 1.001)
        i0 = pos.floor().long()
        w = pos - i0.to(pos.dtype)
        te = tg[i0] * (1 - w) + tg[i0 + 1] * w
        te = te.repeat_interleave(self.hop)[:n]
        if te.shape[0] < n:
            te = torch.cat([te, te[-1:].expand(n - te.shape[0])])
        return te

    def _hcorr_fric_mask(self) -> torch.Tensor | None:
        """(K, C) 0/1 — `HCORR_FRIC_GATE`. 처음 부를 때 만든다 (`--init` 으로 보정을 되살린 판에도 같은 규칙)."""
        if not HCORR_FRIC_GATE or self.hcorr is None or self._pulse_phase is None:
            return None
        m = getattr(self, "_hc_fric_m", None)
        if m is not None:
            return m
        K, C = int(self.hcorr.shape[1]), int(self.hcorr.shape[2])
        T = int(self.track.n_frames)
        fr = np.zeros(T, bool)
        for nm in ("fricative", "sibilant"):
            v = np.asarray(getattr(self.track, nm, np.zeros(0)), bool)[:T]
            fr[:v.size] |= v
        with torch.no_grad():
            u = (CopySynthFitter._pp(self)[0] / (2.0 * math.pi)).detach().cpu().numpy()
        cyc = np.clip(np.floor(u).astype(np.int64) - self._hc_c0, 0, C - 1)
        fr_s = fr[np.clip(np.arange(u.size) // self.hop, 0, T - 1)]
        n_s = np.bincount(cyc, minlength=C).astype(np.float64)
        hit = np.bincount(cyc, weights=fr_s.astype(np.float64), minlength=C) > 0
        f0_c = self.fs / np.maximum(n_s, 1.0)
        k = np.arange(1, K + 1, dtype=np.float64)[:, None]
        mask = np.where(hit[None, :] & (k * f0_c[None, :] >= HCORR_FRIC_HZ), 0.0, 1.0)
        self._hc_fric_m = torch.as_tensor(mask, dtype=torch.float64, device=self.device)
        # **찍는다** — 켜졌는지, 어느 주기에 걸렸는지 로그에서 보이게.
        cs = np.flatnonzero(hit)
        t0 = np.array([np.flatnonzero(cyc == c)[0] / self.fs for c in cs]) if cs.size else np.zeros(0)
        runs, s = [], 0
        for i in range(1, cs.size + 1):
            if i == cs.size or cs[i] != cs[i - 1] + 1:
                runs.append(f"{t0[s]:.3f}–{t0[i - 1]:.3f} s({i - s})")
                s = i
        print(f"  마찰 주기 보정 차단: 목표 마찰 틀 {int(fr.sum())} 개에 걸친 주기 {cs.size} 개에서 {HCORR_FRIC_HZ:g} Hz 위 배음 보정을 끈다"
              + (" — " + ", ".join(runs[:12]) + (" …" if len(runs) > 12 else "") if runs else ""), flush=True)
        return self._hc_fric_m

    def _hcorr_fmin_mask(self) -> torch.Tensor | None:
        """(K, C) 0/1 — `HCORR_FMIN_HZ`: 주기마다 k·f0 가 그 아래인 배음을 끈다. 처음 부를 때 만든다."""
        if (HCORR_FMIN_HZ <= 0.0 and HCORR_FMAX_HZ <= 0.0) or self.hcorr is None or self._pulse_phase is None:
            return None
        m = getattr(self, "_hc_fmin_m", None)
        if m is not None:
            return m
        K, C = int(self.hcorr.shape[1]), int(self.hcorr.shape[2])
        with torch.no_grad():
            u = (CopySynthFitter._pp(self)[0] / (2.0 * math.pi)).detach().cpu().numpy()
        cyc = np.clip(np.floor(u).astype(np.int64) - self._hc_c0, 0, C - 1)
        n_s = np.bincount(cyc, minlength=C).astype(np.float64)
        f0_c = self.fs / np.maximum(n_s, 1.0)
        k = np.arange(1, K + 1, dtype=np.float64)[:, None]
        fk = k * f0_c[None, :]
        keep = fk >= HCORR_FMIN_HZ
        if HCORR_FMAX_HZ > 0.0:
            keep &= fk <= HCORR_FMAX_HZ
        mask = keep.astype(np.float64)
        self._hc_fmin_m = torch.as_tensor(mask, dtype=torch.float64, device=self.device)
        live = (n_s > 0) & keep.any(0)
        k1 = (mask[:, live] > 0).argmax(0) + 1 if live.any() else np.zeros(0)
        k2 = K - (mask[::-1, live] > 0).argmax(0) if live.any() else np.zeros(0)
        rng = lambda v: f"H{int(v.min())}~H{int(v.max())} (중앙 H{int(np.median(v))})" if v.size else "-"
        print(f"  보정 대역 제한: {HCORR_FMIN_HZ:g}~{HCORR_FMAX_HZ if HCORR_FMAX_HZ > 0 else float('inf'):g} Hz 밖 배음 보정을 끈다 — "
              f"주기마다 첫 배음 {rng(k1)}, 끝 배음 {rng(k2)}", flush=True)
        return self._hc_fmin_m

    def _hcorr_signal(self, ctrl: torch.Tensor | None = None):
        """주기별 배음 보정을 샘플률 신호로 편다 (B, N). 없으면 None."""
        if self.hcorr is None:
            return None
        pp = CopySynthFitter._pp(self)[0]
        u = pp / (2.0 * math.pi)
        fl = torch.floor(u.detach())
        idx = torch.clamp(fl.long() - self._hc_c0, 0, self.hcorr.shape[-1] - 1)
        frac = u - fl                                     # 주기 안 위치 (0~1), 위상 오프셋을 따라간다
        k = torch.arange(1, self.hcorr.shape[1] + 1, dtype=u.dtype,
                         device=u.device).unsqueeze(1)
        ang = (2.0 * math.pi) * k * frac.unsqueeze(0)      # (K, N)
        # 창의 좌표: 기본은 φ (열림 기준). `HCORR_WIN_TE` 면 φ − te — 창이 폐쇄 둘레를 남긴다. 기저(ang)는 그대로라
        # 저장된 보정 계수의 뜻이 안 바뀐다 (--init 으로 이어받을 수 있다).
        wfrac = frac
        if HCORR_WIN_TE and ctrl is not None:
            wfrac = torch.remainder(frac - self._te_samples(ctrl, frac.shape[0]).to(frac.dtype), 1.0)
        fm = CopySynthFitter._hcorr_fric_mask(self)       # 클래스 함수로 — 시험의 최소 대역물도 부른다
        A0, B0 = self.hcorr[0], self.hcorr[1]
        if fm is not None:
            A0, B0 = A0 * fm, B0 * fm
        lm = CopySynthFitter._hcorr_fmin_mask(self)
        if lm is not None:
            A0, B0 = A0 * lm, B0 * lm
        if HCORR_CONT:
            # **주기 경계에서 끊기지 않게** (`HCORR_CONT`). 가운데(φ=0.5)는 그 주기 계수, 경계로 갈수록 이웃 주기와 선형으로 섞어
            # 경계(φ=0 = 앞 주기의 φ=1)에서 두 주기의 평균이 되게 한다 — 같은 순간의 값이 하나다.
            C = A0.shape[-1]
            w_next = (frac - 0.5).clamp(min=0.0)                # φ ≥ 0.5: 다음 주기 몫 0 → 0.5
            w_prev = (0.5 - frac).clamp(min=0.0)                # φ < 0.5: 앞 주기 몫 0.5 → 0
            i_p = (idx - 1).clamp(min=0)
            i_n = (idx + 1).clamp(max=C - 1)
            w_c = 1.0 - w_next - w_prev
            a = A0[:, idx] * w_c + A0[:, i_p] * w_prev + A0[:, i_n] * w_next
            b = B0[:, idx] * w_c + B0[:, i_p] * w_prev + B0[:, i_n] * w_next
        else:
            a, b = A0[:, idx], B0[:, idx]
        if HCORR_KMIN > 1:
            # 낮은 배음은 건드리지 않는다 — 들리는 대역의 위상을 지킨다.
            keep = torch.arange(1, a.shape[0] + 1, device=a.device) >= HCORR_KMIN
            a = a * keep.unsqueeze(1)
            b = b * keep.unsqueeze(1)
        sig = (a * torch.cos(ang) + b * torch.sin(ang)).sum(0)
        if HCORR_WIN > 0.0:
            # 폐쇄(φ=0 과 φ=1)까지의 거리로 올림 코사인 창을 만든다 — 한가운데는 0 이 된다.
            d = torch.minimum(wfrac, 1.0 - wfrac)
            w = 0.5 + 0.5 * torch.cos(math.pi * (d / HCORR_WIN).clamp(max=1.0))
            if HCORR_WIN_K > 0:
                # 낮은 배음은 그대로 두고 **높은 배음에만** 씌운다. 두 합을 따로 낸다.
                kk = int(min(HCORR_WIN_K, self.hcorr.shape[1]))
                t_lo = (a[:kk] * torch.cos(ang[:kk]) + b[:kk] * torch.sin(ang[:kk])).sum(0)
                sig = t_lo + (sig - t_lo) * w
            else:
                sig = sig * w
        return (self._hc_scale * sig).unsqueeze(0)

    def synth(self, want_phase: bool = False):
        """엔진을 돌리고, **녹음 경로**가 주어졌으면 그것까지 통과시킨다.

        `room_ir` 은 방·마이크·코덱을 녹음에서 추정한 필터다 (engine/room.py). 이걸
        순방향에 넣으면 적합기가 그 응답을 성도·소스 파라미터로 흡수하지 않는다 —
        추정되는 물리량이 **마른 목소리**의 것이 된다. 위상(`out["phase"]`)은 성문
        위상이라 방을 안 통과한다: 펄스 항은 소스의 시각을 거는 것이므로 그대로 둔다.
        """
        self.eng.reset()
        _ctrl = self.control()
        self.eng.source_add = self._hcorr_signal(_ctrl)
        self.eng.vbar_gain = torch.exp(self.vb_log_g).to(torch.float32) if VOICE_BAR else None
        self.eng.transient_gain = (torch.exp(self.tr_gain)
                                   if self.tr_gain is not None else None)
        if getattr(self, "rel_log_r", None) is not None:
            self.eng.release_frames = [int(x) for x in np.asarray(self.track.bursts, int)]
            self.eng.release_rate = torch.exp(self.rel_log_r)
        pp = self._pp()
        out = self.eng(_ctrl, self.track.events, 0.0, pulse_phase=pp)
        self._last_ga = out.get("glottal_area") if isinstance(out, dict) else None
        y = out["audio"] * torch.exp(self.log_gain).to(torch.float32)
        if HEAD_FIR is not None:
            y = self._head_fir(y)
        if LATE_REVERB:
            y = self._late_reverb(y)
        if ROOM_FIR_MS > 0.0:
            y = self._room_fir(y)
        if DIRECT_EVENTS is not None:           # 입술에서 나온 과도음 — 방·마이크 앞 (§52.402)
            ev = torch.as_tensor(DIRECT_EVENTS, dtype=y.dtype, device=y.device)
            m = min(ev.shape[-1], y.shape[-1])
            y = torch.cat([y[..., :m] + ev[:m], y[..., m:]], -1)
        # 무성 벌점이 쓴다. 외부 물리 음원이면 LF 떨림 진폭이 아니라 **물리 음원 포락 × voice_gain** 을 문다 (§52.46) —
        # 외부 경로에서 LF 진폭은 소리를 내지 않고, F0 를 얼리면 기울기도 거의 없어 균형에서 빠졌다.
        self._amp = out.get("amp_ext") if out.get("amp_ext") is not None else out.get("amp")
        self._re = out.get("reynolds")           # 미래를 보는 레이놀즈 전이 항이 쓴다
        if self.room_ir is not None:
            y = room.apply_ir(y, self.room_ir)
        if BAND_LIMIT_HZ > 0.0:                 # 녹음 사슬의 대역 상한 — 바닥을 더하기 **전** (§52.291)
            y = self._band_limit(y)
        if BAND_LIMIT_LO_HZ > 0.0:              # 녹음 사슬의 저역 차단 — 같은 자리 (§52.401)
            y = self._band_limit_lo(y)
        if self._floor_amp is not None:          # 녹음 바닥 — 방을 지난 뒤, 마이크 앞
            fl = self._floor(y.shape[-1])
            if fl is not None:
                y = y + fl.to(y.device)
        if CODEC_TRACK:                          # 코덱 — 녹음 사슬의 맨 끝 (§52.206)
            y = self._codec(y)
        if CODEC_AAC and not getattr(self, "_codec_aac_off", False):    # 실제 AAC, 직통 기울기 (§52.523)
            y = y + (self._aac(y.detach()) - y.detach())
        return (y, out["phase"]) if want_phase else y

    def _aac(self, y: torch.Tensor) -> torch.Tensor:
        """ffmpeg AAC (`CODEC_AAC` 비트율) 부호화 → 복호화. 지연은 처음 한 번 상호상관으로 잰다 (보통 0). 창 없이 (CREATE_NO_WINDOW)."""
        import os, shutil, subprocess, tempfile
        import soundfile as _sf
        x = y.reshape(-1).double().cpu().numpy()
        d = tempfile.mkdtemp(prefix="aac_")
        src, enc, dec = (os.path.join(d, n) for n in ("a.wav", "a.m4a", "b.wav"))
        try:
            _sf.write(src, x, int(self.fs), subtype="FLOAT")
            fl = 0x08000000 if os.name == "nt" else 0
            subprocess.run([CODEC_FFMPEG, "-y", "-loglevel", "error", "-i", src, "-c:a", "aac", "-b:a", CODEC_AAC, enc],
                           check=True, creationflags=fl, stdin=subprocess.DEVNULL)
            subprocess.run([CODEC_FFMPEG, "-y", "-loglevel", "error", "-i", enc, "-ar", str(int(self.fs)), "-ac", "1", dec],
                           check=True, creationflags=fl, stdin=subprocess.DEVNULL)
            z, _ = _sf.read(dec)
        finally:
            shutil.rmtree(d, ignore_errors=True)
        if not hasattr(self, "_aac_lag"):
            m = min(len(x), len(z) - 2048)
            c = np.correlate(z[:m + 2048], x[:m], "valid")
            self._aac_lag = int(np.argmax(c))
        z = z[self._aac_lag:self._aac_lag + len(x)]
        z = np.pad(z, (0, len(x) - len(z)))
        return torch.as_tensor(z, dtype=y.dtype, device=y.device).reshape(y.shape)

    def render_codec(self) -> np.ndarray | None:
        """코덱(`CODEC_AAC`)을 거친 결과 — 원본과 같은 조건의 비교용. 코덱이 꺼져 있으면 None."""
        if not CODEC_AAC:
            return None
        with torch.no_grad():
            return self.synth()[0].cpu().numpy()

    def _band_limit_lo(self, y: torch.Tensor) -> torch.Tensor:
        """녹음 사슬의 저역 차단 (`BAND_LIMIT_LO_HZ`). 영위상 — 크기만 깎고 시각은 그대로다.

        끝이 둘러 붙지 않게 양쪽에 0.1 s 씩 0 을 대고 FFT 로 곱한다.
        """
        x = y if y.dim() == 2 else y.reshape(1, -1)
        n = x.shape[-1]
        pad = int(0.1 * self.fs)
        m = n + 2 * pad
        key = (float(BAND_LIMIT_LO_HZ), int(BAND_LIMIT_LO_ORDER), m, str(x.device))
        if getattr(self, "_bll_key", None) != key:
            f = torch.fft.rfftfreq(m, 1.0 / self.fs).to(torch.float64)
            r = (float(BAND_LIMIT_LO_HZ) / f.clamp_min(1e-3)) ** (2 * int(BAND_LIMIT_LO_ORDER))
            self._bll_H = (1.0 / torch.sqrt(1.0 + r)).to(x.device)
            self._bll_key = key
        xp = torch.nn.functional.pad(x.to(torch.float64), (pad, pad))
        out = torch.fft.irfft(torch.fft.rfft(xp) * self._bll_H, m)[:, pad:pad + n]
        return out.to(y.dtype) if y.dim() == 2 else out.to(y.dtype).reshape(y.shape)

    def _band_limit(self, y: torch.Tensor) -> torch.Tensor:
        """녹음 사슬의 고정 대역 상한을 씌운다 (`BAND_LIMIT_HZ`). 선형 위상이라 **시각이 안 밀린다**.

        좌우로 `taps//2` 씩 채워 넣고 `conv1d` 하므로 군지연이 정확히 상쇄된다. 펄스 위상 항이
        표본 단위로 걸려 있어 한 표본이라도 밀리면 안 된다.
        """
        key = (float(BAND_LIMIT_HZ), int(BAND_LIMIT_TAPS), str(self.target.device))
        if getattr(self, "_bl_key", None) != key:
            h = _codec_lowpass(float(BAND_LIMIT_HZ), self.fs, int(BAND_LIMIT_TAPS))
            self._bl_key = key
            self._bl_fir = torch.as_tensor(h[None, None, :], dtype=torch.float32,
                                           device=self.target.device)
        x = y if y.dim() == 2 else y.reshape(1, -1)
        fir = self._bl_fir.to(x.dtype)
        pad = fir.shape[-1] // 2
        out = torch.nn.functional.conv1d(
            torch.nn.functional.pad(x.unsqueeze(1), (pad, pad)), fir).squeeze(1)
        return out if y.dim() == 2 else out.reshape(y.shape)

    def _codec_prepare(self):
        """목표의 프레임별 코덱 차단 주파수와 마스크 (1, F, T). 한 번만 한다."""
        if hasattr(self, "_codec_mask"):
            return self._codec_mask
        # **잡음 제거 전 신호에서 잰다.** 코덱 차단은 녹음 사슬의 성질이고, 우리 잡음 제거기는 그 위 대역의
        # 남은 바닥을 더 깎아 **없던 차단을 만들어 낸다** — 같은 음절에서 원본은 17.5 k×42·20 k×20 프레임인데
        # 잡음 제거본은 16.5 k×16 으로 내려앉았다. `codec_source` 가 있으면 그것을 쓰고, 없으면 목표를 쓴다.
        src = getattr(self, "codec_source", None)
        t = self.target if src is None else src
        t = (t if t.dim() == 2 else t.reshape(1, -1))[0].detach().double().cpu()
        n = self.target.shape[-1]
        if t.numel() != n:                                                              # 프레임 수를 목표에 맞춘다
            t = torch.nn.functional.pad(t[:n], (0, max(0, n - t.numel())))
        win = torch.hann_window(CODEC_NFFT, dtype=torch.float64)
        X = torch.stft(t, CODEC_NFFT, CODEC_HOP, window=win, center=True, return_complex=True)
        db = (10.0 * torch.log10(X.real ** 2 + X.imag ** 2 + 1e-20)).numpy()          # (F, T)
        F_, T_ = db.shape
        fr = np.linspace(0.0, self.fs / 2.0, F_)
        ref = db[(fr >= 12000.0) & (fr < 15000.0)].mean(0)
        lev = 10.0 * np.log10((10.0 ** (db / 10.0)).sum(0) + 1e-20)
        hi = fr >= CODEC_MIN_HZ
        cut = np.full(T_, np.nan)
        for j in range(T_):
            below = (db[hi, j] < ref[j] - CODEC_DROP_DB).astype(float)
            run = np.convolve(below, np.ones(CODEC_RUN_BINS) / CODEC_RUN_BINS, mode="same") > 0.9
            k = np.flatnonzero(run)
            cut[j] = fr[hi][k[0]] if len(k) else self.fs / 2.0
        quiet = lev < np.percentile(lev, CODEC_LEVEL_PCT)
        cut[quiet] = np.nan
        ok = np.flatnonzero(np.isfinite(cut))
        if len(ok) == 0:
            cut[:] = self.fs / 2.0
        else:
            cut = np.interp(np.arange(T_), ok, cut[ok])                                 # 조용한 프레임은 이웃에서 채운다
            from scipy.ndimage import median_filter
            cut = median_filter(cut, size=5, mode="nearest")
        self._codec_cut = cut
        n_s = int(self.target.shape[-1])
        t_fr = np.arange(T_) * CODEC_HOP                                                # 프레임 중심 (center=True)
        cut_s = np.interp(np.arange(n_s), t_fr, cut)                                    # 표본마다의 차단
        anc = np.asarray(CODEC_ANCHORS, float)
        j = np.clip(np.searchsorted(anc, cut_s) - 1, 0, len(anc) - 2)                   # 가장 가까운 두 고정점
        w = np.clip((cut_s - anc[j]) / (anc[j + 1] - anc[j]), 0.0, 1.0)
        W = np.zeros((len(anc), n_s))
        np.add.at(W, (j, np.arange(n_s)), 1.0 - w)
        np.add.at(W, (j + 1, np.arange(n_s)), w)
        self._codec_w = torch.as_tensor(W, dtype=torch.float32, device=self.target.device)
        self._codec_fir = torch.as_tensor(
            np.stack([_codec_lowpass(fc, self.fs) for fc in anc]),
            dtype=torch.float32, device=self.target.device).unsqueeze(1)                # (A, 1, TAPS)
        self._codec_mask = self._codec_w
        full = float(np.mean(cut >= 0.49 * self.fs) * 100.0)
        lo_ = cut[cut < 0.49 * self.fs]
        print(f"  코덱 대역폭 트랙: 프레임 {T_}, 차단 없음 {full:.0f} %"
              + (f", 차단 {100 - full:.0f} % (중앙 {np.median(lo_):.0f} Hz, 10/90 % {np.percentile(lo_, 10):.0f}/"
                 f"{np.percentile(lo_, 90):.0f})" if len(lo_) else ""), flush=True)
        return self._codec_mask

    def _codec(self, y: torch.Tensor) -> torch.Tensor:
        """녹음 사슬의 시변 코덱 차단을 씌운다 (`CODEC_TRACK`) — FIR 묶음의 표본별 교차감쇠."""
        self._codec_prepare()
        x = y if y.dim() == 2 else y.reshape(1, -1)
        fir = self._codec_fir.to(x.dtype)
        pad = fir.shape[-1] // 2
        b = torch.nn.functional.conv1d(torch.nn.functional.pad(x.unsqueeze(1), (pad, pad)), fir)   # (B, A, n)
        n = min(b.shape[-1], self._codec_w.shape[-1])
        out = (b[..., :n] * self._codec_w[None, :, :n].to(x.dtype)).sum(1)
        if b.shape[-1] > n:                                                  # 목표보다 긴 렌더의 꼬리는 마지막 무게로
            tail = (b[..., n:] * self._codec_w[None, :, -1:].to(x.dtype)).sum(1)
            out = torch.cat([out, tail], -1)
        return out if y.dim() == 2 else out.reshape(y.shape)

    def _floor_shape(self) -> torch.Tensor:
        """녹음 바닥 잡음의 rfft 진폭 모양 (n//2+1,). 백색 잡음에 곱해 목표와 같은 바닥을 낸다.

        **바닥은 "아무도 말하지 않을 때 있는 것" 에서 잰다** (MEASUREMENTS §52.396). 예전에는
        구간 전체의 10 분위를 썼는데, 이 구간은 10 ms 프레임 281 개 중 **6 개(2.1 %)만** 정점
        −45 dB 아래다 — 10 분위는 말소리 한가운데다. 그 모양으로 만든 잡음의 rms 가 −27.2 dB 인데
        목표의 진짜 조용한 창은 −64.9 dB 였고, 렌더에서 무음 구간이 목표보다 **+6.1 dB** 컸다.
        사용자가 들은 배경 잡음과, 그 바닥에 묻혀 안 들리던 맨 앞 클릭이 둘 다 여기서 나왔다.

        무음 프레임이 모자라면 옛 방식으로 물러난다.
        """
        from .denoise import noise_profile
        t = self.target[0].detach().cpu().double().numpy()
        nf = 2048
        n = t.shape[0]
        if FLOOR_REF is not None and len(FLOOR_REF) >= 20 * nf:
            fr = np.fft.rfftfreq(n, 1.0 / self.fs)
            fp = np.fft.rfftfreq(nf, 1.0 / self.fs)
            r = np.asarray(FLOOR_REF, dtype=np.float64)
            w = max(1, int(round(0.010 * self.fs)))
            m = r.shape[0] // w
            lv = 10.0 * np.log10((r[:m * w].reshape(m, w) ** 2).mean(1) + 1e-30)
            quiet = lv <= np.percentile(lv, FLOOR_REF_PCT)
            q = np.concatenate([r[i * w:(i + 1) * w] for i in np.flatnonzero(quiet)])
            prof = noise_profile(q, int(self.fs), n_fft=nf, hop=nf // 4, quantile=0.5)
            ref_rms = float(np.sqrt((q * q).mean()))
            print(f"  녹음 바닥: 파일 전체의 가장 조용한 {FLOOR_REF_PCT:g} % ({int(quiet.sum())} 프레임)에서 잰다, "
                  f"rms {20 * np.log10(ref_rms + 1e-30):.1f} dB", flush=True)
            shape = np.sqrt(np.interp(fr, fp, prof) + 1e-30)
            rng = np.random.default_rng(0)
            z = np.fft.irfft(np.fft.rfft(rng.standard_normal(n)) * shape, n)
            shape *= ref_rms / max(float(np.sqrt((z * z).mean())), 1e-30)
            return torch.as_tensor(shape, dtype=torch.float64, device=self.target.device)
        fr = np.fft.rfftfreq(n, 1.0 / self.fs)
        fp = np.fft.rfftfreq(nf, 1.0 / self.fs)
        w = max(1, int(round(0.010 * self.fs)))
        m = n // w
        lv = 10.0 * np.log10((t[:m * w].reshape(m, w) ** 2).mean(1) + 1e-30)
        quiet = lv < lv.max() - FLOOR_QUIET_DB
        # **무음이 2048 표본에 못 미쳐도 옛 방식으로 물러나지 않는다** (MEASUREMENTS §52.401). 옛 방식은 말소리의
        # 10 분위라 바닥이 **말소리 모양의 정상 잡음**이 되고, 말 밑에 늘 깔려 사용자에게 "물 흐르는 소리" 로 들렸다.
        # 0.451~3.271 s 구간은 무음이 1920 표본뿐이라 거기 걸렸다. 1024 창까지는 무음에서 잰다.
        nq = int(quiet.sum()) * w
        if nq >= 1024:
            nfq = nf if nq >= nf else 1024
            q = np.concatenate([t[i * w:(i + 1) * w] for i in np.flatnonzero(quiet)])
            prof = noise_profile(q, int(self.fs), n_fft=nfq, hop=nfq // 4, quantile=0.5)
            prof = np.interp(fp, np.fft.rfftfreq(nfq, 1.0 / self.fs), prof)
            ref_rms = float(np.sqrt((q * q).mean()))
            print(f"  녹음 바닥: 무음 {nq} 표본에서 잰다 (창 {nfq}), rms {20 * np.log10(ref_rms + 1e-30):.1f} dB",
                  flush=True)
        else:                                             # 무음이 모자라다 — 옛 방식
            prof = noise_profile(t, int(self.fs), n_fft=nf, hop=512, quantile=0.10)
            ref_rms = None
            print(f"  녹음 바닥: 무음 {nq} 표본뿐 — **말소리 10 분위로 물러난다** (말소리 모양 잡음이 된다)",
                  flush=True)
        shape = np.sqrt(np.interp(fr, fp, prof) + 1e-30)
        # 수준 맞춤: 같은 모양의 잡음을 한 번 만들어 같은 자로 재고 비를 곱한다.
        rng = np.random.default_rng(0)
        z = np.fft.irfft(np.fft.rfft(rng.standard_normal(n)) * shape, n)
        if ref_rms is not None:
            shape *= ref_rms / max(float(np.sqrt((z * z).mean())), 1e-30)
        else:
            got = noise_profile(z, int(self.fs), n_fft=nf, hop=512, quantile=0.5)
            k = (fp > 200) & (fp < 0.45 * self.fs)
            shape *= np.sqrt(np.median(prof[k]) / max(np.median(got[k]), 1e-30))
        return torch.as_tensor(shape, dtype=torch.float64, device=self.target.device)

    def _floor(self, n: int) -> torch.Tensor | None:
        if self._floor_amp is None:
            return None
        w = self.eng.noise.white("floor", 0, n, 1, torch.float64, self.target.device)[0]
        amp = self._floor_amp
        if amp.shape[0] != n // 2 + 1:
            return None
        return torch.fft.irfft(torch.fft.rfft(w) * amp, n).to(torch.float32).unsqueeze(0)

    def synth_dry(self) -> torch.Tensor:
        """녹음 경로를 빼고 렌더한다 — 이게 **목소리 자체**다."""
        self.eng.reset()
        pp = self._pp()
        out = self.eng(self.control(), self.track.events, 0.0, pulse_phase=pp)
        return out["audio"] * torch.exp(self.log_gain).to(torch.float32)






    def measure_lag_ms(self, y: np.ndarray | None = None) -> tuple[np.ndarray, np.ndarray]:
        """창마다 목표 대비 합성의 최적 지연 [ms] 과 그때의 상관. `PULSE_REFINE` 참조.

        양수는 **합성이 늦다**는 뜻이다 (목표의 `s0` 이 합성의 `s0 + d` 와 맞는다).
        저역만 쓴다 — 고역은 위상이 무작위라(§52.80) 최댓값이 주기를 건너뛴다.
        """
        from scipy.signal import butter, sosfiltfilt
        if y is None:
            with torch.no_grad():
                y = self.synth()[0].detach().cpu().numpy().astype(np.float64)
        t = self.target[0].detach().cpu().numpy().astype(np.float64)
        n = min(len(t), len(y))
        sos = butter(4, REFINE_LP_HZ, "lp", fs=self.fs, output="sos")
        a, b = sosfiltfilt(sos, t[:n]), sosfiltfilt(sos, y[:n])
        win = max(64, int(REFINE_WIN_MS * self.fs / 1000.0))
        hop = max(1, int(REFINE_HOP_MS * self.fs / 1000.0))
        lm = max(1, int(REFINE_MAX_MS * self.fs / 1000.0))
        nf = (n - win - 2 * lm) // hop
        lag = np.zeros(max(nf, 0)); rr = np.zeros(max(nf, 0))
        edge = np.zeros(max(nf, 0), dtype=bool)          # 최댓값이 탐색 끝(±REFINE_MAX_MS)에 걸린 창 — 지연이 범위 밖이다
        for i in range(max(nf, 0)):
            s0 = i * hop + lm
            u = a[s0:s0 + win]
            nu = float(np.linalg.norm(u))
            if nu < 1e-9:
                continue
            seg = b[s0 - lm:s0 + win + lm]
            c = np.correlate(seg, u, "valid")                  # 길이 2*lm+1, 색인 j -> 지연 j-lm
            e = np.sqrt(np.convolve(seg * seg, np.ones(win), "valid")) * nu
            c = c / np.maximum(e[:len(c)], 1e-12)
            j = int(np.argmax(c))
            edge[i] = not (0 < j < len(c) - 1)
            if 0 < j < len(c) - 1:                             # 부표본 (포물선 꼭짓점)
                d2 = c[j - 1] - 2 * c[j] + c[j + 1]
                off = 0.5 * (c[j - 1] - c[j + 1]) / d2 if abs(d2) > 1e-12 else 0.0
            else:
                off = 0.0
            lag[i] = (j - lm + float(np.clip(off, -1.0, 1.0))) / self.fs * 1000.0
            rr[i] = float(c[j])
        self._lag_edge = edge
        return lag, rr

    def _refine_by_cycle(self, verbose: bool = True) -> float:
        """주기마다 잰 시각 어긋남만큼 잠금 위상을 앞당긴다. `REFINE_CYCLE` 참조."""
        from scipy.ndimage import median_filter
        dt, ctr = self.cycle_lag_ms()
        if dt.size < 8:
            if verbose:
                print("    잠금 위상 보정(주기): 쓸 주기가 모자라 건너뛴다", flush=True)
            return 0.0
        raw = dt.copy()
        if REFINE_CYCLE_MED > 1:
            dt = median_filter(dt, max(1, int(REFINE_CYCLE_MED) | 1), mode="nearest")
        dt = np.clip(dt, -REFINE_MAX_MS, REFINE_MAX_MS)
        ph = self._pulse_phase[0].detach().cpu().numpy()
        n = len(ph)
        d = np.interp(np.arange(n), ctr, dt * self.fs / 1000.0,
                      left=dt[0] * self.fs / 1000.0, right=dt[-1] * self.fs / 1000.0)
        new = _warp_phase(ph, d)                                 # 합성이 늦으면 위상을 앞당긴다 — 슬루 제한 · 매끈 (§52.532)
        self._pulse_phase = torch.as_tensor(new[None, :], dtype=torch.float64,
                                            device=self._pulse_phase.device)
        moved = float(np.sqrt(np.mean((d / self.fs * 1000.0) ** 2)))
        if verbose:
            print(f"    잠금 위상 보정(주기 {dt.size} 개): 어긋남 중앙 {np.median(raw):+.4f} ms, "
                  f"rms {np.sqrt(np.mean(raw ** 2)):.4f} ms, 10/90 % {np.percentile(dt, 10):+.4f}/"
                  f"{np.percentile(dt, 90):+.4f}, 움직인 양 rms {moved:.4f} ms", flush=True)
        return moved

    def cycle_lag_ms(self, y: np.ndarray | None = None):
        """성문 주기마다 목표 대비 합성의 시각 어긋남 [ms] 과 주기 중심 [표본]. `REFINE_CYCLE` 참조.

        주기 안에서 배음 복소 진폭을 구해 위상차를 k 에 대한 **원점을 지나는 직선**으로 맞춘다.
        기울기 s 가 Δφ_k = s·k 이므로 δt = s/(2π)·T 다. 양수는 합성이 늦다는 뜻(기존 부호와 같다).
        """
        pul = np.asarray(getattr(self.track, "pulses", np.zeros(0)), dtype=np.float64)
        if pul.size < 4:
            return np.zeros(0), np.zeros(0)
        if y is None:
            with torch.no_grad():
                y = self.synth()[0].detach().cpu().numpy().astype(np.float64)
        t = self.target[0].detach().cpu().numpy().astype(np.float64)
        n = min(len(t), len(y))
        K = max(2, int(REFINE_CYCLE_K))
        dt, ctr = [], []
        for a, b in zip(pul[:-1], pul[1:]):
            i0, i1 = int(a * self.fs), int(b * self.fs)
            m = i1 - i0
            if m < 40 or m > self.fs // 60 or i1 > n:
                continue
            q = np.arange(m) / m
            e = np.exp(-2j * np.pi * np.outer(np.arange(1, K + 1), q))
            ct, cy = e @ t[i0:i1] / m, e @ y[i0:i1] / m
            w = np.abs(ct)
            if w.sum() < 1e-12:
                continue
            d = np.angle(cy * np.conj(ct))
            k = np.arange(1, K + 1, dtype=np.float64)
            den = float((w * k * k).sum())
            if den < 1e-30:
                continue
            sl = float((w * k * d).sum() / den)
            # 합성이 δ 만큼 늦으면 cy = ct·exp(−i2πkδ/T) 라 기울기가 음수다 — 부호를 뒤집어
            # 기존 `measure_lag_ms` 와 같은 규약(양수 = 합성이 늦다)으로 맞춘다.
            dt.append(-sl / (2.0 * np.pi) * (m / self.fs * 1000.0))
            ctr.append(0.5 * (i0 + i1))
        return np.asarray(dt), np.asarray(ctr)

    def rescan_phi0(self, n: int | None = None, verbose: bool = True) -> None:
        """위상 오프셋을 다시 훑는다 (`PHI0_RESCAN`, §52.478) — 처음 훑기는 분석 초기값 위에서라 손실이 위상에 대해 믿을 만하지 않고,
        1/12 주기 격자라 거칠다. 성도가 자리 잡은 뒤 한 주기를 n 등분해 가장 낮은 손실 자리로 옮긴다 (다듬기 창의 지연 탐색 범위 밖이던 어긋남)."""
        n = PHI0_RESCAN if n is None else n
        if n <= 0 or self._pulse_phase is None:
            return
        c0 = float(self.pulse_phi0.item())
        best = None
        with torch.no_grad():
            for k in range(n):
                phi = c0 + 2.0 * math.pi * (k / n - 0.5)
                self.pulse_phi0.fill_(phi)
                lv = float(self.loss()[0])
                if best is None or lv < best[0]:
                    best = (lv, phi)
            self.pulse_phi0.fill_(best[1])
        if verbose:
            print(f"    위상 오프셋 다시 훑기: {c0:+.3f} → {best[1]:+.3f} rad (손실 {best[0]:.4f})", flush=True)

    def refine_pulse_phase(self, verbose: bool = True) -> float:
        """잰 지연만큼 잠금 위상을 앞당긴다. 움직인 양의 rms [ms] 를 돌려준다. `PULSE_REFINE` 참조."""
        if self._pulse_phase is None:
            return 0.0
        if PHI0_RESCAN > 0:
            self.rescan_phi0(verbose=verbose)
        from scipy.ndimage import median_filter, uniform_filter1d
        if REFINE_CYCLE:
            mv = self._refine_by_cycle(verbose)
            if PULSE_REGULAR:
                self._reregularize_pulse(verbose)
            return mv
        lag, rr = self.measure_lag_ms()
        raw_lag = lag.copy()
        edge = np.asarray(getattr(self, "_lag_edge", np.zeros(lag.size, dtype=bool)))
        if lag.size < 8:
            return 0.0
        good = rr > 0.5
        n_rr, n_edge = int(good.sum()), int((edge & good).sum()) if edge.size == good.size else 0
        if REFINE_DROP_EDGE and edge.size == good.size:
            good = good & ~edge
        if good.sum() < 8:
            return 0.0
        lag = np.where(good, lag, 0.0)
        lag = median_filter(lag, max(1, REFINE_MED | 1), mode="nearest")
        w = max(1, int(round(REFINE_SMOOTH_MS / REFINE_HOP_MS)))
        lag = uniform_filter1d(lag, w, mode="nearest")
        lag = np.clip(lag, -REFINE_MAX_MS, REFINE_MAX_MS)
        if REFINE_DUMP:
            k_ = getattr(self, "_refine_n", 0)
            self._refine_n = k_ + 1
            np.savez(f"{REFINE_DUMP}_refine{k_}.npz", raw_lag=raw_lag, rr=rr, edge=edge, good=good, lag=lag,
                     hop_ms=REFINE_HOP_MS, max_ms=REFINE_MAX_MS)
        hop = max(1, int(REFINE_HOP_MS * self.fs / 1000.0))
        lm = max(1, int(REFINE_MAX_MS * self.fs / 1000.0))
        ph = self._pulse_phase[0].detach().cpu().numpy()
        n = len(ph)
        centers = np.arange(len(lag)) * hop + lm + 0.5 * REFINE_WIN_MS * self.fs / 1000.0
        d = np.interp(np.arange(n), centers, lag, left=lag[0], right=lag[-1]) * self.fs / 1000.0
        new = _warp_phase(ph, d)                                 # 합성이 늦으면 위상을 앞당긴다 — 변화율 제한 (§52.525)
        self._pulse_phase = torch.as_tensor(new[None, :], dtype=torch.float64,
                                            device=self._pulse_phase.device)
        moved = float(np.sqrt(np.mean((d / self.fs * 1000.0) ** 2)))
        if verbose:
            print(f"    잠금 위상 보정: 지연 중앙 {np.median(lag):+.3f} ms, "
                  f"10/90 % {np.percentile(lag, 10):+.3f}/{np.percentile(lag, 90):+.3f}, "
                  f"움직인 양 rms {moved:.3f} ms (상관 중앙 {np.median(rr[good]):.3f}, "
                  f"끝 걸림 {n_edge}/{n_rr} 창{' 버림' if REFINE_DROP_EDGE else ''})", flush=True)
        if REFINE_SLIP_ITERS > 0:
            self.repair_pulse_slips(verbose)
        if PULSE_REGULAR:
            self._reregularize_pulse(verbose)
        return moved

    def _reregularize_pulse(self, verbose: bool = True) -> None:
        """다듬기 뒤 구동 박자를 다시 정규화한다 (`PULSE_REGULAR`, §52.530). 다듬기의 지연 측정은 20 ms 창마다 흔들려 위상을 0.28–0.44 ms rms 씩
        비틀었고 (KWF_m15 · m19), 정규화로 ~1 % 까지 낮춘 구동 지터가 3.3–3.4 % 로 되돌아가 출력 20–80 Hz 변조가 다시 섰다 (m19 0.1–1k +8 dB).
        다듬기는 느린 정렬만 맡고, 주기 길이는 원본 Praat 주기점으로 되돌린다."""
        if not PULSE_REGULAR or self._pulse_phase is None:
            return
        ph0 = self._pulse_phase[0].detach().cpu().numpy()
        tgt = self.target[0].detach().cpu().numpy().astype(np.float64)
        ph1, rep = regularize_pulse_phase(ph0, tgt, float(self.fs))
        self._pulse_phase = torch.as_tensor(ph1[None, :], dtype=torch.float64, device=self._pulse_phase.device)
        if verbose:
            print(f"    구동 박자 다시 정규화 (§52.530): 빠른 흔들림 {rep.get('fast_rms', 0):.3f} 주기 rms 를 버림", flush=True)

    def measure_slips(self, y: np.ndarray | None = None):
        """미끄러진 창 찾기 (`REFINE_SLIP_ITERS`). 반환 (창 중심 [표본], 최적 지연 [ms, 양수 = 합성이 늦다], 미끄러짐 여부, 유성 창 여부)."""
        from scipy.signal import butter, sosfiltfilt
        if y is None:
            with torch.no_grad():
                y = self.synth()[0].detach().cpu().numpy().astype(np.float64)
        t = self.target[0].detach().cpu().numpy().astype(np.float64)
        n = min(len(t), len(y))
        sos = butter(4, SLIP_LP_HZ, "lp", fs=self.fs, output="sos")
        a, b = sosfiltfilt(sos, t[:n]), sosfiltfilt(sos, y[:n])
        ph = self._pulse_phase[0].detach().cpu().numpy()
        inc = np.gradient(ph)                                   # rad/표본 — 그 자리 주기
        win = int(SLIP_WIN_MS * self.fs / 1000.0); hop = max(1, int(SLIP_HOP_MS * self.fs / 1000.0))
        lmax = int(0.5 * 2.0 * np.pi / max(float(np.percentile(inc, 5)), 1e-6))     # 가장 긴 주기의 반
        idx = np.arange(lmax, n - win - lmax, hop)
        en = np.array([float(np.dot(a[i:i + win], a[i:i + win])) for i in idx])
        voiced = en > np.percentile(en, 30) if en.size else np.zeros(0, bool)
        lag = np.zeros(idx.size); slip = np.zeros(idx.size, bool)
        for k, i in enumerate(idx):
            if not voiced[k]:
                continue
            T = 2.0 * np.pi / max(float(inc[min(i + win // 2, n - 1)]), 1e-6)
            lm = max(1, min(lmax, int(0.5 * T)))
            u = a[i:i + win]; seg = b[i - lm:i + win + lm]
            c = np.correlate(seg, u, "valid")
            e = np.sqrt(np.convolve(seg * seg, np.ones(win), "valid")) * max(float(np.linalg.norm(u)), 1e-12)
            c = c / np.maximum(e[:len(c)], 1e-12)
            j = int(np.argmax(c)); c0 = float(c[lm]); cb = float(c[j])
            lag[k] = (j - lm) / self.fs * 1000.0
            slip[k] = c0 < SLIP_C0 and cb > SLIP_CB and cb - c0 > SLIP_GAIN
        return idx + win // 2, lag, slip, voiced

    def repair_pulse_slips(self, verbose: bool = True) -> int:
        """미끄러진 창이 이어진 구간만 그 지연으로 잠금 위상을 국소 보정한다 (`REFINE_SLIP_ITERS`). 마지막에 남은 미끄러진 창 수를 돌려준다."""
        if self._pulse_phase is None:
            return 0
        prev, keep = None, None
        for it in range(REFINE_SLIP_ITERS + 1):
            ctr, lag, slip, voiced = self.measure_slips()
            ns = int(slip.sum())
            if verbose:
                print(f"    펄스 미끄러짐 수리 {it}: 미끄러진 창 {ns}/{int(voiced.sum())}", flush=True)
            if prev is not None and ns >= prev:                  # 늘었거나 그대로면 직전 위상으로 되돌리고 멈춘다
                self._pulse_phase = keep
                return prev
            if ns == 0 or it == REFINE_SLIP_ITERS:
                return ns
            prev, keep = ns, self._pulse_phase
            d = np.where(slip, lag, 0.0)
            tap = max(1, int(SLIP_TAPER_MS / SLIP_HOP_MS))
            w = np.zeros(d.size)
            for k in np.flatnonzero(slip):                       # 미끄러진 창마다 가장자리 경사 무게 — 이웃 미끄러짐과는 큰 쪽
                lo_, hi_ = max(0, k - tap), min(d.size, k + tap + 1)
                ramp = 1.0 - np.abs(np.arange(lo_, hi_) - k) / (tap + 1)
                w[lo_:hi_] = np.maximum(w[lo_:hi_], ramp)
            dd = np.zeros(d.size)
            for k in range(d.size):                              # 경사 구간은 가장 가까운 미끄러진 창의 지연
                if w[k] > 0:
                    near = np.flatnonzero(slip)[np.argmin(np.abs(np.flatnonzero(slip) - k))]
                    dd[k] = w[k] * d[near]
            ph = self._pulse_phase[0].detach().cpu().numpy()
            n = len(ph)
            dsmp = np.interp(np.arange(n), ctr, dd, left=0.0, right=0.0) * self.fs / 1000.0
            new = _warp_phase(ph, dsmp)                          # 변화율 제한 (§52.525)
            self._pulse_phase = torch.as_tensor(new[None, :], dtype=torch.float64,
                                                device=self._pulse_phase.device)
        return prev or 0

    def _build_pulse_phase(self) -> torch.Tensor | None:
        """목표 폐쇄 시각에서 만든 샘플률 위상 (1, N) [rad, 누적]. `PULSE_LOCK` 참조."""
        n = int(self.target.shape[-1])
        idx = self.pulse_idx.detach().cpu().numpy().astype(np.int64)
        idx = idx[(idx >= 0) & (idx < n)]
        if idx.size < 3:
            return None
        f0 = np.asarray(self.track["f0_target"], dtype=np.float64)
        f0s = np.repeat(np.clip(f0, 50.0, 800.0), self.hop)[:n]
        if f0s.size < n:
            f0s = np.pad(f0s, (0, n - f0s.size), mode="edge")
        inc = 2.0 * np.pi * f0s / self.fs
        lo, hi = int(0.002 * self.fs), int(0.025 * self.fs)
        for a, b in zip(idx[:-1], idx[1:]):
            L = int(b - a)
            if lo <= L <= hi:                       # 그럴듯한 한 주기만 — 무성 틈은 f0 로 잇는다
                inc[a:b] = 2.0 * np.pi / L
        ph = np.cumsum(inc)
        ph -= ph[idx[0]]                            # 첫 폐쇄에서 위상 0
        if PULSE_SMOOTH:
            # **폐쇄 사이를 직선이 아니라 단조 3차(PCHIP)로 잇는다** (§52.480). 직선이면 순간 주파수가 폐쇄마다 계단으로 바뀌어 주기 경계마다
            # 성문 파형의 빠르기가 끊긴다 — 사용자가 짚은 "이산 교정의 인조적 소리". 매듭은 폐쇄 시각(위상 2πk 그대로)과, 폐쇄가 없는 틈의 5 ms 간격.
            from scipy.interpolate import PchipInterpolator
            step = max(1, int(0.005 * self.fs))
            grid = np.arange(0, n, step)
            far = np.ones(grid.size, bool)
            j = np.searchsorted(idx, grid)
            for d in (-1, 0):
                jj = np.clip(j + d, 0, idx.size - 1)
                far &= np.abs(idx[jj] - grid) > step
            kn = np.unique(np.concatenate([idx, grid[far], [0, n - 1]]))
            ph = PchipInterpolator(kn, ph[kn])(np.arange(n))
        return torch.as_tensor(ph[None, :], dtype=torch.float64, device=self.target.device)


    def _cabs(self, z: torch.Tensor) -> torch.Tensor:
        """완화된 복소 크기 `√(x²+y²+η²)` — `z.abs()` 대신 쓴다.

        `z.abs()` 는 z=0 에서 기울기가 0/0 이라 NaN 이다 (`MAG_ETA_REL` 주석 참조).
        η 를 더하면 어디서나 미분 가능하고 기울기 상한이 1 이다.
        """
        return torch.sqrt(z.real ** 2 + z.imag ** 2 + self.mag_eta ** 2)

    def _db(self, x: torch.Tensor) -> torch.Tensor:
        """dB. **로그의 인자를 η 로 막는다** — `log 0 = −∞` 도, 그 기울기 발산도 없다.

        `_cabs` 를 지난 크기는 이미 η 이상이므로 여기 더하는 η 는 이중 안전장치이자
        멜 합성 뒤(선형 결합이라 0 이 될 수 있다)의 바닥이다.
        """
        return 20.0 * torch.log10(x + self.mag_eta)

    def _sc(self, at: torch.Tensor, ap: torch.Tensor) -> torch.Tensor:
        """스펙트럼 수렴도. **놈도 완화한다** — `‖v‖` 는 v=0 에서 같은 0/0 이다.

        적합이 완벽해질수록 `at − ap → 0` 이므로 그 자리로 **다가가는 것이 목적**이다.
        완화하지 않으면 잘 맞을수록 기울기가 불안정해진다.
        """
        m = min(at.shape[-1], ap.shape[-1])
        at, ap = at[..., :m], ap[..., :m]
        e2 = self.mag_eta ** 2
        d = at - ap
        num = torch.sqrt((d * d).sum() + e2)
        den = torch.sqrt((at * at).sum() + e2)
        return num / (den + 1e-9)





    def spectral_loss(self, y: torch.Tensor):
        """(정밀 SC, 포락 dB 오차, 포락 SC, 창별 SC%).

        **선형 빈의 로그 크기 평균을 쓰면 안 된다.** 24 kHz 까지 선형이면 빈의 90 % 가
        2.4 kHz 위에 있고, 그 대역은 목표가 거의 무음이다. 그러면 손실이 무음 구간
        일치로 지배되어 전체 이득을 낮추는 쪽이 이긴다 (실측: 그렇게 해서 0~500 Hz 가
        27 dB 낮은 해의 손실이 더 낮게 나왔다). 그래서 포락 오차는 **멜 대역의 dB**
        로 재고 (로그 주파수 = 대역마다 같은 무게), 정점 −70 dB 아래는 잘라 낸다.
        """
        sc_sum, per = 0.0, {}
        Smel = Smel_raw = harm_raw = None
        for k in self.sizes:
            raw = self._cabs(_stft(y, k, self.wins[k]))[:, :self.bin_max[k]]
            Sp = self._expect(raw, k)
            if k == MEL_FFT:
                Smel, Smel_raw = Sp, raw
            sc = self._sc(self.tgt_S[k], Sp)
            sc_sum = sc_sum + sc
            per[k] = float(100.0 * (1.0 - sc.detach()))
        if Smel is None:
            Smel_raw = self._cabs(
                _stft(y, MEL_FFT, self.wins[MEL_FFT]))[:, :self.bin_max[MEL_FFT]]
            Smel = self._expect(Smel_raw, MEL_FFT)
        Mp = self.mel[:, :Smel.shape[1]] @ Smel
        m = min(Mp.shape[-1], self.tgt_M.shape[-1])
        Mp, Mt = Mp[..., :m], self.tgt_M[..., :m]
        # **clamp 도 abs 도 꺾임이다.** 멜 빈 수천 개마다 꺾이면 손실이 C² 가 아니게
        # 되고 헤시안 기반 진단이 통째로 막힌다 (docs/MEASUREMENTS.md §8.7). 폭은
        # dB 단위 0.5 — 계측 잡음보다 작아 거동은 사실상 그대로다.
        fl = getattr(self, "db_floor_band", None)
        fl = self.db_floor if fl is None else fl
        a = self._soft_floor(self._db(Mt), fl, 0.5)
        b = self._soft_floor(self._db(Mp), fl, 0.5)
        e_ab = self._soft_abs(a - b, 0.5)
        env_db = self._weighted_db(e_ab) / 20.0
        # 고역 포락 손실 (§52.283, 되살림 §52.505) — `HFENV_LO` 위 멜 대역만 골라 **그 대역들 안에서만** 평균한다 (에너지 가중이 아니다).
        # 구현이 정리 때 지워지고 상수만 남아 성대 세대 내내 고역을 무는 항이 없었다 (A 6–10 kHz 57 · 10 kHz 위 48 점).
        self._hfenv = None
        if HFENV_W > 0.0:
            idx = self._hfenv_idx(a.shape[-2], a.device)
            if idx is not None:
                d = self._soft_abs(a.index_select(-2, idx) - b.index_select(-2, idx), 0.5)
                self._hfenv = (d - HFENV_KNEE).clamp_min(0.0).mean() / 20.0
        env_sc = self._sc(Mt, Mp)
        self._env_bands = self.band_scores(Mt, Mp)
        self._voicing = self.voicing_loss(y) if VOICING_W > 0.0 else None
        self._pitch = self.pitch_loss(y) if PITCH_W > 0.0 else None
        return sc_sum / len(self.sizes), env_db, env_sc, per

    def _hfenv_idx(self, n_mel: int, device):
        """중심이 `HFENV_LO` 위인 멜 행의 색인. 한 번만 만든다."""
        key = (n_mel, HFENV_LO, str(device))
        if getattr(self, "_hfe_key", None) == key:
            return self._hfe_idx
        W = self.mel.detach().cpu().numpy()[:n_mel]
        fb = np.fft.rfftfreq(MEL_FFT, 1.0 / self.fs)[:W.shape[1]]
        cf = (W * fb[None, :]).sum(1) / np.maximum(W.sum(1), 1e-12)
        idx = np.flatnonzero(cf >= HFENV_LO)
        self._hfe_key = key
        self._hfe_idx = (torch.as_tensor(idx, device=device, dtype=torch.long) if idx.size else None)
        return self._hfe_idx

    def _voicing_track(self, x: torch.Tensor):
        """(1, n) → (틀 주기성 (F,), 틀 저역 수준 dB (F,)) — 1.5 kHz 아래를 FFT 로 걸러 20 ms 창·5 ms 걸음의 정규 자기상관을 재고,
        주기 1.4–8 ms 에서 부드러운 최대 (logsumexp, 온도 `VOICING_TEMP`)를 취한다."""
        n = x.shape[-1]
        X = torch.fft.rfft(x[0].double())
        f = torch.fft.rfftfreq(n, 1.0 / self.fs).to(X.device)
        lp = torch.fft.irfft(X * (f < 1500.0).to(X.dtype), n)
        W, H = int(0.020 * self.fs), int(0.005 * self.fs)
        fr = lp.unfold(0, W, H)
        fr = fr - fr.mean(-1, keepdim=True)
        e = (fr * fr).mean(-1)
        S = torch.fft.rfft(fr, 2 * W)
        ac = torch.fft.irfft(S.real ** 2 + S.imag ** 2, 2 * W)[:, :W]
        acn = ac / ac[:, :1].clamp_min(1e-30)
        seg = acn[:, int(0.0014 * self.fs):int(0.008 * self.fs)]
        per = VOICING_TEMP * torch.logsumexp(seg / VOICING_TEMP, -1) - VOICING_TEMP * math.log(seg.shape[-1])
        return per.clamp(0.0, 1.0), 10.0 * torch.log10(e + 1e-20)

    def voicing_loss(self, y: torch.Tensor) -> torch.Tensor:
        """**유성/무성 분리** (§52.505) — 원본과 합성의 5 ms 틀 저역 주기성의 차 제곱 평균 (원본 말소리 틀, 저역 수준이 유성 중앙보다
        45 dB 아래가 아닌 틀). 무성 자음에 성대 떨림이 새거나(원본 무성·합성 유성) 모음 사이 평음에서 떨림이 끊기는 것(원본 유성·합성 무성)을
        모두 문다 — 포락 항은 짧은 자음과 떨림의 유무를 거의 보지 못했다."""
        if getattr(self, "_vt_tgt", None) is None:
            with torch.no_grad():
                pt, lt = self._voicing_track(self.target)
                ref = lt[pt > 0.7].median() if bool((pt > 0.7).any()) else lt.max()
                sp = lt > ref - 45.0
                # 무성 틀(주기성 < 0.5)과 유성 틀이 **같은 총 무게** — 무성 자음은 말소리 틀의 10 % 남짓이라 그냥 평균하면 묻힌다
                uv, vv = sp & (pt < 0.5), sp & (pt >= 0.5)
                w = torch.zeros_like(pt)
                if bool(uv.any()):
                    w[uv] = 0.5 / uv.sum()
                if bool(vv.any()):
                    w[vv] = 0.5 / vv.sum()
                self._vt_tgt = (pt, w / w.sum().clamp_min(1e-12))
        pt, w = self._vt_tgt
        ps, _ = self._voicing_track(y)
        k = min(ps.shape[0], pt.shape[0])
        return ((ps[:k] - pt[:k]) ** 2 * w[:k]).sum()

    def _acorr_frames(self, x: torch.Tensor):
        """(1, n) → (정규 자기상관 (F, W), 저역 수준 dB (F,)) — `_voicing_track` 과 같은 틀 (1.5 kHz 아래, 20 ms 창 · 5 ms 걸음)."""
        n = x.shape[-1]
        X = torch.fft.rfft(x[0].double())
        f = torch.fft.rfftfreq(n, 1.0 / self.fs).to(X.device)
        lp = torch.fft.irfft(X * (f < 1500.0).to(X.dtype), n)
        W, H = int(0.020 * self.fs), int(0.005 * self.fs)
        fr = lp.unfold(0, W, H)
        fr = fr - fr.mean(-1, keepdim=True)
        e = (fr * fr).mean(-1)
        S = torch.fft.rfft(fr, 2 * W)
        ac = torch.fft.irfft(S.real ** 2 + S.imag ** 2, 2 * W)[:, :W]
        return ac / ac[:, :1].clamp_min(1e-30), 10.0 * torch.log10(e + 1e-20)

    def pitch_loss(self, y: torch.Tensor) -> torch.Tensor:
        """음높이 항 (`PITCH_W`, 위 설명)."""
        if getattr(self, "_pt_tgt", None) is None:
            with torch.no_grad():
                acn, lt = self._acorr_frames(self.target)
                i0, i1 = int(0.0014 * self.fs), int(0.008 * self.fs)
                seg = acn[:, i0:i1]
                per = seg.max(-1).values
                lag = (seg.argmax(-1) + i0).double()
                ref = lt[per > 0.7].median() if bool((per > 0.7).any()) else lt.max()
                ok = (per >= 0.6) & (lt > ref - 30.0)
                self._pt_tgt = (lag, ok)
        lag_t, ok = self._pt_tgt
        acn, _ = self._acorr_frames(y)
        k = min(acn.shape[0], lag_t.shape[0])
        acn, lag_t, ok = acn[:k], lag_t[:k], ok[:k]
        if not bool(ok.any()):
            return torch.zeros((), dtype=y.dtype, device=y.device)
        W = acn.shape[1]
        L = torch.arange(W, dtype=acn.dtype, device=acn.device)[None, :]
        lo, hi = (0.8 * lag_t)[:, None], (1.25 * lag_t)[:, None]
        m = (L >= lo) & (L <= hi)
        z = torch.where(m, acn / PITCH_TEMP, torch.full_like(acn, -1e9))
        wsm = torch.softmax(z, -1)
        lag_s = (wsm * L).sum(-1)
        per_s = (wsm * acn).sum(-1).detach().clamp(0.0, 1.0)
        err = (torch.log(lag_s.clamp_min(1.0)) - torch.log(lag_t.clamp_min(1.0))) ** 2
        w = per_s * ok.to(per_s.dtype)
        self._pitch_cents = float((1200.0 / math.log(2.0) * torch.sqrt(err.detach())[ok]).median()) if bool(ok.any()) else float("nan")
        return (err * w).sum() / w.sum().clamp_min(1e-6)

    def pth_loss(self, c: torch.Tensor) -> torch.Tensor:
        """발성 문턱 항 (`PTH_W`). c (1, T, C) 제어."""
        from .vf_calibration import grid_index
        if getattr(self, "_pthm", None) is None:
            with np.load(PTH_MAP, allow_pickle=False) as Z:
                P = np.asarray(Z["pth"], float)                     # (F0, ADD, RDO, TA) [cmH2O], nan = 15 까지 안 떪
                axes = [np.asarray(Z[k], float) for k in ("f0", "add", "rdo", "ta")]
            if (any(g.ndim != 1 or not g.size or not np.isfinite(g).all() or np.any(np.diff(g) <= 0) for g in axes)
                    or P.shape != tuple(g.size for g in axes) or np.any(axes[0] <= 0)
                    or np.any(P[np.isfinite(P)] <= 0)):
                raise ValueError(f"Invalid NS threshold grid: {PTH_MAP}")
            P = np.where(np.isfinite(P), P, 20.0)
            self._pthm = dict(lp=torch.as_tensor(np.log(P), dtype=torch.float64), lf=np.log(axes[0]),
                              ad=axes[1], rd=axes[2], ta=axes[3])
            T = int(c.shape[1])
            v = np.asarray(self.track.voiced, bool)[:T] if self.track.voiced.size else np.zeros(T, bool)
            self._pth_vmask = torch.as_tensor(np.pad(v, (0, T - v.size)) if v.size < T else v)
            print(f"  발성 문턱 항: 지도 {PTH_MAP} {P.shape}, 유성 틀 {int(self._pth_vmask.sum())} — 폐압 ≥ {PTH_MARGIN:g} × 문턱", flush=True)
        m = self._pthm
        x = c[0].double()
        rendered = getattr(getattr(getattr(self, "eng", None), "td", None), "last_vf_controls", None)
        def control(name):
            return rendered[name][0].double() if rendered is not None else x[:, INDEX[name]]

        def coord(val, grid):
            if len(grid) == 1:
                return torch.zeros_like(val)
            return 2.0 * grid_index(val, grid) / (len(grid) - 1) - 1.0
        f0 = control("f0_target").clamp_min(50.0)
        cf = coord(torch.log(f0), m["lf"])
        ca = coord(control("adduction"), m["ad"])
        cr = coord(control("rd_offset"), m["rd"])
        ta = control("vf_ta")
        lp = m["lp"].to(x.device)                                   # (F, A, R, TA)
        grid = torch.stack([cr, ca, cf], -1).view(1, 1, 1, -1, 3)    # grid_sample: (x=W=R, y=H=A, z=D=F)
        vals = []
        for l in range(lp.shape[-1]):
            vol = lp[..., l][None, None]                            # (1,1,F,A,R)
            if vol.shape[-1] == 1:
                vol = vol.expand(1, 1, vol.shape[2], vol.shape[3], 2)
            vals.append(torch.nn.functional.grid_sample(vol, grid, align_corners=True, padding_mode="border").view(-1))
        if len(vals) == 1:
            lpth = vals[0]
        else:
            pos = grid_index(ta, m["ta"])
            i = pos.detach().floor().long().clamp(max=len(vals) - 2)
            w = pos - i
            by_ta = torch.stack(vals, -1)
            lpth = ((1 - w) * by_ta.gather(1, i[:, None])[:, 0]
                    + w * by_ta.gather(1, (i + 1)[:, None])[:, 0])
        lps = torch.log(control("p_sub").clamp_min(0.05))
        vm = self._pth_vmask.to(x.device)[: x.shape[0]]
        h = torch.relu(lpth + math.log(PTH_MARGIN) - lps) ** 2
        self._pth_viol = float((h[vm] > 0).double().mean()) if bool(vm.any()) else float("nan")
        return (h * vm.double()).sum() / vm.double().sum().clamp_min(1.0)

    def _band_masks(self) -> list[tuple[str, torch.Tensor]]:
        """멜 빈을 `REPORT_BAND_EDGES` 로 가른 (이름, 마스크) 목록. 멜 필터의 무게중심 주파수로 나눈다."""
        if getattr(self, "_bandm", None) is not None:
            return self._bandm
        mel = self.mel.detach()
        n_freq = mel.shape[1]
        fr = torch.linspace(0.0, self.fs / 2.0, n_freq, dtype=mel.dtype, device=mel.device)
        fc = (mel * fr).sum(1) / mel.sum(1).clamp_min(1e-12)
        edges = [0.0, *REPORT_BAND_EDGES, float(self.fs)]
        out = []
        for i in range(len(edges) - 1):
            lo, hi = edges[i], edges[i + 1]
            m = (fc >= lo) & (fc < hi)
            if not bool(m.any()):
                continue
            name = f"{lo / 1000:g}-{hi / 1000:g}k" if hi < self.fs else f"{lo / 1000:g}k+"
            out.append((name, m))
        self._bandm = out
        return out

    def band_scores(self, Mt: torch.Tensor, Mp: torch.Tensor) -> dict[str, float]:
        """대역별 포락 일치율 % (`_sc` 와 같은 자, 대역 안의 멜 빈만).

        멜 축은 **뒤에서 두 번째**로 고정한다 — (멜, 프레임) 도 (배치, 멜, 프레임) 도 받는다.
        예전 판은 `Mt[:, m]` 이라 2 차원 입력에서 프레임 축을 멜 마스크로 색인해 죽었다.
        """
        out = {}
        for name, m in self._band_masks():
            idx = torch.nonzero(m, as_tuple=False).flatten()
            out[name] = float(100.0 * (1.0 - self._sc(Mt.index_select(-2, idx),
                                                      Mp.index_select(-2, idx)).detach()))
        return out

    @torch.no_grad()
    def _mel_pair(self, y) -> tuple[torch.Tensor, torch.Tensor]:
        """저장된 오디오의 (목표 멜, 합성 멜) — `score_audio` 와 **같은 경로**로 낸다.

        진단이 점수의 분해(대역별·시각별 오차 제곱합)를 내려면 원 행렬이 필요한데, 흉내 내면 경로가 갈라진다.
        """
        t = torch.as_tensor(np.asarray(y, dtype=np.float32), device=self.device)
        t = t.reshape(1, -1) if t.dim() == 1 else t
        n = int(self.target.shape[-1])
        if t.shape[-1] < n:
            t = torch.nn.functional.pad(t, (0, n - t.shape[-1]))
        t = t[:, :n]
        raw = self._cabs(_stft(t, MEL_FFT, self.wins[MEL_FFT]))[:, :self.bin_max[MEL_FFT]]
        Mp = self.mel[:, :raw.shape[1]] @ self._expect(raw, MEL_FFT)
        m = min(Mp.shape[-1], self.tgt_M.shape[-1])
        return self.tgt_M[..., :m], Mp[..., :m]

    @torch.no_grad()
    def score_audio(self, y) -> dict[str, float]:
        """이미 만들어진 오디오를 **적합기와 같은 자**로 채점한다 — 저장된 판을 다시 잴 때 쓴다.

        반환 {"env": 전체 포락 %, 대역 이름: 대역별 %}. 진단 스크립트가 STFT·멜·평활을 흉내 내면
        경로가 갈라져 음수 점수 같은 것이 나온다 (실제로 그랬다) — 여기서 한 번만 정의한다.
        """
        t = torch.as_tensor(np.asarray(y, dtype=np.float32), device=self.device)
        t = t.reshape(1, -1) if t.dim() == 1 else t
        n = int(self.target.shape[-1])
        if t.shape[-1] < n:
            t = torch.nn.functional.pad(t, (0, n - t.shape[-1]))
        t = t[:, :n]
        raw = self._cabs(_stft(t, MEL_FFT, self.wins[MEL_FFT]))[:, :self.bin_max[MEL_FFT]]
        Mp = self.mel[:, :raw.shape[1]] @ self._expect(raw, MEL_FFT)
        m = min(Mp.shape[-1], self.tgt_M.shape[-1])
        Mp, Mt = Mp[..., :m], self.tgt_M[..., :m]
        out = {"env": float(100.0 * (1.0 - self._sc(Mt, Mp)))}
        out.update(self.band_scores(Mt, Mp))
        return out

    def _hf_db(self, y: torch.Tensor):
        """`HFLINE_FFT` 로 STFT 를 떠서 로그 크기를 돌려준다. 두 고역 벌점이 함께 쓴다."""
        S = self._cabs(_stft(y, HFLINE_FFT, self.wins[HFLINE_FFT]))
        return 20.0 * torch.log10(S.clamp_min(1e-9)).double()








































    # ------------------------------------------- 파형 상관 · 주기성 (사용자 요청)
    def hfline_loss(self, y: torch.Tensor, db: torch.Tensor | None = None) -> torch.Tensor:
        """`HFLINE_FMIN` 위에서 **자리를 지키는 봉우리**를 문다 (`HFLINE_W` 참조).

        봉우리성 × 정상성 × 소리 있음을 곱해, 셋이 겹친 자리만 센다.
        """
        db = self._hf_db(y) if db is None else db                                          # (B, F, T)
        if db.shape[-1] < 8:
            return torch.zeros((), dtype=torch.float64, device=self.target.device)
        n_f = db.shape[-2]
        fr = torch.linspace(0.0, self.fs / 2.0, n_f, device=db.device, dtype=db.dtype)
        band = fr >= HFLINE_FMIN
        if int(band.sum()) < HFLINE_PEAK_BINS + 2:
            return torch.zeros((), dtype=db.dtype, device=db.device)
        x = db[..., band, :]
        # 1) 봉우리 — 주파수축 이동평균 대비 솟은 정도
        kf = HFLINE_PEAK_BINS | 1
        loc = torch.nn.functional.avg_pool1d(x.transpose(-1, -2), kf, 1, kf // 2,
                                             count_include_pad=False).transpose(-1, -2)[..., :x.shape[-2], :]
        peak = torch.sigmoid((x - loc - HFLINE_PEAK_DB) / 1.0)
        # 2) 정상성 — 시간축 창 표준편차
        kt = max(3, int(round(HFLINE_MS * self.fs / (HFLINE_FFT // 4) / 1000.0)) | 1)
        if x.shape[-1] <= kt:
            return torch.zeros((), dtype=db.dtype, device=db.device)
        pad = kt // 2
        m = torch.nn.functional.avg_pool1d(x, kt, 1, pad, count_include_pad=False)[..., :x.shape[-1]]
        m2 = torch.nn.functional.avg_pool1d(x * x, kt, 1, pad, count_include_pad=False)[..., :x.shape[-1]]
        std = (m2 - m * m).clamp_min(0.0).sqrt()
        steady = torch.sigmoid((HFLINE_STD_DB - std) / 0.3)
        # 3) 소리가 있는 자리만
        live = torch.sigmoid((x - (x.amax(dim=-2, keepdim=True) - HFLINE_FLOOR_DB)) / 3.0)
        pen = peak * steady * live
        return pen.sum() / float(pen.shape[-2] * pen.shape[-1])

    def _hf_ref(self, name: str, fn) -> float:
        """목표에서 잰 문지기 값 (한 번만, 기울기 없음). `HFLINE_REF` 주석이 근거다."""
        cache = getattr(self, "_hfref", None)
        if cache is None:
            cache = self._hfref = {}
        if name not in cache:
            with torch.no_grad():
                t = self.target
                cache[name] = float(fn(t if t.dim() == 2 else t.reshape(1, -1)))
        return cache[name]

    def _fcorr_lags(self) -> list[int]:
        """지연을 로그 간격으로 고른다 (빈 단위). `HFCOMB_HZ` 범위."""
        df = self.fs / HFLINE_FFT
        lo = max(1, int(round(HFCOMB_HZ[0] / df)))
        hi = max(lo + 1, int(round(HFCOMB_HZ[1] / df)))
        raw = np.unique(np.round(np.geomspace(lo, hi, HFCOMB_LAGS)).astype(int))
        return [int(L) for L in raw if L >= 1]

    def _fcorr(self, y: torch.Tensor, db: torch.Tensor | None = None, band=None):
        """6 kHz 위 주파수축 자기상관 (B, 지연, T) 과 살아 있는 프레임 마스크 (B, T).

        추세(포락 기울기)는 빼고 **무늬**만 남긴다. 시간으로는 `HFLINE_MS` 로 평활해
        **지속되는** 되풀이만 세도록 한다.
        """
        db = self._hf_db(y) if db is None else db
        n_f = db.shape[-2]
        fr = torch.linspace(0.0, self.fs / 2.0, n_f, device=db.device, dtype=db.dtype)
        if band is None:
            sel = fr >= HFLINE_FMIN
        else:
            sel = (fr >= max(band[0], HFLINE_FMIN)) & (fr < band[1])
        x = db[..., sel, :]
        if x.shape[-2] < 24 or x.shape[-1] < 8:
            return None, None
        kd = HFCOMB_DETREND_BINS | 1
        tr = torch.nn.functional.avg_pool1d(x.transpose(-1, -2), kd, 1, kd // 2,
                                            count_include_pad=False).transpose(-1, -2)
        g = x - tr[..., :x.shape[-2], :]
        e = (g * g).sum(dim=-2).clamp_min(1e-12)                        # (B, T)
        rs = [(g[..., :-L, :] * g[..., L:, :]).sum(dim=-2) / e
              for L in self._fcorr_lags() if L < g.shape[-2]]
        if not rs:
            return None, None
        r = torch.stack(rs, -2)                                          # (B, 지연, T)
        kt = max(3, int(round(HFLINE_MS * self.fs / (HFLINE_FFT // 4) / 1000.0)) | 1)
        if r.shape[-1] > kt:
            sh = r.shape
            r = torch.nn.functional.avg_pool1d(r.reshape(-1, 1, sh[-1]), kt, 1, kt // 2,
                                               count_include_pad=False)[:, 0]
            r = r[..., :sh[-1]].reshape(sh)
        lvl = x.mean(-2)                                                 # (B, T)
        live = (lvl > lvl.amax() - 35.0).to(r.dtype)
        return r, live

    def _fcorr_target(self, band=None):
        """목표의 **프레임별** 지연 상관 (1, 지연, T). 한 번만 재고 붙잡아 둔다.

        프레임 평균이 아니라 프레임별이어야 한다 — 평균을 기준으로 삼으면 목표를 목표와
        비교해도 평균 위의 프레임이 벌점을 받아 **자기 자신이 0 이 아니게** 된다(실측 0.0137).
        """
        cache = getattr(self, "_fcorr_t", None)
        if cache is None:
            cache = self._fcorr_t = {}
        key = None if band is None else (float(band[0]), float(band[1]))
        if key not in cache:
            with torch.no_grad():
                t = self.target
                r, _ = self._fcorr(t if t.dim() == 2 else t.reshape(1, -1), band=band)
                cache[key] = None if r is None else r.detach()
        return cache[key]

    def hfcomb_loss(self, y: torch.Tensor, db: torch.Tensor | None = None) -> torch.Tensor:
        """6 kHz 위 주파수축 상관이 **목표보다 높은 만큼**을 지연·프레임마다 문다 (`HFCOMB_W`).

        `HFCOMB_BANDS` 가 있으면 **대역마다 따로** 재고 가장 나쁜 대역을 섞는다 — 통째로 평균하면
        한 대역에 몰린 빗살이 희석돼 문지기가 보는 것을 손실이 못 본다 (§52.326).
        """
        if HFCOMB_BANDS:
            db = self._hf_db(y) if db is None else db
            vals = [self._hfcomb_one(y, db, b) for b in HFCOMB_BANDS]
            vals = [v for v in vals if v is not None]
            if not vals:
                return torch.zeros((), dtype=torch.float64, device=self.target.device)
            v = torch.stack(vals)
            return (1.0 - HFCOMB_BAND_MIX) * v.mean() + HFCOMB_BAND_MIX * v.max()
        v = self._hfcomb_one(y, db, None)
        return v if v is not None else torch.zeros((), dtype=torch.float64,
                                                   device=self.target.device)

    def _hfcomb_one(self, y: torch.Tensor, db, band):
        """한 대역(또는 전체)의 빗살 초과. 못 재면 None."""
        r, live = self._fcorr(y, db, band=band)
        if r is None:
            return None
        rt = self._fcorr_target(band)
        if rt is None:
            ref = torch.full_like(r, HFCOMB_R - HFCOMB_MARGIN)
        else:
            m = min(r.shape[-1], rt.shape[-1])
            r, live = r[..., :m], live[..., :m]
            ref = rt[..., :m]
        # **상수 항을 뺀다** — softplus 는 0 에 닿지 않으므로 무릎 아래에서도 값이 남는다.
        base = self._soft_over(torch.zeros((), dtype=r.dtype, device=r.device)
                               - HFCOMB_MARGIN, HFCOMB_KNEE)
        d = (self._soft_over(r - ref - HFCOMB_MARGIN, HFCOMB_KNEE) - base).clamp_min(0.0)
        w = live.unsqueeze(-2)
        wsum = w.expand_as(d).sum().clamp_min(1.0)
        mean = (d * w).sum() / wsum
        # 지연마다 (살아 있는 프레임 평균) -> 그중 가장 나쁜 K 개
        per_lag = (d * w).sum(-1).sum(0) / w.sum().clamp_min(1.0)
        k = min(HFCOMB_TOPK, per_lag.numel())
        top = torch.topk(per_lag, k).values.mean() if k > 0 else mean
        out = (1.0 - HFCOMB_TOPK_MIX) * mean + HFCOMB_TOPK_MIX * top
        with torch.no_grad():
            ex = ((r.detach() - ref) * w).sum() / w.expand_as(r).sum().clamp_min(1.0)
            self._last_fcorr = float(ex)
        return out

    def _frames(self, x: torch.Tensor, win: int, hop: int) -> torch.Tensor:
        """(1, n) -> (T, win). 마지막 자투리는 버린다."""
        return x[0].unfold(0, win, hop)













    def _band_weight(self, n_mel: int, dtype, device) -> torch.Tensor:
        """멜 빈마다의 **대역 균형 가중** (1, F, 1). `BAND_BALANCE` 참조."""
        key = (n_mel, BAND_GROUPS, BAND_BALANCE, str(device))
        if getattr(self, "_bw_key", None) == key:
            return self._bw
        cf = self.mel.detach().cpu().numpy().argmax(1) * (self.fs / MEL_FFT)
        cf = cf[:n_mel]
        edges = np.geomspace(max(cf[cf > 0].min(), 50.0), max(cf.max(), 100.0), BAND_GROUPS + 1)
        w = np.ones(n_mel)
        for i in range(BAND_GROUPS):
            m = (cf >= edges[i]) & (cf < edges[i + 1] if i < BAND_GROUPS - 1 else cf <= edges[i + 1])
            if m.sum() > 0:
                w[m] = 1.0 / m.sum()
        w = w / w.mean()
        w = (1.0 - BAND_BALANCE) + BAND_BALANCE * w
        self._bw_key = key
        self._bw = torch.as_tensor(w[None, :, None], dtype=dtype, device=device)
        return self._bw

    def _fast_part(self, x: torch.Tensor) -> torch.Tensor:
        """프레임 축에서 느린 성분을 뺀 나머지 = **주기 안 구조**. `FASTFIT_MS` 참조.

        한 축짜리 한 커널이라 STFT 를 또 뜨지 않는다. 가장자리는 replicate 로 채워
        창 밖 프레임이 0 으로 새어 들어오지 않게 한다.
        """
        fr = self.fs / (MEL_FFT // 4)
        L = max(3, int(round(FASTFIT_MS * fr / 1000.0)) | 1)
        ker = getattr(self, "_ff_ker", None)
        if ker is None or ker.shape[-1] != L or ker.dtype != x.dtype or ker.device != x.device:
            w = torch.hann_window(L + 2, device=x.device, dtype=x.dtype)[1:-1]
            ker = (w / w.sum()).view(1, 1, -1)
            self._ff_ker = ker
        z = x.reshape(-1, 1, x.shape[-1])
        z = torch.nn.functional.pad(z, (L // 2, L // 2), mode="replicate")
        return x - torch.nn.functional.conv1d(z, ker).reshape(x.shape)


    def _weighted_db(self, e: torch.Tensor) -> torch.Tensor:
        """구간·대역 균형을 적용한 dB 오차의 평균. 둘 다 0 이면 단순 평균이다."""
        if getattr(self, "_hf_focus", False):
            # 고역 단계: `HF_STAGE_FMIN` 위의 멜 띠만 본다.
            cf = self.mel.detach().cpu().numpy().argmax(1) * (self.fs / MEL_FFT)
            k = np.flatnonzero(cf[:e.shape[-2]] >= HF_STAGE_FMIN)
            if k.size:
                return e.index_select(-2, torch.as_tensor(k, dtype=torch.long,
                                                          device=e.device)).mean()
        if BAND_BALANCE <= 0.0 and SEG_BALANCE <= 0.0:
            return e.mean()
        w = torch.ones_like(e[:1, :1, :1])
        if BAND_BALANCE > 0.0:
            w = w * self._band_weight(e.shape[-2], e.dtype, e.device)
        if SEG_BALANCE > 0.0:
            w = w * self._seg_weight(e.shape[-1])
        return (e * w).sum() / (w.expand_as(e).sum()).clamp_min(1e-9)

    def _seg_weight(self, T: int) -> torch.Tensor:
        """멜 프레임마다의 **구간 균형 가중** (1, 1, T). `SEG_BALANCE` 참조."""
        if getattr(self, "_segw", None) is not None and self._segw.shape[-1] >= T:
            return self._segw[..., :T]
        from .segment import fricative_mask
        hop = MEL_FFT // 4
        t = self.target[0].detach().cpu().numpy()
        idx = np.clip((np.arange(T) * hop / self.fs * 1000.0).astype(int), 0, None)
        voi = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), bool)
        fri = np.asarray(getattr(self.track, "fricative", np.zeros(0, dtype=bool)), bool)
        vel = np.asarray(self.track["velum"], dtype=np.float64)
        m = max(voi.size, 1)
        j = np.clip(idx, 0, m - 1)
        lv = np.array([20 * np.log10(np.std(t[i * hop:(i + 1) * hop]) + 1e-20) for i in range(T)])
        quiet = lv < lv.max() - 35
        vv = voi[j] if voi.size else np.ones(T, bool)
        ff = fri[j] if fri.size else np.zeros(T, bool)
        nn = (vel[j] > 0.5) if vel.size else np.zeros(T, bool)
        trans = np.zeros(T, bool)
        ch = np.diff(np.concatenate([[vv[0]], vv]).astype(int)) != 0
        for k in np.flatnonzero(ch):
            trans[max(k - 15, 0):k + 15] = True
        cls = np.where(quiet, 0, np.where(ff, 1, np.where(nn, 2, np.where(trans, 3, np.where(vv, 4, 5)))))
        w = np.ones(T)
        for c in range(6):
            s = cls == c
            if s.sum() > 0:
                w[s] = 1.0 / s.sum()
        w = w / w.mean()
        # SEG_BALANCE 로 길이비례(1)와 구간균형(w) 사이를 섞는다.
        w = (1.0 - SEG_BALANCE) + SEG_BALANCE * w
        self._segw = torch.as_tensor(w[None, None, :], dtype=self.target.dtype,
                                     device=self.target.device)
        return self._segw




    def _voiced_frames(self, T: int, dtype, device) -> torch.Tensor:
        """멜 프레임마다의 유성 가중 (1, T)."""
        hop = MEL_FFT // 4
        voi = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), bool)
        if voi.size == 0:
            return torch.ones((1, T), dtype=dtype, device=device)
        idx = np.clip((np.arange(T) * hop / self.fs * 1000.0).astype(int), 0, voi.size - 1)
        return torch.as_tensor(voi[idx].astype(np.float64), dtype=dtype, device=device).view(1, T)








    def _periodic_voiced_masks(self, c: torch.Tensor):
        """**원본이 뚜렷이 주기적인** 유성 틀 (내전 바닥) 과, 그중 비음 머머가 아닌 틀 (협착 바닥) — (T,) 불 둘.

        분석 유성만으로는 기식 개시(목표 주기성 0.2~0.5)까지 들어가 바닥이 그것을 유성으로 몰았다(§52.420). 그래서
        목표 저역(80~4000 Hz)의 이웃 주기 상관이 `VOICED_FLOOR_PER` 을 넘는 틀만 쓴다.
        """
        from scipy.signal import butter, sosfiltfilt
        T = c.shape[1]
        v = np.zeros(T, bool)
        vv = np.asarray(self.track.voiced, bool)[:T]
        v[:vv.size] = vv
        tg = self.target[0].detach().cpu().numpy().astype(np.float64)
        lo = sosfiltfilt(butter(4, (80.0, 4000.0), "bp", fs=self.fs, output="sos"), tg)
        f0 = np.asarray(self.track["f0_target"], np.float64)[:T]
        per = np.zeros(T)
        for i in np.flatnonzero(v):
            L = int(round(self.fs / max(f0[i], 60.0)))
            s0 = i * self.hop - L
            if s0 < 0 or s0 + 3 * L >= lo.size:
                continue
            a_, b_ = lo[s0:s0 + L], lo[s0 + L:s0 + 2 * L]
            per[i] = float(np.dot(a_, b_) / (np.linalg.norm(a_) * np.linalg.norm(b_) + 1e-20))
        m = v & (per > VOICED_FLOOR_PER)
        vel = np.asarray(self.track["velum"], np.float64)[:T] if "velum" in INDEX else np.zeros(T)
        mc = m & (vel < 0.3)
        print(f"  주기적 유성 틀 {int(m.sum())} / 분석 유성 {int(v.sum())} (내전 바닥), 협착 바닥 {int(mc.sum())} 틀", flush=True)
        return torch.as_tensor(m, device=c.device), torch.as_tensor(mc, device=c.device)

    def mprior_loss(self, c: torch.Tensor) -> torch.Tensor:
        """기관 운동 사전의 음의 로그 가능도 평균 (`MPRIOR_W`) — 스튜던트 t, 매개변수별 평균의 합."""
        lag = max(1, int(round(MPRIOR_LAG_MS / float(self.track.frame_ms))))
        tot = torch.zeros((), dtype=c.dtype, device=c.device)
        rep = {}
        if MPRIOR_CORPUS:
            cols = []
            for nm in MPRIOR_C_NAMES:
                x = c[0, :, INDEX[nm]]
                if nm in MPRIOR_LOG:
                    x = torch.log(x.clamp_min(1e-3))
                cols.append(x[lag:] - x[:-lag])
            dd = torch.stack(cols, 1)                                   # (T, 3)
            sc = torch.tensor(MPRIOR_C_SCALE, dtype=c.dtype, device=c.device)
            R = torch.tensor(MPRIOR_C_CORR, dtype=c.dtype, device=c.device)
            Sinv = torch.linalg.inv(R * sc[:, None] * sc[None, :])
            q = ((dd @ Sinv) * dd).sum(1)
            k = dd.shape[1]
            nll = torch.log1p(q / MPRIOR_C_NU) * (MPRIOR_C_NU + k) / 2.0
            with torch.no_grad():
                z = dd / sc
                for j, nm in enumerate(MPRIOR_C_NAMES):
                    rep[nm] = float((z[:, j].abs() > 20.0).float().mean())   # 눈금의 20 배 밖 (ν 1.5 의 ≈ 99 분위)
            self._last_mprior = rep
            return nll.mean()
        for nm, sc in MPRIOR_SCALE.items():
            x = c[0, :, INDEX[nm]]
            if nm in MPRIOR_LOG:
                x = torch.log(x.clamp_min(1e-3))
            d = (x[lag:] - x[:-lag]) / sc
            nll = torch.log1p(d * d / MPRIOR_NU) * (MPRIOR_NU + 1.0) / 2.0
            tot = tot + nll.mean()
            with torch.no_grad():
                rep[nm] = float((d.abs() > 4.54).float().mean())
        self._last_mprior = rep                     # 99 분위 밖(문헌 최고 속도 초과) 틀의 비율
        return tot


    def release_prior_loss(self) -> torch.Tensor:
        """파열 개방 속도의 음의 로그 가능도 평균 (`RELEASE_PRIOR_W`) — log R 에 위치 셋 혼합 스튜던트 t."""
        x = self.rel_log_r
        mu = torch.tensor(RELEASE_MU, dtype=x.dtype, device=x.device)
        z = (x.unsqueeze(-1) - mu) / RELEASE_S
        logp = -torch.log1p(z * z / RELEASE_NU) * (RELEASE_NU + 1.0) / 2.0          # 정규화 상수는 셋이 같다 (상수 차는 기울기에 무관)
        nll = -(torch.logsumexp(logp, -1) - math.log(len(RELEASE_MU)))
        with torch.no_grad():
            self._last_rrate = [float(v) for v in torch.exp(x)]
        return nll.mean()

    def sib_prior_loss(self, c: torch.Tensor) -> torch.Tensor:
        """치찰 틀 협착 면적의 음의 로그 가능도 평균 (`SIB_PRIOR_W`) — log(a_c) 스튜던트 t."""
        if getattr(self, "_sp_mask", None) is None:
            sib = np.asarray(getattr(self.track, "sibilant", np.zeros(0, dtype=bool)), bool)
            m = np.zeros(c.shape[1], bool)
            m[:min(sib.size, m.size)] = sib[:m.size]
            self._sp_mask = torch.as_tensor(m, device=c.device)
            self._sp_w = torch.as_tensor(sib_edge_weights(m, SIB_PRIOR_EDGE_MS / float(getattr(self.track, "frame_ms", 1.0))), device=c.device,
                                         dtype=c.dtype)
            print(f"  치찰 협착 사전: 틀 {int(m.sum())} 개, 중앙 {math.exp(SIB_AC_MU):.3f} cm², log 눈금 {SIB_AC_S:g}, t(ν={SIB_AC_NU:g})"
                  + (f", 양 끝 {SIB_PRIOR_EDGE_MS:g} ms 경사" if SIB_PRIOR_EDGE_MS > 0 else ""), flush=True)
        mk = self._sp_mask
        if not bool(mk.any()):
            return torch.zeros((), dtype=c.dtype, device=c.device)
        ac = c[0, :, INDEX["a_c"]]
        tac = getattr(getattr(self, "eng", None), "last_tube_ac", None)
        if tac is not None:                                   # 조음 모형: 관의 실제 구강 최소 면적 (`voice.TUBE_AC`, §52.487)
            ac = tac[0, :ac.shape[0]].to(ac.dtype)
        z = (torch.log(ac.clamp_min(1e-4)) - SIB_AC_MU) / SIB_AC_S
        nll = torch.log1p(z * z / SIB_AC_NU) * (SIB_AC_NU + 1.0) / 2.0
        with torch.no_grad():
            self._last_sprior = float(torch.exp(torch.log(ac.clamp_min(1e-4))[mk].median()))
        w = getattr(self, "_sp_w", None)
        if w is None or SIB_PRIOR_EDGE_MS <= 0:
            return nll[mk].mean()
        return (nll * w)[mk].sum() / mk.sum()

    def formant_prior_loss(self, c: torch.Tensor) -> torch.Tensor:
        """관측 포먼트 사전 (`FORMANT_PRIOR_W`, §52.479): 시간 영역 관의 **면적 함수**(협착·입술 포함)에서 푼 무손실 공진 F1–F3 이
        목표에서 잰 포먼트 근처에 있게 — 로그 비에 스튜던트 t(ν 3, 눈금 `FORMANT_PRIOR_S`). 면적 계수 공간은 식별이 안 돼(같은 포먼트를
        내는 면적이 여럿) 조음이 엉뚱한 골짜기로 샌다: 038 "자" 에서 분석 F1 739 Hz 인데 적합된 관 F1 이 457 Hz 로 가 H2 가 원본보다
        7 dB 셌다. 개성(포먼트 자리)은 자유롭게 두고 관측에서 크게 벗어나는 것만 비싸게 한다. 유성 틀을 `FORMANT_PRIOR_STEP` 마다."""
        from .tube import webster_modes
        if getattr(self, "_fp_idx", None) is None:
            voi = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), bool)
            T = c.shape[1]
            m = np.zeros(T, bool); m[:min(voi.size, T)] = voi[:T]
            fo = np.stack([np.asarray(self.track[f"f{k}"], float)[:T] for k in (1, 2, 3)], 1)
            ok = m[:, None] & (fo > 50.0)
            idx = np.nonzero(ok.any(1))[0][::max(1, FORMANT_PRIOR_STEP)]
            self._fp_idx = torch.as_tensor(idx, device=c.device)
            self._fp_lf = torch.as_tensor(np.log(np.maximum(fo[idx], 50.0)), dtype=c.dtype, device=c.device)
            self._fp_ok = torch.as_tensor(ok[idx], dtype=c.dtype, device=c.device)
            print(f"  관측 포먼트 사전: 유성 틀 {idx.size} 개 (F1–F3, 눈금 {FORMANT_PRIOR_S:g} 로그, t(ν=3))", flush=True)
        if self._fp_idx.numel() == 0:
            return torch.zeros((), dtype=c.dtype, device=c.device)
        cc = c[:, self._fp_idx]
        from .tube import N_ART as _NA
        names = [f"art{k}" for k in range(1, _NA + 1)] + ["c_place", "a_c", "oral_open", "tract_len"]
        d = {n: cc[..., INDEX[n]] for n in names}
        A = self.eng.td.area_frames(d)[0]                                   # (F, N)
        L = d["tract_len"][0].clamp(10.0, 20.0)
        f1, _ = webster_modes(A.clamp_min(1e-3), 1.0, 3)
        lf = torch.log(f1 / L[:, None])
        z = (lf - self._fp_lf) / FORMANT_PRIOR_S
        nll = torch.log1p(z * z / 3.0) * 2.0 * self._fp_ok
        return nll.sum() / self._fp_ok.sum().clamp_min(1.0)

    def shimmer_prior_loss(self, c: torch.Tensor) -> torch.Tensor:
        """주기별 진폭 흔들림(시머)의 분포 사전 (`SHIM_PRIOR_W`, §52.479) — voice_gain 의 빠른 몫(σ `SHIM_PRIOR_MS` 가우시안 추세를 뺀 나머지)
        에 스튜던트 t(ν 3, 눈금 `SHIM_PRIOR_S` dB). 정상 발성의 국소 시머는 0.1–0.4 dB (MDVP 문턱 0.35 dB). 파형 항을 켜면 적합기가
        voice_gain 을 주기마다 ±6 dB 흔들어 원본의 주기별 우연을 쫓았고(038 0.8 s, 성문 유량 자체의 비주기 −26.6 → −14.6 dB, σ 0.13 → 0.33),
        그것이 갈라짐이다. 느린 음절 윤곽은 벌하지 않는다."""
        x = c[0, :, INDEX["voice_gain"]]
        if getattr(self, "_sp_ker", None) is None or self._sp_ker.device != x.device:
            sg = max(1.0, SHIM_PRIOR_MS / float(self.track.frame_ms))
            k = torch.arange(-int(3 * sg), int(3 * sg) + 1, dtype=x.dtype, device=x.device)
            g = torch.exp(-0.5 * (k / sg) ** 2)
            self._sp_ker = (g / g.sum()).view(1, 1, -1)
            voi = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), bool)
            m = np.zeros(x.shape[0], bool)
            m[:min(voi.size, m.size)] = voi[:m.size]
            self._sp_mask = torch.as_tensor(m, device=x.device)
        h = self._sp_ker.shape[-1] // 2
        tr = torch.nn.functional.conv1d(torch.nn.functional.pad(x.view(1, 1, -1), (h, h), mode="replicate"), self._sp_ker.to(x.dtype))[0, 0]
        z = (x - tr) / SHIM_PRIOR_S
        nll = torch.log1p(z * z / 3.0) * 2.0
        mk = self._sp_mask
        return nll[mk].mean() if bool(mk.any()) else nll.mean() * 0.0

    def src_move_loss(self, c: torch.Tensor) -> torch.Tensor:
        """음원 손잡이의 빠른 요동 사전 (`SRC_MOVE_W`, §52.536) — 열마다 σ `SRC_MOVE_MS` 가우시안 추세를 뺀 몫에 스튜던트 t(ν `SRC_MOVE_NU`,
        눈금 `SRC_MOVE_SCALE`), 유성 틀 평균을 열끼리 더한다. 진행 줄에는 t 의 99 분위(|z| > 4.54) 밖 틀의 몫을 찍는다."""
        names = [n for n in SRC_MOVE_SCALE if n in INDEX]
        if getattr(self, "_sm_ker", None) is None or self._sm_ker.device != c.device or self._sm_ker.dtype != c.dtype:
            sg = max(1.0, SRC_MOVE_MS / float(self.track.frame_ms))
            k = torch.arange(-int(3 * sg), int(3 * sg) + 1, dtype=c.dtype, device=c.device)
            g = torch.exp(-0.5 * (k / sg) ** 2)
            self._sm_ker = (g / g.sum()).view(1, 1, -1)
            voi = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), bool)
            m = np.zeros(c.shape[1], bool)
            m[:min(voi.size, m.size)] = voi[:m.size]
            self._sm_mask = torch.as_tensor(m, device=c.device)
            self._sm_scale = torch.tensor([SRC_MOVE_SCALE[n] for n in names], dtype=c.dtype, device=c.device)
            print(f"  음원 요동 사전: 유성 틀 {int(m.sum())} 개, σ {SRC_MOVE_MS:g} ms 추세 제거, t(ν={SRC_MOVE_NU:g}) 눈금 "
                  + ", ".join(f"{n} {SRC_MOVE_SCALE[n]:g}" for n in names), flush=True)
        mk = self._sm_mask[: c.shape[1]]
        if not names or not bool(mk.any()):
            self._last_srcmove = None
            return torch.zeros((), dtype=c.dtype, device=c.device)
        x = torch.stack([torch.log(c[0, :, INDEX[n]].clamp_min(1e-3)) if n in SRC_MOVE_LOG else c[0, :, INDEX[n]]
                         for n in names], 0).unsqueeze(1)                   # (P, 1, T)
        h = self._sm_ker.shape[-1] // 2
        tr = torch.nn.functional.conv1d(torch.nn.functional.pad(x, (h, h), mode="replicate"), self._sm_ker)
        z = (x - tr)[:, 0] / self._sm_scale[:, None]                         # (P, T)
        nll = torch.log1p(z * z / SRC_MOVE_NU) * (SRC_MOVE_NU + 1.0) / 2.0
        with torch.no_grad():
            self._last_srcmove = {n: float((z[j, mk].abs() > 4.54).double().mean()) for j, n in enumerate(names)}
        return nll[:, mk].mean(1).sum()

    def ga_loss(self, ga: torch.Tensor) -> torch.Tensor:
        """성문 역산 항 (`GA_W`) — 주기 창 평균·RMS 의 상대 제곱 오차, 유성 구간."""
        import torch.nn.functional as F
        g = ga[0].double()
        n = min(g.shape[-1], GA_REF.shape[0])
        g = g[:n]
        r = torch.as_tensor(GA_REF[:n], dtype=g.dtype, device=g.device)
        w = max(3, int(GA_WIN_MS * 1e-3 * self.fs)) | 1
        box = lambda x: F.avg_pool1d(x.view(1, 1, -1), w, stride=max(1, w // 4), padding=w // 2, count_include_pad=False).view(-1)
        mg, mr = box(g), box(r)
        sg = torch.sqrt((box(g * g) - mg * mg).clamp_min(1e-12))
        sr = torch.sqrt((box(r * r) - mr * mr).clamp_min(1e-12))
        if getattr(self, "_ga_mask", None) is None or self._ga_mask.shape[0] != mg.shape[0]:
            v = np.asarray(self.track.voiced, bool) if self.track.voiced.size else np.ones(self.n_frames, bool)
            tt = (np.arange(mg.shape[0]) * max(1, w // 4) / self.fs * 1000.0 / float(self.track.frame_ms)).astype(int)
            self._ga_mask = torch.as_tensor(v[np.clip(tt, 0, v.size - 1)], device=g.device)
        m = self._ga_mask
        den = (mr[m] ** 2).mean() + (sr[m] ** 2).mean() + 1e-12
        return (((mg - mr)[m] ** 2).mean() + ((sg - sr)[m] ** 2).mean()) / den

    def vf_anat_loss(self) -> torch.Tensor:
        """성대 정적 배율이 해부 범위(`VF_ANAT`) 밖으로 나간 log 거리의 제곱합 / 0.05²."""
        tdp = self.eng.td
        tot = torch.zeros((), dtype=torch.float64)
        for k, (lo, hi) in VF_ANAT.items():
            s = getattr(tdp, f"log_vf_{k}").double()
            tot = tot + torch.relu(math.log(lo) - s) ** 2 + torch.relu(s - math.log(hi)) ** 2
        return tot / 0.05 ** 2

    def vf_ns_anat_loss(self) -> torch.Tensor:
        """모드 3 화자 상수가 생리 범위(`VF_NS_ANAT`) 밖으로 나간 log 거리의 제곱합 / 0.05².

        **고정된 상수는 빼고** 잰다 (§52.537). 3D 유한요소에서 잰 상수(`--vf-ns-fem`, 층간 결합 0.05 · 불룩함 0.01 · 두께 0.48)는 이 범위 밖이라
        기울기 없는 상수 3839 를 손실에 더했고, 정체 판정(상대 변화)이 모든 단계를 20 회 만에 끊었다 (포락 27 %)."""
        tdp = self.eng.td
        from . import voice_td as vt
        tot = torch.zeros((), dtype=torch.float64, device=tdp.log_ns_len.device)
        for k, (lo, hi) in VF_NS_ANAT.items():
            if f"td_log_ns_{k}" in self.locked_constants:
                continue
            if vt.VF_NS_HARD and k in vt.VF_NS_HARD:
                hlo, hhi = vt.VF_NS_HARD[k]
                lo, hi = max(lo, hlo), min(hi, hhi)
                if lo > hi:
                    raise ValueError(f"Incompatible hard/soft NS bounds for {k}")
            s = getattr(tdp, f"log_ns_{k}").double()
            tot = tot + torch.relu(math.log(lo) - s) ** 2 + torch.relu(s - math.log(hi)) ** 2
        return tot / 0.05 ** 2

    def psub_prior_loss(self, c: torch.Tensor) -> torch.Tensor:
        """말소리 틀(유성·마찰) 폐압의 음의 로그 가능도 평균 (`PSUB_PRIOR_W`) — log 폐압 스튜던트 t."""
        if getattr(self, "_pp_mask", None) is None:
            T = int(c.shape[1])
            m = np.zeros(T, bool)
            for arr in (getattr(self.track, "voiced", np.zeros(0)), getattr(self.track, "fricative", np.zeros(0))):
                arr = np.asarray(arr, bool)[:T]
                m[:arr.size] |= arr
            self._pp_mask = torch.as_tensor(m, device=c.device)
            print(f"  폐압 사전: 말소리 틀 {int(m.sum())} 개, 중앙 {math.exp(PSUB_PRIOR_MU):.1f} cmH2O, log 눈금 {PSUB_PRIOR_S:g}, "
                  f"t(ν={PSUB_PRIOR_NU:g})", flush=True)
        mk = self._pp_mask
        if not bool(mk.any()):
            return torch.zeros((), dtype=c.dtype, device=c.device)
        z = (torch.log(c[0, :, INDEX["p_sub"]].clamp_min(0.1)) - PSUB_PRIOR_MU) / PSUB_PRIOR_S
        nll = torch.log1p(z * z / PSUB_PRIOR_NU) * (PSUB_PRIOR_NU + 1.0) / 2.0
        return nll[mk].mean()

    def add_prior_loss(self, c: torch.Tensor) -> torch.Tensor:
        """유성 틀 내전 수준의 음의 로그 가능도 평균 (`ADD_PRIOR_W`) — 로짓 영역 스튜던트 t."""
        if getattr(self, "_ap_mask", None) is None:
            voi = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)), bool)
            m = np.zeros(c.shape[1], bool)
            m[:min(voi.size, m.size)] = voi[:m.size]
            # 치찰 틀은 뺀다 (§52.481) — 마찰 중에는 성문이 벌어진다. 유성 꼬리가 걸친 ㅅ 틀에서 이 사전이 내전 0.44 를 붙들어 성대가 계속
            # 닿았고, 닫힘의 꺾임이 만든 16 kHz 까지의 배음이 ㅅ 의 잡음 자리를 차지했다 (스펙트로그램: 원본은 잡음, 합성은 사선 배음).
            sib = np.asarray(getattr(self.track, "sibilant", np.zeros(0, dtype=bool)), bool)
            m[:min(sib.size, m.size)] &= ~sib[:m.size]
            self._ap_mask = torch.as_tensor(m, device=c.device)
            print(f"  내전 수준 사전: 유성 틀 {int(m.sum())} 개 (치찰 틀 제외), logit 중앙 {ADD_PRIOR_MU:+g} (내전 "
                  f"{1.0 / (1.0 + math.exp(-ADD_PRIOR_MU)):.2f}), 눈금 {ADD_PRIOR_S:g}, t(ν={ADD_PRIOR_NU:g})", flush=True)
        mk = self._ap_mask
        if not bool(mk.any()):
            return torch.zeros((), dtype=c.dtype, device=c.device)
        a = c[0, :, INDEX["adduction"]].clamp(1e-3, 1.0 - 1e-3)
        z = (torch.log(a / (1.0 - a)) - ADD_PRIOR_MU) / ADD_PRIOR_S
        nll = torch.log1p(z * z / ADD_PRIOR_NU) * (ADD_PRIOR_NU + 1.0) / 2.0
        with torch.no_grad():
            self._last_aprior = float((z[mk].abs() > 4.54).float().mean())     # t_3 의 99 분위 밖
        return nll[mk].mean()

    def _trans_env(self, x: torch.Tensor) -> torch.Tensor:
        """(1, N) → (대역, T) 0.5 ms 포락 [dB], `TRANS_HOP_MS` 간격. 대역은 FFT 에서 코사인 비탈(가장자리의 ±10 %)로 가른다."""
        import torch.nn.functional as F
        n = x.shape[-1]
        nfft = 1 << int(n - 1).bit_length()
        X = torch.fft.rfft(x[0].to(torch.float64), n=nfft)
        f = torch.fft.rfftfreq(nfft, 1.0 / self.fs).to(X.device)
        W = max(2, int(round(TRANS_WIN_MS * 1e-3 * self.fs)))
        hop = max(1, int(round(TRANS_HOP_MS * 1e-3 * self.fs)))
        win = torch.hann_window(W + 2, periodic=False, dtype=torch.float64, device=X.device)[1:-1]
        win = (win / win.sum()).view(1, 1, -1)
        out = []
        for lo, hi in TRANS_BANDS:
            hi = min(hi, 0.45 * self.fs)
            def edge(fc, up):
                t = ((f - fc) / (0.1 * fc)).clamp(-1.0, 1.0)
                r = 0.5 + 0.5 * torch.sin(0.5 * math.pi * t)
                return r if up else 1.0 - r
            m = edge(lo, True) * edge(hi, False)
            yb = torch.fft.irfft(X * m, n=nfft)[:n]
            e = F.conv1d((yb * yb).view(1, 1, -1), win, stride=hop, padding=W // 2)[0, 0]
            out.append(10.0 * torch.log10(e + 1e-20))
        return torch.stack(out)

    def transient_loss(self, y: torch.Tensor) -> torch.Tensor:
        """원본에 없는 짧은 튐 (`TRANS_W`). 10 ms 당 평균으로 낸다 — 튐은 드물어서 전체 평균이면 묻힌다."""
        import torch.nn.functional as F
        hop_s = max(1, int(round(TRANS_HOP_MS * 1e-3 * self.fs))) / self.fs
        mh = max(1, int(round(TRANS_MATCH_MS * 1e-3 / hop_s)))
        bh = max(1, int(round(TRANS_BASE_MS * 1e-3 / hop_s)))
        mx = lambda z: F.max_pool1d(z.unsqueeze(0), 2 * mh + 1, stride=1, padding=mh)[0]
        av = lambda z: F.avg_pool1d(z.unsqueeze(0), 2 * bh + 1, stride=1, padding=bh, count_include_pad=False)[0]
        if getattr(self, "_tr_et", None) is None:
            with torch.no_grad():
                et = self._trans_env(self.target)
                self._tr_et = mx(et)
                self._tr_pt = mx(et - av(et))
                self._tr_floor = (et.max(dim=-1, keepdim=True).values - TRANS_FLOOR_DB)
            print(f"  튐 벌점: 대역 {len(TRANS_BANDS)} 개, 0.5 ms 포락, 목표 ±{TRANS_MATCH_MS:g} ms 최대보다 수준 +{TRANS_L0:g} dB · "
                  f"솟음 +{TRANS_P0:g} dB 를 둘 다 넘는 몫", flush=True)
        es = self._trans_env(y)
        T = min(es.shape[-1], self._tr_et.shape[-1])
        es = es[:, :T]
        et, pt = self._tr_et[:, :T], self._tr_pt[:, :T]
        dl = es - et
        dp = (es - av(es)) - pt
        live = (torch.maximum(et, es.detach()) > self._tr_floor).to(es.dtype)
        z = torch.minimum(dl - TRANS_L0, dp - TRANS_P0)
        if TRANS_LEAK:
            over = self._soft_over(z, TRANS_KNEE)
        else:
            zp = z.clamp_min(0.0)
            over = zp * zp * zp / (zp * zp + TRANS_KNEE * TRANS_KNEE)
        dur10 = max(T * hop_s / 0.010, 1.0)
        with torch.no_grad():
            hit = ((dl >= 3.0) & (dp >= 6.0)).to(es.dtype) * live
            self._last_trans = float(hit.amax(0).sum()) * hop_s * 1000.0       # 튐이 선 시간 [ms] (대역 중 하나라도)
        return (over * over * live).sum() / dur10



    def _prepare_corr(self) -> None:
        """상관·주기성 항이 쓸 창 격자와 유성 마스크를 만든다."""
        self._corr_win = max(64, int(CORR_WIN_MS * self.fs / 1000.0))
        self._corr_hop = max(16, int(CORR_HOP_MS * self.fs / 1000.0))
        tf = self._frames(self.target, self._corr_win, self._corr_hop)
        self._corr_tgt = tf
        self._corr_te = (tf * tf).sum(-1)
        v = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)))
        T = tf.shape[0]
        if v.size:
            c = (np.arange(T) * self._corr_hop + self._corr_win // 2) / self.hop
            vm = v[np.clip(c.astype(int), 0, v.size - 1)]
        else:
            vm = np.ones(T, dtype=bool)
        lvl = self._corr_te.detach()
        live = lvl > float(lvl.max()) * 1e-4          # 정점 대비 −40 dB
        self._corr_live = torch.as_tensor(vm, device=live.device) & live
        # --- 주기성 ---
        f0 = np.asarray(self.track["f0_target"], dtype=np.float64)
        c = (np.arange(T) * self._corr_hop + self._corr_win // 2) / self.hop
        f0f = f0[np.clip(c.astype(int), 0, max(f0.size - 1, 0))] if f0.size else np.zeros(T)
        lag = np.where(f0f > 50.0, np.round(self.fs / np.maximum(f0f, 50.0)), 0).astype(int)
        self._per_lag = lag
        self._per_ok = torch.as_tensor((lag > 0) & (lag < self._corr_win // 2),
                                       device=live.device) & self._corr_live
        # 고역통과 커널 (창 씌운 sinc). 고정 상수라 미분에 영향이 없다.
        n = 129
        t = np.arange(n) - n // 2
        fc = HNR_HP_HZ / self.fs
        lp = np.sinc(2 * fc * t) * np.hanning(n)
        lp = lp / lp.sum()
        hp = -lp
        hp[n // 2] += 1.0
        self._hp = torch.as_tensor(hp, dtype=self.target.dtype,
                                   device=self.target.device).view(1, 1, n)
        # 통과 대역들 — 결함이 있는 자리를 손실이 직접 보게 한다 (§52.88, §52.174).
        self._bps = []
        for lo, hi in (HNR_BP_HZ,) + tuple(HNR_BANDS):
            if not (lo and hi) or not hi > lo > 0.0 or hi >= 0.5 * self.fs:
                continue
            k_hi = np.sinc(2 * (hi / self.fs) * t) * np.hanning(n)
            k_lo = np.sinc(2 * (lo / self.fs) * t) * np.hanning(n)
            bp = k_hi / k_hi.sum() - k_lo / k_lo.sum()
            self._bps.append(torch.as_tensor(bp, dtype=self.target.dtype,
                                             device=self.target.device).view(1, 1, n))
        self._bp = self._bps[0] if self._bps else None      # 옛 이름 (진단이 쓴다)
        with torch.no_grad():
            self.tgt_per = self._periodicity(self.target)

    def _periodicity(self, y: torch.Tensor) -> torch.Tensor:
        """(대역 수, T) — 제 주기 지연 정규화 자기상관. 전대역 · >`HNR_HP_HZ` · `HNR_BP_HZ` · `HNR_BANDS`.
        지연은 틀마다 목표 지연 ± `PER_LAG_SEARCH` 안에서 **전대역** 상관이 가장 큰 정수 지연 (저역이 지배해 모호하지 않다) 하나를 골라 모든 대역에 쓴다
        (§52.532) — 대역마다 최대를 고르면 고역에서는 진동하는 상관의 아무 마루나 집어 잡음도 주기적으로 잡힌다 (원본 8–12 kHz 0.05 → 0.28)."""
        hp = torch.nn.functional.conv1d(y.unsqueeze(1), self._hp,
                                        padding=self._hp.shape[-1] // 2)[:, 0]
        sigs = [y, hp]
        for bp in getattr(self, "_bps", ()):
            sigs.append(torch.nn.functional.conv1d(y.unsqueeze(1), bp,
                                                   padding=bp.shape[-1] // 2)[:, 0])
        w, h = self._corr_win, self._corr_hop
        T = self._per_ok.shape[0]
        dev = y.device
        idx = torch.arange(T, device=dev) * h
        lag = torch.as_tensor(self._per_lag, device=dev)
        ar = torch.arange(w, device=dev)

        def corr_at(sig, lg):
            n = sig.shape[-1]
            a = sig[0][(idx[:, None] + ar[None, :]).clamp(max=n - 1)]
            b = sig[0][(idx[:, None] + lg[:, None] + ar[None, :]).clamp(min=0, max=n - 1)]
            return (a * b).sum(-1) / torch.sqrt((a * a).sum(-1) * (b * b).sum(-1) + 1e-20)

        if PER_LAG_SEARCH > 0.0:
            with torch.no_grad():                                    # 지연 고르기 (정수 색인 — 기울기는 고른 지연의 상관으로 흐른다)
                okm = self._per_ok.cpu().numpy()
                lv = self._per_lag[okm] if okm.any() else self._per_lag
                K = int(math.ceil(PER_LAG_SEARCH * float(max(int(np.percentile(lv, 95)) if lv.size else 1, 1))))
                best = lag.clone()
                rbest = torch.full((T,), -2.0, dtype=y.dtype, device=dev)
                for o in range(-K, K + 1):
                    lg = lag + o
                    r = corr_at(y, lg)
                    ok = (abs(o) <= PER_LAG_SEARCH * lag.double() + 0.5) & (lg > 0)
                    upd = ok & (r > rbest)
                    rbest = torch.where(upd, r, rbest)
                    best = torch.where(upd, lg, best)
            lag = best
        return torch.stack([corr_at(sig, lag) for sig in sigs])

    def hnr_loss(self, y: torch.Tensor) -> torch.Tensor:
        """주기성을 목표에 **일치**시킨다. 시끄러운 쪽을 더 세게 문다."""
        p = self._periodicity(y)
        d = self.tgt_per - p                      # + 면 합성이 더 시끄럽다
        # **목표에서 값도 기울기도 0 이어야 한다.** 예전 형태
        # `softplus(d)·A + softplus(−d)` 는 d=0 에서 0.02·ln2·(A+1) = 0.0555 이고 기울기가
        # 0.5·(1−A) ≠ 0 이라, 최소점이 d = −0.02·ln A = −0.022 — 합성이 목표보다 **더
        # 주기적인** 쪽에 있었다. 즉 이 항은 늘 배음을 더 가지런하게 미는 쪽으로 치우쳐
        # 있었다(MEASUREMENTS §50.2 탐침: 목표 그대로 넣어도 hnr 0.0555).
        # 비대칭 후버: |d| 의 매끈한 형태에 시끄러운 쪽(d>0) 가중을 σ 로 섞는다.
        pen = self._soft_abs(d, 0.02) * (1.0 + (HNR_ASYM - 1.0) * torch.sigmoid(d / 0.02))
        w = self._per_ok.to(pen.dtype)
        return (pen * w).sum() / (w.sum().clamp_min(1.0) * pen.shape[0])

    # ------------------------------------------------- 유성 구간의 세 통계









    def _decompose_target(self) -> tuple[np.ndarray, np.ndarray] | None:
        """목표를 조화 성분과 잔차로 가른다 (`waveform.decompose`).

        성문 펄스에서 나온 국소 F0 로 3 주기 창에서 최소제곱을 푼다. 무성 구간에서는
        F0 가 없어 조화 성분이 0 이 되고 전부 잔차로 간다 — 따로 마스크가 필요 없다.
        """
        from .waveform import decompose
        tgt = self.target[0].detach().cpu().numpy().astype(np.float64)
        f0 = np.asarray(self.track["f0_target"], dtype=np.float64)
        voi = np.asarray(getattr(self.track, "voiced", np.zeros(0, dtype=bool)))
        if voi.shape[0] == f0.shape[0]:
            f0 = np.where(voi, f0, 0.0)
        try:
            _, har, res = decompose(tgt, self.fs, f0, self.hop)
        except Exception:
            return None
        return har, res

    def _harmonic_weight(self, k: int) -> torch.Tensor:
        """(1, F, T) 조화 우세도 — 이 시간·주파수 빈이 얼마나 '주기적'인가.

            w = |STFT(조화)| / (|STFT(조화)| + |STFT(잔차)|)

        모음의 낮은 하모닉에서 1 에 가깝고, 마찰 잡음과 모음 고역의 기식에서 0 에
        가깝다. 목표에서 한 번만 계산하는 상수다.

        두 곳이 이 값을 쓴다. 위상 항은 **w 로 가중**해 조화부만 보고(난류의 위상은
        재도 뜻이 없다), 크기 항은 **1−w 로 가중**해 난류부에서 기대 스펙트럼을
        비교한다(실현을 맞추라고 하면 기울기가 잡음이다).
        """
        b = self.bin_max[k]
        if self._har_res is None:
            return torch.ones(1, b, 1, device=self.device)
        har, res = self._har_res
        H = self._cabs(_stft(torch.as_tensor(har, dtype=torch.float32,
                                             device=self.device).unsqueeze(0),
                             k, self.wins[k]))[:, :b]
        R = self._cabs(_stft(torch.as_tensor(res, dtype=torch.float32,
                                             device=self.device).unsqueeze(0),
                             k, self.wins[k]))[:, :b]
        return (H / (H + R + 1e-9)).detach()

    def _time_smooth(self, S: torch.Tensor, k: int) -> torch.Tensor:
        """파워 영역에서 시간축 이동평균 -> 크기. 난류의 **기대** 스펙트럼을 만든다.

        파워가 가법적이므로 평균은 파워에서 낸다. 폭은 `NOISE_EXPECT_MS` 이고 창
        크기별로 프레임 수가 다르다 (긴 창은 이미 시간 폭이 커서 평활이 거의 없다).
        """
        n = self._sm_frames.get(k, 1)
        if n <= 1 or S.shape[-1] < 2:
            return S
        n = min(n, S.shape[-1] // 2 * 2 + 1)
        pad = n // 2
        p = torch.nn.functional.pad(S ** 2, (pad, n - 1 - pad), mode="replicate")
        return torch.sqrt(torch.nn.functional.avg_pool1d(p, n, stride=1) + 1e-20)

    def _expect(self, S: torch.Tensor, k: int) -> torch.Tensor:
        """난류 우세 빈만 기대 스펙트럼으로 갈아 끼운다.

        `(1−w)` 로 섞으므로 조화부는 프레임별 실현 그대로 남는다. 목표와 합성에
        **똑같이** 걸리므로 편향은 생기지 않고 기울기의 분산만 줄어든다.
        """
        if NOISE_EXPECT_MS <= 0 or self._har_res is None:
            return S
        wn = self._noise_w.get(k)
        if wn is None:
            return S
        m = min(S.shape[-1], wn.shape[-1])
        w = wn[..., :m]
        s = S[..., :m]
        return s + w * (self._time_smooth(s, k) - s)

    @staticmethod
    def _soft_over(x: torch.Tensor, width: float) -> torch.Tensor:
        """relu 의 부드러운 대체. width 만큼의 폭으로 무릎을 뭉갠다.

        **relu 를 쓰면 안 된다.** 꺾임점에서 2 차 도함수가 정의되지 않아 손실이 C² 가
        아니게 되고, 그러면 헤시안 기반 진단(유효 파라미터 수 γ 등)이 통째로 막힌다.
        실측으로 확인했다: 유한차분 헤시안의 대칭성(uᵀHv = vᵀHu)이 ε 을 4 자릿수
        쓸어도 41.9 / 47.5 / 178.2 / 153.5 % 로 깨졌다 (docs/MEASUREMENTS.md §8.7).
        손실은 결정적이었으므로 원인은 무작위성이 아니라 꺾임이다.

        width → 0 이면 relu 로 수렴한다. 벌점으로서의 성질(문턱 아래는 거의 0, 위는
        선형)은 그대로 두고 미분만 매끄럽게 만든다.
        """
        return width * torch.nn.functional.softplus(x / width)

    @staticmethod
    def _soft_abs(x: torch.Tensor, width: float) -> torch.Tensor:
        """|x| 의 부드러운 대체 (의사 후버). 작은 x 에서 x²/2width, 큰 x 에서 |x|.

        포락 오차의 L1 이 손실의 최대 꺾임원이었다 — 멜 빈 수천 개마다 a=b 에서
        꺾인다. width 는 "이 정도 차이는 오차로 안 친다" 는 뜻이고, dB 단위에서
        0.5 dB 면 계측 잡음보다 작아 거동이 사실상 안 바뀐다.
        """
        return width * (torch.sqrt(1.0 + (x / width) ** 2) - 1.0)

    def _band_floor(self, mdb: torch.Tensor):
        """밴드별 바닥 (…, n_mels, 1). `BAND_FLOOR_DB` 주석이 근거다."""
        glob = float(mdb.max())
        if BAND_FLOOR_DB <= 0.0:
            return glob - DB_RANGE
        own = mdb.amax(-1, keepdim=True) - BAND_FLOOR_DB
        return own.clamp(min=glob - BAND_FLOOR_MIN, max=glob - DB_RANGE)

    def _lower_floor_to_recording(self) -> None:
        """`FLOOR_REC_MARGIN_DB` — 대역 바닥을 합성이 더하는 녹음 바닥 잡음의 멜 dB 중앙값 + 여유까지 내린다."""
        fl = self._floor(self.target.shape[-1])
        if fl is None:
            return
        S = self._expect(self._cabs(_stft(fl.to(self.target.device).to(self.target.dtype), MEL_FFT,
                                          self.wins[MEL_FFT]))[:, :self.bin_max[MEL_FFT]], MEL_FFT)
        rec = self._db(self.mel[:, :S.shape[1]] @ S).median(-1, keepdim=True).values + FLOOR_REC_MARGIN_DB
        glob = float(self.tgt_Mdb.max())
        old = self.db_floor_band
        new = torch.minimum(old, rec).clamp_min(glob - BAND_FLOOR_MIN)
        self.db_floor_band = new
        d = (old - new).flatten()
        lo = d > 0.5
        print(f"  손실 바닥 → 녹음 바닥 + {FLOOR_REC_MARGIN_DB:g} dB: 멜 {int(lo.sum())}/{d.numel()} 밴드를 내림 "
              f"(최대 {float(d.max()):.1f} dB, 중앙 {float(d[lo].median()) if bool(lo.any()) else 0.0:.1f} dB)", flush=True)

    @staticmethod
    def _soft_floor(x: torch.Tensor, floor, width: float) -> torch.Tensor:
        """clamp_min 의 부드러운 대체. floor + softplus(x − floor)."""
        return floor + width * torch.nn.functional.softplus((x - floor) / width)

    def _report_nonfinite(self, it: int, ps, names) -> None:
        """비유한 기울기가 **어느 파라미터의 어느 프레임**에서 나는지 찍는다.

        `w` 는 (Tc, P_fit) 이므로 열 = 파라미터, 행 = 격자점이다. 열 이름을 붙여
        주면 원인 파라미터가 바로 보인다. `FORMANT_ML_DEBUG_NONFINITE=1` 로 켠다.
        """
        for nm, p in zip(names, ps):
            if p.grad is None or torch.isfinite(p.grad).all():
                continue
            bad = ~torch.isfinite(p.grad)
            if p.grad.dim() == 2:
                cols = bad.any(0).nonzero().flatten().tolist()
                rows = bad.any(1).nonzero().flatten().tolist()
                who = [self.names[c] for c in cols if c < len(self.names)]
                print(f"    [{it}] 비유한 {nm}: 파라미터 {who}  "
                      f"격자점 {rows[:8]}{'...' if len(rows) > 8 else ''} "
                      f"({len(rows)}/{p.grad.shape[0]})", flush=True)
            else:
                idx = bad.nonzero().flatten().tolist()
                who = [self.names[c] for c in idx if c < len(self.names)] if nm == "d" else idx
                print(f"    [{it}] 비유한 {nm}: {who}", flush=True)

    @staticmethod
    def _pseudo_huber(r: torch.Tensor) -> torch.Tensor:
        """후버의 매끄러운 형태. torch.where 는 1 차 도함수만 이어져 C² 가 아니다.

        √(1+r²) − 1 은 작은 r 에서 r²/2, 큰 r 에서 r−1 로 후버와 같은 모양이면서
        무한히 미분 가능하다.
        """
        return torch.sqrt(1.0 + r * r) - 1.0

    def penalty(self) -> torch.Tensor:
        return self._penalty_core() + self._room_fir_penalty()

    def _penalty_core(self) -> torch.Tensor:
        """물리적으로 성립하지 않는 해를 막는다.

        (1) 포먼트 순서. F4 가 F1 아래로 내려가는 해가 실제로 나왔다.
        (2) 대역폭이 중심 주파수를 넘지 않을 것 — 넘으면 그건 극이 아니라 기울기다.
        (3) 조음 속도. 계측된 생리적 상한(`VEL_LIMIT_HZ_PER_MS`)을 넘는 이동은 문다.
        """
        u = self._u()
        pen = torch.zeros((), dtype=torch.float64, device=self.device)
        if getattr(self, "hcorr", None) is not None:
            if HCORR_L2 > 0.0:
                pen = pen + HCORR_L2 * (self.hcorr ** 2 * self._hcorr_kw()).mean()
            if HCORR_TV > 0.0 and self.hcorr.shape[-1] > 1:
                dv = self.hcorr[..., 1:] - self.hcorr[..., :-1]
                pen = pen + HCORR_TV * (dv ** 2).mean()
            if HCORR_KTV > 0.0 and self.hcorr.shape[1] > 1:
                dk = self.hcorr[:, 1:] - self.hcorr[:, :-1]
                pen = pen + HCORR_KTV * (dk ** 2).mean()
            if HCORR_PLOCK > 0.0:
                # 주기에 걸친 합성 벡터 길이 — 위상이 모이면 1, 흩어지면 0.
                kk = int(min(HCORR_PLOCK_K, self.hcorr.shape[1]))
                a_, b_ = self.hcorr[0][:kk], self.hcorr[1][:kk]          # (k, C)
                mag = torch.sqrt(a_ * a_ + b_ * b_ + 1e-20)
                res = torch.sqrt(a_.sum(-1) ** 2 + b_.sum(-1) ** 2 + 1e-20)
                R = res / mag.sum(-1).clamp_min(1e-12)
                pen = pen + HCORR_PLOCK * (1.0 - R).mean()
            if HCORR_GAP > 0.0 and self.hcorr.shape[1] > 1:
                # 주기 전체에 걸쳐 에너지 가중으로 모은다 — 조용한 주기가 비를 흔들지 않게.
                num = (self.hcorr[:, 1:] * self.hcorr[:, :-1]).sum()
                den = (self.hcorr ** 2).sum()
                pen = pen + HCORR_GAP * 0.5 * (1.0 - num / (den + 1e-30))
        if TRANSIENT_PRIOR > 0.0 and getattr(self, "tr_gain", None) is not None:
            # 잰 크기(로그 이득 0)에서 멀어지는 만큼 문다 — 클릭을 끄는 길을 막는다.
            pen = pen + TRANSIENT_PRIOR * (self.tr_gain ** 2).mean()
        if len(self.f_idx) >= 2:
            f = torch.stack([self._to_val(u[:, i], self.specs[i]) for i in self.f_idx], 1)
            gap = self._soft_over(f[:, :-1] + F_MARGIN_HZ - f[:, 1:], 30.0) / 1000.0
            pen = pen + 10.0 * (gap * gap).mean()
            for j, i in enumerate(self.f_idx):
                nb = self.names[i].replace("f", "bw")
                if nb in self.names:
                    k = self.names.index(nb)
                    bw = self._to_val(u[:, k], self.specs[k])
                    over = self._soft_over(bw - 0.8 * f[:, j], 30.0) / 1000.0
                    pen = pen + 2.0 * (over * over).mean()
        if VEL_W > 0 and VEL_MODE != "off" and u.shape[0] > 1:
            dt = max(self.track.frame_ms, 1e-6)
            tab = {"hinge": VEL_LIMIT_HZ_PER_MS, "huber": VEL_KNEE_HZ_PER_MS,
                   "accel": ACC_KNEE_HZ_PER_MS2}[VEL_MODE]
            for nm, lim in tab.items():
                if nm not in self.names or u.shape[0] < 3:
                    continue
                k = self.names.index(nm)
                v = self._to_val(u[:, k], self.specs[k])
                if VEL_MODE == "accel":
                    # 2 차 차분. 한 방향으로 꾸준히 가는 급전은 여기서 0 에 가깝고,
                    # 부호가 뒤집히는 난동만 크게 나온다.
                    rate = (v[2:] - 2.0 * v[1:-1] + v[:-2]).abs() / (dt * dt)
                else:
                    rate = (v[1:] - v[:-1]).abs() / dt
                if VEL_MODE == "hinge":
                    over = self._soft_over(rate - lim, 0.05 * lim) / 100.0
                    pen = pen + VEL_W * (over * over).mean()
                else:
                    # 후버. lim 으로 나눠 무차원으로 만든다 (파라미터끼리 같은 저울).
                    r = rate / lim
                    h = self._pseudo_huber(r)
                    pen = pen + VEL_W * h.mean()
        if ARTIC_VEL_W > 0 and u.shape[0] > 1:
            # **1 차 차분(속도)이다.** 포먼트에는 2 차(가속도)를 쓰지만(빠르게
            # 움직이는 것은 허용하고 방향을 홱 바꾸는 것만 문다), 여기서 막을 것은
            # 방향 전환이 아니라 **불가능한 속도** 자체다.
            dt = max(self.track.frame_ms, 1e-6)
            for nm, knee in ARTIC_VEL_KNEE.items():
                if nm not in self.names:
                    continue
                k = self.names.index(nm)
                lg = torch.log(self._to_val(u[:, k], self.specs[k]).clamp_min(1e-4))
                rate = (lg[1:] - lg[:-1]).abs() / dt
                # **문턱 위만 문다.** 처음에는 `pseudo_huber(rate/knee)` 를 썼는데
                # 그건 무릎 **아래**에서도 이차로 벌하므로 실제 제스처까지 눌린다.
                # 실측 (yang_00000040 0.18~0.55 s, ARTIC_VEL_W=1.0):
                #     a_c 속도 95 분위 0.449 -> **0.015** neper/ms
                # 가장 빠른 실제 제스처가 0.172 인데 그 11 배 **아래**로 얼렸다.
                # 대가는 포락 90.67 -> 87.85 %, 무게중심 r 0.983 -> 0.880 이었다
                # (§27.3). 스파이크만 깎아야 하는데 조음 자체를 죽인 것이다.
                #
                # softplus 로 초과분만 취하면 한계 아래는 사실상 공짜다. 폭은
                # 무릎의 20 % — relu 에 충분히 가깝고 C² 는 지킨다.
                # (정확히 0 은 아니다: 속도 0 에서 softplus(−5) = 6.7e-3 이 새고
                #  의사후버를 지나 프레임당 ~9e-7 로 남는다. 손실이 ~1.0 이므로
                #  무시할 양이고, 대신 미분이 어디서나 살아 있다.)
                over = self._soft_over(rate - knee, 0.2 * knee) / knee
                pen = pen + ARTIC_VEL_W * self._pseudo_huber(over).mean()
        if BW_LAW_W > 0.0 and len(self.f_idx) >= 1:
            # **대역폭을 손실 법칙 쪽으로 당긴다.** 포먼트 주파수는 그대로 자유다 —
            # 조음이 정하는 양이기 때문이다. 묶는 것은 "그 주파수의 극이 얼마나
            # 감쇠하는가" 뿐이고, 그건 기하가 아니라 손실이 정한다.
            bw_floor = float(getattr(self.eng.tract, "bw_floor", 40.0))
            bw_slope = float(getattr(self.eng.tract, "bw_slope", 0.05))
            for i in self.f_idx:
                nb = self.names[i].replace("f", "bw")
                if nb not in self.names:
                    continue
                k = self.names.index(nb)
                f = self._to_val(u[:, i], self.specs[i]).clamp_min(50.0)
                b = self._to_val(u[:, k], self.specs[k]).clamp_min(1.0)
                law = bw_floor + bw_slope * f
                r = torch.log(b / law) / BW_LAW_TOL
                pen = pen + BW_LAW_W * self._pseudo_huber(r).mean()
        if RIPPLE_W > 0 and self.w.shape[0] >= 3:
            # 격자 간격은 **stride 를 곱한 실제 시간**이다. 성긴 격자에서 같은
            # 증분은 훨씬 느린 변화이므로 벌점도 그만큼 작아야 한다.
            dt = max(self.track.frame_ms, 1e-6) * max(self.stride, 1)
            acc = (self.w[2:] - 2.0 * self.w[1:-1] + self.w[:-2]).abs() / (dt * dt)
            pen = pen + RIPPLE_W * self._pseudo_huber(acc / RIPPLE_KNEE).mean()
        return pen

    def term_breakdown(self) -> dict:
        """손실 항별 (값, 무게, 몫) — 진단. 포락 항은 무게 1."""
        self._collect = True
        try:
            with torch.no_grad():
                lv = self.loss()
                tot = float(lv[0] if isinstance(lv, tuple) else lv)
            T = dict(self._terms)
        finally:
            self._collect = False
        out = {}
        for k, v in T.items():
            val = float(v.detach()) if torch.is_tensor(v) else float(v)
            w = 1.0 if k == "env" else self._termw.get(k, float("nan"))
            out[k] = (val, w, val * w / max(tot, 1e-12))
        return out

    def loss(self):
        """손실 — **다섯 자만** (MEASUREMENTS §52.475, 사용자: *"필요한 자 5 개 빼고 다 갖다버리고"*).

        1. 포락 — 다해상도 멜 dB + SC (`spectral_loss`)
        2. 배음 크기 — 0~3 kHz 배음 (`self.harmonic`)
        3. 배음/잡음 비 — 대역별 (`hnr_loss`, `HNR_W`)
        4. 튐 — 원본에 없는 짧은 튐 (`transient_loss`, `TRANS_W`)
        5. 생리 사전 — 기관 운동·내전 수준·치찰 협착·파열 개방 속도 (`MPRIOR_W`·`ADD_PRIOR_W`·`SIB_PRIOR_W`·`RELEASE_PRIOR_W`)

        그 밖의 43 개 항은 지웠다. 적합기가 서로 다른 항 사이의 줄다리기로 비물리적인 해를 냈고(§52.472), 항마다 막으면 다른 항이 같은 해를
        다른 길로 냈다. 제어열 매개화의 정칙화(L1·L2·매끄러움·사전)와 `penalty()` 의 물리 제약은 자가 아니라 표현의 일부라 남긴다.
        """
        y = self.synth()
        sc, env_db, env_sc, per = self.spectral_loss(y)
        env = 4.0 * env_db + env_sc + 0.5 * sc    # 포락(dB)이 주 목적, SC 는 보조
        l = env
        T = {"env": env} if self._collect else None
        self._last_db = float(env_db.detach()) * 20.0

        def add(name, base, term):
            nonlocal l
            if T is not None:
                T[name] = term
                self._termw[name] = float(self._bal.get(name, base))
            l = l + self._bal.get(name, base) * term

        if self.harmonic is not None:
            add("harmonic", self.harmonic_weight, self.harmonic(y[0]))
        if WAVE_W > 0.0:
            add("wave", WAVE_W, self.wave_loss(y))
        if HNR_W > 0.0:
            add("hnr", HNR_W, self.hnr_loss(y))
        if HFENV_W > 0.0 and getattr(self, "_hfenv", None) is not None:
            add("hfenv", HFENV_W, self._hfenv)
        if HFLINE_W > 0.0 or HFCOMB_W > 0.0:
            # **고역 가로줄 벌점** (§52.106 · §52.117, 사용자 지시 "6 kHz 위로 30 ms 넘게 일정한 봉우리에 매우 강한 벌점", "6 kHz 뒤 주파수축 상관에
            # 벌점"). 정리 때 구현이 지워지고 무게 30 만 남아 아무 일도 안 했다 — 성대 세대에서 가로줄이 되살아난 까닭 하나 (§52.515).
            _hfdb = self._hf_db(y)
            if HFLINE_W > 0.0:
                v = self.hfline_loss(y, _hfdb)
                if HFLINE_REF > 0.0:
                    v = self._soft_over(v - HFLINE_REF * self._hf_ref("line", self.hfline_loss), 0.002)
                add("hfline", HFLINE_W, v)
            if HFCOMB_W > 0.0:
                v = self.hfcomb_loss(y, _hfdb)
                if HFCOMB_REF > 0.0:
                    v = self._soft_over(v - HFCOMB_REF * self._hf_ref("comb", self.hfcomb_loss), 0.002)
                add("hfcomb", HFCOMB_W, v)
        if VOICING_W > 0.0 and getattr(self, "_voicing", None) is not None:
            add("voicing", VOICING_W, self._voicing)
        if PITCH_W > 0.0 and getattr(self, "_pitch", None) is not None:
            add("pitch", PITCH_W, self._pitch)
        if PTH_W > 0.0 and PTH_MAP is not None and getattr(self, "_last_ctrl", None) is not None:
            add("pth", PTH_W, self.pth_loss(self._last_ctrl))
        if TRANS_W > 0.0:
            add("trans", TRANS_W * getattr(self, "_trans_ramp", 1.0), self.transient_loss(y))
        if MPRIOR_W > 0.0:
            add("mprior", MPRIOR_W, self.mprior_loss(self._last_ctrl))
        if ADD_PRIOR_W > 0.0:
            add("aprior", ADD_PRIOR_W, self.add_prior_loss(self._last_ctrl))
        if SIB_PRIOR_W > 0.0:
            add("sprior", SIB_PRIOR_W, self.sib_prior_loss(self._last_ctrl))
        if PSUB_PRIOR_W > 0.0:
            add("pprior", PSUB_PRIOR_W, self.psub_prior_loss(self._last_ctrl))
        if GA_W > 0.0 and GA_REF is not None and getattr(self, "_last_ga", None) is not None:
            add("ga", GA_W, self.ga_loss(self._last_ga))
        if VF_ANAT_W > 0.0 and VF_STATIC_FIT and getattr(self.eng, "td", None) is not None and hasattr(self.eng.td, "log_vf_len"):
            add("vfanat", VF_ANAT_W, self.vf_anat_loss())
        if VF_NS_ANAT_W > 0.0 and getattr(self.eng, "td", None) is not None and hasattr(self.eng.td, "log_ns_len")                 and __import__("formant_ml.engine.voice_td", fromlist=["x"]).VF_NS:
            add("nsanat", VF_NS_ANAT_W, self.vf_ns_anat_loss())
        if ART_CONS_W > 0.0 and ART_SEGMENTS is not None:
            add("acons", ART_CONS_W, self.art_cons_loss(self._last_ctrl))
        if FORMANT_PRIOR_W > 0.0 and getattr(self, "_last_ctrl", None) is not None and _voice_mod.TD_TUBE:
            add("fprior", FORMANT_PRIOR_W, self.formant_prior_loss(self._last_ctrl))
        if SHIM_PRIOR_W > 0.0 and getattr(self, "_last_ctrl", None) is not None:
            add("vprior", SHIM_PRIOR_W, self.shimmer_prior_loss(self._last_ctrl))
        if SRC_MOVE_W > 0.0 and getattr(self, "_last_ctrl", None) is not None:
            add("smove", SRC_MOVE_W, self.src_move_loss(self._last_ctrl))
        if RELEASE_PRIOR_W > 0.0 and getattr(self, "rel_log_r", None) is not None:
            add("rprior", RELEASE_PRIOR_W, self.release_prior_loss())
        if self.lam_l1 > 0:
            # 희소한 제어열 — √(w²+δ²)−δ (0 에서 미분 가능).
            d = self.w * self.scale
            dl = 0.1 * self.scale
            l = l + self.lam_l1 * (torch.sqrt(d * d + dl * dl) - dl).mean()
        if BOUND_W > 0.0:
            over = self._soft_over(self._u().abs() - BOUND_U, 0.3)
            l = l + BOUND_W * (over * over).mean()
        if MOTION and MOTION_L2 > 0.0:
            layers = [self.w] + list(self.w_coarse)
            base = min(float(q.shape[0]) for q in layers)
            for q in layers:
                l = l + MOTION_L2 * (float(q.shape[0]) / base) * (q * q).mean()
        if self.lam_smooth > 0:
            sm = sum(((q[1:] - q[:-1]) ** 2).mean()
                     for q in ([self.w] + list(self.w_coarse)) if q.shape[0] > 1)
            if torch.is_tensor(sm):
                add("smooth", self.lam_smooth, sm)
        if self.lam_prior > 0:
            d = (self._u() - self.u0) * self.prior_w * self.prior_mask
            add("prior", self.lam_prior, (d * d).mean())
        if T is not None:
            self._terms = T
        return l + self.penalty(), sc, env_sc, per

    def _backward(self, l: torch.Tensor) -> None:
        l.backward()

    def balance(self, params=None, verbose: bool = False) -> None:
        """항마다 기울기 규범을 재서 유효 가중을 맞춘다 (`BALANCE` 주석 참조).

        **눈금은 한 번만 맞추고 굳힌다.** 처음에는 단계마다 다시 쟀는데, 그러면 이미
        만족된 항은 기울기가 0 에 가까워져 가중이 무한히 커진다 — 실측(`out/L16`)에서
        `smooth` 가 4.81 → 18.3 → 52.7 → **219** 로 폭증해 제어열을 얼렸고(포락
        88.6 → 80.3), 반대로 `corr` 는 1.07 → **0.05** 로 사실상 꺼져 끊김이
        21 → 47 로 돌아왔다. 다중 해상도는 층마다 0 에서 새로 시작하므로 매끄러움
        항의 기울기가 특히 작아 이 병이 크게 드러났다. 목적은 **단위를 맞추는 것**
        이지 진척을 똑같이 만드는 것(GradNorm 원형)이 아니다.

        그래서 각 항은 **처음 기울기가 잡힌 단계에서 한 번** 재고 그 뒤로 굳힌다.
        `phase` 처럼 뒤 단계에서 처음 나타나는 항만 그때 잰다. 전역 스칼라 단계(1 단계,
        `w` 가 최적화 대상이 아니다)에서는 균형하지 않는다.
        """
        if not BALANCE:
            self._bal = {}
            return
        ps = [q for q in (params or self.opt_params()) if q.requires_grad]
        if not any(q is self.w for q in ps):
            return
        self._collect = True
        try:
            self.loss()
            T = dict(self._terms)
        finally:
            self._collect = False

        def gnorm(t):
            # 이 단계가 최적화하지 않는 파라미터에만 걸린 항(예: 1 단계의 prior·smooth 는
            # `w` 에만 걸린다)은 기울기가 비어 있다 — 0 으로 두고 균형에서 뺀다.
            g = torch.autograd.grad(t, ps, retain_graph=True, allow_unused=True)
            s2 = [(x * x).sum() for x in g if x is not None]
            return float(torch.sqrt(torch.stack(s2).sum())) if s2 else 0.0

        missing = [k for k, t in T.items()
                   if k != "env" and k not in self._bal and BAL_W.get(k, 0.0) > 0.0
                   and k not in BAL_FIXED
                   and torch.is_tensor(t) and t.requires_grad]
        if not missing:
            return
        g_env = gnorm(T["env"])
        if not (g_env > 0.0):
            return
        out, capped = [], []
        for k in missing:
            if k in BAL_PRESET:
                self._bal[k] = float(BAL_PRESET[k])
                out.append(f"{k} {self._bal[k]:.3g}(고정)")
                continue
            t = T[k]
            gk = gnorm(t)
            if gk > 0.0 and BAL_W.get(k, 0.0) > 0.0:
                w = BAL_W[k] * g_env / gk
                if BAL_MAX > 0.0 and w > BAL_MAX * BAL_W[k]:
                    capped.append(f"{k} {w:.3g}->{BAL_MAX * BAL_W[k]:.3g}")
                    w = BAL_MAX * BAL_W[k]
                self._bal[k] = w
                out.append(f"{k} {self._bal[k]:.3g}")
        if verbose:
            print("      균형 가중: " + ", ".join(out), flush=True)
            if capped:
                print("      균형 상한에 걸림: " + ", ".join(capped), flush=True)

    # ------------------------------------------------------------- 적합
    def fit(self, iters: int = 200, lr: float = 0.05, log_every: int = 25,
            verbose: bool = True, params: list | None = None,
            sizes: tuple[int, ...] | None = None,
            patience: int = 0, tol: float = 3e-4,
            ramp: tuple | None = None) -> FitReport:
        """`patience` 회 동안 손실이 `tol`(상대) 만큼도 안 줄면 멈춘다.

        **코퍼스 규모로 가려면 수렴 판정이 필요하다.** 지금까지는 고정 반복 뒤 최저손실
        스냅샷을 취할 뿐이라 이미 수렴한 구간에서도 예산을 다 썼다 (docs/HANDOFF.md §5:
        "구간당 5 -> 25 분이 됐다"). 45 분 코퍼스를 200 ms 구간으로 쪼개면 수천 개다.

        `patience=0` 이면 끈다 — 예전 거동 그대로다. 코사인 스케줄러가 lr 을 줄이는
        중이므로 문턱을 너무 크게 잡으면 아직 내려갈 수 있는데 멈춘다. 3e-4 는 실측에서
        마지막 20 % 구간의 회차당 개선폭보다 작다.
        """
        if sizes is not None:
            self.sizes = list(sizes)
        if iters < 0:
            raise ValueError("iters must be nonnegative")
        self._project_ns_bounds(verbose=verbose)
        if FREEZE_CONTROLS and iters > 0:
            params = self._hc_leaves()
            if not params:
                iters = 0                  # 보정이 없으면 움직일 것이 없다
        if iters == 0:
            with torch.no_grad():
                loss, sc, env_sc, per = self.loss()
            return FitReport(float(100.0 * (1.0 - env_sc)), float(100.0 * (1.0 - sc)),
                             self._last_db, per, float(loss), 0, [],
                             dict(getattr(self, "_env_bands", {})))
        # **목적함수를 계단으로 바꾸지 않는다** (연속변형 / graduated non-convexity).
        # 위상 단계는 `phase_weight` 를 0 에서 3.0 으로 한 번에 올려 왔고, 그래서 §27 이
        # 적은 대로 **항상 한 번 꺾였다가 회복**한다 — 200 회로는 회복을 못 끝내
        # 기준선이 ±4 점 흔들린다(§46.1). 매끄럽게 켜면 해를 따라가며 변형하게 된다.
        # `ramp = (목표가중, 올리는 회차)`.
        if BALANCE:
            self.balance(None if FREEZE_CONTROLS else params, verbose)
        opt = torch.optim.Adam(params or self.opt_params(), lr=lr)
        cyc_T = 0
        if SCHED == "sgdr" and iters >= 2 * SGDR_CYCLES:
            cyc_T = max(1, iters // SGDR_CYCLES)

            def _lam(i, T=cyc_T, n=iters):
                c = min(i // T, SGDR_CYCLES - 1)          # 나머지 회차는 마지막 주기에 붙인다
                t = i - c * T
                Tc = T if c < SGDR_CYCLES - 1 else max(n - c * T, 1)
                peak = SGDR_DECAY ** c
                return 0.05 + (peak - 0.05) * 0.5 * (1.0 + math.cos(math.pi * min(t, Tc) / Tc))
            sch = torch.optim.lr_scheduler.LambdaLR(opt, _lam)
        else:
            sch = torch.optim.lr_scheduler.CosineAnnealingLR(opt, max(iters, 1), eta_min=lr * 0.05)
        eta_min = lr * 0.05              # 상향 뒤 코사인을 다시 짤 때 같은 바닥으로 식힌다
        best = (-1e18, None, None, None)
        hist: list[tuple[float, float]] = []
        bad_grads = 0
        stall = 0
        bump_stall, bumps = 0, 0        # 정체 감지 -> lr 상향 (`LR_BUMP_MAX`)
        env_at_bump = None              # 직전 상향 시점의 포락 — 효과 없으면 멈춘다
        bump_done = False
        self._lr_bumps = 0               # 진단·시험이 읽는다
        lr_pre_bump = None               # 첫 상향 직전의 lr — 상향이 헛돌면 여기로 돌아온다 (§52.473)
        # 보정만 적합하는 판(`FREEZE_CONTROLS`)은 lr 을 올리지 않는다 — 제어열의 평탄한 곳을 빠져나오라고 둔 장치인데, 보정 계수 5 만 개에서는
        # 한 번에 발산했다 (W18b 2.1 단계: 포락 78 → 17 → 9 %, 회복하며 4~9 kHz 에 +20~38 dB 가 남았다).
        bump_on = LR_BUMP_MAX > 0 and not FREEZE_CONTROLS
        seed0 = self.eng.cfg.seed
        ema = None
        budget = int(iters)              # lr 상향 때마다 `LR_BUMP_EXTRA` 만큼 늘어난다
        nf_retry = 0                     # 비유한 손실에서 되돌린 횟수 (`NONFINITE_RETRY`)
        it = -1
        while True:
            it += 1
            if it >= budget:
                break
            if VF_CYCLE_LOCK > 0 and VF_LOCK_EVERY > 0 and it > 0 and it % VF_LOCK_EVERY == 0:
                # 단계 안에서도 주기 시각을 다시 맞춘다 — 제어가 바뀌면 성대 주기가 표류해 시각에 민감한 포락이 출렁였다 (§52.491)
                with torch.no_grad():
                    self.vf_cycle_lock(iters=VF_LOCK_REFRESH, verbose=False)
            if RESEED:
                self._reseed_n = getattr(self, "_reseed_n", 0) + 1
                self.eng.cfg.seed = 1000 + self._reseed_n
            if ramp is not None:
                # **가중을 직접 바꾸지 말고 배율로 건다.** `--balance` 는 위상 가중을
                # 굳힌 값(`_bal["phase"]`)으로 덮어쓰므로, `phase_weight` 를 바꾸면 램프가
                # 조용히 무시된다 — 실측(`out/L20`)이 `out/L18` 과 0 회차 손실부터 소수점까지
                # 같았다. 배율은 균형 여부와 상관없이 최종 가중에 곱해진다.
                tgt, ri = ramp
                self.phase_weight = float(tgt)
                self._phase_ramp = min(1.0, (it + 1) / max(int(ri), 1))
                ramping = self._phase_ramp < 1.0
            else:
                self._phase_ramp = 1.0
                ramping = False
            self._trans_ramp = min(1.0, (it + 1) / TRANS_RAMP) if TRANS_RAMP > 0 else 1.0
            if cyc_T and it > 0 and it % cyc_T == 0 and it // cyc_T < SGDR_CYCLES:
                stall = 0             # 재시동 직후의 오르막은 정체가 아니다
                if verbose:
                    print(f"    [{it:4d}] 웜 리스타트 (lr ×{SGDR_DECAY ** (it // cyc_T):.2f})",
                          flush=True)
            opt.zero_grad(set_to_none=True)
            l, sc, env_sc, per = self.loss()
            if it == 0 and os.environ.get("GRADCHECK") and torch.isfinite(l):
                self._gradcheck(params or self.opt_params(), l)
            if not torch.isfinite(l):
                # **비유한이면 단계를 버리지 않고 최선으로 되돌려 걸음을 줄인다** (§52.478). 예전엔 단계를 끝냈고, 다음 단계도 같은 자리에서
                # 곧바로 다시 비유한이 나 전체 발화 적합(F_td1)이 2.1 단계 133 회에서 멈춘 채 끝났다.
                nf_retry += 1
                if best[1] is None or nf_retry > NONFINITE_RETRY:
                    if verbose:
                        print(f"    [{it}] 손실 비유한 — 중단")
                    break
                if NONFINITE_DUMP and nf_retry == 1:
                    with torch.no_grad():
                        np.save(NONFINITE_DUMP, self.control()[0].detach().cpu().numpy())
                self._restore(best[1])
                opt.state.clear()
                for g in opt.param_groups:
                    g["lr"] = g["lr"] * 0.5
                if hasattr(sch, "base_lrs"):
                    sch.base_lrs = [b_ * 0.5 for b_ in sch.base_lrs]
                if verbose:
                    print(f"    [{it}] 손실 비유한 — 최선 상태로 되돌리고 lr 반으로 ({nf_retry}/{NONFINITE_RETRY})", flush=True)
                continue
            env = float(100.0 * (1.0 - env_sc.detach()))
            fine = float(100.0 * (1.0 - sc.detach()))
            hist.append((env, fine))
            # **파라미터 사본은 걸음을 딛기 전에 뜬다.** step() 뒤에 뜨면 n 회차의 손실과
            # n+1 회차의 파라미터가 짝지어져, 복원해도 그 손실이 안 나온다(실측: 최선
            # 1.3185 로 기록해 놓고 복원하니 1.4828).
            score = -float(l.detach())
            if RESEED:
                # 잡음 실현마다 손실이 흔들린다 — 운 좋은 씨앗을 최선으로 뽑지 않게 평균한다.
                ema = -score if ema is None else (1 - RESEED_EMA) * ema + RESEED_EMA * (-score)
                score = -ema
            # 스냅샷은 조금이라도 나아지면 뜬다. 멈춤 판정만 **의미 있는** 개선을 센다.
            gain = score - best[0]
            # **램프 중에는 최선 상태를 뜨지 않는다.** 가중이 회차마다 다르니 손실끼리
            # 비교가 성립하지 않는다 — 초반의 작은 위상 가중에서 손실이 낮게 계산되어
            # 위상 단계 시작 상태가 "최선" 으로 뽑히고 단계 전체가 헛돈다.
            if ramping:
                gain = 0.0
            elif score > best[0]:
                best = (score, self._snapshot(), None,
                        (env, fine, self._last_db, float(l.detach()), per))
            # **정체하면 lr 을 올린다** (`LR_BUMP_MAX` 참조). `patience` 의 조기 종료와 달리 멈추지 않고 탈출시킨다.
            if not ramping and bump_on:
                bump_stall = 0 if gain > LR_BUMP_TOL * abs(score) else bump_stall + 1
                # **단계 최선값도 문턱 아래여야 한다** (MEASUREMENTS §52.185). 격자를 갈아 끼운 직후에는
                # 포락이 잠깐 내려간다 — 실측 `hnr35` 2.3 단계: [0] 91.74 → [25] 89.47 에서 현재값만 보고
                # 올렸고, 그 상향이 포락을 −5.10 점 떨어뜨렸다. 그건 "낮게 수렴" 이 아니라 교체 과도다.
                best_env = best[3][0] if best[3] is not None else env
                if (bump_stall >= LR_BUMP_PATIENCE and bumps < LR_BUMP_MAX
                        and it >= LR_BUMP_WARMUP
                        and max(env, best_env) < LR_BUMP_ENV and not bump_done):
                    if env_at_bump is not None and env - env_at_bump < LR_BUMP_MIN_GAIN:
                        bump_done = True          # 직전 상향이 헛돌았다 — 이 단계에서는 그만
                        if verbose:
                            print(f"    [{it:4d}] 직전 상향이 포락을 {env - env_at_bump:+.2f} 점밖에 "
                                  f"못 올렸다 — 상향 중단 (구조적 한계로 본다)", flush=True)
                        # **헛돈 상향의 자리를 버린다** (MEASUREMENTS §52.473). 예전에는 여기서 그냥 이어 갔다 — 올린 lr(×2, ×4) 그대로,
                        # 망가진 자리에서. W18b 는 그 자리에서 회복하며 에너지 가중 손실이 싸게 보는 4~9 kHz 에 +20~38 dB 를 남긴 채 끝났다.
                        # 최선으로 되돌리고, Adam 의 모멘트(발산한 걸음의 기억)를 비우고, lr 을 첫 상향 전 값에서 남은 예산 위에 다시 식힌다.
                        if best[1] is not None and score < best[0]:
                            self._restore(best[1])
                        opt.state.clear()
                        if lr_pre_bump is not None:
                            for g, v in zip(opt.param_groups, lr_pre_bump):
                                g["lr"] = v
                                g["initial_lr"] = v
                            if isinstance(sch, torch.optim.lr_scheduler.CosineAnnealingLR):
                                sch = torch.optim.lr_scheduler.CosineAnnealingLR(
                                    opt, max(budget - it - 1, 1), eta_min=eta_min)
                            elif hasattr(sch, "base_lrs"):
                                sch.base_lrs = list(lr_pre_bump)
                        if verbose:
                            print(f"    [{it:4d}] 최선 상태(손실 {-best[0]:.4f})로 되돌리고 lr 을 상향 전 "
                                  f"{lr_pre_bump[0] if lr_pre_bump else float('nan'):.4g} 로 — Adam 모멘트 비움", flush=True)
                        continue
                    if lr_pre_bump is None:
                        lr_pre_bump = [float(g["lr"]) for g in opt.param_groups]
                    env_at_bump = env
                    # **최선 지점으로 되돌린 뒤 올린다** (MEASUREMENTS §52.136). 상향 전에
                    # 이미 최선에서 멀어져 있으면, 올린 lr 이 그 나쁜 자리에서 더 멀리 간다 —
                    # 실측(`out/M/SYL/ctl`): 72.4 % 에서 세 번 올린 뒤 39.5 % 로 발산해
                    # 연장 예산 260 회를 통째로 버렸다. 스냅샷이 결과는 지켜 주지만 **예산은
                    # 못 지킨다.** 최선에서 출발하면 "정체하면 더 크게 걷는다" 가 제 뜻대로 된다.
                    if best[1] is not None and score < best[0]:
                        self._restore(best[1])
                        if verbose:
                            print(f"    [{it:4d}] 상향 전 최선 상태로 복귀 "
                                  f"(손실 {-score:.4f} -> {-best[0]:.4f})", flush=True)
                    for g in opt.param_groups:
                        g["lr"] = float(g["lr"]) * LR_BUMP_FACTOR
                    bumps += 1
                    self._lr_bumps = bumps
                    budget = min(budget + LR_BUMP_EXTRA, int(iters) + LR_BUMP_MAX * LR_BUMP_EXTRA)
                    if BUMP_RESCHED and isinstance(sch, torch.optim.lr_scheduler.CosineAnnealingLR):
                        # **코사인을 남은 예산 위에 다시 짠다** (MEASUREMENTS §52.256). 예전에는 기준값만 두 배로
                        # 올리고 원래 주기(`iters`)를 그대로 돌렸다. 코사인은 `T_max` 를 지나면 **다시 올라간다** —
                        # 연장 120×3 회 동안 lr 이 바닥에서 되올라 600 회째에 처음의 8 배가 됐고, 올린 모든 단계가
                        # 400 회 뒤에 무너졌다(실측 fin2 2.2: 350 회 89.29 → 600 회 37.34 %). 올린 lr 에서 출발해
                        # 연장 끝에 같은 바닥에 닿게 하면 "정체하면 크게 걷고 다시 식힌다" 가 제 뜻대로 된다.
                        for g in opt.param_groups:
                            g["initial_lr"] = g["lr"]
                        sch = torch.optim.lr_scheduler.CosineAnnealingLR(
                            opt, max(budget - it - 1, 1), eta_min=eta_min)
                    elif hasattr(sch, "base_lrs"):  # sgdr: 람다가 끝에서 멈추므로 기준값만 올린다
                        sch.base_lrs = [b * LR_BUMP_FACTOR for b in sch.base_lrs]
                    bump_stall = 0
                    stall = 0
                    if verbose:
                        print(f"    [{it:4d}] 정체 {LR_BUMP_PATIENCE} 회 · 포락 {env:.2f}% < "
                              f"{LR_BUMP_ENV:g}% -> lr ×{LR_BUMP_FACTOR:g} ({bumps}/{LR_BUMP_MAX}), "
                              f"{LR_BUMP_EXTRA} 회 연장 (예산 {budget})",
                              flush=True)
                    # **되돌린 회차는 걸음을 딛지 않는다.** 위의 `_restore` 가 파라미터를 제자리에서 바꾸므로
                    # 지금 손에 든 그래프(`l`)는 **바뀌기 전** 값으로 지어진 것이다. 그대로 backward 하면
                    # 낡은 기울기를 새 상태에 적용하는 셈이고, 실제로 autograd 가 "inplace 로 바뀌었다" 며
                    # 죽는다(주기별 배음 보정을 켜자 드러났다 — 그전에는 조용히 틀린 걸음이었다).
                    continue
            stall_before = stall          # 증가 **전** 값 — 건너뛴 회차에 되돌린다
            if patience > 0 and not ramping:     # 램프 중의 "정체" 는 수렴의 증거가 아니다
                stall = 0 if gain > tol * abs(score) else stall + 1
                if stall >= patience:
                    if verbose:
                        print(f"    [{it}] 수렴 ({patience} 회 정체) — 조기 종료")
                    break
            self._backward(l)
            ps = self.opt_params()
            # **비유한 기울기로 걸음을 딛으면 안 된다.** Adam 의 모멘트가 NaN 으로
            # 오염되면 그 뒤 모든 파라미터가 NaN 이 되고, 손실을 보기 전에 엔진 안에서
            # 터진다(실측: 탄음 구간에서 int(NaN)).
            if any(p.grad is not None and not torch.isfinite(p.grad).all() for p in ps):
                bad_grads += 1
                if DEBUG_NONFINITE:
                    self._report_nonfinite(it, ps, ["w", "d", "log_gain", "pulse_phi0"]
                                           + ["hf%d" % i for i in range(len(self.hf))])
                # **건너뛰지 말고 성분만 지운다.** 예전에는 회차 전체를 버렸는데,
                # 그러면 파라미터가 안 변하므로 **다음 회차도 똑같이 비유한**이다.
                # 결정적으로 갇힌다 — 실측(out/sw/r000, yang_00000040 전체):
                # 모든 단계가 "[30] 수렴 + 비유한 29 회 건너뜀" 으로 끝났다. 즉
                # 단계당 실제 걸음이 **1 번**뿐이었고 포락이 82.7 % 에 머물렀다
                # (같은 파일의 정상 적합은 93.1 %).
                #
                # 비유한 성분을 0 으로 두면 나머지 성분으로 걸음을 딛으므로 상태가
                # 바뀌고, 다음 회차에는 그 자리를 벗어난다. Adam 의 모멘트도
                # 오염되지 않는다 (0 은 유한하다).
                for p in ps:
                    if p.grad is not None:
                        torch.nan_to_num_(p.grad, nan=0.0, posinf=0.0, neginf=0.0)
                # 정체 계수는 되돌린다 — 기울기 일부를 버린 회차의 정체는 수렴의
                # 증거가 아니다 (§27: 위상 단계가 골짜기 한복판에서 멈췄다).
                stall = stall_before
            torch.nn.utils.clip_grad_norm_(ps, 5.0)
            opt.step()
            self._project_ns_bounds()
            sch.step()
            if verbose and (it % log_every == 0 or it == iters - 1):
                print(f"    [{it:4d}] 포락 {env:6.2f}%  정밀 {fine:6.2f}%  "
                      f"오차 {self._last_db:5.2f} dB  펄스 {self._last_pulse:.3f}  "
                      + (f"주기상관 {self._last_fastcorr:+.3f}  "
                         if getattr(self, "_last_fastcorr", None) is not None else "")
                      # 새 항들의 **값 자체**(활성화 정도)를 찍는다 — 찍히지 않으면 켜졌는지 알 수 없다 (§52.188)
                      + "".join(f"{nm} {getattr(self, a):.3f}  " for nm, a in
                                (("사이", "_last_ih"), ("선폭", "_last_ihline"),
                                 ("공진식", "_last_hres"), ("협화", "_last_cons_val"),
                                 ("줄무늬", "_last_vstripe"), ("고역협화", "_last_cons_hf"),
                                 ("주기포락", "_last_pcyc"), ("동기위상", "_last_phsync"),
                                 ("고정위상", "_last_phfix"), ("칸별dB", "_last_logbin"), ("결맞음", "_last_hcoh"),
                                 ("늦게죽음", "_last_pcycup"), ("무음넘침", "_last_quiet"), ("꼬리결손", "_last_tail"), ("튐ms", "_last_trans"))
                                if getattr(self, a, None) is not None)
                      + ("".join(f"초과{k[:3]} {v * 100:.2f}%  " for k, v in self._last_mprior.items())
                         if getattr(self, "_last_mprior", None) else "")
                      + (f"내전사전밖 {self._last_aprior * 100:.1f}%  " if getattr(self, "_last_aprior", None) is not None else "")
                      + ("".join(f"요동{k[:4]} {v * 100:.1f}%  " for k, v in self._last_srcmove.items())
                         if getattr(self, "_last_srcmove", None) else "")
                      + (f"치찰협착 {self._last_sprior:.3f}cm²  " if getattr(self, "_last_sprior", None) is not None else "")
                      + (f"MVF {self._last_mvf:.0f}Hz  " if getattr(self, "_last_mvf", None) is not None else "")
                      + ("개방 " + "/".join(f"{v:.0f}" for v in torch.exp(self.rel_log_r).tolist()) + "cm²/s  "
                         if getattr(self, "rel_log_r", None) is not None else "")
                      + (f"보이스바 {20 * float(self.vb_log_g) / math.log(10):+.1f}dB  " if VOICE_BAR else "")
                      + (f"잔향 RT {self._last_rv[0] * 1000:.0f}ms {self._last_rv[1]:+.1f}dB  "
                         if (LATE_REVERB and getattr(self, "_last_rv", None)) else "")
                      + f"손실 {float(l.detach()):.4f}", flush=True)
        self.eng.cfg.seed = seed0
        if verbose and bad_grads:
            print(f"    (기울기 비유한 {bad_grads} 회 건너뜀)")
        if best[1] is not None:
            self._restore(best[1])
            env, fine, db, lv, per = best[3]
        else:
            env = fine = db = lv = float("nan"); per = {}
        return FitReport(env, fine, db, per, lv, len(hist), hist,
                         dict(getattr(self, "_env_bands", {})))

    @property
    def hcorr(self):
        """(2, K, C). `HCORR_RANK` > 0 이면 **인수의 곱**이라 잎이 아니다."""
        if getattr(self, "_hc_u", None) is None:
            return getattr(self, "_hcorr_raw", None)
        return torch.einsum("akr,arc->akc", self._hc_u, self._hc_v)

    @hcorr.setter
    def hcorr(self, v):
        self._hcorr_raw = v

    def opt_params(self) -> list:
        """최적화 대상 전부. **한 군데서만 정의한다** — 예전에는 이 목록이 네 곳에
        따로 적혀 있었고(옵티마이저·기울기 가드·스냅샷·최선 복원) 그래서 고역
        파라미터를 어디에도 못 넣은 채로 남았다."""
        if getattr(self, "_hf_focus", False):
            return list(self.hf) or [self.log_gain]     # 고역 단계: 전역 손잡이만
        self._ensure_room()
        out = ([self.w] + list(self.w_coarse)
               + [self.d, self.log_gain, self.pulse_phi0] + self.hf)
        if LATE_REVERB and not LR_FIXED:
            out.extend([self.rv_log_rt, self.rv_g_db])
        if ROOM_FIR_MS > 0.0 and getattr(self, "room_theta", None) is not None:
            out.append(self.room_theta)
        if VOICE_BAR and not VB_FIXED:
            out.append(self.vb_log_g)
        if getattr(self, "_hc_u", None) is not None:
            out.extend([self._hc_u, self._hc_v])       # 저차원 인수가 잎이다
        elif getattr(self, "hcorr", None) is not None:
            out.append(self.hcorr)
        if getattr(self, "w_ev", None) is not None:
            out.append(self.w_ev)
        if getattr(self, "tr_gain", None) is not None:
            out.append(self.tr_gain)
        if getattr(self, "rel_log_r", None) is not None:
            out.append(self.rel_log_r)
        if ART_SEGMENTS is not None and ART_TARGETS:
            self._art_setup()
            out.extend([self.art_z, self.art_d])
        return out

    # ------------------------------------------------------------------ 음소 목표 조음 (§52.487)
    def _art_setup(self) -> None:
        """음소 목표·경계 잎 텐서를 만든다 (한 번). 목표 초기값: 자음은 W02 MRI 자세, 모음은 제어열(코드북 역산)의 그 구간 중앙값."""
        if getattr(self, "art_z", None) is not None:
            return
        from .articulation import W02_FIT, W02_SHAPES
        z = np.load(W02_SHAPES, allow_pickle=True)
        pn = list(z["param_names"]); shapes = {str(n): s for n, s in zip(z["names"], z["shapes"])}
        from . import voice_td as _vtdx
        self._art_names = ([f"vtl_{n}" for n in W02_FIT] + (["velum"] if ART_VELUM else [])
                           + (["ff_add"] if _vtdx.LARYNX else []) + (["adduction"] if ART_LARYNX else []))
        self._art_idx = [INDEX[n] for n in self._art_names]
        ne = np.array([PARAMS[n].default for n in self._art_names]); sp = np.array([PARAMS[n].hi - PARAMS[n].lo for n in self._art_names])
        self._art_ne, self._art_sp = ne, sp
        fm = float(self.track.frame_ms) / 1000.0
        vals = np.asarray(self.track.values)[:, self._art_idx]
        Z, B = [], []
        for k, (t0, t1, shp) in enumerate(ART_SEGMENTS):
            a, b = int(round(t0 / fm)), max(int(round(t0 / fm)) + 1, int(round(t1 / fm)))
            med = np.median(vals[a:min(b, len(vals))], 0) if b > a and a < len(vals) else ne
            if not ART_INIT_FROM_TRACK and shp is not None and shp in shapes and "(" in shp:   # 자음 — MRI 자세
                x = med.copy()                                  # 조음기 밖 열(내전 등)은 제어열 중앙값
                x[:len(W02_FIT)] = [shapes[shp][pn.index(n)] for n in W02_FIT]
                if ART_VELUM:
                    x[self._art_names.index("velum")] = 0.0
                if _vtdx.LARYNX:
                    x[self._art_names.index("ff_add")] = 0.0
            else:                                                           # 모음·쉼 — 역산 궤적의 중앙값
                x = med.copy()
            if _vtdx.LARYNX and not ART_INIT_FROM_TRACK:           # 된소리(ㄲ ㄸ ㅃ ㅆ ㅉ, MFA 기호의 ͈)는 가성대를 좁혀 출발
                labf = str(ART_LABELS[k]) if ART_LABELS is not None else ""
                fi = self._art_names.index("ff_add")
                x[fi] =FF_TENSE_INIT if "\u0348" in labf else (med[fi] if (shp is None or "(" not in shp) else 0.0)
            if ART_VELUM and not ART_INIT_FROM_TRACK:
                vi = self._art_names.index("velum")
                lab = str(ART_LABELS[k]).replace("ː", "") if ART_LABELS is not None else ""
                if lab in NASAL_LABELS:
                    x[vi] = ART_VELUM_NASAL
                elif shp is not None and "(" in shp:
                    x[vi] = 0.0
                else:
                    x[vi] = med[vi]
            Z.append((x - ne) / sp)
            if k:
                B.append(t0)
        dev = self.w.device
        self.art_z = torch.as_tensor(np.array(Z), dtype=torch.float64, device=dev).requires_grad_(True)
        self.art_d = torch.zeros(len(B), dtype=torch.float64, device=dev, requires_grad=True)
        self._art_b0 = torch.as_tensor(np.array(B), dtype=torch.float64, device=dev)
        self._art_t = torch.arange(self.n_frames, dtype=torch.float64, device=dev) * fm + 0.5 * fm
        taus = [float(PARAM_TAU_PHYS.get(n, TARGET_TAU_DEFAULT)) for n in self._art_names]
        ks = []
        for tau in taus:
            s_ = tau / (fm * 1000.0)
            L = max(3, int(math.ceil(7.0 * s_)))
            tt = torch.arange(L, dtype=torch.float64, device=dev)
            h = tt * tt * torch.exp(-tt / s_)
            ks.append((h / h.sum()).flip(0))
        Lmax = max(k.shape[0] for k in ks)
        self._art_ker = torch.stack([torch.nn.functional.pad(k, (Lmax - k.shape[0], 0)) for k in ks]).unsqueeze(1)   # (C,1,L)
        print(f"  음소 목표 조음: 구간 {len(Z)} · 조음기 {len(self._art_names)} · 경계 ±{ART_BND_MS:g} ms · 시상수 "
              + ", ".join(f"{n[4:]} {t:g}" for n, t in zip(self._art_names, taus)) + " ms", flush=True)

    def _art_attenuation(self, T: int):
        """원본의 틀별 3–10 kHz 수준 [dB] (5 ms 창, 틀 가운데)과 구간마다의 이웃 모음 기준 (앞뒤 모음 구간 중앙값의 작은 쪽; 없으면 nan)."""
        from scipy.signal import butter, sosfiltfilt
        fm = float(self.track.frame_ms) / 1000.0
        sr = self.hop / fm
        x = self.target[0].detach().cpu().double().numpy()
        w = max(1, int(0.005 * sr))
        idx = np.clip((np.arange(T) * fm + 0.5 * fm) * sr, 0, x.size - 1).astype(int)

        def _lev(lo, hi):
            b = sosfiltfilt(butter(4, [lo, min(hi, 0.45 * sr)], "bp", fs=sr, output="sos"), x)
            return 10.0 * np.log10(np.convolve(b * b, np.ones(w) / w, "same")[idx] + 1e-14)

        def _refs(e):
            out = []
            for k in range(len(ART_SEGMENTS)):
                vs = []
                for j in (k - 1, k + 1):
                    if 0 <= j < len(ART_SEGMENTS) and ART_SEGMENTS[j][2] is not None and "(" not in ART_SEGMENTS[j][2]:
                        a_, b_ = int(round(ART_SEGMENTS[j][0] / fm)), int(round(ART_SEGMENTS[j][1] / fm))
                        a2, b2 = (a_ + 5, b_ - 5) if b_ - a_ > 14 else (a_, b_)
                        seg = e[max(a2, 0):min(b2, T)]
                        if seg.size:
                            vs.append(float(np.median(seg)))
                out.append(min(vs) if vs else float("nan"))
            return out
        e = _lev(3000.0, 10000.0)
        el = _lev(100.0, 1500.0)
        self._att_lf = (el, _refs(el))                   # 저역 (100–1500 Hz) — 폐쇄는 저역도 꺼진다 (§52.511)
        if 0.45 * sr > 12000.0:                          # 고역 (10–16 kHz) — 비음 웅얼의 고역 감쇠 (§52.533)
            eh = _lev(10000.0, 16000.0)
            self._att_hf = (eh, _refs(eh))
        else:
            self._att_hf = None
        return e, _refs(e)

    def _glot_spec(self, T: int):
        """녹음이 정하는 성문 상태 (§52.509) — 틀마다 (벌림 틀, 모음 틀) 참거짓 (T,). 기준 = 유성 틀 저역(1.5 kHz 아래) 수준의 중앙.
        벌림 = 3–10 kHz 가 기준의 30 dB 안(마찰·기식이 있다)이고 저역이 기준보다 15 dB 넘게 꺼졌다; 모음 = 주기성 > 0.6 이고 저역이 기준의 10 dB 안.
        나머지(폐쇄 무음·쉼·삐걱 목소리)는 자유. **주기성만으로는 못 가른다** — A 의 ㅅ 은 원본 저역 주기성이 0.51–0.68 (앞 모음의 떨림 꼬리·잔향,
        저역 −18 ~ −24 dB)이고, C 는 삐걱 목소리라 주기성 0.7 을 넘는 틀이 없다."""
        fm = float(self.track.frame_ms) / 1000.0
        with torch.no_grad():
            pt, lt = self._voicing_track(self.target)
        pt, lt = pt.cpu().numpy(), lt.cpu().numpy()
        tf = np.arange(pt.size) * 0.005 + 0.010                                   # 20 ms 창의 가운데
        tc = np.arange(T) * fm + 0.5 * fm
        per = np.interp(tc, tf, pt)
        lev = np.interp(tc, tf, lt)
        th = 0.7 if np.sum(pt > 0.7) >= 5 else 0.5
        ref = float(np.median(lt[pt > th])) if np.sum(pt > th) >= 5 else float(np.percentile(lt, 90))
        e, _ = self._art_attenuation(T)
        uv = (e > ref - 30.0) & (lev < ref - 15.0)
        vv = (per > 0.6) & (lev > ref - 10.0)
        return uv, vv

    def art_cons_loss(self, c: torch.Tensor) -> torch.Tensor:
        """자음 목표의 협착 명세 벌점 (`ART_CONS_W`) — 궤적의 구강 최소 면적 (관의 30 % 부터 입술까지, W02 대리 모형)."""
        if getattr(self, "_acons", None) is None:
            fm = float(self.track.frame_ms) / 1000.0
            T = int(c.shape[1])
            kind = np.zeros(T, np.int64)                     # 0 없음, 1 폐쇄, 2 마찰
            place = [None] * T                               # 자리 창 (ART_PLACE)
            att = self._art_attenuation(T) if ART_PLACE else None
            n_ac = 0
            for sk, (t0, t1, shp) in enumerate(ART_SEGMENTS):
                if shp is None or "(" not in shp:
                    continue
                d = t1 - t0
                pw = ART_PLACE_WIN.get(shp.split("-")[1]) if ART_PLACE and shp.count("-") >= 2 else None
                lab = str(ART_LABELS[sk]).replace("ː", "") if ART_LABELS is not None and sk < len(ART_LABELS) else ""
                nasal_ = lab in NASAL_LABELS
                if att is not None and "closure" in shp:
                    # **닫힌 정도는 녹음이 말한다** (§52.507): 폐쇄음·파찰음은 원본의 3–10 kHz 가 이웃 모음보다 `ART_CLOSE_DB` 넘게 꺼진 틀에서만
                    # 폐쇄를, 파찰음은 이웃 모음보다 `ART_FRIC_DB` 넘게 밝은 틀에서 마찰을 명세한다. 038 의 ㅊ(시 뒤, 마찰로 약화)·C ㄱ(모음 사이
                    # 유성 연음, −10 dB)은 닫히지 않았다 — 음운 정의대로 닫으라고 하면 원본이 마찰 봉우리인 곳에 무음을, 유성인 곳에 끊김을 강요한다.
                    # 명세가 없는 틀에도 자리 창(창 밖 열림)은 건다: 어디서 좁히는지는 음운이, 얼마나 좁히는지는 녹음이 정한다.
                    i0, i1 = max(0, int(round(t0 / fm))), min(T, int(round(t1 / fm)))
                    ref = att[1][sk]
                    aff = any(s_ in lab for s_ in ("ɕ", "ʑ", "ts", "dz"))
                    # **폐쇄는 저역도 꺼진다** (§52.511): 고역만 보면 개방 직후 모음 첫머리(고역이 아직 약하다)를 폐쇄로 셌다 — WGB 의 ㄲ 개방이
                    # 원본(0.34 s)보다 45 ms 늦었다. 폐쇄 = 3–10 kHz ≥ `ART_CLOSE_DB` 꺼짐 **그리고** 100–1500 Hz ≥ `ART_CLOSE_LF_DB` 꺼짐.
                    # 비음 바로 뒤는 코로 저역이 계속 나오므로(ㄴ→ㅈ: 고역 −18 ~ −21, 저역 +1 ~ −4 dB) 고역만 본다. A 의 ㄱ 은 저역이 −3 ~ −5 dB 뿐 —
                    # 입으로 떨림이 나오는, 닫히지 않은 약화 [ɣ] 다.
                    el_, rl_ = self._att_lf[0], self._att_lf[1][sk]
                    prev_nas = sk > 0 and ART_LABELS is not None and str(ART_LABELS[sk - 1]).replace("ː", "") in NASAL_LABELS

                    hf_ = getattr(self, "_att_hf", None)
                    rh_ = hf_[1][sk] if hf_ is not None else float("nan")

                    def _is_closed(i):
                        if nasal_:
                            # **비음도 녹음이 정한다** (§52.522): 코로 저역이 나오므로 고역만 — 3–10 kHz 가 이웃 모음보다 `ART_NASAL_CLOSE_DB` 넘게 꺼진 틀.
                            # 038 의 'n'(어느)은 −3 ~ −5, ŋ(청)은 −1 ~ −8 dB 뿐 (저역 그대로) — 빠른 말의 닫히지 않은 비음이다. 고정 규칙(구간 20–60 % 폐쇄)은
                            # 원본에 없는 폐쇄를 강요해 속도 한계 아래에서 앞뒤 모음까지 막았다 (KWA_p3 81.9 → 74.4 %).
                            # **또는 10–16 kHz 가 같은 만큼 꺼진 틀** (§52.533): 038 의 ɲ 은 3–10 kHz 가 −3 (최저 −11) 인데 10–16 kHz 는 −10 (최저 −13) — 비음 웅얼의
                            # 고역 감쇠. 3–10 kHz 만 보아 열어 두었더니 합성의 ɲ 10–16 kHz 가 원본보다 +6 ~ +19 dB (성문 주기로 맥동하는 기식 잡음이 입으로, 포락
                            # 주기성 0.78 · 원본 0.13). n(어느) 은 10–16 kHz 가 +9 라 그대로 열린다.
                            if hf_ is not None and rh_ == rh_ and hf_[0][i] < rh_ - ART_NASAL_CLOSE_DB:
                                return True
                            return att[0][i] < ref - ART_NASAL_CLOSE_DB
                        return att[0][i] < ref - ART_CLOSE_DB and (prev_nas or el_[i] < rl_ - ART_CLOSE_LF_DB)
                    closed_any = any(_is_closed(i) for i in range(i0, i1))
                    # 녹음에서 개방이 일어난 뒤(마지막 폐쇄 틀 + `ART_REL_MS`)는 닫혀 있으면 안 된다 (§52.514) — 자리만 걸었더니 WGB 의 ㄲ 이 폐쇄 명세
                    # (무게 30)에 밀려 접촉점 너머 깊은 목표를 잡고 개방이 원본보다 50 ms 늦었다.
                    last_cl = max((i for i in range(i0, i1) if _is_closed(i)), default=None)
                    rel_from = None if last_cl is None else last_cl + 1 + int(round(ART_REL_MS / (fm * 1000.0)))
                    for i in range(i0, i1):
                        if rel_from is not None and i >= rel_from:
                            kind[i] = 6
                            place[i] = pw
                            n_ac += 1
                            continue
                        if _is_closed(i):
                            kind[i] = 1
                        elif aff and att[0][i] > ref + ART_FRIC_DB:
                            kind[i] = 2
                        else:
                            # 폐쇄가 있는 구간의 나머지 틀은 개방·기식의 전이라 자리만; **구간 어디에도 폐쇄가 없으면** 그 자리에서 열려 있어야 한다
                            # (≥ `ART_OPEN_A`) — WGC 의 모음 사이 ㄱ 이 MRI 폐쇄 목표를 그대로 지녀 떨림이 끊기고(주기성 0.28, 원본 0.50) 개방 파열이
                            # 6–16 kHz 를 +20–28 dB 넘쳤다. 원본은 닫히지 않은 유성 연음이다.
                            kind[i] = 4 if (closed_any or nasal_) else 5          # 닫히지 않은 비음은 자리만 (열림을 강요하지 않는다)
                        place[i] = pw
                        n_ac += 1
                    continue
                if "closure" in shp:
                    a_, b_, k_ = t0 + 0.2 * d, t0 + 0.6 * d, 1
                elif "fricative" in shp:
                    a_, b_, k_ = t0 + 0.2 * d, t1 - 0.2 * d, 2
                else:
                    continue
                i0, i1 = max(0, int(round(a_ / fm))), min(T, int(round(b_ / fm)))
                kind[i0:i1] = k_
                for i in range(i0, i1):
                    place[i] = pw
            if att is not None:
                print(f"  녹음 기준 협착 정도: 폐쇄음·파찰음 틀 {n_ac} 개 중 폐쇄 {int(sum(kind[i] == 1 for i in range(T) if place[i] is not None))} 개 "
                      f"(3–10 kHz 가 이웃 모음 −{ART_CLOSE_DB:g} dB 밑)", flush=True)
            self._aplace, self._aplace_pl = None, (place if ART_PLACE else None)
            uvv = self._glot_spec(T)[0] if (ART_PLACE and ART_LARYNX) else None
            n_dv = 0
            lipthr = np.zeros(T)
            lpr = np.full((T, 2), np.nan)
            for sk, (t0, t1, shp) in (enumerate(ART_SEGMENTS) if ART_VOWEL_A > 0.0 else []):
                # 쉼(shp None)도 모음처럼 관이 열려 있어야 한다 (입술은 뺀다) — 명세가 없어 앞 판 궤적의 중앙값(인두 폐쇄)을 그대로 지녔다 (§52.509)
                if shp is not None and "(" in shp:
                    continue
                if shp is None and not ART_PLACE:
                    continue
                d = t1 - t0
                a_, b_, k_ = t0 + 0.2 * d, t1 - 0.2 * d, 3
                i0, i1 = max(0, int(round(a_ / fm))), min(T, int(round(b_ / fm)))
                kind[i0:i1] = k_
                if shp is not None:
                    labv = str(ART_LABELS[sk]).replace("ː", "") if ART_LABELS is not None and sk < len(ART_LABELS) else ""
                    lipthr[i0:i1] = ART_VOWEL_LIP_A[1] if labv in ROUNDED_LABELS else ART_VOWEL_LIP_A[0]
                    lpr[i0:i1] = ART_VOWEL_LP[1] if labv in ROUNDED_LABELS else ART_VOWEL_LP[0]
                if uvv is not None and shp is not None:
                    # **무성화된 모음** (§52.516): 한국어 고모음은 무성 자음 사이에서 성문이 열린 채 혀가 좁힘을 지녀 마찰로 난다 ('시' 의 i —
                    # 원본 0.38–0.43 s 는 5–16 kHz 가 밝은 마찰). 모음 열림을 걸었더니 BF 는 그 자리 고역이 비었다. 녹음이 벌림(마찰 있음·저역 꺼짐)으로
                    # 본 모음 틀은, 이웃이 마찰음·파찰음이면 그 자리의 마찰 명세를 받는다 — 닫힌 정도는 녹음이 정한다.
                    pw_n = None
                    for j in (sk - 1, sk + 1):
                        if 0 <= j < len(ART_SEGMENTS) and ART_SEGMENTS[j][2] is not None and ART_SEGMENTS[j][2].count("-") >= 2:
                            sj = ART_SEGMENTS[j][2]
                            lj = str(ART_LABELS[j]) if ART_LABELS is not None and j < len(ART_LABELS) else ""
                            if "fricative" in sj or any(s_ in lj for s_ in ("ɕ", "ʑ", "ts", "dz")):
                                pw_n = ART_PLACE_WIN.get(sj.split("-")[1])
                                break
                    if pw_n is not None:
                        j0, j1 = max(0, int(round(t0 / fm))), min(T, int(round(t1 / fm)))
                        for i in range(j0, j1):
                            if uvv[i]:
                                kind[i] = 2
                                place[i] = pw_n
                                n_dv += 1
            if n_dv:
                print(f"  무성화 모음: {n_dv} 틀에 이웃 마찰음 자리의 마찰 명세", flush=True)
                self._aplace_pl = place if ART_PLACE else None
            self._acons = torch.as_tensor(kind, device=c.device)
            self._alip = torch.as_tensor(lipthr, device=c.device)
            self._alpr = torch.as_tensor(lpr, device=c.device)
            print(f"  모음 입술 내밂 범위: {int(np.isfinite(lpr[:, 0]).sum())} 틀 (평순 {ART_VOWEL_LP[0]}, 원순 {ART_VOWEL_LP[1]})", flush=True)
            if lipthr.any():
                print(f"  모음 입술 하한: {int((lipthr > 0).sum())} 틀 (비원순 ≥ {ART_VOWEL_LIP_A[0]:g}, 원순 ≥ {ART_VOWEL_LIP_A[1]:g} cm²)", flush=True)
            print(f"  자음 협착 명세: 폐쇄 틀 {int((kind == 1).sum())} 개 (구강 최소 ≤ {ART_CLOSE_A:g} cm²), 마찰 틀 "
                  f"{int((kind == 2).sum())} 개 ({ART_FRIC_A[0]:g}–{ART_FRIC_A[1]:g} cm²), 모음 틀 {int((kind == 3).sum())} 개 (관 최소 ≥ {ART_VOWEL_A:g})",
                  flush=True)
        kind = self._acons
        if not bool((kind > 0).any()):
            return torch.zeros((), dtype=c.dtype, device=c.device)
        from . import voice_td as _vtd
        tde = getattr(self.eng, "td", None)
        if tde is not None and _vtd.ARTIC == "w02":
            # **관에 실제로 들어가는 모양으로 잰다** (§52.519) — 해부 적응 대리 모형 + 생리 평활 + 속도 제한 (`voice_td._tube_frames`). 예전에는
            # 해부 없는 W02 대리 모형에 평활 전 제어값을 넣어, 명세(무게 300)가 관에 들어가지 않는 모양에 걸렸다: ㄲ 은 손실로는 칸 17 에서
            # 0.0001 cm² 로 닫혔는데 관에서는 연구개 창 최소가 2.04 → 0.069 cm² 로 끝내 안 닫혔고, 첫 'n' 도 관에서는 최소 0.066 cm² 였다.
            dct = {n: c[:, :, INDEX[n]] for n in INDEX}
            A = tde._tube_frames(dct)[0][0]
            if _vtd.W02_ANAT:
                # **값은 관의 면적, 기울기는 부호 있는 면적의 완만한 softplus** (straight-through, §52.522). 값까지 완만한 면적으로 재면 관에서 이미
                # 닫힌(1e-4) 자세가 0.012 cm² 로 보여 "폐쇄 ≤ 0.005" 가 필요 이상으로 깊이 누르라고 요구했다 (KWA_p3 82.2 → 78.6 %).
                As = tde.tube_frames_soft(dct)[0].to(A.dtype)
                A = A + (As - As.detach())
        else:
            sur = _vtd._w02()
            p = torch.stack([c[0, :, INDEX[f"vtl_{n}"]] for n in sur.names], -1)
            A, _, _ = sur(p)
        k = int(0.3 * A.shape[-1])
        la = torch.log(_vtd._softmin_all(A[:, k:].double(), 0.01).clamp_min(1e-5)).to(c.dtype)
        lv = torch.log(_vtd._softmin_all(A[:, 1:-2].double(), 0.01).clamp_min(1e-5)).to(c.dtype)      # 모음: 성문 첫 칸·입술 뺀 관 전체
        els_pen = torch.zeros_like(la)
        if self._aplace is None and self._aplace_pl is not None:
            place, T, N = self._aplace_pl, int(A.shape[0]), int(A.shape[-1])
            sc = (N - 1) / 27.0                              # 창은 28 칸 기준
            win = np.zeros((T, N)); els = np.zeros((T, N))
            for i, pw in enumerate(place[:T]):
                if pw is None:
                    continue
                lo_, hi_ = int(round(pw[0] * sc)), int(round(pw[1] * sc))
                win[i, lo_:hi_ + 1] = 1.0
                els[i, 1:] = 1.0
                els[i, max(1, lo_ - 1):hi_ + 2] = 0.0
            has = np.array([pw is not None for pw in place[:T]] + [False] * max(0, T - len(place)))
            self._aplace = (torch.as_tensor(win, dtype=torch.float64, device=A.device),
                            torch.as_tensor(els, dtype=torch.float64, device=A.device),
                            torch.as_tensor(has, device=A.device))
            print(f"  조음 자리: 자리 창을 쓰는 틀 {int(has.sum())} 개, 창 밖 ≥ {ART_ELSE_A:g} cm² ({N} 칸)", flush=True)
        if self._aplace is not None:
            # 자리 창 안의 부드러운 최소로 협착을 재고, 창 밖은 열려 있어야 한다 (가려진 칸은 큰 값으로 밀어낸다)
            win, els, has = self._aplace
            Ad = A.double()[: win.shape[0]]

            def _msoft(m):
                return -0.01 * (torch.logsumexp(-(Ad + 1e3 * (1.0 - m.double())) / 0.01, -1)
                                - torch.log(m.double().sum(-1).clamp_min(1.0)))
            lw = torch.log(_msoft(win).clamp_min(1e-5)).to(c.dtype)
            le = torch.log(_msoft(els).clamp_min(1e-5)).to(c.dtype)
            la = torch.where(has, lw, la)
            els_pen = torch.where(has, torch.relu(math.log(ART_ELSE_A) - le) ** 2, els_pen)
        close = torch.relu(la - math.log(ART_CLOSE_A)) ** 2 + els_pen
        fric = torch.relu(math.log(ART_FRIC_A[0]) - la) ** 2 + torch.relu(la - math.log(ART_FRIC_A[1])) ** 2 + els_pen
        vow = torch.relu(math.log(ART_VOWEL_A) - lv) ** 2 if ART_VOWEL_A > 0.0 else torch.zeros_like(lv)
        alip = getattr(self, "_alip", None)
        if alip is not None and bool((alip > 0).any()):
            # 모음의 입술 (§52.522) — 관 최소는 입술 칸을 빼고 재서(원순 모음 때문), 적합이 비원순 ʌ 에서 입술을 0.045 cm² 로 닫아 넘치는 고역을 눌렀다
            lipA = A[: alip.shape[0], -1].double()
            lp = torch.where(alip > 0, torch.relu(torch.log(alip.clamp_min(1e-6)) - torch.log(lipA.clamp_min(1e-5))) ** 2, torch.zeros_like(lipA))
            vow = vow + lp.to(vow.dtype)[: vow.shape[0]]
        alpr = getattr(self, "_alpr", None)
        if alpr is not None and tde is not None and _vtd.ARTIC == "w02" and bool(torch.isfinite(alpr[:, 0]).any()):
            # 모음의 입술 내밂 범위 (§52.527) — 관에 들어가는 값 (생리 평활·속도 한계 뒤). 눈금 0.1 cm 로 나눠 log 면적 벌점과 같은 크기로.
            lpv = tde._w02_smooth(dct, "LP")[0][: alpr.shape[0]].double()
            ok_ = torch.isfinite(alpr[:, 0])
            lo_, hi_ = torch.nan_to_num(alpr[:, 0], nan=-9.0), torch.nan_to_num(alpr[:, 1], nan=9.0)
            plp = torch.where(ok_, ((torch.relu(lo_ - lpv) + torch.relu(lpv - hi_)) / 0.1) ** 2, torch.zeros_like(lpv))
            vow = vow + plp.to(vow.dtype)[: vow.shape[0]]
        opn = rel = els_pen
        if self._aplace is not None:
            opn = els_pen + torch.relu(math.log(ART_OPEN_A) - lw) ** 2       # 폐쇄 증거 없는 폐쇄음: 자리 창 안도 열림
            rel = els_pen + torch.relu(math.log(ART_REL_A) - lw) ** 2        # 개방 뒤: 닫혀 있지 않다
        pen = torch.where(kind == 1, close, torch.where(kind == 2, fric, torch.where(kind == 3, vow,
                                                                                      torch.where(kind == 4, els_pen,
                                                                                                  torch.where(kind == 5, opn,
                                                                                                              torch.where(kind == 6, rel,
                                                                                                                          torch.zeros_like(la)))))))
        with torch.no_grad():
            self._last_acons = float(torch.exp(la[kind == 1]).median()) if bool((kind == 1).any()) else float("nan")
        out = pen[kind > 0].mean()
        if ART_LARYNX and ART_PLACE:
            # **성문 상태도 녹음이 정한다** (§52.509): WGA 는 ㅅ·무성화된 '시' 동안 내전 0.37–0.44 (뒤쪽 틈 ~0.04 mm — 닫힘)로 떨었다.
            # 마찰·기식이 있고 주기성이 없는 틀은 벌림(내전 ≤ `ART_ABD_ADD`, 틈 ≥ ~2 mm — 한국어 ㅅ·기식음의 성문 열림은 수 mm, Kagaya 1974),
            # 또렷이 주기적인 틀은 모음(≥ `ART_ADD_VOICED`). 폐쇄 무음처럼 증거가 없는 틀은 건드리지 않는다. 눈금 0.05 로 나눠 log 면적 벌점과 같은 크기로.
            if getattr(self, "_gspec", None) is None or self._gspec[0].shape[0] != c.shape[1]:
                uv, vv = self._glot_spec(int(c.shape[1]))
                self._gspec = (torch.as_tensor(uv, device=c.device), torch.as_tensor(vv, device=c.device))
                print(f"  녹음 기준 성문 상태: 벌림 틀 {int(uv.sum())} 개 (내전 ≤ {ART_ABD_ADD:g}), 모음 틀 {int(vv.sum())} 개 "
                      f"(내전 ≥ {ART_ADD_VOICED:g})", flush=True)
            uv, vv = self._gspec
            ad = c[0, :, INDEX["adduction"]]
            g = torch.where(uv, torch.relu(ad - ART_ABD_ADD), torch.where(vv, torch.relu(ART_ADD_VOICED - ad), torch.zeros_like(ad)))
            m = uv | vv
            if bool(m.any()):
                out = out + ((g[m] / 0.05) ** 2).mean()
        return out

    def art_trajectory(self) -> torch.Tensor:
        """(T, C) 조음기 궤적 [VTL 단위] — 목표 계단 → 임계감쇠 3 차 응답."""
        self._art_setup()
        b = self._art_b0 + (ART_BND_MS / 1000.0) * torch.tanh(self.art_d)
        st = torch.sigmoid((self._art_t[:, None] - b[None, :]) / (ART_EDGE_MS / 1000.0))      # (T, K−1)
        z = self.art_z[:1] + st @ (self.art_z[1:] - self.art_z[:-1])                          # (T, C)
        x = z * torch.as_tensor(self._art_sp, dtype=z.dtype, device=z.device) + torch.as_tensor(self._art_ne, dtype=z.dtype, device=z.device)
        L = self._art_ker.shape[-1]
        xp = torch.nn.functional.pad(x.t().unsqueeze(0), (L - 1, 0), mode="replicate")          # (1, C, T+L−1)
        y = torch.nn.functional.conv1d(xp, self._art_ker, groups=x.shape[1])[0].t()
        if ART_LEAD > 0.0:                                     # 조음 앞섬 — 조음기마다 ART_LEAD·τ 만큼 앞당긴다
            if getattr(self, "_art_lead_idx", None) is None or self._art_lead_idx.shape != y.shape:
                T_ = y.shape[0]
                sh = torch.as_tensor([int(round(ART_LEAD * float(PARAM_TAU_PHYS.get(n, TARGET_TAU_DEFAULT)) / float(self.track.frame_ms)))
                                      for n in self._art_names], device=y.device)
                self._art_lead_idx = (torch.arange(T_, device=y.device)[:, None] + sh[None, :]).clamp(max=T_ - 1)
            y = torch.gather(y, 0, self._art_lead_idx)
        lo = torch.as_tensor([PARAMS[n].lo for n in self._art_names], dtype=y.dtype, device=y.device)
        hi = torch.as_tensor([PARAMS[n].hi for n in self._art_names], dtype=y.dtype, device=y.device)
        return torch.minimum(torch.maximum(y, lo), hi)

    def _art_override(self, c: torch.Tensor) -> torch.Tensor:
        y = self.art_trajectory().to(c.dtype)
        c = c.clone()
        c[0, :, self._art_idx] = y[: c.shape[1]]
        return c

    def _hc_leaves(self) -> list:
        """주기별 보정의 잎 텐서 (저차원 인수면 둘, 아니면 하나, 없으면 빈 목록)."""
        if getattr(self, "_hc_u", None) is not None:
            return [self._hc_u, self._hc_v]
        return [self.hcorr] if getattr(self, "hcorr", None) is not None else []

    @staticmethod
    def _excitation_peaks(y: np.ndarray, marks: np.ndarray, fs: float) -> np.ndarray:
        """주기마다의 들뜸 시각 [표본] — 2–10 kHz 대역 포락(0.15 ms 평활)의 봉우리를 표시 사이 [m_k, m_{k+1}) 에서. 원본과 합성에 같은 자."""
        from scipy.signal import butter, sosfiltfilt
        sos = butter(4, [2000.0, 10000.0], "bp", fs=fs, output="sos")
        e = sosfiltfilt(sos, y) ** 2
        w = max(1, int(0.00015 * fs))
        e = np.convolve(e, np.ones(w) / w, "same")
        out = np.full(marks.size - 1, -1.0)
        for k in range(marks.size - 1):
            a, b = int(marks[k]), int(marks[k + 1])
            if b - a < 8 or b > e.size:
                continue
            i = a + int(np.argmax(e[a:b]))
            # 포물선 보간으로 표본 사이 자리
            if a < i < b - 1:
                y0, y1, y2 = e[i - 1], e[i], e[i + 1]
                d = y0 - 2 * y1 + y2
                out[k] = i + (0.5 * (y0 - y2) / d if d < 0 else 0.0)
            else:
                out[k] = i
        return out

    @staticmethod
    def _excitation_peaks_c(y: np.ndarray, marks: np.ndarray, left: np.ndarray, right: np.ndarray, fs: float) -> np.ndarray:
        """표시마다 그 둘레 창 [m_k − left_k, m_k + right_k) 에서의 들뜸 시각 [표본] (2–10 kHz 대역 포락 봉우리, `_excitation_peaks` 와 같은 자).
        표시 **사이** 창은 Praat 표시가 들뜸 가까이 놓여 있어 한 들뜸이 앞 창의 끝과 뒤 창의 처음에 번갈아 잡혔다 (원본 창 안 자리 0–0.1 에 45,
        0.8–1 에 14 — 목표가 겹치고 빠졌다, §52.493)."""
        from scipy.signal import butter, sosfiltfilt
        sos = butter(4, [2000.0, 10000.0], "bp", fs=fs, output="sos")
        e = sosfiltfilt(sos, y) ** 2
        w = max(1, int(0.00015 * fs))
        e = np.convolve(e, np.ones(w) / w, "same")
        out = np.full(marks.size, -1.0)
        for k in range(marks.size):
            a, b = int(marks[k] - left[k]), int(marks[k] + right[k])
            a, b = max(a, 1), min(b, e.size - 1)
            if b - a < 8:
                continue
            i = a + int(np.argmax(e[a:b]))
            if a < i < b - 1:
                y0, y1, y2 = e[i - 1], e[i], e[i + 1]
                d = y0 - 2 * y1 + y2
                out[k] = i + (0.5 * (y0 - y2) / d if d < 0 else 0.0)
            else:
                out[k] = i
        return out

    def vf_pll_calibrate(self, iters: int, verbose: bool = True) -> float | None:
        """위상 고정 고리의 목표 시각표를 세운다 (`VF_PLL`, §52.493). 목표 닫힘 = 원본 들뜸 시각 tp (표시마다 그 둘레 창, `_excitation_peaks_c`)
        − 표시별 **닫힘 → 들뜸 지연**. 지연은 합성에서 직접 잰다 — 같은 창의 합성 들뜸 sp 와 그 앞에 잡힌 고리 닫힘의 차 (이웃
        `VF_PLL_SMOOTH` 표시 중앙값). 어긋남(sp − tp)으로 지연을 고치면 고리가 못 따라간 몫까지 지연에 섞여 되먹임이 된다 (VLdC: 지연 −0.5 ~
        +1.1 ms, 포락 81.6 → 56.5 %). 들뜸을 못 잡은 원본 표시는 표시 + 중앙 지연으로 메운다. 돌려준 값은 들뜸 어긋남 |ms| 의 중앙."""
        from . import voice_td as _vtd
        from . import tube_td as _tdm
        from scipy.ndimage import median_filter
        tdp = self.eng.td
        tdp.vf_qcyc = None                                          # 고리가 주기 시각을 맡는다 — 앞 판의 표본률 배율은 버린다
        marks = np.asarray(self.pulse_idx.detach().cpu().numpy(), dtype=np.int64)
        tgt = self.target[0].detach().cpu().numpy().astype(np.float64)
        marks = marks[(marks >= 0) & (marks < tgt.size)]
        if marks.size < 5:
            return None
        key = (marks.size, int(marks[0]), int(marks[-1]))
        if getattr(self, "_pll_key", None) != key:
            # 표시 사이가 f0 궤적 주기의 n 배(n ≥ 2)면 n 등분한다 — Praat 펄스가 옥타브 아래로 빠진 자리.
            f0t = np.asarray(self.track["f0_target"], dtype=np.float64)
            fr = float(self.track.frame_ms) * 1e-3 * self.fs
            pm = np.diff(marks).astype(np.float64)
            mid = 0.5 * (marks[:-1] + marks[1:])
            f0m = f0t[np.clip((mid / fr).astype(int), 0, max(f0t.size - 1, 0))] if f0t.size else np.zeros(pm.size)
            ratio = np.where(f0m > 50.0, pm * f0m / self.fs, 1.0)
            new, nsub = [float(marks[0])], 0
            for k in range(pm.size):
                n = int(round(ratio[k]))
                if n >= 2 and abs(ratio[k] - n) < 0.3 and pm[k] / n > 0.0015 * self.fs:
                    new.extend(float(marks[k]) + pm[k] * i / n for i in range(1, n))
                    nsub += 1
                new.append(float(marks[k + 1]))
            m = np.round(np.asarray(new)).astype(np.int64)
            if verbose and nsub:
                print(f"  고리 시각표: 표시 사이 {nsub} 곳을 f0 궤적 주기로 나눴다 (표시 {marks.size} → {m.size})", flush=True)
            # 표시마다 창: 앞뒤 주기의 반씩 (한쪽이 끊김이면 다른 쪽으로)
            pm = np.diff(m).astype(np.float64)
            lo, hi = np.r_[np.inf, pm], np.r_[pm, np.inf]
            lim0, lim1 = 0.0015 * self.fs, 0.012 * self.fs
            lo_ok, hi_ok = (lo > lim0) & (lo < lim1), (hi > lim0) & (hi < lim1)
            lo0, hi0 = np.where(lo_ok, lo, 0.0), np.where(hi_ok, hi, 0.0)
            per = np.where(lo_ok & hi_ok, 0.5 * (lo0 + hi0), lo0 + hi0)
            good = lo_ok | hi_ok
            left = np.where(lo_ok, 0.5 * lo0, 0.5 * per)
            right = np.where(hi_ok, 0.5 * hi0, 0.5 * per)
            tp = self._excitation_peaks_c(tgt, m, left, right, self.fs)
            have = good & (tp >= 0)
            dly = float(np.median((tp - m)[have])) if have.any() else 0.0
            tp = np.where(have, tp, m + dly)
            self._pll_m, self._pll_lr, self._pll_per = m, (left, right), per
            self._pll_tp, self._pll_good, self._pll_have, self._pll_key = tp, good, have, key
            if getattr(self, "_pll_off", None) is None or self._pll_off.shape[0] != tp.shape[0]:
                self._pll_off = np.full(tp.shape[0], VF_PLL_OFF0_MS * 1e-3 * self.fs)
        tp, good, have = self._pll_tp, self._pll_good, self._pll_have
        m, (left, right), per_m = self._pll_m, self._pll_lr, self._pll_per
        OS = _vtd.OS
        best, med = None, None
        for it in range(int(iters) + 1):
            tdp.vf_pll_t = ((tp - self._pll_off) * OS)[good]
            y = self.render().astype(np.float64).reshape(-1)[:tgt.size]
            sp = self._excitation_peaks_c(y, m, left, right, self.fs)
            e = sp - tp
            ok = have & (sp >= 0) & (np.abs(e) < 0.4 * np.maximum(per_m, 1.0))
            if ok.sum() < 3:
                return None
            ev = tdp.last_ev[0] / OS if tdp.last_ev and tdp.last_ev[0] is not None else np.zeros(0)
            # 표시마다: 합성 들뜸 바로 앞(반 주기 안)의 닫힘 → 지연, 목표 닫힘과 가장 가까운 닫힘 → 고리 어긋남
            d = np.full(tp.size, np.nan)
            trk = np.full(tp.size, np.nan)
            if ev.size:
                j = np.searchsorted(ev, sp, side="right") - 1
                okd = ok & (j >= 0)
                dd = sp - ev[np.clip(j, 0, ev.size - 1)]
                okd &= (dd >= 0) & (dd < 0.5 * per_m)
                d[okd] = dd[okd]
                pt48 = tp - self._pll_off
                jn = np.clip(np.searchsorted(ev, pt48), 1, max(ev.size - 1, 1))
                near = np.where(np.abs(ev[jn - 1] - pt48) < np.abs(ev[np.minimum(jn, ev.size - 1)] - pt48),
                                ev[jn - 1], ev[np.minimum(jn, ev.size - 1)])
                trk[good] = (near - pt48)[good]
            u = getattr(tdp, "last_pll_u", None)
            sat = float(np.mean(np.abs(u) > 0.98 * _tdm.PLL_GAINS["umax"])) if u is not None and u.size else 0.0
            med = float(np.median(np.abs(e[ok]))) / self.fs * 1000.0
            if verbose:
                ms = 1000.0 / self.fs
                okt = np.isfinite(trk) & (np.abs(trk) < 0.5 * np.maximum(per_m, 1.0))
                print(f"  고리 시각표 {it}: 짝 {int(ok.sum())}/{int(good.sum())} 표시, 들뜸 어긋남 |e| 중앙 {med:.3f} · 90 % "
                      f"{float(np.percentile(np.abs(e[ok]), 90)) * ms:.3f} ms · 닫힘 추종 |e| 중앙 "
                      f"{(float(np.median(np.abs(trk[okt]))) * ms if okt.any() else float('nan')):.3f} · 90 % "
                      f"{(float(np.percentile(np.abs(trk[okt]), 90)) * ms if okt.any() else float('nan')):.3f} ms · "
                      f"지연 중앙 {(float(np.nanmedian(d)) * ms if np.isfinite(d).any() else float('nan')):.3f} ms · 배율 한계 {100 * sat:.0f} %",
                      flush=True)
            if best is None or med < best[0]:
                best = (med, self._pll_off.copy())
                self._pll_diag = np.stack([tp, np.where(ok, sp, np.nan), self._pll_off.copy(), d, trk], 0)   # 진단 (트랙에 남긴다)
            import os as _os
            if _os.environ.get("PLL_DUMP"):
                rr = tdp.last_rec[0] if tdp.last_rec else None
                np.savez(f"{_os.environ['PLL_DUMP']}_{it}.npz", ev=ev, pt=tdp.vf_pll_t / OS, u=(u if u is not None else np.zeros(0)),
                         ga=(rr[:, 7:9] if rr is not None else np.zeros(0)), y=y, tgt=tgt, marks=m, tp=tp, sp=sp, off=self._pll_off)
            if it == iters:
                break
            idx = np.flatnonzero(np.isfinite(d))
            if idx.size < 3:
                break
            ds = median_filter(d[idx], size=max(1, VF_PLL_SMOOTH), mode="nearest")
            self._pll_off = np.interp(np.arange(tp.size), idx, ds)
        self._pll_off = best[1]
        tdp.vf_pll_t = ((tp - self._pll_off) * OS)[good]
        return best[0]

    def vf_cycle_lock(self, iters: int | None = None, verbose: bool = True) -> float | None:
        """주기 시각 맞춤 (`VF_CYCLE_LOCK`) — 합성 소리의 주기별 들뜸이 원본의 것과 같은 때 오도록 그 앞 주기의 긴장을 **표본률**로 고친다.
        자는 원본·합성에 같다 (`_excitation_peaks`, 원본 펄스 표시 사이 창). 돌려준 값은 어긋남 |ms| 의 중앙.
        `VF_PLL` 이면 배율 대신 고리의 시각표를 다시 잰다 (`vf_pll_calibrate`)."""
        from . import voice_td as _vtd
        iters = VF_CYCLE_LOCK if iters is None else int(iters)
        if iters <= 0 or not (_voice_mod.TD_TUBE and _vtd.GLOTTIS == "vf"):
            return None
        if VF_PLL:
            return self.vf_pll_calibrate(min(iters, 3), verbose)
        tdp = self.eng.td
        marks = np.asarray(self.pulse_idx.detach().cpu().numpy(), dtype=np.int64)
        tgt = self.target[0].detach().cpu().numpy().astype(np.float64)
        marks = marks[(marks >= 0) & (marks < tgt.size)]
        if marks.size < 5:
            return None
        per_m = np.diff(marks)
        tp = self._excitation_peaks(tgt, marks, self.fs)
        good_t = (tp >= 0) & (per_m > 0.0015 * self.fs) & (per_m < 0.012 * self.fs)
        OS = _vtd.OS
        n96 = int(tgt.size * OS)
        qcyc = np.ones(n96) if tdp.vf_qcyc is None or tdp.vf_qcyc.shape[0] != n96 else tdp.vf_qcyc.copy()
        ramp = max(2, int(0.0002 * self.fs * OS))
        med = None
        best = (np.inf, qcyc.copy())                 # 반복 가운데 가장 나은 배율을 남긴다 — 맞춤이 나빠지지 않게
        for it in range(iters + 1):
            tdp.vf_qcyc = qcyc
            y = self.render().astype(np.float64).reshape(-1)[:tgt.size]
            sp = self._excitation_peaks(y, marks, self.fs)
            ok = good_t & (sp >= 0)
            e = np.where(ok, sp - tp, 0.0)                                  # 48 kHz 표본, + 면 합성이 늦다
            ok &= np.abs(e) < 0.4 * per_m
            if ok.sum() < 3:
                return None
            med = float(np.median(np.abs(e[ok]))) / self.fs * 1000.0
            score = med * (1.0 + max(0.0, 1.0 - ok.sum() / max(1, good_t.sum())))   # 짝이 줄면 벌점
            if score < best[0]:
                best = (score, qcyc.copy())
            if verbose:
                print(f"  주기 시각 맞춤 {it}: 짝 {int(ok.sum())} 주기, 들뜸 어긋남 |e| 중앙 {med:.3f} · 90 % "
                      f"{float(np.percentile(np.abs(e[ok]), 90)) / self.fs * 1000.0:.3f} ms", flush=True)
            if it == iters:
                break
            lq = np.log(qcyc)
            # 앞 주기의 긴장을 고치면 **뒤 닫힘이 모두 같은 만큼** 옮겨진다 (순수한 위상 이동, `out/_tmp/vf/qstep.py`: e^0.05 → −0.198 ms 가
            # 그 뒤 모든 닫힘에). 그러므로 주기마다 **어긋남의 증분** e_k − e_{k−1} 만 고친다 — 누적 e_k 를 주기마다 고치면 과보정이다.
            # 이어짐의 첫 짝만 절대 어긋남을 고친다.
            for k in range(1, sp.size):
                if not ok[k]:
                    continue
                if ok[k - 1]:
                    Ti = float(sp[k] - sp[k - 1])
                    first = k < 2 or not ok[k - 2]
                    de = float(e[k]) - (0.0 if first else float(e[k - 1]))
                    s0 = float(sp[k - 1])
                else:
                    # 이어짐의 첫 주기 — 앞 들뜸이 짝지어지지 않았다: 원본 주기 길이로 그 앞 한 주기를 잡아 절대 어긋남을 건다
                    Ti = float(per_m[k - 1])
                    de = float(e[k])
                    s0 = max(0.0, float(sp[k]) - Ti)
                if Ti <= 8:
                    continue
                Tn = max(0.5 * Ti, Ti - VF_CYCLE_GAIN * de)
                dl = float(np.clip(np.log(Ti / Tn), -VF_CYCLE_STEP, VF_CYCLE_STEP))
                a0, b0 = int(s0 * OS), int(sp[k] * OS)                        # 합성 시간축(96 kHz)의 그 주기
                if b0 - a0 <= 2 * ramp:
                    continue
                w = np.ones(b0 - a0)
                r = 0.5 - 0.5 * np.cos(np.pi * np.arange(ramp) / ramp)
                w[:ramp] = r
                w[-ramp:] = r[::-1]
                lq[a0:b0] += dl * w
            qcyc = np.exp(np.clip(lq, -VF_LOCK_MAX, VF_LOCK_MAX))
        tdp.vf_qcyc = best[1]
        return med

    def vf_pitch_lock(self, iters: int | None = None, verbose: bool = True) -> float | None:
        """자기 진동 성대의 음높이 맞춤 (`VF_LOCK_ITERS`). 돌려준 값은 유성 틀 f0 오차 |cents| 의 중앙 (성대 모드가 아니면 None)."""
        from . import voice_td as _vtd
        if not (_voice_mod.TD_TUBE and _vtd.GLOTTIS == "vf"):
            return None
        iters = VF_LOCK_ITERS if iters is None else int(iters)
        tdp = self.eng.td
        if VF_PLL:
            tdp.vf_qcyc = None              # 고리 판은 앞 판의 표본률 배율 없이 기본 긴장을 잰다 (그 배율과 짝인 틀 배율이면 고리가 한계에 붙는다)
        forced = VF_FORCE_PITCH and not getattr(self, "_vf_pitch_forced", False)
        if VF_CYCLE_LOCK > 0 and getattr(self, "_vf_pitch_done", False) and not forced:
            return None                     # 주기 시각 맞춤이 주기 길이를 정한다 — 틀 배율을 다시 흔들면 맞춘 시각이 흩어진다 (§52.491)
        self._vf_pitch_done = True
        if forced:
            # 성대 모형을 바꾼 첫 패스 (§52.504): 앞 모형의 긴장 배율을 버리고 1 에서, 고리를 잠시 끄고 새 모형의 기본 긴장을 잡는다
            # (고리가 켜져 있으면 고리가 오차를 흡수해 기본 긴장이 안 잡힌다 — 모드 3 첫 판의 닫힘 추종 0.5–0.8 ms, VTL 판 0.3–0.4).
            self._vf_pitch_forced = True
            tdp.vf_qcorr = None
            pll_keep, tdp.vf_pll_t = tdp.vf_pll_t, None
            try:
                return self._vf_pitch_lock_run(iters, verbose)
            finally:
                tdp.vf_pll_t = pll_keep
        return self._vf_pitch_lock_run(iters, verbose)

    def _vf_pitch_lock_run(self, iters: int, verbose: bool) -> float | None:
        from . import voice_td as _vtd
        tdp = self.eng.td
        T = int(self.control().shape[1])
        f0t = np.asarray(self.track["f0_target"], dtype=np.float64)[:T]
        f0t = np.pad(f0t, (0, T - f0t.size)) if f0t.size < T else f0t
        voiced = np.asarray(self.track.voiced, bool)[:T] if self.track.voiced.size else f0t > 0
        voiced = np.pad(voiced, (0, T - voiced.size)) if voiced.size < T else voiced
        qc = (np.ones(T) if tdp.vf_qcorr is None or tdp.vf_qcorr.shape[-1] != T
              else tdp.vf_qcorr[0].detach().cpu().numpy().astype(np.float64).copy())
        H = self.hop * _vtd.OS
        med = None
        for it in range(iters + 1):
            tdp.vf_qcorr = torch.as_tensor(qc[None, :], dtype=torch.float64)
            self.render()
            idx, per = _vtd.TDPath.measure_f0(tdp.last_rec[0])
            if idx.size < 2:
                if verbose:
                    print("  음높이 맞춤: 합성이 떨지 않는다 — 건너뜀", flush=True)
                return None
            fc = (idx - 0.5 * per * _vtd.td.FS_SIM) / H             # 주기 가운데의 틀 위치
            fsim = np.interp(np.arange(T), fc, 1.0 / per)
            j = np.clip(np.searchsorted(fc, np.arange(T)), 1, fc.size - 1)
            gap = np.minimum(np.abs(fc[j] - np.arange(T)), np.abs(fc[j - 1] - np.arange(T)))
            ok = voiced & (f0t > 0) & (gap * H / _vtd.td.FS_SIM < 1.5 / np.maximum(fsim, 50.0))
            ok &= np.abs(np.log(np.maximum(f0t, 1.0) / np.maximum(fsim, 1.0))) < VF_LOCK_OUTLIER
            if not ok.any():
                return None
            cents = 1200.0 * np.log2(f0t[ok] / fsim[ok])
            med = float(np.median(np.abs(cents)))
            if os.environ.get("VF_LOCK_DUMP"):
                c_ = self.control()[0].detach().cpu().numpy()
                np.savez(f"{os.environ['VF_LOCK_DUMP']}_{it}.npz", f0t=f0t, fsim=fsim, ok=ok, qc=qc, voiced=voiced, idx=idx, per=per,
                         rec=tdp.last_rec[0][::4], ctrl=c_, names=np.array(sorted(INDEX, key=INDEX.get)))
            if verbose:
                print(f"  음높이 맞춤 {it}: 유성 틀 {int(ok.sum())}/{int(voiced.sum())}, |오차| 중앙 {med:.1f} · 90 % "
                      f"{float(np.percentile(np.abs(cents), 90)):.1f} cents, 긴장 배율 {qc[ok].min():.3f}–{qc[ok].max():.3f}", flush=True)
            if it == iters:
                break
            lu = np.zeros(T)
            lu[ok] = np.clip(np.log(f0t[ok] / fsim[ok]), -VF_LOCK_STEP, VF_LOCK_STEP)
            w = np.convolve(ok.astype(float), np.ones(5), "same")
            lus = np.convolve(lu, np.ones(5), "same") / np.maximum(w, 1e-9)
            lq = np.log(qc)
            lq[ok] += lus[ok]
            idx_ok = np.where(ok)[0]
            lq = np.interp(np.arange(T), idx_ok, lq[idx_ok])               # 무성 틈은 양옆 유성 틀에서 잇는다
            qc = np.exp(np.clip(lq, -VF_LOCK_MAX, VF_LOCK_MAX))
        return med

    def _gradcheck(self, params, l) -> None:
        """실제 적합 손실에서 무작위 방향의 중앙 차분 ↔ 자동미분 (진단, 환경 변수 `GRADCHECK`, §52.504). 매개변수 텐서마다 따로."""
        ps = [p for p in params if p.requires_grad and p.numel() > 0]
        gs = torch.autograd.grad(l, ps, retain_graph=True, allow_unused=True)
        if os.environ.get("GRADCHECK") == "2":
            # 부호 걸음 시험: Adam 의 첫걸음처럼 θ − s·sign(g) 로 옮겨 손실이 줄어드는지 (텐서마다, 그리고 모두 함께)
            l0 = float(l.detach())
            groups = [[i] for i in range(len(ps)) if gs[i] is not None][:int(os.environ.get("GRADCHECK_N", "8"))] + [
                [i for i in range(len(ps)) if gs[i] is not None]]
            for grp in groups:
                row = []
                base = [ps[i].detach().clone() for i in grp]
                for s_ in (3e-4, 1e-3, 3e-3, 1e-2, 3e-2):
                    with torch.no_grad():
                        for i, b in zip(grp, base):
                            ps[i].copy_(b - s_ * torch.sign(gs[i]))
                        row.append(f"{s_:g}: {float(self.loss()[0]) - l0:+.4f}")
                        for i, b in zip(grp, base):
                            ps[i].copy_(b)
                tag = "모두" if len(grp) > 1 else f"[{grp[0]}] {tuple(ps[grp[0]].shape)}"
                print(f"      부호 걸음 {tag}: 손실 변화 " + " · ".join(row), flush=True)
            return
        if os.environ.get("GRADCHECK") == "4":
            # 항별 대조 (§52.524): 텐서마다 무작위 방향 d 로 손실의 항마다 (자동미분 d·∇항, 보폭별 중앙 차분)
            gen = torch.Generator().manual_seed(0)
            hs = [float(v) for v in os.environ.get("GRADCHECK_H", "1e-2,1e-3").split(",")]
            sel = [int(v) for v in os.environ.get("GRADCHECK_SEL", "0,6,7").split(",")]
            for i, p in enumerate(ps):
                if i not in sel:
                    continue
                d = torch.randn(p.shape, generator=gen, dtype=torch.float64).to(p.dtype).to(p.device)
                self._collect = True
                try:
                    l_ = self.loss()[0]
                    T0 = dict(self._terms)
                    T0["penalty"] = self.penalty()
                    ads = {}
                    for k, v in T0.items():
                        if torch.is_tensor(v) and v.requires_grad:
                            g_ = torch.autograd.grad(v * float(self._bal.get(k, 1.0)) if k not in ("env", "penalty") else v, [p],
                                                     retain_graph=True, allow_unused=True)[0]
                            ads[k] = float((g_ * d).sum()) if g_ is not None else 0.0
                    b = p.detach().clone()
                    fds = {k: [] for k in ads}
                    for h in hs:
                        vals = []
                        for sgn in (1.0, -1.0):
                            with torch.no_grad():
                                p.copy_(b + sgn * h * d)
                                self.loss()
                                Tt = dict(self._terms)
                                Tt["penalty"] = self.penalty()
                                p.copy_(b)
                            vals.append(Tt)
                        for k in ads:
                            w_ = 1.0 if k in ("env", "penalty") else float(self._bal.get(k, 1.0))
                            fp, fm = (float(t_[k]) * w_ if k in t_ else 0.0 for t_ in vals)
                            fds[k].append((fp - fm) / (2 * h))
                finally:
                    self._collect = False
                for k in ads:
                    print(f"      항 [{i}] {k:10s} 자동 {ads[k]:+.4e} · " + " · ".join(f"h {h:g} {v:+.4e}" for h, v in zip(hs, fds[k])), flush=True)
            return
        if os.environ.get("GRADCHECK") == "3":
            # 직선 훑기 (§52.524): 텐서마다 무작위 방향 d 로 L(θ + t d) − L(θ), t ∈ [−H, H] 21 점 + 같은 자리 두 번 (결정론)
            gen = torch.Generator().manual_seed(0)
            H = float(os.environ.get("GRADCHECK_H", "1e-2"))
            with torch.no_grad():
                l0 = float(self.loss()[0])
                l0b = float(self.loss()[0])
            print(f"      직선 훑기: 같은 자리 두 번 {l0:.9f} · {l0b:.9f} (차 {l0b - l0:+.3e})", flush=True)
            # 합성 음성의 매끈함: r(h) = ‖y₊ − 2y₀ + y₋‖ / ‖y₊ − y₋‖ — 매끈하면 h 에 비례해 줄고, 거칠면 O(1) 에 머문다
            for i, (p, g) in enumerate(zip(ps, gs)):
                if g is None or i >= int(os.environ.get("GRADCHECK_N", "8")):
                    continue
                d = torch.randn(p.shape, generator=torch.Generator().manual_seed(100 + i), dtype=torch.float64).to(p.dtype).to(p.device)
                b = p.detach().clone()
                rs = []
                with torch.no_grad():
                    y0 = self.synth()[0].double()
                    for h in (1e-2, 1e-3, 1e-4):
                        p.copy_(b + h * d)
                        yp = self.synth()[0].double()
                        p.copy_(b - h * d)
                        ym = self.synth()[0].double()
                        p.copy_(b)
                        rs.append(f"h {h:g}: r {float((yp - 2 * y0 + ym).norm() / (yp - ym).norm().clamp_min(1e-30)):.3e}")
                print(f"      음성 매끈함 [{i}] {tuple(p.shape)}: " + " · ".join(rs), flush=True)
            for i, (p, g) in enumerate(zip(ps, gs)):
                if g is None or i >= int(os.environ.get("GRADCHECK_N", "8")):
                    continue
                d = torch.randn(p.shape, generator=gen, dtype=torch.float64).to(p.dtype).to(p.device)
                ad = float((g * d).sum())
                b = p.detach().clone()
                row = []
                for t in np.linspace(-H, H, 21):
                    with torch.no_grad():
                        p.copy_(b + float(t) * d)
                        row.append(float(self.loss()[0]) - l0)
                        p.copy_(b)
                print(f"      직선 [{i}] {tuple(p.shape)} 자동미분 기울기 {ad:+.4e}: " + " ".join(f"{v:+.2e}" for v in row), flush=True)
            return
        gen = torch.Generator().manual_seed(0)
        hs = [float(v) for v in os.environ.get("GRADCHECK_H", "1e-3,1e-4").split(",")]
        for i, (p, g) in enumerate(zip(ps, gs)):
            if g is None or i >= int(os.environ.get("GRADCHECK_N", "8")):
                continue
            d = torch.randn(p.shape, generator=gen, dtype=torch.float64).to(p.dtype).to(p.device)
            ad = float((g * d).sum())
            b = p.detach().clone()
            out = []
            for h in hs:
                with torch.no_grad():
                    p.copy_(b + h * d)
                    lp = float(self.loss()[0])
                    p.copy_(b - h * d)
                    lm = float(self.loss()[0])
                    p.copy_(b)
                out.append(f"h {h:g}: 차분 {(lp - lm) / (2 * h):+.4e}")
            print(f"      기울기 점검 [{i}] {tuple(p.shape)}: 자동미분 {ad:+.4e} · " + " · ".join(out), flush=True)

    def vf_level_lock(self, iters: int | None = None, verbose: bool = True) -> float | None:
        """자기 진동 성대의 음량 맞춤 (`VF_LEVEL_LOCK`). 돌려준 값은 유성 틀 음량 차(중앙 뺀) |dB| 의 중앙."""
        from . import voice_td as _vtd
        if not (_voice_mod.TD_TUBE and _vtd.GLOTTIS == "vf"):
            return None
        iters = VF_LEVEL_LOCK if iters is None else int(iters)
        if iters <= 0:
            return None
        tdp = self.eng.td
        T = int(self.control().shape[1])
        voiced = np.asarray(self.track.voiced, bool)[:T] if self.track.voiced.size else np.ones(T, bool)
        voiced = np.pad(voiced, (0, T - voiced.size)) if voiced.size < T else voiced
        hw = int(0.010 * self.fs)
        yt = self.target[0].detach().cpu().numpy().astype(np.float64)

        def levels(x):
            return np.array([10.0 * np.log10(np.mean(x[max(0, i * self.hop - hw):i * self.hop + hw] ** 2) + 1e-20) for i in range(T)])
        Lt = levels(yt)
        ok = voiced & (Lt > Lt.max() - 40.0)
        if not ok.any():
            return None
        pc = (np.ones(T) if tdp.vf_pscorr is None or tdp.vf_pscorr.shape[-1] != T
              else tdp.vf_pscorr[0].detach().cpu().numpy().astype(np.float64).copy())
        g = np.exp(-0.5 * (np.arange(-15, 16) / (10.0 / (1000.0 * self.hop / self.fs))) ** 2)
        med = None
        for it in range(iters + 1):
            tdp.vf_pscorr = torch.as_tensor(pc[None, :], dtype=torch.float64)
            Ly = levels(self.render().astype(np.float64)[:yt.size])
            d = Lt - Ly
            d = d - np.median(d[ok])
            med = float(np.median(np.abs(d[ok])))
            if verbose:
                print(f"  음량 맞춤 {it}: 유성 틀 {int(ok.sum())}, 모양 차 |dB| 중앙 {med:.2f} · 90 % {float(np.percentile(np.abs(d[ok]), 90)):.2f}, "
                      f"폐압 배율 {pc[ok].min():.2f}–{pc[ok].max():.2f}", flush=True)
            if it == iters:
                break
            st = np.zeros(T)
            st[ok] = np.clip(d[ok] * math.log(2.0) / _vtd.VF_PS_DB2, -VF_LEVEL_STEP, VF_LEVEL_STEP)
            w = np.convolve(ok.astype(float), g, "same")
            sts = np.convolve(st, g, "same") / np.maximum(w, 1e-9)
            lp = np.log(pc)
            lp[ok] += sts[ok]
            idx_ok = np.where(ok)[0]
            lp = np.interp(np.arange(T), idx_ok, lp[idx_ok])
            pc = np.exp(np.clip(lp, -VF_LEVEL_MAX, VF_LEVEL_MAX))
        return med

    def _pp(self):
        """합성에 넘기는 펄스 위상 = 잠금 위상 + 오프셋. `PHI0_AS_TIME` 이면 오프셋을 **시간**으로 건다 (§52.478):
        ψ + φ0·f(t)/f_ref (f 는 5 ms 로 고른 순간 주파수). 원본의 성문 닫힘과 합성의 닫힘 사이는 관의 전파·관성 지연이라 주기와 무관한
        시간이다 — 위상으로 두면 같은 오프셋이 주기에 비례하는 시간이 되어, f0 가 235 → 400 Hz 로 오르는 038 첫머리에서 펄스 위상 0 이
        원본 닫힘보다 1.74 → 0.17 ms 로 떠다녔다."""
        if self._pulse_phase is None:
            return None
        if not PHI0_AS_TIME:
            return self._pulse_phase + self.pulse_phi0
        key = (id(self._pulse_phase), self._pulse_phase.shape[-1])
        if getattr(self, "_pp_key", None) != key:
            ps = self._pulse_phase[0].detach().double()
            d = torch.cat([ps[1:2] - ps[:1], ps[1:] - ps[:-1]])
            w = max(1, int(0.005 * self.fs))
            ker = torch.ones(1, 1, w, dtype=d.dtype, device=d.device) / w
            fs_ = torch.nn.functional.conv1d(torch.nn.functional.pad(d.view(1, 1, -1), (w // 2, w - 1 - w // 2), mode="replicate"), ker)[0, 0]
            g = fs_ / fs_.median().clamp_min(1e-9)
            self._pp_g = g.to(self._pulse_phase.dtype).unsqueeze(0)
            self._pp_key = key
        return self._pulse_phase + self.pulse_phi0 * self._pp_g

    def _snapshot(self):
        snap = tuple(q.detach().clone() for q in self.opt_params())
        tdp = getattr(self.eng, "td", None)
        ex = {}
        if tdp is not None and getattr(tdp, "vf_qcyc", None) is not None:
            ex["vf_qcyc"] = tdp.vf_qcyc.copy()                  # 제어와 짝인 주기 시각 배율 (§52.491)
        if tdp is not None and getattr(tdp, "vf_pll_t", None) is not None:
            ex["vf_pll_t"] = tdp.vf_pll_t.copy()                # 고리 시각표와 그 오프셋 (§52.493)
            ex["pll_off"] = None if getattr(self, "_pll_off", None) is None else self._pll_off.copy()
        return snap + ((("vf_state", ex),) if ex else ())

    def _phi0_tournament(self, cands, global_iters, stage_iters, lr_global, lr_frame, patience, verbose=True) -> None:
        """`PHI0_TOURNAMENT` (§52.478): 위상 오프셋 후보마다 짧게 적합(전역 + 첫 격자)해 포락이 가장 높은 오프셋을 고른다.

        처음 훑기는 분석 초기값 위의 손실이라 위상에 대해 믿을 만하지 않다 — 자기 적합 시험에서 참 펄스 위상을 주고도 오프셋이
        2.3 rad 어긋나면 77.7 %, 맞으면 88.3 % 였고, 같은 설정이 판마다 73.7~89.3 % 로 갈렸다(오프셋 −2.62 대 −2.09).
        상태(전역 스칼라·제어열 층)를 떠 두고 후보마다 되돌린 뒤, 이긴 오프셋으로 처음부터 원래 일정을 돈다.
        """
        st = (self._snapshot(), self.w, list(self.w_coarse), self.stride)
        lr_g = float(lr_global[0] if isinstance(lr_global, (tuple, list)) else lr_global)
        gp = [self.d, self.log_gain, self.pulse_phi0] + self.hf + ([self.rv_log_rt, self.rv_g_db] if (LATE_REVERB and not LR_FIXED) else []) + ([self.vb_log_g] if (VOICE_BAR and not VB_FIXED) else []) + ([self.rel_log_r] if getattr(self, 'rel_log_r', None) is not None else [])
        res = []
        for lv, phi in cands:
            snap, w, wc, stride = st
            self.w, self.w_coarse, self.stride = w, list(wc), stride
            self._restore(snap)
            with torch.no_grad():
                self.pulse_phi0.fill_(phi)
            self._global_stage = True
            self.fit(min(global_iters, TOUR_GLOBAL_ITERS), lr_g, 10 ** 9, False, params=gp, sizes=STAGES[0], patience=patience)
            self._global_stage = False
            self.set_grid(GRID_MS[0])
            self.fit(min(stage_iters, TOUR_STAGE_ITERS), lr_frame, 10 ** 9, False, sizes=STAGES[0], patience=patience)
            with torch.no_grad():
                env = float(100.0 * (1.0 - self.loss()[2]))
            res.append((env, phi, float(self.pulse_phi0.item())))
            if verbose:
                print(f"    위상 오프셋 겨루기: {phi:+.2f} rad → 짧은 적합 포락 {env:.2f} % (오프셋 {res[-1][2]:+.2f})", flush=True)
        snap, w, wc, stride = st
        self.w, self.w_coarse, self.stride = w, list(wc), stride
        self._restore(snap)
        self._global_stage = True
        win = max(res)
        with torch.no_grad():
            self.pulse_phi0.fill_(win[1])
        if verbose:
            print(f"  펄스 잠금: 겨루기로 위상 오프셋 {win[1]:+.2f} rad (짧은 적합 포락 {win[0]:.2f} %)", flush=True)

    def _restore(self, snap) -> None:
        ps = self.opt_params()
        with torch.no_grad():
            for q, v in zip(ps, snap):
                q.copy_(v)
        if len(snap) > len(ps) and isinstance(snap[-1], tuple) and snap[-1][0] == "vf_state":
            ex = snap[-1][1]
            if "vf_qcyc" in ex:
                self.eng.td.vf_qcyc = ex["vf_qcyc"].copy()
            if "vf_pll_t" in ex:
                self.eng.td.vf_pll_t = ex["vf_pll_t"].copy()
                if ex.get("pll_off") is not None:
                    self._pll_off = ex["pll_off"].copy()

    def pick_lr_global(self, candidates, iters: int, verbose: bool = True) -> float:
        """짧은 탐침으로 전역 단계의 lr 을 고른다.

        **구간마다 맞는 걸음 크기가 다르다.** 40 ms 짜리 탄음은 lr 0.05 에서 포락
        60.3 % 인데 0.02 면 90.9 % 다 (실측, lr 에 단조). 반대로 소스 기울기가 7 dB/oct
        틀린 합성 모음은 0.02 로는 못 돌아오고 0.05 가 필요하다. 하나로 못 정하므로
        짧게 재 보고 손실이 가장 낮은 것을 쓴다.
        """
        start = self._snapshot()
        best = (float("inf"), float(candidates[0]))
        for lr in candidates:
            self._restore(start)
            rep = self.fit(iters, float(lr), 10 ** 9, False,
                           params=[self.d, self.log_gain, self.pulse_phi0] + self.hf + ([self.rv_log_rt, self.rv_g_db] if (LATE_REVERB and not LR_FIXED) else []) + ([self.vb_log_g] if (VOICE_BAR and not VB_FIXED) else []) + ([self.rel_log_r] if getattr(self, 'rel_log_r', None) is not None else []),
                           sizes=STAGES[0])
            if np.isfinite(rep.loss) and rep.loss < best[0]:
                best = (rep.loss, float(lr))
            if verbose:
                print(f"      lr {float(lr):5.3f} -> 손실 {rep.loss:.4f}")
        self._restore(start)
        return best[1]


    def fit_staged(self, global_iters: int = 200, stage_iters: int = 150,
                   lr_global=(0.015, 0.03, 0.05, 0.09), lr_frame: float = 0.04,
                   phase_iters: int = 800, phase_w: float = 3.0,
                   lr_phase=(0.05, 0.12, 0.25),
                   verbose: bool = True, log_every: int = 50,
                   patience: int = 0) -> FitReport:
        """전역 스칼라 -> 제어 격자를 성기게에서 촘촘하게, 창도 함께 늘려 가며.

        `patience` 는 각 단계의 수렴 판정에 그대로 넘어간다. 코퍼스를 통째로 돌릴 때
        쓴다 (`scripts/parametrize_corpus.py`). 기본 0 = 예전 거동.
        """
        if min(global_iters, stage_iters, phase_iters) < 0:
            raise ValueError("Iteration budgets must be nonnegative")
        if LR_SCALE != 1.0:
            lr_global = (tuple(float(x) * LR_SCALE for x in lr_global) if isinstance(lr_global, (tuple, list))
                         else float(lr_global) * LR_SCALE)
            lr_frame = float(lr_frame) * LR_SCALE
        if global_iters == stage_iters == phase_iters == 0 and HF_STAGE_ITERS == 0:
            # Render-only means no LR probes, phase sweep, or grid replacement.
            return self.fit(0, verbose=verbose, sizes=FFT_SIZES)
        self._global_stage = True        # 1 단계(와 그 앞의 위상 훑기·lr 탐침) 표시 — `IH_SKIP_GLOBAL` 이 읽는다
        self.vf_pitch_lock(verbose=verbose)
        if VF_LEVEL_LOCK > 0 and not getattr(self, "_vf_level_done", False):
            self._vf_level_done = True
            self.vf_level_lock(verbose=verbose)
        self.vf_cycle_lock(verbose=verbose)
        if IH_SKIP_GLOBAL and INTERHARM_W > 0.0 and verbose:
            print("  1 단계: 배음 사이 항을 끈다 (IH_SKIP_GLOBAL — 2.1 부터 켠다)", flush=True)
        if (global_iters + stage_iters + phase_iters > 0 and PULSE_LOCK and getattr(self, "_pulse_phase", None) is not None
                and getattr(self, "_phi0_restored", False)):
            # **되살린 위상을 지킨다** (MEASUREMENTS §52.466). 다듬기(`--init`)가 앞 판의 `pulse_phi0` 를 되살린 뒤에도 아래 12 등분 훑기가
            # 늘 돌아 격자점(1/12 주기 간격)으로 덮었다 — 되살린 값은 후보에도 없었다. 주기별 보정은 그 위상에 묶여 있어 보정이 엉뚱한 자리에 놓였고,
            # 모든 다듬기가 처음 50 회에 포락 3~5 점을 잃었다가 되찾았다. 038 은 −2.385 → −0.52 rad (0.3 주기)로 옮겨져 출발 61.6 %, 끝 69 % 였다.
            if verbose:
                print(f"  펄스 잠금: 되살린 위상 오프셋 {float(self.pulse_phi0.item()):+.3f} rad 를 지킨다 (훑기 건너뜀)", flush=True)
        elif (global_iters + stage_iters + phase_iters > 0
                and PULSE_LOCK and getattr(self, "_pulse_phase", None) is not None):
            # **위상 오프셋을 먼저 훑는다.** 잠금을 켜면 `pulse_loss` 가 항등적으로 0 이라 `pulse_phi0` 를
            # 끌어 줄 항이 스펙트럼 손실뿐인데, 그 손실은 위상에 대해 다봉이다 — 실측(`L53/s040`)에서
            # 최적 오프셋이 −2.62 rad 로 초기값에서 멀었다. 12 등분해 한 번 재고 가장 나은 자리에서 시작한다.
            best = None
            scan = []
            with torch.no_grad():
                for k in (range(12) if PHI0_FIXED is None else ()):
                    phi = -math.pi + 2.0 * math.pi * k / 12.0
                    self.pulse_phi0.fill_(phi)
                    lv = float(self.loss()[0])
                    scan.append((lv, phi))
                    if best is None or lv < best[0]:
                        best = (lv, phi)
                if PHI0_FIXED is not None:
                    self.pulse_phi0.fill_(PHI0_FIXED)
                    best = (float(self.loss()[0]), PHI0_FIXED)
                self.pulse_phi0.fill_(best[1])
            if verbose:
                print(f"  펄스 잠금: 위상 오프셋 {best[1]:+.2f} rad ({best[1] / (2 * math.pi):+.3f} 주기), "
                      f"손실 {best[0]:.4f}", flush=True)
            if PHI0_TOURNAMENT > 0 and stage_iters > 0:
                self._phi0_tournament(sorted(scan)[:PHI0_TOURNAMENT], global_iters, stage_iters, lr_global, lr_frame,
                                      patience, verbose)
        # **주기별 배음 보정은 위상 오프셋 훑기 뒤에 준비한다** — 주기 색인이 `pulse_phi0` 를 따라간다 (§52.268).
        self._hcorr_prepare()
        if verbose:
            print(f"  1 단계 전역 {len(self.names)} 스칼라 (이득 {self.gain_db():+.1f} dB)")
        if isinstance(lr_global, (int, float)):
            lr_global = (float(lr_global),)
        if global_iters > 0 and len(lr_global) > 1:
            probe = max(20, global_iters // 4)
            lr_g = self.pick_lr_global(lr_global, probe, verbose)
            if verbose:
                print(f"      -> lr {lr_g:.3f} 선택")
        else:
            lr_g = float(lr_global[0])
        rep = self.fit(global_iters, lr_g, log_every, verbose,
                       params=[self.d, self.log_gain, self.pulse_phi0] + self.hf + ([self.rv_log_rt, self.rv_g_db] if (LATE_REVERB and not LR_FIXED) else []) + ([self.vb_log_g] if (VOICE_BAR and not VB_FIXED) else []) + ([self.rel_log_r] if getattr(self, 'rel_log_r', None) is not None else []),
                       sizes=STAGES[0], patience=patience)
        self._global_stage = False
        self.vf_pitch_lock(verbose=verbose)
        self.vf_cycle_lock(verbose=verbose)
        # 전역 단계가 끝나면 성도가 대충 자리를 잡는다 — 그때 한 번 보정해야 2.1 단계가 **고쳐진 위상 위에서**
        # 움직인다. 단계 뒤에만 걸면 2.1 은 어긋난 위상 위에서 다 끝나 버린다 (§52.80).
        if PULSE_REFINE > 0 and self._pulse_phase is not None and not FREEZE_CONTROLS:
            self.refine_pulse_phase(verbose)
        if stage_iters > 0:
            for si, (grid, sizes) in enumerate(zip(GRID_MS, STAGES)):
                tc = self.set_grid(grid)
                if verbose:
                    print(f"  2.{si + 1} 단계  격자 {grid:g} ms ({tc} 점)  창 {sizes}", flush=True)
                rep = self.fit(stage_iters, lr_frame * (0.75 ** si), log_every, verbose,
                               sizes=sizes, patience=patience)
                self.vf_pitch_lock(verbose=verbose)
                self.vf_cycle_lock(verbose=verbose)
                if PULSE_REFINE > 1 and si + 2 <= PULSE_REFINE and self._pulse_phase is not None and not FREEZE_CONTROLS:
                    self.refine_pulse_phase(verbose)
                if STOP_AFTER_STAGE > 0 and si + 1 >= STOP_AFTER_STAGE:
                    if verbose:
                        print(f"  2.{si + 1} 단계 뒤 멈춤 (STOP_AFTER_STAGE, 진단용 — MEASUREMENTS §52.57)", flush=True)
                    break
        # **위상 단계는 기본이다.** 크기만 맞추면 위상은 물리가 강제하는 곳에서만 맞는다.
        # 실측(코퍼스 150 ms 창 4 개): 조화 SNR +3.3/+1.0/+3.5/−2.6 -> +24.7/+16.5/+12.9/+16.2,
        # 위상 모양 오차 7.6/29.9/65.5/25.4° -> 3.4/17.8/32.6/16.4°. 포락은 안 나빠졌다.
        # **위상 단계는 예산이 모자랐다.** 예전 값(lr = lr_frame·0.4 = 0.016, 200 반복)은
        # 어느 구간에서도 바닥에 못 닿았다. 학습률과 반복만 올린 실측(무제약):
        #
        #   | 구간      | 예전 (lr 0.016 / 200) | lr 0.12 / 800 |
        #   |-----------|-----------------------|---------------|
        #   | 정상 모음 |                  3.4° |      **0.1°** |
        #   | 설측 닐   |                 96.5° |     **36.4°** |
        #   | 탄음 이리 |                 50.9° |     **18.3°** |
        #
        # 기구를 하나도 안 더하고 설측 2.6 배, 탄음 2.8 배다. 크기 적합 단계는 설측의
        # 위상을 아예 못 건드렸고(94.8 -> 96.5°) 오직 이 단계만 움직였다.
        if HF_STAGE_ITERS > 0 and self.hf:
            if verbose:
                print(f"  2.5 단계  고역만 ({HF_STAGE_FMIN:.0f} Hz 위, 전역 {len(self.hf)} 개, "
                      f"{HF_STAGE_ITERS} 반복)", flush=True)
            self._hf_focus = True
            try:
                self.fit(HF_STAGE_ITERS, 0.05, log_every, verbose, sizes=FFT_SIZES,
                         patience=max(20, HF_STAGE_ITERS // 4))
            finally:
                self._hf_focus = False
        self.sizes = list(FFT_SIZES)
        return rep

    # ------------------------------------------------------------- 결과
    def result_track(self) -> ControlTrack:
        with torch.no_grad():
            v = self.control()[0].double().cpu().numpy()
        return ControlTrack(v, self.track.frame_ms, list(self.track.events))

    def render(self, seed: int | None = None) -> np.ndarray:
        """적합된 파라미터로 합성. `seed` 를 주면 **난류의 실현만** 바꾼다.

        같은 파라미터를 시드만 바꾼 합성 간 거리는 실현 분산을 추정하는 대조군이다.
        `turbulence.corrected_sc` 의 보정은 목표 분산 추정에도 의존하므로,
        여러 시드의 대역·시간 구조와 함께 읽는다. 시드별로 다시 적합하지 않는다.

        시드는 **`cfg.seed` 로** 바꾼다. `eng.noise` 에 직접 대입하면 조용히 무시된다 —
        `synth()` 가 부르는 `VoiceEngine.reset()` 이 `NoiseBank(self.cfg.seed)` 로
        덮어쓰기 때문이다.
        """
        with torch.no_grad():
            if seed is None:
                self._codec_aac_off = True                       # 결과 파일은 코덱 없이 (§52.523)
                try:
                    return self.synth()[0].cpu().numpy()
                finally:
                    self._codec_aac_off = False
            old = self.eng.cfg.seed
            try:
                self.eng.cfg.seed = int(seed)
                return self.synth()[0].cpu().numpy()
            finally:
                self.eng.cfg.seed = old

    def fidelity(self, seed_b: int = 991) -> dict:
        """실현 분산을 추정해 차감한 진단용 성적표.

        `fine_corr` 은 분산 추정에 의존한다. `resolved=False` 이면 편향을
        판별하지 못했으며, 보정값은 신뢰구간의 하한이 아니다. `trust` 는
        잔여거리 비율이고 `floor` 는 실현 기준 추정값이지 보편적 상한이 아니다.
        여러 시드·대역·시간 구조와 청취를 함께 평가해야 한다.
        """
        from . import turbulence as tb
        tgt = self.target[0].detach().cpu().numpy().astype(np.float64)
        a = self.render()
        b = self.render(seed_b)
        out = tb.spectral_fidelity(tgt, a, b, self.fs, tuple(FFT_SIZES), self.f_max)
        out["spectrum_match"] = tb.spectrum_match(tgt, a, self.fs)
        return out

    def gain_db(self) -> float:
        return float(20.0 * self.log_gain.detach().item() / math.log(10))

    def moved(self) -> list[tuple[str, float, float]]:
        """(이름, 초기 중앙값, 적합 중앙값). 어떤 파라미터가 얼마나 움직였는지."""
        out = []
        with torch.no_grad():
            u = self._u()
            for i, sp in enumerate(self.specs):
                a = float(self._to_val(self.u0[:, i], sp).median())
                b = float(self._to_val(u[:, i], sp).median())
                out.append((sp.name, a, b))
        return out
